_CONFIG_HELD = threading.local()


class ConfigError(RuntimeError):
    pass


def _config_path() -> Path:
    if APP_DATA != _INITIAL_APP_DATA:
        return APP_DATA / 'gitline.json'
    if _PROFILE_OVERRIDE_MODE and os.environ.get('GITLINE_CONFIG_FILE'):
        return Path(os.environ['GITLINE_CONFIG_FILE']).expanduser().resolve()
    # Explicit helper/test modes and in-process fixtures can isolate their data.
    if _PROFILE_OVERRIDE_MODE and os.environ.get('GITLINE_DATA_DIR'):
        return APP_DATA / 'gitline.json'
    return _SCRIPT_DIR / 'gitline.json'


@contextlib.contextmanager
def _config_lock():
    """Serialize section updates across GUI threads and credential-helper processes."""
    with _CONFIG_MUTEX:
        target = _config_path()
        held = getattr(_CONFIG_HELD, 'paths', None)
        if held is None:
            held = _CONFIG_HELD.paths = set()
        if target in held:
            yield
            return
        target.parent.mkdir(parents=True, exist_ok=True)
        descriptor = os.open(str(target) + '.lock', os.O_CREAT | os.O_RDWR, 0o600)
        locked = False
        try:
            if os.fstat(descriptor).st_size == 0:
                os.write(descriptor, b'\0')
            deadline = time.monotonic() + 15
            while True:
                try:
                    if os.name == 'nt':
                        import msvcrt
                        os.lseek(descriptor, 0, os.SEEK_SET)
                        msvcrt.locking(descriptor, msvcrt.LK_NBLCK, 1)
                    else:
                        import fcntl
                        fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
                    locked = True
                    break
                except OSError:
                    if time.monotonic() >= deadline:
                        raise ConfigError(f'Konfiguracja jest używana przez inny proces: {target}') from None
                    time.sleep(.02)
            held.add(target)
            yield
        finally:
            held.discard(target)
            if locked:
                if os.name == 'nt':
                    import msvcrt
                    os.lseek(descriptor, 0, os.SEEK_SET)
                    msvcrt.locking(descriptor, msvcrt.LK_UNLCK, 1)
                else:
                    import fcntl
                    fcntl.flock(descriptor, fcntl.LOCK_UN)
            os.close(descriptor)


def _read_config() -> dict:
    target = _config_path()
    try:
        with target.open('r', encoding='utf-8-sig') as stream:
            data = json.load(stream)
    except FileNotFoundError:
        return {'schema_version': 1}
    except (OSError, ValueError, UnicodeError) as error:
        raise ConfigError(f'Nie można odczytać konfiguracji {target}. Popraw plik JSON lub jego uprawnienia.') from error
    if not isinstance(data, dict) or data.get('schema_version', 1) != 1:
        raise ConfigError(f'Nieobsługiwany format konfiguracji: {target}')
    return data


def _config_has_section(name: str) -> bool:
    with _config_lock():
        return name in _read_config()


def _config_section(name: str, default=None):
    import copy
    with _config_lock():
        return copy.deepcopy(_read_config().get(name, default))


def _set_config_section(name: str, value) -> None:
    import tempfile
    with _config_lock():
        target = _config_path()
        data = _read_config()
        data['schema_version'] = 1
        data[name] = value
        serialized = json.dumps(data, ensure_ascii=False, indent=2, allow_nan=False) + '\n'
        temporary = None
        try:
            with tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', dir=target.parent,
                                             prefix=target.name + '.', suffix='.tmp', delete=False) as stream:
                temporary = Path(stream.name)
                stream.write(serialized); stream.flush(); os.fsync(stream.fileno())
            os.replace(temporary, target)
        except OSError as error:
            raise ConfigError(f'Nie można zapisać konfiguracji obok skryptu: {target}') from error
        finally:
            if temporary is not None:
                with contextlib.suppress(FileNotFoundError): temporary.unlink()

