def _bootstrap_check_cancelled():
    if _BOOTSTRAP_CANCEL_EVENT is not None and _BOOTSTRAP_CANCEL_EVENT.is_set():
        raise _BootstrapCancelled('Przygotowanie anulowane.')


def _bootstrap_progress(stage='', detail='', current=None, total=None):
    """Publish installer events; only the Tk main thread consumes this queue."""
    queue = _BOOTSTRAP_PROGRESS_QUEUE
    if queue is not None:
        queue.put({'kind': 'progress', 'stage': stage, 'detail': detail,
                   'current': current, 'total': total})


def _normal_gui_start() -> bool:
    # CLI modes and credential protocols keep their original streams even when
    # launched by a GUI process that carries our relaunch environment marker.
    return (not any(argument.startswith('-') for argument in sys.argv[1:])
            and not sys.flags.interactive and not sys.flags.inspect)


def _start_early_gui():
    """Paint the startup logo before importing the application and account code."""
    global _EARLY_GUI_APP, _EARLY_GUI_SPLASH
    if not _normal_gui_start() or _EARLY_GUI_SPLASH is not None:
        return
    from PySide6.QtWidgets import QApplication
    from PySide6.QtGui import QFont
    if os.name == 'nt':
        try:
            import ctypes
            ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID('Gitline.Desktop')
        except (AttributeError, OSError):
            pass
    app = QApplication.instance() or QApplication(sys.argv[:1])
    app.setApplicationName(APP_ID); app.setApplicationDisplayName(APP_NAME); app.setOrganizationName(APP_ID)
    app.setStyle('Fusion'); app.setFont(QFont('Segoe UI', 10))
    _EARLY_GUI_APP = app
    _EARLY_GUI_SPLASH = _startup_splash_type()()
    _EARLY_GUI_SPLASH.prepare()


def _pulse_early_gui():
    if _EARLY_GUI_SPLASH is not None:
        _EARLY_GUI_SPLASH.pulse()


def _private_windows_console() -> bool:
    """Recognize our own console, including py.exe and a venv redirector."""
    import ctypes
    from ctypes import wintypes
    kernel = ctypes.WinDLL('kernel32', use_last_error=True)
    kernel.GetConsoleProcessList.argtypes = (ctypes.POINTER(wintypes.DWORD), wintypes.DWORD)
    kernel.GetConsoleProcessList.restype = wintypes.DWORD
    processes = (wintypes.DWORD * 8)()
    count = kernel.GetConsoleProcessList(processes, len(processes))
    current = os.getpid()
    if not 1 <= count <= len(processes) or current not in processes[:count]:
        return False
    if count == 1:
        return True

    class ProcessEntry(ctypes.Structure):
        _fields_ = [('dwSize', wintypes.DWORD), ('cntUsage', wintypes.DWORD),
                    ('th32ProcessID', wintypes.DWORD), ('th32DefaultHeapID', ctypes.c_size_t),
                    ('th32ModuleID', wintypes.DWORD), ('cntThreads', wintypes.DWORD),
                    ('th32ParentProcessID', wintypes.DWORD), ('pcPriClassBase', wintypes.LONG),
                    ('dwFlags', wintypes.DWORD), ('szExeFile', wintypes.WCHAR * 260)]
    kernel.CreateToolhelp32Snapshot.argtypes = (wintypes.DWORD, wintypes.DWORD)
    kernel.CreateToolhelp32Snapshot.restype = wintypes.HANDLE
    kernel.Process32FirstW.argtypes = (wintypes.HANDLE, ctypes.POINTER(ProcessEntry))
    kernel.Process32NextW.argtypes = (wintypes.HANDLE, ctypes.POINTER(ProcessEntry))
    kernel.CloseHandle.argtypes = (wintypes.HANDLE,)
    snapshot = kernel.CreateToolhelp32Snapshot(2, 0)
    if snapshot in (None, ctypes.c_void_p(-1).value):
        return False
    entries = {}
    try:
        entry = ProcessEntry(); entry.dwSize = ctypes.sizeof(entry)
        present = kernel.Process32FirstW(snapshot, ctypes.byref(entry))
        while present:
            entries[entry.th32ProcessID] = (entry.th32ParentProcessID, entry.szExeFile.lower())
            present = kernel.Process32NextW(snapshot, ctypes.byref(entry))
    finally:
        kernel.CloseHandle(snapshot)
    ancestors, parent = set(), entries.get(current, (0, ''))[0]
    while parent and parent not in ancestors:
        ancestors.add(parent)
        parent = entries.get(parent, (0, ''))[0]

    kernel.OpenProcess.argtypes = (wintypes.DWORD, wintypes.BOOL, wintypes.DWORD)
    kernel.OpenProcess.restype = wintypes.HANDLE
    kernel.QueryFullProcessImageNameW.argtypes = (wintypes.HANDLE, wintypes.DWORD,
                                                wintypes.LPWSTR, ctypes.POINTER(wintypes.DWORD))
    def process_image(pid):
        handle = kernel.OpenProcess(0x1000, False, pid)
        if not handle:
            return ''
        try:
            buffer = ctypes.create_unicode_buffer(32768); length = wintypes.DWORD(len(buffer))
            return os.path.normcase(buffer.value) if kernel.QueryFullProcessImageNameW(
                handle, 0, buffer, ctypes.byref(length)) else ''
        finally:
            kernel.CloseHandle(handle)
    executable = os.path.normcase(str(Path(sys.executable).resolve()))
    redirected = (process_image(current) != executable
                  and (Path(sys.executable).parent.parent / 'pyvenv.cfg').is_file())
    for pid in processes[:count]:
        if pid == current:
            continue
        name = entries.get(pid, (0, ''))[1]
        if pid not in ancestors:
            return False
        if name == 'py.exe':
            continue
        if not (name == 'python.exe' and redirected and process_image(pid) == executable):
            return False
    # A shell joining during discovery turns this into a shared console.
    final = (wintypes.DWORD * 8)()
    final_count = kernel.GetConsoleProcessList(final, len(final))
    return final_count == count and set(final[:final_count]) == set(processes[:count])


def _console_stream(stream) -> bool:
    if stream is None:
        return True
    try:
        import ctypes
        import msvcrt
        from ctypes import wintypes
        handle = msvcrt.get_osfhandle(stream.fileno())
        mode = wintypes.DWORD()
        kernel = ctypes.WinDLL('kernel32', use_last_error=True)
        kernel.GetConsoleMode.argtypes = (wintypes.HANDLE, ctypes.POINTER(wintypes.DWORD))
        return bool(kernel.GetConsoleMode(handle, ctypes.byref(mode)))
    except (AttributeError, OSError, ValueError):
        return False


def _windows_console_attached() -> bool:
    try:
        import ctypes
        from ctypes import wintypes
        process = (wintypes.DWORD * 1)()
        return bool(ctypes.WinDLL('kernel32', use_last_error=True).GetConsoleProcessList(process, 1))
    except (AttributeError, OSError, ValueError):
        return True  # An uncertain console remains under the caller's control.


def _prepare_gui_log() -> None:
    global _GUI_LOG_STREAM
    APP_DATA.mkdir(parents=True, exist_ok=True)
    if _GUI_LOG_STREAM is None:
        _GUI_LOG_STREAM = (APP_DATA / 'application.log').open('a', encoding='utf-8', errors='replace', buffering=1)
    for name in ('stdout', 'stderr', '__stdout__', '__stderr__'):
        if _console_stream(getattr(sys, name)):
            setattr(sys, name, _GUI_LOG_STREAM)


def _show_bootstrap_message(detail: str) -> None:
    import ctypes
    ctypes.windll.user32.MessageBoxW(None, detail, APP_NAME, 0x10)


def _prepare_gui_console() -> None:
    """Relaunch only a private GUI console; never hide an existing terminal."""
    global _GUI_HIDDEN_MODE
    if os.name != 'nt' or not _normal_gui_start():
        return
    try:
        private = _private_windows_console()
    except (AttributeError, OSError, ValueError):
        private = False
    inherited = os.environ.get('GITLINE_GUI_DETACHED') == '1'
    if not private:
        # pythonw has no console. Bootstrap children carry this marker and log
        # their failures even though their supplied stderr is already a file.
        if not _windows_console_attached() and (sys.stderr is None or inherited):
            _GUI_HIDDEN_MODE = True
            try:
                _prepare_gui_log()
            except OSError as error:
                _bootstrap_error(f'Nie można otworzyć dziennika aplikacji: {error}')
                raise SystemExit(1) from error
        return
    _GUI_HIDDEN_MODE = True
    try:
        _prepare_gui_log()
        child = Path(sys.executable).with_name('pythonw.exe')
        if not child.is_file():
            child = Path(sys.executable)
        environment = os.environ.copy()
        environment['GITLINE_GUI_DETACHED'] = '1'
        subprocess.Popen([str(child), str(Path(__file__).resolve()), *sys.argv[1:]],
                         stdin=subprocess.DEVNULL, stdout=sys.stdout, stderr=sys.stderr,
                         env=environment, creationflags=_NO_WINDOW)
    except (OSError, ValueError) as error:
        _bootstrap_error(f'Nie udało się uruchomić interfejsu aplikacji: {error}')
        raise SystemExit(1) from error
    # Exiting also releases a waiting py.exe/venv launcher. No terminal HWND is
    # hidden or detached, which preserves PowerShell, cmd, and Windows Terminal.
    raise SystemExit(0)


def _startup_event_api():
    """Session-local acknowledgement; no shared config or marker files."""
    import ctypes
    from ctypes import wintypes
    api = ctypes.WinDLL('kernel32', use_last_error=True)
    api.CreateEventW.argtypes = (ctypes.c_void_p, wintypes.BOOL, wintypes.BOOL, wintypes.LPCWSTR)
    api.CreateEventW.restype = wintypes.HANDLE
    api.OpenEventW.argtypes = (wintypes.DWORD, wintypes.BOOL, wintypes.LPCWSTR)
    api.OpenEventW.restype = wintypes.HANDLE
    api.SetEvent.argtypes = (wintypes.HANDLE,); api.SetEvent.restype = wintypes.BOOL
    api.WaitForSingleObject.argtypes = (wintypes.HANDLE, wintypes.DWORD)
    api.WaitForSingleObject.restype = wintypes.DWORD
    api.CloseHandle.argtypes = (wintypes.HANDLE,); api.CloseHandle.restype = wintypes.BOOL
    return api


class _StartupHandoff:
    def __init__(self):
        import ctypes
        import uuid
        self._api = _startup_event_api()
        self.name = 'Local\\Gitline.Startup.' + uuid.uuid4().hex
        self._handle = self._api.CreateEventW(None, True, False, self.name)
        if not self._handle:
            raise OSError(ctypes.get_last_error(), 'Nie można przygotować przekazania okna aplikacji.')

    def ready(self):
        if not self._handle: return False
        result = self._api.WaitForSingleObject(self._handle, 0)
        if result not in (0, 258):
            raise OSError('Nie można sprawdzić gotowości okna aplikacji.')
        return result == 0

    def close(self):
        handle, self._handle = self._handle, None
        if handle: self._api.CloseHandle(handle)


def _create_startup_handoff():
    return _StartupHandoff()


def _notify_startup_visible() -> bool:
    """Acknowledge a painted golden splash to this launch's setup window."""
    name = os.environ.pop('GITLINE_STARTUP_EVENT', '')
    prefix = 'Local\\Gitline.Startup.'
    suffix = name.removeprefix(prefix)
    if (os.name != 'nt' or not name.startswith(prefix) or len(suffix) != 32
            or any(character not in '0123456789abcdef' for character in suffix)):
        return False
    try:
        api = _startup_event_api()
        handle = api.OpenEventW(0x0002, False, name)  # EVENT_MODIFY_STATE only.
        if not handle: return False
        try: return bool(api.SetEvent(handle))
        finally: api.CloseHandle(handle)
    except (OSError, AttributeError):
        return False  # A setup process that already closed cannot break startup.


def _bootstrap_notice(message: str) -> None:
    if sys.stdout is not None:
        try:
            print(message, flush=True)
        except (OSError, UnicodeError):
            pass


def _bootstrap_error(message: str) -> None:
    log_path = APP_DATA / 'application.log' if _GUI_HIDDEN_MODE else _BOOTSTRAP_LOG
    detail = f"{message}\n\nDziennik: {log_path}"
    if sys.stderr is not None:
        try:
            print(detail, file=sys.stderr, flush=True)
        except (OSError, UnicodeError):
            pass
    if _GUI_HIDDEN_MODE or sys.stderr is None:
        try:
            if sys.stderr is not _GUI_LOG_STREAM or _GUI_LOG_STREAM is None:
                APP_DATA.mkdir(parents=True, exist_ok=True)
                with log_path.open('a', encoding='utf-8', errors='replace') as log:
                    log.write(detail + '\n')
        except OSError:
            pass
    if os.name == "nt" and _normal_gui_start() and (_GUI_HIDDEN_MODE or sys.stderr is None):
        try:
            _show_bootstrap_message(detail)
        except (AttributeError, OSError):
            pass


@contextlib.contextmanager
def _bootstrap_lock():
    """OS-owned lock: another launch can wait, and a crash cannot leave it held."""
    lock_file = (APP_DATA / "runtime.lock").open("a+b")
    acquired = False
    try:
        lock_file.seek(0, os.SEEK_END)
        if lock_file.tell() == 0:
            lock_file.write(b"0")
            lock_file.flush()
        deadline = time.monotonic() + 900
        while not acquired:
            _bootstrap_check_cancelled()
            lock_file.seek(0)
            try:
                if os.name == "nt":
                    import msvcrt
                    msvcrt.locking(lock_file.fileno(), msvcrt.LK_NBLCK, 1)
                else:
                    import fcntl
                    fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
                acquired = True
            except OSError:
                if time.monotonic() >= deadline:
                    raise RuntimeError("Inne uruchomienie nadal przygotowuje środowisko. Spróbuj ponownie później.")
                time.sleep(0.25)
        yield
    finally:
        if acquired:
            lock_file.seek(0)
            if os.name == "nt":
                import msvcrt
                msvcrt.locking(lock_file.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl
                fcntl.flock(lock_file.fileno(), fcntl.LOCK_UN)
        lock_file.close()


def _bootstrap_env() -> dict[str, str]:
    env = os.environ.copy()
    # These process-local changes prevent an unrelated Python environment from
    # contaminating the private runtime. No user/system environment is modified.
    env.pop("PYTHONHOME", None)
    env.pop("PYTHONPATH", None)
    env.pop("VIRTUAL_ENV", None)
    env.pop("GITLINE_RELAUNCHED", None)
    if not _PROFILE_OVERRIDE_MODE:
        env.pop("GITLINE_DATA_DIR", None)
        env.pop("GITLINE_CONFIG_FILE", None)
    env["PYTHONNOUSERSITE"] = "1"
    env["PYTHONUTF8"] = "1"
    return env


def _bootstrap_source(internal=False, index_url="", username="", password="") -> dict:
    """Validate a source before any environment creation or download."""
    from urllib.parse import urlsplit, urlunsplit
    if not internal:
        return {"internal": False, "index_url": _PUBLIC_PYPI_INDEX, "username": "", "password": ""}
    index_url, username = index_url.strip(), username.strip()
    if not index_url:
        raise ValueError("Podaj adres repozytorium pakietów Artifactory, zakończony /simple.")
    if "://" not in index_url:
        index_url = "https://" + index_url
    try:
        parsed = urlsplit(index_url)
        valid = (parsed.scheme == "https" and bool(parsed.hostname) and parsed.username is None
                 and parsed.password is None and not parsed.query and not parsed.fragment
                 and not any(char.isspace() or ord(char) < 32 for char in index_url))
        parsed.port
    except ValueError:
        valid = False
    if not valid:
        raise ValueError("Podaj adres HTTPS indeksu pip. Login i hasło wpisz w osobnych polach.")
    if bool(username) != bool(password):
        raise ValueError("Wpisz login i hasło albo pozostaw oba pola puste.")
    if any(ord(char) < 32 for char in username + password):
        raise ValueError("Login i hasło nie mogą zawierać znaków sterujących.")
    return {"internal": True, "index_url": urlunsplit(parsed).rstrip("/"),
            "username": username, "password": password}


def _bootstrap_source_defaults() -> dict:
    result = {"internal": False, "index_url": _ARTIFACTORY_INDEX, "username": "reader",
              "shortcuts": _bootstrap_shortcut_choices()}
    central = _config_has_section('bootstrap')
    if not central:
        return result
    try:
        saved = _config_section('bootstrap')
        if not isinstance(saved, dict) or not isinstance(saved.get('internal', False), bool):
            raise ValueError('Nieprawidłowe ustawienie źródła pakietów.')
        # Validate persisted URLs too; never accept embedded credentials.
        internal = _bootstrap_source(True, saved.get("index_url", _ARTIFACTORY_INDEX))
        result.update(internal=saved.get('internal', False), index_url=internal["index_url"])
        if isinstance(saved.get("username"), str):
            result["username"] = saved["username"]
        elif 'username' in saved:
            raise ValueError('Nieprawidłowy login źródła pakietów.')
        if 'shortcuts' in saved and (not isinstance(saved['shortcuts'], dict)
                                    or any(not isinstance(value, bool) for value in saved['shortcuts'].values())):
            raise ValueError('Nieprawidłowe ustawienia skrótów.')
        result['shortcuts'] = _bootstrap_shortcut_choices(saved.get('shortcuts'))
    except (OSError, ValueError, TypeError, AttributeError) as error:
        raise ConfigError(f'Nieprawidłowa sekcja bootstrap w {_config_path()}: {error}') from error
    return result


def _save_bootstrap_source(source: dict) -> None:
    # Credentials are never written to preferences, requirements or the ready marker.
    previous = _bootstrap_source_defaults()
    with _config_lock():
        saved = _config_section('bootstrap', {})
        saved = dict(saved) if isinstance(saved, dict) else {}
        saved.pop('password', None)
        saved.update(internal=source['internal'],
                     index_url=source['index_url'] if source['internal'] else previous['index_url'],
                     username=source['username'] if source['internal'] else previous['username'],
                     shortcuts=_bootstrap_shortcut_choices(source.get('shortcuts', previous['shortcuts'])))
        _set_config_section('bootstrap', saved)


def _bootstrap_shortcut_choices(saved=None) -> dict:
    saved = saved if isinstance(saved, dict) else {}
    return {name: saved[name] if isinstance(saved.get(name), bool) else True
            for name in ('desktop', 'taskbar', 'start_menu')}


def _bootstrap_source_window(tk, ttk, defaults, *, retained=False):
    """Build a setup window using only the Python installation's bundled Tk."""
    root = tk.Tk(); root.withdraw()
    root.title(f"{APP_NAME} · Przygotowanie")
    root.configure(background="#171821")
    root.resizable(False, False)
    style = ttk.Style(root)
    style.theme_use("clam")
    style.configure("Setup.TFrame", background="#171821")
    style.configure("Setup.TLabel", background="#171821", foreground="#e9e8f3", font=("Segoe UI", 10))
    style.configure("SetupTitle.TLabel", background="#171821", foreground="#f4f0ff", font=("Segoe UI", 18, "bold"))
    style.configure("SetupHint.TLabel", background="#171821", foreground="#aaa9bb", font=("Segoe UI", 9))
    style.configure("Setup.TCheckbutton", background="#171821", foreground="#e9e8f3", font=("Segoe UI", 10))
    style.map("Setup.TCheckbutton", background=[("active", "#171821")])
    style.configure("Setup.TEntry", fieldbackground="#252634", foreground="#f4f0ff", padding=(8, 5))
    style.map("Setup.TEntry", fieldbackground=[("disabled", "#1d1e28")], foreground=[("disabled", "#68697a")])
    style.configure("Setup.TButton", padding=(14, 6), font=("Segoe UI", 10))
    style.configure("SetupPrimary.TButton", padding=(14, 6), background="#c3b1f5", foreground="#191322", font=("Segoe UI", 10, "bold"))
    style.map("SetupPrimary.TButton", background=[("active", "#d4c6fa")])
    body = ttk.Frame(root, padding=(20, 18), style="Setup.TFrame"); body.grid(sticky="nsew")
    body.columnconfigure(0, weight=1)
    ttk.Label(body, text="Przygotuj Gitline", style="SetupTitle.TLabel").grid(row=0, sticky="w")
    ttk.Label(body, text="Wybierz, skąd pobrać biblioteki aplikacji.", style="SetupHint.TLabel").grid(row=1, sticky="w", pady=(3, 10))
    internal = tk.BooleanVar(root, value=defaults["internal"])
    address = tk.StringVar(root, value=defaults["index_url"])
    username = tk.StringVar(root, value=defaults["username"])
    password = tk.StringVar(root)
    checkbox = ttk.Checkbutton(body, text="Czy wewnętrzne Artifactory?", variable=internal, style="Setup.TCheckbutton")
    checkbox.grid(row=2, sticky="w", pady=(0, 6))
    credentials = ttk.Frame(body, style="Setup.TFrame"); credentials.grid(row=3, sticky="ew")
    credentials.columnconfigure((0, 1), weight=1, uniform='credentials')
    entries = []
    for caption, variable, masked, row, column, span in (
            ("Adres indeksu pip (…/simple)", address, False, 0, 0, 2),
            ("Login", username, False, 2, 0, 1), ("Hasło", password, True, 2, 1, 1)):
        inset = (0, 6) if row and not column else (6, 0) if column else (0, 0)
        ttk.Label(credentials, text=caption, style="Setup.TLabel").grid(
            row=row, column=column, columnspan=span, sticky="w", padx=inset, pady=(6 if row else 0, 3))
        entry = ttk.Entry(credentials, textvariable=variable, show="•" if masked else "",
                          width=54 if span == 2 else 24, style="Setup.TEntry")
        entry.grid(row=row + 1, column=column, columnspan=span, sticky="ew", padx=inset)
        entries.append(entry)
    hint = ttk.Label(body, style="SetupHint.TLabel", wraplength=660)
    hint.grid(row=4, sticky="w", pady=(5, 10))
    shortcut_choices = _bootstrap_shortcut_choices(defaults.get('shortcuts'))
    shortcut_vars = {name: tk.BooleanVar(root, value=value) for name, value in shortcut_choices.items()}
    shortcuts = ttk.Frame(body, style="Setup.TFrame"); shortcuts.grid(row=5, sticky='w')
    ttk.Label(shortcuts, text='Skróty:', style='Setup.TLabel').grid(row=0, column=0, padx=(0, 10))
    for column, (name, caption) in enumerate((('desktop', 'Pulpit'), ('taskbar', 'Pasek zadań'),
                                             ('start_menu', 'Menu Start')), start=1):
        option = ttk.Checkbutton(shortcuts, text=caption, variable=shortcut_vars[name], style='Setup.TCheckbutton')
        option.grid(row=0, column=column, sticky='w', padx=(0, 12))
        if os.name != 'nt': option.state(['disabled'])
    ttk.Label(body, text='Pasek zadań: po starcie kliknij „Przypnij” i potwierdź w Windows.',
              style='SetupHint.TLabel', wraplength=660).grid(row=6, sticky='w', pady=(3, 0))
    paths = ttk.Label(body, text=f'Konfiguracja: {_config_path()}\nŚrodowisko: {_RUNTIME_DIR}',
                      style='SetupHint.TLabel', wraplength=660, justify='left')
    paths.grid(row=7, sticky='w', pady=(12, 0))
    error = ttk.Label(body, text="", style="Setup.TLabel", foreground="#ffb4a9", wraplength=660)
    error.grid(row=8, sticky="w", pady=(7, 0)); error.grid_remove()
    buttons = ttk.Frame(body, style="Setup.TFrame"); buttons.grid(row=9, sticky="e", pady=(12, 0))
    result = {"source": None}

    def changed(*unused):
        for entry in entries:
            entry.configure(state="normal" if internal.get() else "disabled")
        if internal.get(): credentials.grid()
        else: credentials.grid_remove()
        hint.configure(text="Hasło tylko do tej instalacji — nie zapisujemy go na dysku."
                       if internal.get() else "Publiczne PyPI: https://pypi.org/simple.")
        error.configure(text=""); error.grid_remove()
        # Keep the expanded form inside the screen when Artifactory is enabled.
        root.update_idletasks()
        width, height = root.winfo_reqwidth(), root.winfo_reqheight()
        root.geometry(f"+{max(0, (root.winfo_screenwidth() - width) // 2)}+{max(0, (root.winfo_screenheight() - height) // 2)}")

    def confirm(*unused):
        if retained and result.get('_busy'):
            return
        try:
            result["source"] = _bootstrap_source(internal.get(), address.get(), username.get(), password.get())
            result['source']['shortcuts'] = {name: value.get() for name, value in shortcut_vars.items()}
        except ValueError as exc:
            error.configure(text=str(exc)); error.grid()
            return
        if retained:
            password.set('')
            callback = result.get('_on_confirm')
            if callback is not None: callback(result['source'])
        else:
            root.destroy()

    cancel_button = ttk.Button(buttons, text="Anuluj", command=root.destroy, style="Setup.TButton")
    cancel_button.pack(side="left", padx=(0, 10))
    ttk.Button(buttons, text="Przygotuj środowisko", command=confirm, style="SetupPrimary.TButton").pack(side="left")
    internal.trace_add("write", changed); changed()
    root.bind("<Return>", confirm); root.bind("<Escape>", lambda event: root.destroy())
    root.protocol("WM_DELETE_WINDOW", root.destroy)
    root.update_idletasks()
    width, height = root.winfo_reqwidth(), root.winfo_reqheight()
    root.geometry(f"+{max(0, (root.winfo_screenwidth() - width) // 2)}+{max(0, (root.winfo_screenheight() - height) // 2)}")
    # Exposed local controls also allow deterministic, no-download setup regressions.
    return root, result, {"internal": internal, "address": address, "username": username,
                           "password": password, "entries": entries, "confirm": confirm, "error": error,
                             "shortcuts": shortcut_vars, "paths": paths, "form": body, "cancel": cancel_button}


class _BootstrapSetupSession:
    """One Tk window; worker threads send events and never call Tk."""
    def __init__(self, root, result, controls, ttk, prepare):
        import queue
        self.root, self.result, self.controls, self.prepare = root, result, controls, prepare
        self.events, self.cancel_event = queue.Queue(), threading.Event()
        self.worker = None; self.closed = False; self.started = 0.0; self.phase = 'form'; self.exit_code = 0
        self.close_error_requested = False
        self.previous_queue, self.previous_cancel = _BOOTSTRAP_PROGRESS_QUEUE, _BOOTSTRAP_CANCEL_EVENT
        self.pane = ttk.Frame(root, padding=20, style='Setup.TFrame')
        self.pane.columnconfigure(0, weight=1)
        self.stage = ttk.Label(self.pane, text='Przygotowanie Gitline', style='SetupTitle.TLabel')
        self.stage.grid(sticky='w')
        self.detail = ttk.Label(self.pane, text='', style='SetupHint.TLabel', wraplength=620, justify='left')
        self.detail.grid(sticky='w', pady=(8, 12))
        self.bar = ttk.Progressbar(self.pane, mode='indeterminate', length=540)
        self.bar.grid(sticky='ew')
        self.elapsed = ttk.Label(self.pane, text='', style='SetupHint.TLabel')
        self.elapsed.grid(sticky='w', pady=(7, 0))
        actions = ttk.Frame(self.pane, style='Setup.TFrame'); actions.grid(sticky='e', pady=(12, 0))
        self.retry_button = ttk.Button(actions, text='Spróbuj ponownie', command=self.retry, style='Setup.TButton')
        self.retry_button.grid(row=0, column=0, padx=(0, 8)); self.retry_button.grid_remove()
        self.close_button = ttk.Button(actions, text='Anuluj', command=self.close, style='Setup.TButton')
        self.close_button.grid(row=0, column=1)
        result['_on_confirm'] = self.start
        controls['cancel'].configure(command=self.close)
        root.protocol('WM_DELETE_WINDOW', self.close)
        root.bind('<Escape>', lambda event: self.close())
        self.timer = root.after(50, self.poll)

    def start(self, source):
        if self.worker is not None and self.worker.is_alive(): return
        global _BOOTSTRAP_PROGRESS_QUEUE, _BOOTSTRAP_CANCEL_EVENT
        _BOOTSTRAP_PROGRESS_QUEUE, _BOOTSTRAP_CANCEL_EVENT = self.events, self.cancel_event
        self.cancel_event.clear(); self.result['_busy'] = True; self.phase = 'working'; self.exit_code = 0
        self.close_error_requested = False
        self.started = time.monotonic()
        self.controls['form'].grid_remove(); self.pane.grid(sticky='nsew')
        self.retry_button.grid_remove(); self.close_button.configure(text='Anuluj', state='normal')
        self.stage.configure(text='Przygotowanie środowiska')
        self.detail.configure(text='Sprawdzam środowisko tej kopii Gitline…')
        self.bar.configure(mode='indeterminate'); self.bar.start(12)
        def work():
            try:
                _bootstrap_check_cancelled()
                _save_bootstrap_source(source)
                outcome = self.prepare(source)
                self.events.put({'kind': 'done', 'outcome': outcome})
            except _BootstrapCancelled:
                self.events.put({'kind': 'cancelled'})
            except BaseException as error:
                self.events.put({'kind': 'error', 'error': error})
            finally:
                source['password'] = ''
        self.worker = threading.Thread(target=work, name='Gitline setup', daemon=False)
        self.worker.start()

    def poll(self):
        if self.closed: return
        import queue
        try:
            for unused in range(100):
                event = self.events.get_nowait(); kind = event['kind']
                if kind == 'progress':
                    if self.cancel_event.is_set(): continue
                    if event.get('stage'):
                        self.stage.configure(text=str(event['stage'])[:180])
                    if event.get('detail'):
                        self.detail.configure(text=str(event['detail'])[-1200:])
                    current, total = event.get('current'), event.get('total')
                    if isinstance(current, (int, float)) and isinstance(total, (int, float)) and total > 0:
                        self.bar.stop(); self.bar.configure(mode='determinate', maximum=total, value=max(0, min(current, total)))
                    elif str(self.bar.cget('mode')) != 'indeterminate':
                        self.bar.configure(mode='indeterminate'); self.bar.start(12)
                    if event.get('stage') == 'Uruchamianie Gitline':
                        self.phase = 'handoff'; self.close_button.configure(text='Zamknij przygotowanie')
                elif kind == 'done':
                    self.bar.stop()
                    if event.get('outcome') == 'handoff':
                        self.destroy(); return
                    self.phase = 'complete'; self.stage.configure(text='Gitline jest gotowy')
                    self.detail.configure(text='Środowisko zostało przygotowane. Możesz zamknąć to okno i uruchomić aplikację.')
                    self.close_button.configure(text='Zamknij', state='normal')
                elif kind == 'cancelled':
                    self.destroy(); return
                elif kind == 'error':
                    error = event['error']; self.bar.stop(); self.exit_code = 1
                    self.phase = 'error'; self.stage.configure(text='Nie udało się zakończyć przygotowania')
                    self.detail.configure(text=str(error)[-1800:] or 'Przygotowanie zostało przerwane.')
                    self.close_button.configure(text='Zamknij', state='normal')
                    if getattr(error, 'retryable', True): self.retry_button.grid()
                    else: self.retry_button.grid_remove()
        except queue.Empty:
            pass
        if (self.cancel_event.is_set() and self.worker is not None and not self.worker.is_alive()
                and self.events.empty()
                and (self.phase != 'error' or self.close_error_requested)):
            self.destroy(); return
        if self.started:
            seconds = int(time.monotonic() - self.started)
            self.elapsed.configure(text=f'Czas: {seconds // 60}:{seconds % 60:02d}')
        self.timer = self.root.after(50, self.poll)

    def retry(self):
        if self.worker is not None and self.worker.is_alive(): return
        self.pane.grid_remove(); self.controls['form'].grid()
        self.controls['password'].set(''); self.result['source'] = None; self.result['_busy'] = False
        self.cancel_event.clear(); self.phase = 'form'; self.exit_code = 0

    def close(self):
        if self.worker is not None and self.worker.is_alive():
            self.close_error_requested = self.phase in ('error', 'complete')
            self.cancel_event.set()
            self.close_button.configure(text='Kończenie…', state='disabled')
            self.detail.configure(text='Kończenie bieżącego etapu…')
            return
        self.destroy()

    def destroy(self):
        if self.closed: return
        global _BOOTSTRAP_PROGRESS_QUEUE, _BOOTSTRAP_CANCEL_EVENT
        self.closed = True
        _BOOTSTRAP_PROGRESS_QUEUE, _BOOTSTRAP_CANCEL_EVENT = self.previous_queue, self.previous_cancel
        self.bar.stop()
        with contextlib.suppress(Exception): self.root.after_cancel(self.timer)
        self.controls['password'].set('')
        source = self.result.get('source')
        if isinstance(source, dict): source['password'] = ''
        self.root.destroy()


def _choose_bootstrap_source(*, prepare=None):
    try:
        import tkinter as tk
        from tkinter import ttk
    except ImportError as exc:
        raise RuntimeError("Okno przygotowania wymaga Tkintera. W instalatorze Pythona włącz składnik Tcl/Tk (tkinter).") from exc
    try:
        root, result, _controls = _bootstrap_source_window(tk, ttk, _bootstrap_source_defaults(), retained=prepare is not None)
        session = _BootstrapSetupSession(root, result, _controls, ttk, prepare) if prepare is not None else None
        root.deiconify(); root.lift(); root.mainloop()
    except tk.TclError as exc:
        raise RuntimeError("Nie można otworzyć okna przygotowania. Sprawdź dostępność pulpitu i składnika Tcl/Tk w Pythonie.") from exc
    if session is not None:
        return session.exit_code
    source = result["source"]
    if source is None:
        _bootstrap_notice("Anulowano przygotowanie środowiska.")
        raise SystemExit(0)
    _save_bootstrap_source(source)
    return source


def _bootstrap_pip(source: dict) -> tuple[list[str], dict[str, str]]:
    """Keep the index password out of process arguments and inherited pip config."""
    from urllib.parse import quote, urlsplit, urlunsplit
    parsed = urlsplit(source["index_url"])
    netloc = parsed.netloc
    if source["internal"] and source["username"]:
        netloc = quote(source["username"], safe="") + ":" + quote(source["password"], safe="") + "@" + netloc
    environment = _bootstrap_env()
    environment["PIP_CONFIG_FILE"] = os.devnull
    environment["GITLINE_PIP_INDEX"] = urlunsplit(parsed._replace(netloc=netloc))
    options = []
    if source["internal"]:
        no_proxy = ",".join(filter(None, (environment.get("NO_PROXY"), environment.get("no_proxy"), parsed.hostname)))
        environment["NO_PROXY"] = environment["no_proxy"] = no_proxy
        # Preserve support for the corporate gateway's internal certificate chain.
        options = ["--trusted-host", parsed.hostname]
    return options, environment


def _bootstrap_python_works(python: Path) -> bool:
    if not python.is_file():
        return False
    try:
        code = ("import sys; from pathlib import Path; assert sys.prefix != sys.base_prefix; "
                f"assert Path(sys.prefix).resolve() == Path({str(_RUNTIME_DIR)!r}).resolve()")
        result = subprocess.run([str(python), "-I", "-c", code],
                                stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                                creationflags=_NO_WINDOW, env=_bootstrap_env(), timeout=30)
        return result.returncode == 0
    except (OSError, subprocess.TimeoutExpired):
        return False


_TASKBAR_MANUAL_HINT = ('Kliknij ikonę Gitline na pasku zadań prawym przyciskiem '
                        'i wybierz „Przypnij do paska zadań”.')


class _WindowsCOM:
    """Small stdlib COM adapter shared by documented Shell and WinRT APIs."""
    def __init__(self):
        import ctypes
        import uuid
        self.c = ctypes
        class GUID(ctypes.Structure):
            _fields_ = [('data1', ctypes.c_uint32), ('data2', ctypes.c_uint16),
                        ('data3', ctypes.c_uint16), ('data4', ctypes.c_ubyte * 8)]
        self.GUID = GUID
        self.guid = lambda value: GUID.from_buffer_copy(uuid.UUID(value).bytes_le)
        self.ole = ctypes.WinDLL('ole32')
        self.ole.CoInitializeEx.argtypes = (ctypes.c_void_p, ctypes.c_uint32)
        self.ole.CoInitializeEx.restype = ctypes.c_long
        result = self.ole.CoInitializeEx(None, 2)
        self.initialized = result in (0, 1)
        if not self.initialized and (result & 0xffffffff) != 0x80010106:
            self.check(result)
    @staticmethod
    def check(result):
        if result < 0: raise OSError(f'Windows API: 0x{result & 0xffffffff:08X}')
    def invoke(self, pointer, index, signature=(), *values):
        c = self.c
        table = c.cast(pointer, c.POINTER(c.POINTER(c.c_void_p))).contents
        function = c.WINFUNCTYPE(c.c_long, c.c_void_p, *signature)(table[index])
        self.check(function(pointer, *values))
    def query(self, pointer, iid):
        c = self.c; result = c.c_void_p(); guid = self.guid(iid)
        self.invoke(pointer, 0, (c.POINTER(self.GUID), c.POINTER(c.c_void_p)), c.byref(guid), c.byref(result))
        return result
    def release(self, pointer):
        if pointer:
            self.invoke(pointer, 2)
    def close(self):
        if self.initialized:
            self.ole.CoUninitialize(); self.initialized = False
    def __enter__(self): return self
    def __exit__(self, *unused): self.close()


def _windows_shortcut_folders() -> dict:
    with _WindowsCOM() as api:
        c = api.c; shell = c.WinDLL('shell32')
        shell.SHGetKnownFolderPath.argtypes = (c.POINTER(api.GUID), c.c_uint32, c.c_void_p, c.POINTER(c.c_void_p))
        shell.SHGetKnownFolderPath.restype = c.c_long
        api.ole.CoTaskMemFree.argtypes = (c.c_void_p,)
        result = {}
        for name, value in (('desktop', 'B4BFCC3A-DB2C-424C-B029-7FE99A87C641'),
                            ('start_menu', 'A77F5D77-2E2B-44C3-A6A2-ABA601054A51')):
            pointer = c.c_void_p(); guid = api.guid(value)
            api.check(shell.SHGetKnownFolderPath(c.byref(guid), 0, None, c.byref(pointer)))
            try: result[name] = Path(c.wstring_at(pointer))
            finally: api.ole.CoTaskMemFree(pointer)
        return result


def _write_windows_shortcut(path: Path, executable: Path, script: Path, icon: Path) -> None:
    """Write an atomic .lnk with the same identity and icon as the running app."""
    path.parent.mkdir(parents=True, exist_ok=True)
    staged = path.with_name(f'.{path.stem}-{os.getpid()}.tmp.lnk')
    try:
        with _WindowsCOM() as api:
            c = api.c; link = c.c_void_p(); properties = persist = None
            api.ole.CoCreateInstance.argtypes = (c.POINTER(api.GUID), c.c_void_p, c.c_uint32,
                                                c.POINTER(api.GUID), c.POINTER(c.c_void_p))
            api.ole.CoCreateInstance.restype = c.c_long
            clsid, iid = api.guid('00021401-0000-0000-C000-000000000046'), api.guid('000214F9-0000-0000-C000-000000000046')
            api.check(api.ole.CoCreateInstance(c.byref(clsid), None, 1, c.byref(iid), c.byref(link)))
            try:
                for method, text in ((20, str(executable)), (11, subprocess.list2cmdline(['-I', '-X', 'utf8', str(script)])),
                                     (9, str(script.parent)), (7, 'Gitline — klient Git')):
                    api.invoke(link, method, (c.c_wchar_p,), text)
                api.invoke(link, 17, (c.c_wchar_p, c.c_int), str(icon), 0)
                api.invoke(link, 15, (c.c_int,), 1)
                properties = api.query(link, '886D8EEB-8CF2-4446-8D02-CDBA1DBDCF99')
                class PropertyKey(c.Structure):
                    _fields_ = [('format', api.GUID), ('pid', c.c_uint32)]
                class PropVariant(c.Structure):
                    _fields_ = [('vt', c.c_uint16), ('reserved', c.c_uint16 * 3),
                                ('value', c.c_void_p), ('padding', c.c_void_p)]
                text = c.create_unicode_buffer('Gitline.Desktop')
                key = PropertyKey(api.guid('9F4C2855-9F79-4B39-A8D0-E1D42DE1D5F3'), 5)
                value = PropVariant(); value.vt = 31; value.value = c.cast(text, c.c_void_p)
                api.invoke(properties, 6, (c.POINTER(PropertyKey), c.POINTER(PropVariant)), c.byref(key), c.byref(value))
                api.invoke(properties, 7)
                persist = api.query(link, '0000010B-0000-0000-C000-000000000046')
                api.invoke(persist, 6, (c.c_wchar_p, c.c_int), str(staged), 1)
            finally:
                for pointer in (persist, properties, link): api.release(pointer)
        staged.replace(path)
    finally:
        staged.unlink(missing_ok=True)


def _save_shortcut_icon(path: Path) -> None:
    """Reuse the app's original vector logo at normal Windows icon sizes."""
    import struct
    from PySide6.QtCore import QByteArray, QBuffer, QIODevice
    app = QApplication.instance() or QApplication([])
    frames = []
    for size in (16, 24, 32, 48, 64, 128, 256):
        data = QByteArray(); buffer = QBuffer(data)
        buffer.open(QIODevice.OpenModeFlag.WriteOnly)
        pixmap = ui_icon('logo', '#baa8ff', size).pixmap(size, size)
        pixmap.setDevicePixelRatio(1)
        if not pixmap.save(buffer, 'PNG'): raise RuntimeError('Nie można przygotować ikony Gitline.')
        frames.append((size, bytes(data)))
    offset = 6 + 16 * len(frames)
    content = bytearray(struct.pack('<HHH', 0, 1, len(frames)))
    for size, data in frames:
        content.extend(struct.pack('<BBBBHHII', size % 256, size % 256, 0, 0, 1, 32, len(data), offset))
        offset += len(data)
    for size, data in frames: content.extend(data)
    path.parent.mkdir(parents=True, exist_ok=True)
    staged = path.with_suffix('.tmp.ico')
    staged.write_bytes(content); staged.replace(path)


def _prepare_shortcut_icon(runtime_python: Path, script: Path, target: Path) -> None:
    launcher = ("import importlib.util,sys; from pathlib import Path; "
                "spec=importlib.util.spec_from_file_location('_gitline_icon',sys.argv[1]); "
                "module=importlib.util.module_from_spec(spec); sys.modules[spec.name]=module; "
                "spec.loader.exec_module(module); module._save_shortcut_icon(Path(sys.argv[2]))")
    env = _bootstrap_env(); env['QT_QPA_PLATFORM'] = 'offscreen'
    _bootstrap_run([str(runtime_python), '-I', '-X', 'utf8', '-c', launcher, str(script), str(target)], timeout=60, env=env)


def _install_windows_shortcuts(runtime_python: Path, choices: dict) -> dict:
    choices = _bootstrap_shortcut_choices(choices)
    result = {'created': [], 'errors': []}
    if os.name != 'nt' or not any(choices[name] for name in ('desktop', 'start_menu')): return result
    script, icon = Path(__file__).resolve(), APP_DATA / 'gitline.ico'
    executable = runtime_python.with_name('pythonw.exe')
    try:
        if not executable.is_file(): raise RuntimeError('Brakuje pythonw.exe potrzebnego do uruchomienia bez konsoli.')
        _prepare_shortcut_icon(runtime_python, script, icon)
        folders = _windows_shortcut_folders()
    except (OSError, RuntimeError) as error:
        result['errors'].append(str(error)); return result
    for name in ('desktop', 'start_menu'):
        if not choices[name]: continue
        target = folders[name] / f'{APP_NAME}.lnk'
        try:
            _write_windows_shortcut(target, executable, script, icon)
            result['created'].append(str(target))
        except (OSError, RuntimeError) as error:
            result['errors'].append(f'{target}: {error}')
    return result


class _WindowsTaskbarPinRequest:
    """Documented TaskbarManager request; created and polled on the foreground UI thread."""
    # https://learn.microsoft.com/windows/apps/develop/windows-integration/pin-to-taskbar
    # ABI: https://github.com/microsoft/windows-rs/blob/master/crates/libs/windows/src/Windows/UI/Shell/mod.rs
    def __init__(self):
        self.api = _WindowsCOM()
        self._references = []; self._ro_initialized = False; self._closed = False
        self._operation = self._info = None
        self._completed = False; self._result = False
        c = self.api.c
        try:
            import winreg
            key_path = r'SOFTWARE\Microsoft\Windows\CurrentVersion\AppModel\LimitedAccessFeatures\com.microsoft.windows.taskbar.pin'
            try:
                with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, key_path) as key:
                    seed = winreg.QueryValueEx(key, '4096B239A7295B635C090E647E867B5707DA6AB6CB78340B01FE4E0C8F4953D4')[0]
                if seed:
                    raise RuntimeError('Ta wersja Windows wymaga ręcznego przypięcia aplikacji.')
            except FileNotFoundError:
                pass
            user = c.WinDLL('user32')
            user.GetForegroundWindow.restype = c.c_void_p
            user.GetWindowThreadProcessId.argtypes = (c.c_void_p, c.POINTER(c.c_uint32))
            foreground_process = c.c_uint32()
            user.GetWindowThreadProcessId(user.GetForegroundWindow(), c.byref(foreground_process))
            if foreground_process.value != os.getpid():
                raise RuntimeError('Kliknij „Przypnij” w aktywnym oknie Gitline.')
            self.runtime = c.WinDLL('combase')
            self.runtime.RoInitialize.argtypes = (c.c_uint32,); self.runtime.RoInitialize.restype = c.c_long
            result = self.runtime.RoInitialize(0)
            if (result & 0xffffffff) == 0x80010106: result = self.runtime.RoInitialize(1)
            self.api.check(result); self._ro_initialized = True
            self.runtime.WindowsCreateString.argtypes = (c.c_wchar_p, c.c_uint32, c.POINTER(c.c_void_p))
            self.runtime.WindowsCreateString.restype = c.c_long
            self.runtime.WindowsDeleteString.argtypes = (c.c_void_p,)
            self.runtime.RoGetActivationFactory.argtypes = (c.c_void_p, c.POINTER(self.api.GUID), c.POINTER(c.c_void_p))
            self.runtime.RoGetActivationFactory.restype = c.c_long
            name = c.c_void_p(); text = 'Windows.UI.Shell.TaskbarManager'
            self.api.check(self.runtime.WindowsCreateString(text, len(text), c.byref(name)))
            try:
                # Marker and ABI are published in Microsoft's Windows SDK/windows-rs.
                for iid in ('CDFEFD63-E879-4134-B9A7-8283F05F9480', 'DB32AB74-DE52-4FE6-B7B6-95FF9F8395DF'):
                    guid = self.api.guid(iid); factory = c.c_void_p()
                    self.api.check(self.runtime.RoGetActivationFactory(name, c.byref(guid), c.byref(factory)))
                    self._references.append(factory)
            finally:
                self.runtime.WindowsDeleteString(name)
            manager = c.c_void_p()
            self.api.invoke(factory, 6, (c.POINTER(c.c_void_p),), c.byref(manager))
            self._references.append(manager)
            allowed = c.c_ubyte()
            self.api.invoke(manager, 7, (c.POINTER(c.c_ubyte),), c.byref(allowed))
            if not allowed.value:
                raise RuntimeError('Windows nie zezwala teraz na przypięcie. Aplikacja potrzebuje skrótu w menu Start i aktywnego okna.')
            self._operation = c.c_void_p()
            self.api.invoke(manager, 10, (c.POINTER(c.c_void_p),), c.byref(self._operation))
            self._references.append(self._operation)
            self._info = self.api.query(self._operation, '00000036-0000-0000-C000-000000000046')
            self._references.append(self._info)
        except Exception:
            self.close()
            raise

    def poll(self):
        if self._closed: raise RuntimeError('Prośba o przypięcie została zamknięta.')
        if self._completed: return self._result
        c = self.api.c; status = c.c_int()
        try:
            self.api.invoke(self._info, 7, (c.POINTER(c.c_int),), c.byref(status))
            if status.value == 0: return None
            if status.value == 1:
                value = c.c_ubyte()
                self.api.invoke(self._operation, 8, (c.POINTER(c.c_ubyte),), c.byref(value))
                self._result = bool(value.value)
            elif status.value != 2:
                error = c.c_long()
                self.api.invoke(self._info, 8, (c.POINTER(c.c_long),), c.byref(error))
                self.api.check(error.value)
                raise RuntimeError('Windows nie potwierdził przypięcia aplikacji.')
            self._completed = True
            return self._result
        except OSError as error:
            raise RuntimeError('Windows nie potwierdził przypięcia aplikacji: ' + str(error)) from None

    def close(self):
        if self._closed: return
        self._closed = True
        if self._info:
            with contextlib.suppress(OSError):
                if not self._completed: self.api.invoke(self._info, 9)
                self.api.invoke(self._info, 10)
        for pointer in reversed(self._references):
            with contextlib.suppress(OSError): self.api.release(pointer)
        self._references.clear()
        if self._ro_initialized:
            self.runtime.RoUninitialize(); self._ro_initialized = False
        self.api.close()


def _start_taskbar_pin_request():
    """Call only after a foreground user click, never from bootstrap or an installer."""
    if os.name != 'nt': raise RuntimeError('Przypinanie do paska zadań jest dostępne w Windows.')
    try:
        return _WindowsTaskbarPinRequest()
    except (OSError, AttributeError) as error:
        raise RuntimeError('Ta instalacja Windows nie udostępnia prośby o przypięcie aplikacji. ' + str(error)) from None


def _write_locked_requirements(path: Path, dependencies: dict[str, str]) -> None:
    """One source file contains the complete, hash-verified release lock."""
    lines = []
    for name, version in sorted(dependencies.items()):
        hashes = _LOCKED_WHEELS.get(name, ())
        if not hashes:
            raise RuntimeError(f"Brak sum kontrolnych zależności {name}.")
        lines.append(f"{name}=={version} " + " ".join("--hash=sha256:" + item for item in hashes))
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


def _download_verified(url: str, target: Path, expected_sha256: str) -> None:
    import hashlib
    import tempfile
    import urllib.request
    target.parent.mkdir(parents=True, exist_ok=True)
    temporary = None
    try:
        _bootstrap_check_cancelled()
        request = urllib.request.Request(url, headers={"User-Agent": f"Gitline/{APP_VERSION}"})
        with urllib.request.urlopen(request, timeout=60) as response:
            _bootstrap_check_cancelled()
            if not response.url.startswith("https://"):
                raise RuntimeError("Serwer pobierania nie używa HTTPS.")
            try:
                expected_size = int(response.headers.get('Content-Length', ''))
                if not 0 < expected_size <= 256 * 1024 * 1024: expected_size = None
            except (TypeError, ValueError):
                expected_size = None
            _bootstrap_progress('Pobieranie Gita', target.name, current=0, total=expected_size)
            with tempfile.NamedTemporaryFile(dir=target.parent, suffix=".download", delete=False) as output:
                temporary = Path(output.name)
                digest = hashlib.sha256()
                total = 0; updated = time.monotonic()
                while chunk := response.read(1024 * 1024):
                    _bootstrap_check_cancelled()
                    total += len(chunk)
                    if total > 256 * 1024 * 1024:
                        raise RuntimeError("Pobrany pakiet przekracza oczekiwany rozmiar.")
                    digest.update(chunk)
                    output.write(chunk)
                    if expected_size is not None and total > expected_size: expected_size = None
                    if time.monotonic() - updated >= 0.1:
                        _bootstrap_progress('Pobieranie Gita', target.name, current=total, total=expected_size)
                        updated = time.monotonic()
        _bootstrap_check_cancelled()
        if expected_size is not None and total != expected_size: expected_size = None
        _bootstrap_progress('Sprawdzanie pobranego Gita', target.name, current=total, total=expected_size)
        if digest.hexdigest() != expected_sha256:
            raise RuntimeError("Suma kontrolna pobranego Gita jest nieprawidłowa. Uruchom aplikację ponownie.")
        temporary.replace(target)
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


def _extract_git(archive: Path, target: Path) -> None:
    import stat
    import zipfile
    target.mkdir(parents=True, exist_ok=True)
    root = target.resolve()
    with zipfile.ZipFile(archive) as bundle:
        for member in bundle.infolist():
            path = (root / member.filename).resolve()
            if not path.is_relative_to(root) or stat.S_ISLNK(member.external_attr >> 16):
                raise RuntimeError("Pakiet Gita zawiera nieprawidłową ścieżkę.")
        bundle.extractall(root)
    if not (root / "cmd" / "git.exe").is_file():
        raise RuntimeError("Pakiet Gita jest niekompletny.")


def _bootstrap_git() -> None:
    """Install a private Git on Windows x64, never change PATH or system Git."""
    if os.name != "nt":
        return
    import glob
    import shutil
    local = os.environ.get("LOCALAPPDATA", "")
    candidates = [shutil.which("git"), str(APP_DATA / "git" / "cmd" / "git.exe")]
    if local:
        candidates += glob.glob(str(Path(local) / "GitHubDesktop" / "app-*" / "resources" / "app" / "git" / "cmd" / "git.exe"))
        candidates.append(str(Path(local) / "Programs" / "Git" / "cmd" / "git.exe"))
    for variable in ("ProgramFiles", "ProgramW6432", "ProgramFiles(x86)"):
        if os.environ.get(variable):
            candidates.append(str(Path(os.environ[variable]) / "Git" / "cmd" / "git.exe"))
    if any(candidate and Path(candidate).is_file() for candidate in candidates):
        return
    if platform.machine().lower() not in ("amd64", "x86_64"):
        raise RuntimeError("Na tej architekturze zainstaluj Git, a następnie uruchom plik ponownie.")
    _bootstrap_notice(f"{APP_NAME}: przygotowuję prywatnego Gita. Nie zmieniam ustawień systemu…")
    archive = APP_DATA / f"MinGit-{_GIT_RELEASE}.zip"
    _download_verified(_GIT_DOWNLOAD, archive, _GIT_SHA256)
    import tempfile
    staged = Path(tempfile.mkdtemp(prefix="git-install-", dir=APP_DATA))
    try:
        _extract_git(archive, staged)
        target = APP_DATA / "git"
        if target.exists():
            target.rename(APP_DATA / f"git-incomplete-{time.time_ns()}")
        staged.rename(target)
    finally:
        archive.unlink(missing_ok=True)


def _bootstrap_redactor(command, environment):
    import re
    from urllib.parse import quote, unquote, urlsplit, urlunsplit
    secrets = set()
    urls = re.compile(r'https?://[^\s\'"<>]+')
    for argument in [*command, *(environment.get(name, '') for name in
                      ('GITLINE_PIP_INDEX', 'PIP_INDEX_URL', 'PIP_EXTRA_INDEX_URL'))]:
        for match in urls.finditer(argument):
            try: url = urlsplit(match.group())
            except ValueError: continue
            if url.password:
                password = unquote(url.password)
                secrets.update((url.netloc.rsplit('@', 1)[0], url.password, password, quote(password, safe='')))
    secrets = sorted(filter(None, secrets), key=len, reverse=True)

    def redact(value: str | bytes, partial=False) -> str:
        if isinstance(value, bytes):
            value = value.decode('utf-8', errors='replace')
        for secret in secrets:
            value = value.replace(secret, '***')
        if partial:
            # A timed-out child may end in the middle of a known password.
            for secret in secrets:
                for size in range(min(len(value), len(secret) - 1), 0, -1):
                    if value.endswith(secret[:size]):
                        value = value[:-size] + '***'; break
        def clean_url(match):
            text = match.group()
            try:
                url = urlsplit(text)
                netloc = ('***@' + url.netloc.rsplit('@', 1)[1]) if '@' in url.netloc else url.netloc
                return urlunsplit(url._replace(netloc=netloc, query='***' if url.query else '', fragment=''))
            except ValueError:
                return re.sub(r'^(https?://)[^/]*@', r'\1***@', text).split('?', 1)[0]
        value = urls.sub(clean_url, value)
        return value
    return redact


class _BootstrapOutputStream:
    """Redact complete installer lines before logging or emitting UI progress."""
    def __init__(self, log, redact, progress):
        import codecs
        import re
        self.log, self.redact, self.progress = log, redact, progress
        self.decoder = codecs.getincrementaldecoder('utf-8')('replace')
        self.separators = re.compile(r'([\r\n])')
        self.pending, self.tail, self.package = '', '', ''
        self.discarding = False

    def _line(self, value, partial=False):
        import re
        line = self.redact(value, partial=partial)
        self.log.write(line + '\n'); self.log.flush()
        self.tail = (self.tail + line + '\n')[-16000:]
        clean = re.sub(r'\x1b\[[0-?]*[ -/]*[@-~]', '', line).strip()
        collecting = re.match(r'^Collecting\s+([A-Za-z0-9][A-Za-z0-9_.-]*(?:==[A-Za-z0-9_.+-]+)?)(?=\s|$|\[)', clean)
        if collecting:
            self.package = collecting[1][:180]
            self.progress('Przygotowanie pakietów', self.package)
        elif clean.startswith(('Downloading ', 'Using cached ')):
            prefix = 'Downloading ' if clean.startswith('Downloading ') else 'Using cached '
            candidate = clean[len(prefix):].split(' ', 1)[0]
            detail = self.package
            if re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.+-]{0,200}\.(?:whl|zip|gz)', candidate):
                detail = candidate
            size = re.search(r'\((\d+(?:\.\d+)?\s*(?:bytes|kB|MB|GB))\)', clean)
            if size: detail += (' · ' if detail else '') + size[1]
            self.progress('Pobieranie pakietu' if prefix == 'Downloading ' else 'Pakiet z pamięci podręcznej', detail)
        elif clean.startswith(('Installing collected packages:', 'Successfully installed ')):
            installing = clean.startswith('Installing collected packages:')
            source = clean.split(':', 1)[1] if installing else clean[len('Successfully installed '):]
            packages = [item for item in re.split(r'[,\s]+', source.strip())
                        if re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.+-]{0,180}', item)]
            self.progress('Instalowanie pakietów' if installing else 'Pakiety zainstalowane', ', '.join(packages)[:300])

    def feed(self, chunk, *, final=False):
        for piece in self.separators.split(self.decoder.decode(chunk, final=final)):
            if piece in ('\r', '\n'):
                if self.discarding:
                    self._line('[Pominięto zbyt długi wiersz instalatora.]')
                elif self.pending:
                    self._line(self.pending)
                self.pending, self.discarding = '', False
            elif not self.discarding:
                self.pending += piece
                if len(self.pending) > 64 * 1024:
                    # Never split a huge line across secret-redaction boundaries.
                    self.pending, self.discarding = '', True
        if final:
            if self.discarding:
                self._line('[Pominięto zbyt długi wiersz instalatora.]')
            elif self.pending:
                self._line(self.pending, partial=True)
            self.pending, self.discarding = '', False


class _BootstrapPipeReader:
    """Poll installer output in memory without a blocking reader thread."""
    def __init__(self, pipe):
        self.descriptor = pipe.fileno()
        if os.name == 'nt':
            import ctypes
            from ctypes import wintypes
            import msvcrt
            self.ctypes, self.dword = ctypes, wintypes.DWORD
            self.handle = wintypes.HANDLE(msvcrt.get_osfhandle(self.descriptor))
            self.peek = ctypes.WinDLL('kernel32', use_last_error=True).PeekNamedPipe
            self.peek.argtypes = [wintypes.HANDLE, wintypes.LPVOID, wintypes.DWORD,
                                 ctypes.POINTER(wintypes.DWORD), ctypes.POINTER(wintypes.DWORD),
                                 ctypes.POINTER(wintypes.DWORD)]
            self.peek.restype = wintypes.BOOL
        else:
            os.set_blocking(self.descriptor, False)

    def read(self, maximum=64 * 1024):
        if os.name == 'nt':
            available = self.dword()
            if not self.peek(self.handle, None, 0, None, self.ctypes.byref(available), None):
                error = self.ctypes.get_last_error()
                if error in (109, 232): return b''  # A closed writer or pipe.
                raise self.ctypes.WinError(error)
            if not available.value: return b''
            maximum = min(maximum, available.value)
        try:
            return os.read(self.descriptor, maximum)
        except BlockingIOError:
            return b''


class _BootstrapCleanupError(RuntimeError):
    retryable = False


def _terminate_bootstrap_process(process):
    """Stop only this launch's installer tree, including a venv redirector."""
    if process.poll() is not None: return
    if os.name != 'nt':
        process.kill(); process.wait(); return
    taskkill = Path(os.environ.get('SystemRoot', 'C:/Windows')) / 'System32' / 'taskkill.exe'
    try:
        result = subprocess.run([str(taskkill), '/PID', str(process.pid), '/T', '/F'],
                                stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                                stderr=subprocess.DEVNULL, creationflags=_NO_WINDOW,
                                timeout=15, env=_bootstrap_env())
        if result.returncode and process.poll() is None:
            raise _BootstrapCleanupError('Nie potwierdzono zakończenia drzewa instalatora. Nie ponawiaj przygotowania środowiska, dopóki instalator nie zakończy pracy.')
        process.wait(timeout=5)
    except (OSError, subprocess.TimeoutExpired):
        raise _BootstrapCleanupError('System nie potwierdził zakończenia instalatora. Poczekaj na jego zakończenie przed ponownym przygotowaniem środowiska.') from None


def _bootstrap_run(command: list[str], timeout: int = 600, *, env: dict[str, str] | None = None) -> None:
    environment = dict(env if env is not None else _bootstrap_env())
    environment.update(PYTHONUNBUFFERED='1', PYTHONIOENCODING='utf-8')
    redact = _bootstrap_redactor(command, environment)

    with _BOOTSTRAP_LOG.open("a", encoding="utf-8") as log:
        log.write(f"\n[{time.strftime('%Y-%m-%d %H:%M:%S')}] " + repr([redact(arg) for arg in command]) + "\n")
        log.flush()
        stream = _BootstrapOutputStream(log, redact, _bootstrap_progress)
        try:
            _bootstrap_check_cancelled()
            process = subprocess.Popen(command, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                                       stderr=subprocess.STDOUT, env=environment,
                                       creationflags=_NO_WINDOW, bufsize=0)
            reader = None; deadline = time.monotonic() + timeout
            try:
                reader = _BootstrapPipeReader(process.stdout)
                while True:
                    _bootstrap_check_cancelled()
                    chunk = reader.read()
                    if chunk: stream.feed(chunk)
                    code = process.poll()
                    if code is not None and not chunk: break
                    if time.monotonic() >= deadline:
                        raise subprocess.TimeoutExpired(command, timeout)
                    if not chunk: time.sleep(0.05)
            finally:
                try:
                    if process.poll() is None: _terminate_bootstrap_process(process)
                    process.wait()
                    # Bound the final drain even if another child inherited the
                    # writer. Raw output never reaches a temporary/log file.
                    remaining = 1024 * 1024
                    while reader is not None and remaining > 0:
                        chunk = reader.read(min(64 * 1024, remaining))
                        if not chunk: break
                        stream.feed(chunk); remaining -= len(chunk)
                    stream.feed(b'', final=True)
                finally:
                    process.stdout.close()
        except subprocess.TimeoutExpired:
            raise RuntimeError(f"Przygotowanie środowiska przekroczyło limit {timeout} sekund.") from None
        except OSError as exc:
            raise RuntimeError(redact(str(exc))) from None
    if code:
        raise RuntimeError(f"Przygotowanie środowiska nie powiodło się (kod {code}). Sprawdź połączenie z internetem i uruchom plik ponownie.")


def _bootstrap_probe(python: Path, *, own_runtime=True) -> bool:
    if not python.is_file():
        return False
    code = (
        "import importlib.metadata as m; "
        f"deps={_DEPENDENCIES!r}; "
        "assert all(m.version(k)==v for k,v in deps.items()); "
        "from PySide6 import QtCore, QtGui, QtWidgets; import keyring"
    )
    if own_runtime:
        code += ("; import sys; from pathlib import Path; assert sys.prefix != sys.base_prefix; "
                 f"assert Path(sys.prefix).resolve() == Path({str(_RUNTIME_DIR)!r}).resolve()")
    try:
        result = subprocess.run(
            [str(python), "-I", "-c", code], stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL, stderr=subprocess.PIPE,
            creationflags=_NO_WINDOW, env=_bootstrap_env(), timeout=45,
        )
        if result.returncode and result.stderr:
            with _BOOTSTRAP_LOG.open("a", encoding="utf-8") as log:
                log.write(result.stderr.decode("utf-8", errors="replace") + "\n")
        return result.returncode == 0
    except (OSError, subprocess.TimeoutExpired):
        return False


_STARTUP_SPLASH_TYPE = None


def _startup_splash_type():
    """Load the startup-only Qt surface lazily, after the private runtime is ready."""
    global _STARTUP_SPLASH_TYPE
    if _STARTUP_SPLASH_TYPE is not None:
        return _STARTUP_SPLASH_TYPE
    import math
    from PySide6.QtCore import Qt, QTimer, Signal, QPointF, QRectF
    from PySide6.QtGui import (QColor, QFont, QLinearGradient, QPainter, QPainterPath,
                              QPen, QPolygonF, QRadialGradient)
    from PySide6.QtWidgets import QApplication, QWidget

    class StartupSplash(QWidget):
        """Small software-rendered 3D logo, independent of catalog/network readiness."""
        logo_ready = Signal()
        closed = Signal()
        _INTRO_SECONDS = 1.62
        _SPIN_RAMP_SECONDS = 0.18
        _SPIN_PERIOD_SECONDS = 1.4
        _FADE_SECONDS = 0.18

        def __init__(self):
            from PySide6.QtGui import QCursor
            super().__init__(None, Qt.WindowType.SplashScreen | Qt.WindowType.FramelessWindowHint |
                             Qt.WindowType.WindowStaysOnTopHint)
            self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
            self.setAttribute(Qt.WidgetAttribute.WA_QuitOnClose, False)
            self.setWindowTitle(f'{APP_NAME} · Uruchamianie')
            self.setAccessibleName(f'{APP_NAME} — uruchamianie aplikacji')
            self.setFixedSize(400, 350)
            self.setStyleSheet('background: transparent;')
            screen = QApplication.screenAt(QCursor.pos()) or QApplication.primaryScreen()
            if screen is not None:
                self.move(screen.availableGeometry().center() - self.rect().center())
            # Separate solid links let the leading edge pass through a real opening.
            # Both meshes and their beveled cross sections live in this source file.
            self._links = (self._link_mesh(opened=True), self._link_mesh(opened=False))
            self.started_at = time.monotonic()
            self.angle = -0.22
            self.frame_count = 0
            self._animation_elapsed = 0.0
            self._last_tick_at = self.started_at
            self._logo_painted = False
            self._minimum_display_seconds = 2.0
            self._reveal = 0.0
            self._travel, self._thread_tilt = self._assembly_pose(0.0)
            self._slot_turn, self._lock_seat = self._locking_pose(0.0)
            self._opacity = 1.0
            self._handoff_at = None
            self._finish_window = None
            self._timer = QTimer(self)
            self._timer.setTimerType(Qt.TimerType.PreciseTimer)
            self._timer.setInterval(16)
            self._timer.timeout.connect(self._advance)

        def showEvent(self, event):
            self._last_tick_at = time.monotonic()
            self._timer.start()
            super().showEvent(event)

        def prepare(self):
            """Paint an actual 3D frame before synchronous widget construction."""
            from PySide6.QtCore import QEventLoop
            self.show()
            self.raise_()
            self.activateWindow()
            if self._logo_painted: return
            loop = QEventLoop()
            self.logo_ready.connect(loop.quit); self.closed.connect(loop.quit)
            guard = QTimer(); guard.setSingleShot(True)
            guard.timeout.connect(loop.quit); guard.start(1000)
            try:
                loop.exec()
            finally:
                guard.stop()
                self.logo_ready.disconnect(loop.quit); self.closed.disconnect(loop.quit)

        def pulse(self):
            """Paint between setup stages without dispatching half-built UI callbacks."""
            if self.isVisible():
                self._advance()
                self.repaint()

        def _advance(self):
            if not self.isVisible(): return
            now = time.monotonic()
            # A blocked Qt thread must not skip the assembly when it wakes up.
            # Bound each visual step; completed startup can then finish the same 3D intro.
            self._animation_elapsed += min(0.05, max(0.0, now - self._last_tick_at))
            self._last_tick_at = now
            elapsed = self._animation_elapsed
            progress = min(1.0, elapsed / 0.12)
            self._reveal = progress * progress * (3 - 2 * progress)
            self._travel, self._thread_tilt = self._assembly_pose(elapsed)
            self._slot_turn, self._lock_seat = self._locking_pose(elapsed)
            # Integrate a smooth acceleration: no rotation during the reveal and
            # no jump in angular velocity when the spin begins or reaches full speed.
            spin_elapsed = max(0.0, elapsed - self._INTRO_SECONDS)
            ramp = min(1.0, spin_elapsed / self._SPIN_RAMP_SECONDS)
            spin = self._SPIN_RAMP_SECONDS * (ramp ** 3 - 0.5 * ramp ** 4)
            spin += max(0.0, spin_elapsed - self._SPIN_RAMP_SECONDS)
            self.angle = -0.22 + spin * math.tau / self._SPIN_PERIOD_SECONDS
            self._opacity = 1.0
            if (self._finish_window is not None and self._handoff_at is None
                    and getattr(self._finish_window, '_startup_ready', True)
                    and elapsed >= self._minimum_display_seconds - self._FADE_SECONDS):
                self._handoff_at = elapsed + self._FADE_SECONDS
            if self._handoff_at is not None:
                remaining = max(0.0, min(1.0, (self._handoff_at - elapsed) / self._FADE_SECONDS))
                self._opacity = remaining * remaining * (3 - 2 * remaining)
                if elapsed >= self._handoff_at:
                    self._handoff()
                    return
            self.update()

        def finish(self, window, minimum_ms=2000):
            """Finish the visible introduction once the local initial view is ready."""
            self._finish_window = window
            self._minimum_display_seconds = max(minimum_ms / 1000, self._INTRO_SECONDS + self._SPIN_RAMP_SECONDS + self._FADE_SECONDS)
            if not self.isVisible():
                self._handoff()
                return
            self._advance()

        @staticmethod
        def _show_window(window):
            window.hide()
            window.setAttribute(Qt.WidgetAttribute.WA_DontShowOnScreen, False)
            window.show()

        def _handoff(self):
            window, self._finish_window = self._finish_window, None
            if window is not None:
                self._show_window(window)
                window.raise_()
                window.activateWindow()
            self.close()

        def closeEvent(self, event):
            self._timer.stop()
            # Alt+F4 during the introduction must not strand an already-created window.
            window, self._finish_window = self._finish_window, None
            if window is not None:
                self._show_window(window)
            self.closed.emit()
            super().closeEvent(event)

        @staticmethod
        def _assembly_pose(elapsed):
            def ease(start, duration):
                value = max(0.0, min(1.0, (elapsed - start) / duration))
                return value * value * (3 - 2 * value)

            # Keep the inserted link edge-on while its partner rotates the slot away.
            # Only after that lock completes does the closed link settle into its tilt.
            travel = 62.0 * (1 - ease(0.10, 0.60))
            tilt = math.pi / 2 - math.radians(25) * ease(1.30, 0.28)
            return travel, tilt

        @staticmethod
        def _locking_pose(elapsed):
            def ease(start, duration):
                value = max(0.0, min(1.0, (elapsed - start) / duration))
                return value * value * (3 - 2 * value)
            # Seat the closed link slightly deeper for metal-to-metal clearance.
            # A quarter-turn moves the slot away from the straight withdrawal path.
            seat = 2.0 * ease(0.70, 0.14)
            turn = math.pi / 2 * ease(0.86, 0.40)
            return turn, seat

        @staticmethod
        def _link_mesh(opened):
            """Rounded diamond with a thick, beveled section and solid slot ends."""
            # The bend radius exceeds the band width; otherwise the inner corners
            # fold over themselves. The slot also clears the entire beveled section.
            radius, corner_cut = 39.0, 10.0
            corners = [(0.0, -radius), (radius, 0.0), (0.0, radius), (-radius, 0.0)]
            path = [(18.0 - radius, -18.0)] if opened else [(-corner_cut, corner_cut - radius)]

            def line(end):
                start = path[-1]
                steps = max(1, math.ceil(math.dist(start, end) / 6.5))
                for step in range(1, steps + 1):
                    t = step / steps
                    path.append(tuple(a + (b - a) * t for a, b in zip(start, end)))

            for index, corner in enumerate(corners[:3] if opened else corners):
                previous, following = corners[(index - 1) % 4], corners[(index + 1) % 4]
                entrance = tuple(c + (p - c) * corner_cut / radius for c, p in zip(corner, previous))
                leave = tuple(c + (p - c) * corner_cut / radius for c, p in zip(corner, following))
                if math.dist(path[-1], entrance) > 1e-6:
                    line(entrance)
                for step in range(1, 9):
                    t = step / 8
                    path.append(tuple((1 - t) ** 2 * a + 2 * t * (1 - t) * b + t ** 2 * c
                                      for a, b, c in zip(entrance, corner, leave)))
            line((18.0 - radius, 18.0) if opened else path[0])
            if not opened:
                path.pop()

            # Old extrusion was only 5.6 units deep. Rounded bevels now join a
            # 13.6-unit band to a 12.4-unit depth, so the metal stays substantial edge-on.
            section = ((6.8, 4.2), (4.8, 6.2), (-4.8, 6.2), (-6.8, 4.2),
                       (-6.8, -4.2), (-4.8, -6.2), (4.8, -6.2), (6.8, -4.2))
            vertices, faces = [], []
            for index, point in enumerate(path):
                previous = path[max(0, index - 1)] if opened else path[(index - 1) % len(path)]
                following = path[min(len(path) - 1, index + 1)] if opened else path[(index + 1) % len(path)]
                dx, dy = following[0] - previous[0], following[1] - previous[1]
                length = math.hypot(dx, dy)
                for width, depth in section:
                    vertices.append((point[0] + width * dy / length,
                                     point[1] - width * dx / length, depth))
            for index in range(len(path) - (1 if opened else 0)):
                following = (index + 1) % len(path)
                for edge in range(8):
                    faces.append((index * 8 + edge, following * 8 + edge,
                                  following * 8 + (edge + 1) % 8, index * 8 + (edge + 1) % 8))
            if opened:
                faces.extend((tuple(range(8)), tuple((len(path) - 1) * 8 + edge for edge in reversed(range(8)))))
            return tuple(vertices), tuple(faces)

        def _posed_link(self, index):
            """Pose solid mesh vertices before the shared camera/whole-logo rotation."""
            bank = -0.48 + (self._thread_tilt if index else 0.0)
            cb, sb = math.cos(bank), math.sin(bank)
            turn = self._slot_turn if not index else 0.0
            ct, st = math.cos(turn), math.sin(turn)
            offset = -22.0 - self._travel + self._lock_seat if index else 22.0
            vertices = []
            for x, y, z in self._links[index][0]:
                x, y = ct * x - st * y, st * x + ct * y
                vertices.append((x + offset, cb * y - sb * z, sb * y + cb * z))
            return tuple(vertices)

        def _paint_links(self, painter):
            from PySide6.QtGui import QPolygonF
            cy, sy = math.cos(self.angle), math.sin(self.angle)
            axis = math.radians(18)
            ca, sa = math.cos(axis), math.sin(axis)
            tilt = -0.04 + 0.05 * math.sin(self.angle * 0.6)
            cx, sx = math.cos(tilt), math.sin(tilt)
            center_y = 140 + 2 * math.sin(self.angle * 0.8)
            faces = []
            for index, (unused_mesh, polygons) in enumerate(self._links):
                vertices = []
                for x, y, z in self._posed_link(index):
                    x, y = ca * x - sa * y, sa * x + ca * y
                    x, z = cy * x + sy * z, -sy * x + cy * z
                    vertices.append((x, cx * y - sx * z, sx * y + cx * z))
                for polygon in polygons:
                    points = [vertices[index] for index in polygon]
                    a, b, c = points[:3]
                    u, v = [b[i] - a[i] for i in range(3)], [c[i] - a[i] for i in range(3)]
                    normal = (u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0])
                    length = math.sqrt(sum(value * value for value in normal))
                    if length < 1e-6 or sum(normal[i] * ((430 if i == 2 else 0) - a[i]) for i in range(3)) <= 0:
                        continue
                    normal = tuple(value / length for value in normal)
                    diffuse = max(0.0, sum(a * b for a, b in zip(normal, (-0.35, -0.45, 0.82))))
                    specular = max(0.0, sum(a * b for a, b in zip(normal, (-0.18, -0.24, 0.954)))) ** 28
                    # Broad gold reflections and bright bevels reveal volume without
                    # a texture, graphics driver dependency, or opaque crossing masks.
                    sheen = 0.035 * math.sin((a[0] - a[1]) * 0.055)
                    color = QColor.fromRgbF(*(min(1.0, max(0.0, base + light * diffuse + shine * specular + sheen))
                                              for base, light, shine in ((0.50, 0.37, 0.30),
                                                                        (0.32, 0.37, 0.32), (0.12, 0.25, 0.34))))
                    projected = QPolygonF([QPointF(200 + x * 430 / (430 - z), center_y + y * 430 / (430 - z))
                                           for x, y, z in points])
                    faces.append((sum(point[2] for point in points) / len(points), projected, color))
            for unused_depth, polygon, color in sorted(faces, key=lambda face: face[0]):
                # Slightly overlap adjacent faces to seal antialiasing seams.
                painter.setPen(QPen(color, 0.85))
                painter.setBrush(color)
                painter.drawPolygon(polygon)

        def paintEvent(self, event):
            from PySide6.QtGui import QRadialGradient
            self.frame_count += 1
            painter = QPainter(self)
            painter.setRenderHints(QPainter.RenderHint.Antialiasing | QPainter.RenderHint.SmoothPixmapTransform)
            painter.setOpacity(self._opacity)
            painter.setPen(Qt.PenStyle.NoPen)
            for step in range(5, 0, -1):
                painter.setBrush(QColor(5, 6, 12, 9))
                painter.drawRoundedRect(QRectF(34 - step * 2, 19 - step, 332 + step * 4, 306 + step * 3), 35, 35)
            card = QLinearGradient(200, 16, 200, 322)
            card.setColorAt(0, QColor(28, 27, 25, 247))
            card.setColorAt(1, QColor(14, 16, 19, 247))
            painter.setBrush(card)
            painter.setPen(QPen(QColor(214, 184, 123, 48), 1))
            painter.drawRoundedRect(QRectF(34, 16, 332, 306), 32, 32)
            glow = QRadialGradient(QPointF(200, 139), 137)
            glow.setColorAt(0, QColor(201, 160, 82, round(32 * self._reveal)))
            glow.setColorAt(1, QColor(201, 160, 82, 0))
            painter.save()
            card_clip = QPainterPath()
            card_clip.addRoundedRect(QRectF(34, 16, 332, 306), 32, 32)
            painter.setClipPath(card_clip)
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(glow)
            painter.drawEllipse(QRectF(63, 2, 274, 274))
            painter.restore()
            painter.save()
            painter.setOpacity(self._opacity * self._reveal)
            painter.setPen(Qt.PenStyle.NoPen)
            for step in range(6, 0, -1):
                painter.setBrush(QColor(4, 7, 12, 15))
                painter.drawEllipse(QRectF(200 - 49 - step * 3, 224 - step, 98 + step * 6, 10 + step * 2))

            self._paint_links(painter)
            painter.restore()
            font = QFont(self.font()); font.setPixelSize(28); font.setWeight(QFont.Weight.DemiBold)
            font.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, 2.4)
            painter.setFont(font); painter.setPen(QColor('#f0e4c9'))
            painter.drawText(QRectF(40, 239, 320, 36), Qt.AlignmentFlag.AlignCenter, APP_NAME.upper())
            font.setPixelSize(11); font.setWeight(QFont.Weight.Normal)
            font.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, 0.6)
            painter.setFont(font); painter.setPen(QColor('#a8b2c5'))
            painter.drawText(QRectF(40, 276, 320, 17), Qt.AlignmentFlag.AlignCenter, 'Klient Git')
            font.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, 0)
            painter.setFont(font); painter.setPen(QColor('#8d97aa'))
            painter.drawText(QRectF(40, 298, 320, 17), Qt.AlignmentFlag.AlignCenter, 'Uruchamianie')
            painter.end()
            if not self._logo_painted and self._reveal >= 0.6:
                self._logo_painted = True
                _notify_startup_visible()
                self.logo_ready.emit()

    _STARTUP_SPLASH_TYPE = StartupSplash
    return _STARTUP_SPLASH_TYPE


def _bootstrap_launch_with_handoff(runtime_python):
    """Supervise startup off the Tk thread; the Qt process owns its later lifetime."""
    _bootstrap_check_cancelled()
    handoff = _create_startup_handoff()
    child = None
    try:
        child_python = runtime_python.with_name('pythonw.exe') if os.name == 'nt' else runtime_python
        environment = _bootstrap_env()
        environment.update(GITLINE_STARTUP_EVENT=handoff.name, GITLINE_GUI_DETACHED='1')
        command = [str(child_python), '-I', '-X', 'utf8', str(Path(__file__).resolve()), *sys.argv[1:]]
        _bootstrap_progress(stage='Uruchamianie Gitline', detail='Czekam na pierwszą klatkę złotej animacji…')
        with (APP_DATA / 'application.log').open('a', encoding='utf-8') as log:
            child = subprocess.Popen(command, stdin=subprocess.DEVNULL, stdout=log, stderr=subprocess.STDOUT,
                                     env=environment, creationflags=_NO_WINDOW)
        started, delayed = time.monotonic(), False
        while True:
            if handoff.ready():
                return 'handoff'
            _bootstrap_check_cancelled()
            code = child.poll()
            if code is not None:
                raise RuntimeError(f'Aplikacja zakończyła działanie przed pokazaniem okna (kod {code}).\n'
                                   f'Szczegóły: {APP_DATA / "application.log"}')
            if not delayed and time.monotonic() - started >= 90:
                delayed = True
                _bootstrap_progress(stage='Uruchamianie Gitline',
                    detail='Uruchamianie trwa dłużej. Nadal czekam na okno aplikacji. Możesz zamknąć przygotowanie; aplikacja będzie uruchamiać się dalej.')
            time.sleep(.05)
    except _BootstrapCancelled:
        raise
    except BaseException as error:
        if child is not None:
            error.retryable = False
        raise
    finally:
        handoff.close()


def bootstrap(_source=None, *, _retained=False) -> None:
    """Prepare the private environment, then relaunch this same single file."""
    if "--help" in sys.argv[1:] or "-h" in sys.argv[1:]:
        _bootstrap_notice(
            f"{APP_NAME} {APP_VERSION}\n"
            "Użycie: python gitline.py [folder repozytorium] [opcje]\n\n"
            "  --setup                Wybierz źródło pakietów, skróty i przygotuj środowisko\n"
            "  --self-test            Sprawdź podstawowe operacje w tymczasowym repozytorium\n"
            "  --check                Sprawdź kod i uruchom wszystkie testy regresji\n"
            "  --diagnose             Sprawdź Git, GCM i dostępność magazynu poświadczeń\n"
            "  --smoke-test           Sprawdź uruchomienie interfejsu\n"
            "  --screenshot PLIK      Zapisz zrzut interfejsu i zakończ\n"
            "  --report PLIK          Zapisz raport testów w formacie JSON\n"
            "  -h, --help             Pokaż pomoc bez instalowania zależności\n\n"
            f"Konfiguracja: {_config_path()}\n"
            f"Środowisko tej kopii: {_RUNTIME_DIR}\n"
            f"Dzienniki, prywatny Git i ikony: {APP_DATA}\n"
            "Wymagany Windows, Python 3.10–3.14 (64-bit) i internet przy pierwszym uruchomieniu.\n"
            "Biblioteki i brakujący Git na Windows x64 są przygotowywane automatycznie.\n"
            "Biblioteki: publiczne PyPI lub własne Artifactory — wybór przed instalacją.\n"
            "Okno przygotowania korzysta ze składnika Tcl/Tk dołączonego do Pythona.\n"
            "Każda kopia przygotowuje własne środowisko i ustawienia obok pliku.\n"
            "Do przekazania wystarczy sam gitline.py."
        )
        raise SystemExit(0)

    if sys.platform != 'win32':
        _bootstrap_error(f'Ta wersja {APP_NAME} działa tylko w Windows. Nie przygotowano środowiska.')
        raise SystemExit(1)

    if not (3, 10) <= sys.version_info[:2] < (3, 15):
        _bootstrap_error(f"Ta wersja {APP_NAME} wymaga Pythona 3.10–3.14.")
        raise SystemExit(1)

    if sys.maxsize <= 2**32:
        _bootstrap_error(f"Ta wersja {APP_NAME} wymaga 64-bitowego Pythona.")
        raise SystemExit(1)

    if any(argument in sys.argv[1:] for argument in ('--self-test', '--check', '--smoke-test', '--screenshot')):
        # Developer/test invocations may explicitly use their supplied interpreter;
        # they never install packages or prepare a normal GUI profile.
        if _bootstrap_probe(Path(sys.executable), own_runtime=False):
            return
        _bootstrap_error('Testy wymagają interpretera z zależnościami Gitline. Nie przygotowano środowiska.')
        raise SystemExit(1)

    runtime_python = _RUNTIME_DIR / ("Scripts/python.exe" if os.name == "nt" else "bin/python")
    marker = _RUNTIME_DIR / ".gitline-ready.json"
    expected = {"dependencies": _DEPENDENCIES, "python": list(sys.version_info[:2]), "machine": platform.machine()}
    in_runtime = Path(sys.prefix).resolve() == _RUNTIME_DIR.resolve()
    try:
        APP_DATA.mkdir(parents=True, exist_ok=True)
        if (_RUNTIME_DIR.resolve().parent != _SCRIPT_DIR.resolve()
                or _RUNTIME_DIR.resolve().name != f'.gitline-venv-{sys.version_info.major}.{sys.version_info.minor}'):
            raise RuntimeError('Środowisko musi znajdować się bezpośrednio obok tej kopii gitline.py. Nie użyto innego środowiska.')
        with _bootstrap_lock():
            _bootstrap_check_cancelled()
            _bootstrap_progress(stage='Sprawdzanie środowiska', detail='Sprawdzam interpreter i zainstalowane biblioteki…')
            try:
                ready = json.loads(marker.read_text(encoding="utf-8")) == expected
            except (OSError, ValueError):
                ready = False

            ready = ready and _bootstrap_probe(runtime_python)
            configured = _config_has_section('bootstrap')
            if _source is None and (not ready or not configured or '--setup' in sys.argv[1:]):
                raise _BootstrapNeedsSource()
            source = _source
            if not ready:
                _bootstrap_check_cancelled()
                _bootstrap_notice(f"{APP_NAME}: przygotowuję prywatne środowisko. Pierwszy start może potrwać kilka minut…")
                if not _bootstrap_python_works(runtime_python):
                    base_python = Path(sys.executable)
                    if os.name == "nt" and base_python.name.lower() == "pythonw.exe":
                        base_python = base_python.with_name("python.exe")
                    runtime_target = _RUNTIME_DIR.resolve()
                    if (runtime_target.parent != _SCRIPT_DIR.resolve()
                            or runtime_target.name != f".gitline-venv-{sys.version_info.major}.{sys.version_info.minor}"
                            or in_runtime):
                        raise RuntimeError("Nie można bezpiecznie odbudować środowiska. Uruchom plik z zainstalowanego Pythona.")
                    # Rebuild stale Windows redirectors after Python is moved/reinstalled.
                    # --clear is limited to the validated private runtime directory.
                    _bootstrap_progress(stage='Tworzenie środowiska', detail=str(runtime_target))
                    _bootstrap_run([str(base_python), "-m", "venv", "--clear", str(runtime_target)], timeout=180)
                # A previous process may have been interrupted after creating
                # python.exe but before completing ensurepip.
                _bootstrap_check_cancelled()
                _bootstrap_progress(stage='Przygotowanie instalatora', detail='Sprawdzam pip…')
                pip_check = subprocess.run(
                    [str(runtime_python), "-m", "pip", "--version"],
                    stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL, env=_bootstrap_env(),
                    creationflags=_NO_WINDOW, timeout=45,
                )
                if pip_check.returncode:
                    _bootstrap_run([str(runtime_python), "-m", "ensurepip", "--upgrade"], timeout=180)
                requirements = _RUNTIME_DIR / ".gitline-requirements.txt"
                _write_locked_requirements(requirements, _DEPENDENCIES)
                pip_options, pip_env = _bootstrap_pip(source)
                _bootstrap_check_cancelled()
                _bootstrap_progress(stage='Instalowanie bibliotek', detail='Pobieram i instaluję biblioteki Gitline…')
                _bootstrap_notice(f"{APP_NAME}: instaluję biblioteki z {source['index_url']}…")
                # runpy uses pip's normal module entry point; credentials travel only
                # in the child's environment, never in OS process arguments or files.
                pip_launcher = ("import os,runpy,sys; sys.argv=['pip','--isolated','install',"
                                "'--index-url',os.environ.pop('GITLINE_PIP_INDEX'),*sys.argv[1:]]; "
                                "runpy.run_module('pip',run_name='__main__')")
                try:
                    _bootstrap_run([
                        str(runtime_python), '-I', '-u', '-X', 'utf8', '-c', pip_launcher, *pip_options,
                        "--disable-pip-version-check", "--no-input", "--only-binary=:all:",
                        "--require-hashes", "--force-reinstall", "--requirement", str(requirements),
                    ], env=pip_env)
                finally:
                    pip_env.pop("GITLINE_PIP_INDEX", None)
                    source["password"] = ""
                _bootstrap_check_cancelled()
                _bootstrap_progress(stage='Sprawdzanie bibliotek', detail='Sprawdzam gotowe środowisko Qt…')
                if not _bootstrap_probe(runtime_python):
                    # Remove the marker so a partial installation is always retried.
                    marker.unlink(missing_ok=True)
                    raise RuntimeError("Biblioteki interfejsu nie mogą się uruchomić. Szczegóły zapisano w dzienniku instalacji.")
                staged_marker = marker.with_suffix(".tmp")
                staged_marker.write_text(json.dumps(expected, indent=2), encoding="utf-8")
                staged_marker.replace(marker)
                _bootstrap_notice(f"{APP_NAME}: środowisko jest gotowe.")

            _bootstrap_check_cancelled()
            _bootstrap_progress(stage='Przygotowanie Git', detail='Sprawdzam dostępność narzędzi Git…')
            _bootstrap_git()
            if source is not None and 'shortcuts' in source:
                _bootstrap_check_cancelled()
                _bootstrap_progress(stage='Przygotowanie skrótów', detail='Tworzę wybrane skróty w Windows…')
                choices = _bootstrap_shortcut_choices(source['shortcuts'])
                integration = _install_windows_shortcuts(runtime_python, choices)
                with _config_lock():
                    saved = _config_section('bootstrap', {})
                    saved = dict(saved) if isinstance(saved, dict) else {}
                    saved['taskbar_pending'] = os.name == 'nt' and choices['taskbar']
                    saved['shortcut_results'] = integration
                    _set_config_section('bootstrap', saved)
                if integration['errors']:
                    notice = 'Gitline jest gotowy, ale nie wszystkie skróty zostały utworzone:\n' + '\n'.join(integration['errors'])
                    _bootstrap_notice(notice)
                    if _GUI_HIDDEN_MODE and not _retained: _show_bootstrap_message(notice)

        if "--setup" in sys.argv[1:]:
            _bootstrap_notice(f"Gotowe. Interpreter: {runtime_python}")
            if _retained: return 'complete'
            raise SystemExit(0)
        if _retained:
            return _bootstrap_launch_with_handoff(runtime_python)
        if in_runtime and sys.flags.isolated:
            return
        child_python = runtime_python
        if os.name == "nt" and (_GUI_HIDDEN_MODE or Path(sys.executable).name.lower() == "pythonw.exe"):
            child_python = runtime_python.with_name("pythonw.exe")
        child_env = _bootstrap_env()
        if _GUI_HIDDEN_MODE:
            child_env['GITLINE_GUI_DETACHED'] = '1'
        else:
            child_env.pop('GITLINE_GUI_DETACHED', None)
        command = [str(child_python), '-I', '-X', 'utf8', str(Path(__file__).resolve()), *sys.argv[1:]]
        if _GUI_HIDDEN_MODE:
            result = subprocess.run(command, stdin=subprocess.DEVNULL, stdout=sys.stdout, stderr=sys.stderr,
                                    env=child_env, creationflags=_NO_WINDOW)
            if result.returncode:
                _bootstrap_error(f"Aplikacja zakończyła działanie z kodem {result.returncode}.\nSzczegóły: {APP_DATA / 'application.log'}")
        elif sys.stdout is None or sys.stderr is None:
            with (APP_DATA / "application.log").open("a", encoding="utf-8") as log:
                result = subprocess.run(command, stdin=subprocess.DEVNULL, stdout=log,
                                        stderr=log, env=child_env, creationflags=_NO_WINDOW)
            if result.returncode:
                _bootstrap_error(f"Aplikacja zakończyła działanie z kodem {result.returncode}.\nSzczegóły: {APP_DATA / 'application.log'}")
        else:
            result = subprocess.run(command, env=child_env)
        raise SystemExit(result.returncode)
    except _BootstrapNeedsSource:
        # Leaving the context above releases runtime.lock before the Tk dialog
        # starts a worker, and again before that worker starts the Qt child.
        try:
            prepare = None if '--diagnose' in sys.argv[1:] else lambda source: bootstrap(source, _retained=True)
            selected = _choose_bootstrap_source(prepare=prepare)
        except (OSError, RuntimeError) as error:
            _bootstrap_error(str(error))
            raise SystemExit(1) from error
        if isinstance(selected, dict):
            return bootstrap(selected)  # Direct source providers used by isolated checks.
        raise SystemExit(selected)
    except _BootstrapCancelled:
        raise
    except (OSError, RuntimeError, subprocess.SubprocessError) as exc:
        try:
            with _BOOTSTRAP_LOG.open("a", encoding="utf-8") as log:
                traceback.print_exc(file=log)
        except OSError:
            pass
        if _retained:
            raise
        _bootstrap_error(str(exc))
        raise SystemExit(1) from exc
    finally:
        if isinstance(_source, dict):
            _source['password'] = ''

if __name__ == '__main__':
    _prepare_gui_console()
    if not any(argument in sys.argv[1:] for argument in ('--credential-helper', '--auth-lock-test-child')):
        bootstrap()
        try:
            _start_early_gui()
        except Exception as error:
            if _EARLY_GUI_SPLASH is not None:
                _EARLY_GUI_SPLASH.close()
            _bootstrap_error(str(error))
            raise SystemExit(1) from error

# --- Git backend: standard library only ---------------------------------------
import dataclasses
import datetime
import glob
import os
from pathlib import Path
import re
import shutil
import subprocess
import tempfile

_pulse_early_gui()


class GitError(RuntimeError):
    """An actionable Git failure safe to show in the interface."""


_TASK_CANCELLATION = threading.local()


def _task_cancel_event():
    return getattr(_TASK_CANCELLATION, 'event', None)


def _check_task_cancelled():
    event = _task_cancel_event()
    if event is not None and event.is_set():
        raise GitError('Operacja anulowana.')


def _run_cancellable(cancel_event, function):
    """Keep cancellation local to this worker; repository writes opt out."""
    previous = _task_cancel_event()
    _TASK_CANCELLATION.event = cancel_event
    try:
        _check_task_cancelled()
        return function()
    finally:
        _TASK_CANCELLATION.event = previous


def _cancellable_read_process(command, *, output, environment, timeout, flags, data=None):
    """Poll an owned read child without pipe threads, including binary stdin."""
    _check_task_cancelled()
    with contextlib.ExitStack() as captures:
        errors = captures.enter_context(tempfile.TemporaryFile())
        input_ = subprocess.DEVNULL
        if data is not None:
            input_ = captures.enter_context(tempfile.TemporaryFile())
            input_.write(data); input_.seek(0)
        process = subprocess.Popen(command, stdout=output, stderr=errors,
                                   stdin=input_, env=environment,
                                   creationflags=flags, shell=False)
        deadline = time.monotonic() + timeout
        try:
            while process.poll() is None:
                _check_task_cancelled()
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise subprocess.TimeoutExpired(command, timeout)
                try:
                    process.wait(timeout=min(0.1, remaining))
                except subprocess.TimeoutExpired:
                    pass
            _check_task_cancelled()
            errors.seek(max(0, os.fstat(errors.fileno()).st_size - 1024 * 1024))
            return subprocess.CompletedProcess(command, process.returncode, stderr=errors.read())
        finally:
            if process.poll() is None:
                process.kill()
            process.wait()


