    @property
    def conflicted(self):
        return (self.index_status + self.worktree_status) in {
            "DD", "AU", "UD", "UA", "DU", "AA", "UU"
        }

    @property
    def staged(self):
        return self.index_status not in (" ", "?", "!") and not self.conflicted

    @property
    def unstaged(self):
        return self.worktree_status not in (" ", "!") or self.conflicted


