@dataclasses.dataclass(frozen=True)
class GitProgress:
    phase: str
    current: int | None = None
    total: int | None = None
    percent: int | None = None
    endpoint_index: int = 1
    endpoint_total: int = 1
    transferred_bytes: int | None = None
    bytes_per_second: int | None = None


_GIT_PROGRESS_PATTERN = re.compile(
    r'^(?:remote: )?(Enumerating objects|Counting objects|Compressing objects|Writing objects|Receiving objects|Resolving deltas):[ \t]+'
    r'(?:(\d{1,3})% \((\d{1,12})/(\d{1,12})\)|(\d{1,12}))'
    r'(?:, (\d{1,12}(?:\.\d{1,3})?) (B|bytes|KiB|MiB|GiB) \| '
    r'(\d{1,12}(?:\.\d{1,3})?) (B|bytes|KiB|MiB|GiB)/s)?(?:, done\.)?$', re.ASCII
)


def parse_git_progress(line):
    """Accept Git's numeric English counters; never expose a remote/hook line."""
    if not isinstance(line, (str, bytes)) or len(line) > 1024:
        return None
    if isinstance(line, bytes):
        try: line = line.decode('ascii')
        except UnicodeDecodeError: return None
    match = _GIT_PROGRESS_PATTERN.fullmatch(line.strip(' \t\r\n'))
    if not match:
        return None
    label, percent, current, total, count, transferred, transfer_unit, speed, speed_unit = match.groups()
    phases = {'Enumerating objects': 'enumerating', 'Counting objects': 'counting',
              'Compressing objects': 'compressing', 'Writing objects': 'writing',
              'Receiving objects': 'receiving', 'Resolving deltas': 'resolving'}
    if percent is not None:
        current, total, percent = int(current), int(total), int(percent)
        if percent > 100 or total == 0 or current > total:
            return None
    else:
        if label not in ('Enumerating objects', 'Counting objects'):
            return None
        current = int(count)
    if transferred is not None and label not in ('Writing objects', 'Receiving objects'):
        return None
    units = {'B': 1, 'bytes': 1, 'KiB': 1024, 'MiB': 1024 ** 2, 'GiB': 1024 ** 3}
    return GitProgress(phases[label], current, total, percent,
                       transferred_bytes=round(float(transferred) * units[transfer_unit]) if transferred is not None else None,
                       bytes_per_second=round(float(speed) * units[speed_unit]) if speed is not None else None)


def _notify_git_progress(callback, value):
    # A display observer must not interrupt a push that may already be accepted.
    try: callback(value)
    except Exception: pass


class _GitProgressStream:
    def __init__(self, callback):
        self.callback = callback
        self.pending = b''
        self.discarding = False
        self.last = None
        self.queued = {}
        self.last_emitted = 0.0

    def feed(self, chunk):
        pieces = re.split(b'[\r\n]', chunk)
        for index, piece in enumerate(pieces):
            if not self.discarding:
                if len(self.pending) + len(piece) <= 1024:
                    self.pending += piece
                else:
                    self.pending = b''
                    self.discarding = True
            if index < len(pieces) - 1:
                if not self.discarding:
                    self._line(self.pending)
                self.pending = b''
                self.discarding = False
        self.flush()

    def flush(self):
        # Keep only the latest numbers for each known phase, at most 20 UI
        # updates per second while Git runs. The queue has at most eight keys.
        if self.queued and time.monotonic() - self.last_emitted >= 0.05:
            phase = next(iter(self.queued))
            _notify_git_progress(self.callback, self.queued.pop(phase))
            self.last_emitted = time.monotonic()

    def finish(self):
        if not self.discarding and self.pending:
            self._line(self.pending)
        self.pending = b''
        # Drain the bounded final phase updates before the command result.
        for value in self.queued.values():
            _notify_git_progress(self.callback, value)
        self.queued.clear()

    def _line(self, line):
        value = parse_git_progress(line)
        if value is None or value == self.last:
            return
        self.last = value
        self.queued[value.phase] = value
        if value.phase in ('writing', 'resolving') and value.percent == 100:
            self.queued['awaiting_server'] = GitProgress('awaiting_server')


