def _clean_squash_provenance(value, oid_length=None):
    """Validate optional display metadata; it never authorizes a rewrite/push."""
    if (not isinstance(value, dict) or value.get('version') != 1
            or not isinstance(value.get('complete'), bool)
            or not isinstance(value.get('entries'), list) or len(value['entries']) > 2000):
        return None
    entries, seen, count = [], set(), 0
    for entry in value['entries']:
        if not isinstance(entry, dict): return None
        oid, originals = entry.get('oid'), entry.get('original_oids')
        is_squash = entry.get('is_squash', True)
        if (not isinstance(oid, str) or not re.fullmatch(r'[0-9a-f]{40}|[0-9a-f]{64}', oid)
                or not isinstance(is_squash, bool) or oid in seen
                or oid_length is not None and len(oid) != oid_length):
            return None
        seen.add(oid)
        if originals is not None:
            if (not isinstance(originals, list) or not (2 if is_squash else 1) <= len(originals) <= 20000
                    or any(not isinstance(item, str) or len(item) != len(oid)
                           or not re.fullmatch(r'[0-9a-f]+', item) for item in originals)
                    or len(set(originals)) != len(originals)):
                return None
            count += len(originals)
            if count > 20000: return None
        entries.append(dict(oid=oid, original_oids=list(originals) if originals is not None else None,
                            is_squash=is_squash))
    return dict(version=1, complete=value['complete'], entries=entries)


