@dataclasses.dataclass(frozen=True)
class DiffLine:
    kind: str
    old_line: int | None
    new_line: int | None
    text: str


@dataclasses.dataclass(frozen=True)
class DiffDocument:
    lines: tuple
    truncated: bool = False


def parse_diff_document(content):
    """Parse unified hunks without confusing file headers with changed text."""
    lines = []
    old_line = new_line = 0
    old_left = new_left = 0
    in_hunk = False
    document_lines = str(content).split("\n")
    if document_lines and document_lines[-1] == "":
        document_lines.pop()
    for text in document_lines:
        match = re.match(r"^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@(?:.*)$", text)
        if match:
            old_line, new_line = int(match[1]), int(match[3])
            old_left = int(match[2]) if match[2] is not None else 1
            new_left = int(match[4]) if match[4] is not None else 1
            in_hunk = bool(old_left or new_left)
            lines.append(DiffLine("hunk", None, None, text))
            continue
        if text.startswith("\\ No newline at end of file"):
            lines.append(DiffLine("note", None, None, text))
            continue
        if in_hunk and text.startswith("-") and old_left:
            lines.append(DiffLine("delete", old_line, None, text))
            old_line += 1
            old_left -= 1
        elif in_hunk and text.startswith("+") and new_left:
            lines.append(DiffLine("add", None, new_line, text))
            new_line += 1
            new_left -= 1
        elif in_hunk and text.startswith(" ") and old_left and new_left:
            lines.append(DiffLine("context", old_line, new_line, text))
            old_line += 1
            new_line += 1
            old_left -= 1
            new_left -= 1
        else:
            in_hunk = False
            lines.append(DiffLine("meta", None, None, text))
        in_hunk = in_hunk and bool(old_left or new_left)
    return DiffDocument(tuple(lines), bool(getattr(content, "truncated", False)))


def present_diff_document(content):
    """Collapse known patch headers without changing source lines or numbering."""
    document = parse_diff_document(content)
    # Combined hunks have one prefix/line range per parent, not two columns.
    # Preserve their complete representation until the editor supports it.
    if any(line.kind == 'meta' and line.text.startswith(('diff --cc ', 'diff --combined ', '@@@'))
           for line in document.lines):
        return document

    def decode_path(value):
        if not value.startswith('"'):
            return value if '"' not in value else None
        if len(value) < 2 or not value.endswith('"'):
            return None
        raw, index, end = bytearray(), 1, len(value) - 1
        escapes = {'a': 7, 'b': 8, 't': 9, 'n': 10, 'v': 11, 'f': 12, 'r': 13,
                   '\\': 92, '"': 34}
        while index < end:
            char = value[index]
            if char == '"':
                return None
            if char != '\\':
                raw.extend(char.encode('utf-8', 'replace')); index += 1
                continue
            index += 1
            if index >= end:
                return None
            char = value[index]
            if char in escapes:
                raw.append(escapes[char]); index += 1
            elif re.fullmatch(r'[0-7]{3}', value[index:index + 3]) and index + 3 <= end:
                byte = int(value[index:index + 3], 8)
                if byte > 255:
                    return None
                raw.append(byte); index += 3
            else:
                return None
        return raw.decode('utf-8', 'replace') if b'\0' not in raw else None

    def visible_path(value):
        # A filename must not create extra QTextDocument blocks or hidden tabs.
        escapes = {'\n': r'\n', '\r': r'\r', '\t': r'\t'}
        return ''.join(escapes.get(char, f'\\u{ord(char):04x}')
                       if ord(char) < 32 or ord(char) in (127, 0x2028, 0x2029) else char
                       for char in value)

    def header_paths(text):
        value = text.removeprefix('diff --git ')
        if value.startswith('"'):
            index = 1
            while index < len(value):
                if value[index] == '\\':
                    index += 2
                elif value[index] == '"':
                    if value[index + 1:index + 2] != ' ':
                        return None, None
                    pair = value[:index + 1], value[index + 2:]
                    break
                else:
                    index += 1
            else:
                return None, None
        elif ' "' in value:
            pair = value.split(' "', 1)
            pair = pair[0], '"' + pair[1]
        elif value.count(' ') == 1:
            pair = value.split(' ', 1)
        else:
            # Spaces need not be C-quoted. Equal paths have one provable split;
            # ambiguous renamed paths are supplied by rename/from/to headers.
            length = (len(value) - 5) // 2
            path = value[2:2 + length]
            if value != f'a/{path} b/{path}':
                return None, None
            pair = 'a/' + path, 'b/' + path
        old, new = (decode_path(item) for item in pair)
        if old is None or new is None or not old.startswith('a/') or not new.startswith('b/'):
            return None, None
        return old[2:], new[2:]

    def present_file(block):
        boundary = next((index for index, line in enumerate(block[1:], 1) if line.kind != 'meta'), len(block))
        header, body = block[1:boundary], block[boundary:]
        if any(line.text == 'GIT binary patch' for line in header):
            return block
        old, new = header_paths(block[0].text)
        fields, details, retained = {}, [], []
        for line in header:
            text = line.text
            if text.startswith(('--- ', '+++ ')):
                value = decode_path(text[4:].removesuffix('\t'))
                prefix = 'a/' if text.startswith('--- ') else 'b/'
                if value is None or (value != '/dev/null' and not value.startswith(prefix)):
                    return block
                fields['old' if prefix == 'a/' else 'new'] = value if value == '/dev/null' else value[2:]
            elif text.startswith(('rename from ', 'rename to ', 'copy from ', 'copy to ')):
                key, value = None, None
                for prefix in ('rename from ', 'rename to ', 'copy from ', 'copy to '):
                    if text.startswith(prefix):
                        key, value = prefix.strip(), decode_path(text[len(prefix):])
                        break
                if value is None:
                    return block
                fields[key] = value
            elif re.fullmatch(r'index [0-9a-fA-F]+\.\.[0-9a-fA-F]+(?: [0-7]{6})?', text):
                continue
            elif re.fullmatch(r'(old mode|new mode|new file mode|deleted file mode) [0-7]{6}', text):
                key, value = text.rsplit(' ', 1); fields[key] = value
            elif re.fullmatch(r'(dis)?similarity index (100|[0-9]{1,2})%', text):
                details.append(('Zmieniono ' if text.startswith('dissimilarity') else 'Podobieństwo ') + text.rsplit(' ', 1)[1])
            elif text.startswith('Binary files ') and text.endswith(' differ'):
                details.append('Plik binarny')
            else:
                retained.append(line)
        for action, label in (('rename', 'Zmiana nazwy'), ('copy', 'Kopia')):
            source, target = fields.get(action + ' from'), fields.get(action + ' to')
            if (source is None) != (target is None):
                return block
            if source is not None:
                old, new = source, target
                details.insert(0, label)
        old, new = fields.get('old', old), fields.get('new', new)
        if not old or not new:
            return block
        if old == '/dev/null' or 'new file mode' in fields:
            details.insert(0, 'Nowy plik')
        if new == '/dev/null' or 'deleted file mode' in fields:
            details.insert(0, 'Usunięty plik')
        if 'old mode' in fields or 'new mode' in fields:
            if 'old mode' not in fields or 'new mode' not in fields:
                return block
            details.append('Tryb ' + fields['old mode'] + ' → ' + fields['new mode'])
        for key in ('new file mode', 'deleted file mode'):
            if key in fields:
                details.append('Tryb ' + fields[key])
        title = visible_path(old if new == '/dev/null' else new)
        if old != new and '/dev/null' not in (old, new):
            title = visible_path(old) + ' → ' + visible_path(new)
        if details:
            title += ' · ' + ' · '.join(dict.fromkeys(details))
        return [DiffLine('file', None, None, title), *retained, *body]

    output, block = [], []
    for line in document.lines:
        if line.kind == 'meta' and line.text.startswith('diff --git '):
            if block:
                output.extend(present_file(block))
            block = [line]
        elif block:
            block.append(line)
        else:
            output.append(line)
    if block:
        output.extend(present_file(block))
    return DiffDocument(tuple(output), document.truncated)


def _decode_preview(raw, truncated=False, encoding="utf-8", errors="strict"):
    import codecs
    decoder = codecs.getincrementaldecoder(encoding)(errors=errors)
    return decoder.decode(raw, final=not truncated)


@dataclasses.dataclass(frozen=True)
class RevertPlan:
    repo: str
    source_ref: str
    head_oid: str
    commit: CommitDetails
    mainline: int | None = None


@dataclasses.dataclass(frozen=True)
class RevertResult:
    old_head: str
    new_head: str
    commit_oid: str
    conflicted: bool = False
    message: str = ''


@dataclasses.dataclass(frozen=True)
class RepoState:
    path: str
    branch: str
    upstream: str
    ahead: int
    behind: int
    changes: list
    branches: list
    remotes: list
    commits: list
    stash_count: int
    operation: str
    head_ref: str = ""
    head_oid: str = ""


def _git_safe_text(value):
    value = re.sub(r"(?i)(https?://)[^\s/@]+(?::[^\s/@]*)?@", r"\1[credentials]@", str(value))
    value = re.sub(r"(?i)([?&](?:access_token|token|password|key|secret)=)[^\s&#]+", r"\1[redacted]", value)
    value = re.sub(r"\b(?:gh[pousr]_[A-Za-z0-9_]+|github_pat_[A-Za-z0-9_]+)\b", "[redacted]", value)
    return value


def discover_git():
    """Find Git, including the distribution bundled with GitHub Desktop."""
    candidates = []
    if "_PRIVATE_GIT_ROOT" in globals():
        candidates.append(str(_PRIVATE_GIT_ROOT / "cmd" / "git.exe"))
    if "APP_DATA" in globals():
        candidates.append(str(APP_DATA / "git" / "cmd" / "git.exe"))
    on_path = shutil.which("git")
    if on_path:
        candidates.append(on_path)
    local = os.environ.get("LOCALAPPDATA", "")
    if local:
        desktop = glob.glob(os.path.join(local, "GitHubDesktop", "app-*"))
        def version_key(path):
            return tuple(int(n) for n in re.findall(r"\d+", os.path.basename(path)))
        for directory in sorted(desktop, key=version_key, reverse=True):
            candidates.append(os.path.join(directory, "resources", "app", "git", "cmd", "git.exe"))
        candidates.extend([
            os.path.join(local, "Programs", "Git", "cmd", "git.exe"),
            os.path.join(local, "Git", "cmd", "git.exe"),
        ])
    for variable in ("ProgramFiles", "ProgramW6432", "ProgramFiles(x86)"):
        base = os.environ.get(variable)
        if base:
            candidates.append(os.path.join(base, "Git", "cmd", "git.exe"))
    candidates.extend([r"C:\Program Files\Git\cmd\git.exe", "/usr/bin/git", "/usr/local/bin/git", "/opt/homebrew/bin/git"])
    for candidate in candidates:
        if os.path.isfile(candidate):
            return os.path.abspath(candidate)
    raise GitError("Nie znaleziono Gita. Zainstaluj Git ze strony https://git-scm.com/downloads lub GitHub Desktop, a następnie uruchom aplikację ponownie.")


class GitBackend:
    DIFF_LIMIT = 250_000

    def __init__(self, git_exe=None, auth_options=None, environment=None):
        self.git_exe = str(git_exe or discover_git())
        self.auth_options = list(auth_options or [])
        self.environment = dict(environment or {})

    def with_account(self, account_id):
        if account_id is not None and (not isinstance(account_id, str) or any(c in account_id for c in "\0\r\n")):
            raise GitError("Wybierz prawidłowe konto.")
        environment = dict(self.environment)
        environment["GITLINE_ACCOUNT_ID"] = account_id or None
        return type(self)(self.git_exe, self.auth_options, environment)

    def with_native_credentials(self):
        """Remove only Gitline's helper override, preserving the user's Git chain."""
        options, index = [], 0
        while index < len(self.auth_options):
            block = self.auth_options[index:index + 6]
            if (len(block) == 6 and block[:3] == ["-c", "credential.helper=", "-c"]
                    and block[3].startswith("credential.helper=!")
                    and block[3].endswith(" --credential-helper")
                    and block[4:] == ["-c", "credential.useHttpPath=true"]):
                index += 6
                continue
            options.append(self.auth_options[index])
            index += 1
        environment = dict(self.environment)
        environment["GITLINE_ACCOUNT_ID"] = None
        return type(self)(self.git_exe, options, environment)

    def _with_remote(self, remote):
        environment = dict(self.environment)
        environment["GITLINE_REMOTE"] = remote
        return type(self)(self.git_exe, self.auth_options, environment)

    def _execute(self, repo, args, timeout=30, output_limit=None, allowed=(0,), progress=None):
        if not isinstance(args, (list, tuple)) or not all(isinstance(arg, str) for arg in args):
            raise GitError("Argumenty polecenia Git muszą być listą wartości tekstowych.")
        if any("\0" in arg for arg in args):
            raise GitError("Argument polecenia Git zawiera niedozwolony znak pusty (NUL).")
        command = [self.git_exe, "--no-pager", "-c", "color.ui=false", "-c", "core.quotepath=false"]
        # Scope this to commands receiving file arguments. Applying it globally
        # breaks stash's internally generated pathspecs on Git for Windows.
        if args and args[0] in {"diff", "show", "add", "reset", "rm", "ls-files"}:
            command.append("--literal-pathspecs")
        command += list(self.auth_options)
        if os.name == "nt":
            command += ["-c", "core.longpaths=true"]
        if repo is not None:
            command += ["-C", str(repo)]
        command += list(args)
        environment = os.environ.copy()
        # The helper is a fresh process: pass the GUI's actual profile instead
        # of letting it rediscover a different default or inherited directory.
        environment["GITLINE_DATA_DIR"] = str(Path(APP_DATA).resolve())
        environment["GITLINE_CONFIG_FILE"] = str(_config_path())
        for key in ("GITLINE_ACCOUNT_ID", "GITLINE_REPOSITORY", "GITLINE_REMOTE"):
            environment.pop(key, None)
        for key, value in self.environment.items():
            if value is None:
                environment.pop(key, None)
            else:
                environment[key] = str(value)
        if repo is not None:
            environment["GITLINE_REPOSITORY"] = str(Path(repo).resolve())
        environment.update({"GIT_TERMINAL_PROMPT": "0", "GCM_INTERACTIVE": "never", "GIT_OPTIONAL_LOCKS": "0"})
        for key in list(environment):
            if key.startswith(("GIT_TRACE", "GCM_TRACE")) or key == "GIT_CURL_VERBOSE":
                environment.pop(key, None)
        # Do not inherit a parent Git process's repository or index selection.
        for key in ("GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_COMMON_DIR",
                     "GIT_OBJECT_DIRECTORY", "GIT_ALTERNATE_OBJECT_DIRECTORIES", "GIT_NAMESPACE"):
            environment.pop(key, None)
        if progress is not None:
            environment.update(LC_ALL='C', LANG='C', LANGUAGE='C')
        flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
        try:
            # File-backed capture bounds memory even when a tracked file has a huge diff.
            with tempfile.TemporaryFile() as output:
                if progress is None and _task_cancel_event() is not None:
                    result = _cancellable_read_process(command, output=output, environment=environment,
                                                       timeout=timeout, flags=flags)
                elif progress is None:
                    result = subprocess.run(command, stdout=output, stderr=subprocess.PIPE,
                                            stdin=subprocess.DEVNULL, env=environment,
                                            timeout=timeout, creationflags=flags, shell=False)
                else:
                    with tempfile.TemporaryDirectory(prefix='gitline-progress-', ignore_cleanup_errors=True) as capture:
                        error_path = Path(capture) / 'stderr'
                        # A separate reader handle preserves the child's write offset.
                        with error_path.open('w+b') as errors, error_path.open('rb', buffering=0) as reader:
                            process = subprocess.Popen(command, stdout=output, stderr=errors,
                                                       stdin=subprocess.DEVNULL, env=environment,
                                                       creationflags=flags, shell=False)
                            stream = _GitProgressStream(progress)
                            deadline = time.monotonic() + timeout
                            exit_size = None
                            try:
                                while True:
                                    remaining = 64 * 1024 if exit_size is None else min(64 * 1024, max(0, exit_size - reader.tell()))
                                    chunk = reader.read(remaining)
                                    if chunk:
                                        stream.feed(chunk)
                                    else:
                                        stream.flush()
                                    code = process.poll()
                                    if code is not None:
                                        if exit_size is None:
                                            exit_size = os.fstat(reader.fileno()).st_size
                                        if reader.tell() >= exit_size or time.monotonic() >= deadline:
                                            break
                                    if code is None and time.monotonic() >= deadline:
                                        raise subprocess.TimeoutExpired(command, timeout)
                                    if not chunk:
                                        time.sleep(0.05)
                                stream.finish()
                                reader.seek(max(0, os.fstat(reader.fileno()).st_size - 64 * 1024))
                                result = subprocess.CompletedProcess(command, code, stderr=reader.read(64 * 1024))
                            finally:
                                if process.poll() is None:
                                    process.kill()
                                process.wait()
                output.seek(0)
                raw = output.read(output_limit + 1 if output_limit else 1024 * 1024 if progress is not None else -1)
        except subprocess.TimeoutExpired:
            detail = " Serwer mógł już przyjąć commity; sprawdź jego stan przed ponownym wysłaniem." if progress is not None or args and args[0] == "push" else ""
            raise GitError(f"Git nie zakończył operacji w ciągu {timeout} sekund. Przy operacjach zdalnych sprawdź połączenie i logowanie, a następnie odśwież widok przed ponowną próbą." + detail) from None
        except OSError as error:
            raise GitError(_git_safe_text(f"Nie udało się uruchomić Gita: {error}")) from None
        if result.returncode not in allowed:
            message = result.stderr.decode("utf-8", "replace").strip() or raw.decode("utf-8", "replace").strip() or "Git nie mógł zakończyć operacji."
            message = _git_safe_text(message)
            if "Authentication failed" in message or "could not read Username" in message or "terminal prompts disabled" in message:
                message += f"\nPołącz konto w panelu Konta aplikacji {APP_NAME} i spróbuj ponownie."
            elif "Permission denied (publickey)" in message:
                message += "\nSprawdź, czy klucz SSH jest załadowany i zapewnia dostęp do tego repozytorium."
            elif "index.lock" in message:
                message += "\nPoczekaj na zakończenie innych operacji Git, a następnie odśwież widok."
            elif "unable to auto-detect email" in message or "Author identity unknown" in message:
                message += "\nUstaw nazwę autora i adres e-mail w ustawieniach autora tego repozytorium."
            raise GitError(message[:6000])
        truncated = bool(output_limit and len(raw) > output_limit)
        if truncated:
            raw = raw[:output_limit]
        value = _decode_preview(raw, truncated, errors="replace")
        if truncated:
            value += "\n\n… Podgląd skrócono do 250 KB. Otwórz plik w edytorze, aby zobaczyć pozostałą treść.\n"
        return result.returncode, DiffPreview(value, truncated) if output_limit else value

    def run(self, repo, args, timeout=30):
        return self._execute(repo, args, timeout=timeout)[1]

    def _optional(self, repo, args, allowed=(0, 1, 128)):
        code, output = self._execute(repo, args, allowed=allowed)
        return output.strip() if code == 0 else ""

    def root(self, path):
        candidate = Path(path).expanduser()
        try:
            candidate = candidate.resolve()
            if candidate.is_file():
                candidate = candidate.parent
            available = candidate.is_dir()
        except OSError:
            available = False
        if not available:
            raise GitError(repository_unavailable_message(candidate))
        return self.run(candidate, ["rev-parse", "--show-toplevel"]).strip()

    def _has_head(self, repo):
        return bool(self._optional(repo, ["rev-parse", "--verify", "HEAD"]))

    def changes(self, repo):
        """Read worktree/index changes without loading unrelated repository data."""
        data = self.run(repo, ["status", "--porcelain=v1", "-z", "--untracked-files=all"])
        entries = data.split("\0")
        changes = []
        index = 0
        while index < len(entries):
            entry = entries[index]
            index += 1
            if not entry:
                continue
            if len(entry) < 4 or entry[2] != " ":
                raise GitError("Git zwrócił nieoczekiwany stan pliku. Odśwież widok i spróbuj ponownie.")
            original = ""
            if "R" in entry[:2] or "C" in entry[:2]:
                if index >= len(entries):
                    raise GitError("Git zwrócił niepełne informacje o zmianie nazwy pliku.")
                original = entries[index]
                index += 1
            changes.append(FileChange(entry[3:], entry[0], entry[1], original))
        return changes

    def snapshot(self, repo):
        repo = self.root(repo)
        changes = self.changes(repo)
        head_oid = self._optional(repo, ["rev-parse", "--verify", "HEAD"])
        has_head = bool(head_oid)
        head_ref = self._optional(repo, ["symbolic-ref", "--quiet", "HEAD"])
        branch = head_ref.removeprefix("refs/heads/")
        if not branch:
            branch = "Poza gałęzią · " + self.run(repo, ["rev-parse", "--short", "HEAD"]).strip() if has_head else "main"
        upstream = self._optional(repo, ["rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{upstream}"]) if has_head else ""
        ahead = behind = 0
        if upstream:
            counts = self.run(repo, ["rev-list", "--left-right", "--count", "HEAD...@{upstream}"]).split()
            ahead, behind = int(counts[0]), int(counts[1])
        branch_data = self.run(repo, ["for-each-ref", "--sort=refname", "--format=%(refname)%00%(objectname)", "refs/heads/"])
        branches = []
        for entry in branch_data.splitlines():
            full_ref, oid = entry.split("\0", 1)
            branches.append(BranchRef(full_ref.removeprefix("refs/heads/"), full_ref, oid))
        if not has_head and head_ref and all(item.ref != head_ref for item in branches):
            branches.insert(0, BranchRef(branch, head_ref))
        remotes = self.run(repo, ["remote"]).splitlines()
        commits = []
        if has_head:
            fields = self.run(repo, ["log", "-z", "-150", "--format=%H%x00%h%x00%s%x00%an%x00%aI%x00%D"]).split("\0")
            for offset in range(0, len(fields) - 5, 6):
                commits.append(Commit(*fields[offset:offset + 6]))
        stash_count = int(self._optional(repo, ["rev-list", "--walk-reflogs", "--count", "refs/stash"]) or "0")
        git_dir = Path(self.run(repo, ["rev-parse", "--absolute-git-dir"]).strip())
        operation = ""
        for marker, name in (("rebase-merge", "rebase"), ("rebase-apply", "rebase"),
                             ("MERGE_HEAD", "merge"), ("CHERRY_PICK_HEAD", "cherry-pick"),
                             ("REVERT_HEAD", "revert"), ("BISECT_LOG", "bisect")):
            if (git_dir / marker).exists():
                operation = name
                break
        return RepoState(repo, branch, upstream, ahead, behind, changes, branches, remotes, commits,
                         stash_count, operation, head_ref, head_oid)

    def _paths(self, paths):
        if isinstance(paths, (str, FileChange)):
            paths = [paths]
        result = []
        for item in paths:
            values = [item.path, item.original_path] if isinstance(item, FileChange) else [item]
            for value in values:
                if value and value not in result:
                    if not isinstance(value, str) or "\0" in value:
                        raise GitError("Wybierz pliki znajdujące się w repozytorium.")
                    normalized = os.path.normpath(value)
                    if os.path.isabs(value) or os.path.splitdrive(value)[0] or normalized == ".." or normalized.startswith(".." + os.sep):
                        raise GitError("Wybierz pliki znajdujące się w repozytorium.")
                    result.append(value)
        return result

    def diff(self, repo, path, staged=False, original_path=""):
        paths = self._paths([FileChange(path, " ", " ", original_path)])
        if not paths:
            return "Wybierz plik, aby zobaczyć jego zmiany."
        args = ["diff", "--no-ext-diff", "--no-textconv", "--find-renames", "--unified=3"]
        if staged:
            args.append("--cached")
        output = self._execute(repo, args + ["--"] + paths, output_limit=self.DIFF_LIMIT)[1]
        if output:
            return output
        if staged:
            return "Ten plik nie ma zmian przygotowanych do commita."
        tracked = self._optional(repo, ["ls-files", "--error-unmatch", "--", path])
        if tracked:
            return "Brak nieprzygotowanych zmian tekstowych. Zmiana może dotyczyć podmodułu lub uprawnień pliku."
        file_path = Path(repo) / path
        if not file_path.is_file():
            return "Podgląd tekstowy tego pliku jest niedostępny."
        # Avoid reading links pointing outside the worktree.
        if file_path.is_symlink():
            return "Dowiązanie symboliczne → " + os.readlink(file_path)
        if not file_path.resolve().is_relative_to(Path(repo).resolve()):
            return "Ta ścieżka prowadzi poza repozytorium. Otwórz plik w edytorze."
        try:
            with file_path.open("rb") as handle:
                raw = handle.read(self.DIFF_LIMIT + 1)
        except OSError as error:
            raise GitError(_git_safe_text(f"Nie udało się odczytać pliku: {error}")) from None
        if b"\0" in raw:
            return "Plik binarny — podgląd tekstowy jest niedostępny."
        try:
            content = _decode_preview(raw[:self.DIFF_LIMIT], len(raw) > self.DIFF_LIMIT, encoding="utf-8-sig")
        except UnicodeDecodeError:
            return "Ten plik jest binarny lub ma kodowanie inne niż UTF-8. Otwórz go w edytorze."
        lines = content.split("\n")
        if lines[-1] == "":
            lines.pop()
        preview = f"diff --git a/{path} b/{path}\nnew file\n--- /dev/null\n+++ b/{path}\n@@ -0,0 +1,{len(lines)} @@\n"
        preview += "\n".join("+" + line for line in lines)
        if len(raw) > self.DIFF_LIMIT:
            preview += "\n\n… Podgląd skrócono do 250 KB."
        return DiffPreview(preview, len(raw) > self.DIFF_LIMIT)

    def commit_diff(self, repo, oid, paths=None):
        if not isinstance(oid, str) or not re.fullmatch(r"[0-9a-fA-F]{7,64}", oid):
            raise GitError("Wybierz prawidłowy commit.")
        selected_paths = self._paths(paths) if paths is not None else []
        if paths is not None and not selected_paths:
            raise GitError('Wybierz plik do podglądu commita.')
        format_ = "%H%x00%an%x00%ae%x00%aI%x00%cn%x00%ce%x00%cI%x00%P%x00%B%x00"
        output = self._execute(repo, ["show", "--format=format:" + format_, "--patch", "--always",
                                    "--diff-merges=first-parent", "--src-prefix=a/", "--dst-prefix=b/",
                                    "--no-ext-diff", "--no-textconv", "--find-renames", oid, "--", *selected_paths],
                               output_limit=self.DIFF_LIMIT)[1]
        fields = str(output).split("\0", 9)
        truncated = bool(getattr(output, "truncated", False))
        if len(fields) < 9 or (len(fields) < 10 and not truncated):
            raise GitError("Nie udało się odczytać informacji o commicie.")
        details = CommitDetails(*fields[:7], tuple(fields[7].split()), fields[8].strip())
        patch = fields[9].lstrip("\n") if len(fields) == 10 else "… Podgląd skrócono: opis commita przekracza limit podglądu."
        return CommitPreview(patch, details, truncated)

    def _commit_range_endpoints(self, repo, oids, minimum=1):
        """Pin one commit or a contiguous first-parent range, including merges."""
        if isinstance(oids, (str, bytes)):
            if minimum > 1 or isinstance(oids, bytes):
                raise GitError('Wybierz kolejne commity do podglądu.')
            oids = [oids]
        try:
            selected = tuple(oids)
        except TypeError:
            raise GitError('Wybierz commity do podglądu.') from None
        if not minimum <= len(selected) <= 500 or any(not isinstance(oid, str) or
                not re.fullmatch(r'[0-9a-fA-F]{40}|[0-9a-fA-F]{64}', oid) for oid in selected):
            raise GitError(f'Wybierz od {minimum} do 500 kolejnych commitów do podglądu.')
        selected = tuple(oid.lower() for oid in selected)
        if len(set(selected)) != len(selected):
            raise GitError('Zakres podglądu zawiera powtórzone commity.')
        rows = self.run(repo, ['rev-list', '--no-walk=unsorted', '--parents', *selected, '--']).splitlines()
        parents = {parts[0]: tuple(parts[1:]) for parts in (row.split() for row in rows) if parts}
        if set(parents) != set(selected):
            raise GitError('Nie udało się odczytać całego zaznaczonego zakresu. Odśwież historię.')
        older = {values[0] for values in parents.values() if values}
        newest = set(selected) - older
        if len(newest) != 1:
            raise GitError('Wybierz ciągły zakres commitów bez przerw, w jednej linii pierwszych rodziców.')
        newest = next(iter(newest))
        ordered, current = [], newest
        while current in parents and current not in ordered:
            ordered.append(current)
            current = parents[current][0] if parents[current] else ''
        if len(ordered) != len(selected):
            raise GitError('Wybierz ciągły zakres commitów bez przerw, w jednej linii pierwszych rodziców.')
        base = current or self.run(repo, ['hash-object', '-t', 'tree', '--stdin']).strip()
        return base, newest

    def commit_range_diff(self, repo, oids, paths=None):
        """Compare the oldest selected parent's tree with the newest tree."""
        base, newest = self._commit_range_endpoints(repo, oids, minimum=2)
        selected_paths = self._paths(paths) if paths is not None else []
        if paths is not None and not selected_paths:
            raise GitError('Wybierz plik do wspólnego podglądu commitów.')
        output = self._execute(repo, ['diff', '--patch', '--src-prefix=a/', '--dst-prefix=b/',
                                     '--no-ext-diff', '--no-textconv', '--find-renames', base, newest, '--', *selected_paths],
                               output_limit=self.DIFF_LIMIT)[1]
        return RangePreview(output, getattr(output, 'truncated', False))

    def commit_files(self, repo, oids):
        """Return exact per-file status and added/deleted lines for the net change."""
        base, newest = self._commit_range_endpoints(repo, oids)
        output = self._execute(repo, ['diff', '--raw', '--numstat', '-z', '--no-abbrev',
                                     '--no-ext-diff', '--no-textconv', '--find-renames',
                                     '--ignore-submodules=none', base, newest, '--'],
                               output_limit=4 * 1024 * 1024)[1]
        if getattr(output, 'truncated', False):
            raise GitError('Lista plików przekracza limit podglądu 4 MB. Wybierz mniejszy zakres commitów.')
        if not output:
            return ()
        try:
            fields = str(output).split('\0')
            if fields.pop() != '':
                raise ValueError('incomplete NUL output')
            entries, position = [], 0
            while position < len(fields) and fields[position].startswith(':'):
                header = re.fullmatch(r':[0-7]{6} [0-7]{6} [0-9a-f]+ [0-9a-f]+ ([ACDMRTUX])(?:\d{1,3})?', fields[position])
                if header is None:
                    raise ValueError('invalid raw header')
                status = header[1]
                path = fields[position + 1]
                position += 2
                original = ''
                if status in ('R', 'C'):
                    original, path = path, fields[position]
                    position += 1
                if not path or status in ('R', 'C') and not original:
                    raise ValueError('empty path')
                entries.append((path, original, status))
            statistics = {}
            while position < len(fields):
                added, deleted, path = fields[position].split('\t', 2)
                position += 1
                original = ''
                renamed = not path
                if renamed:
                    original, path = fields[position:position + 2]
                    position += 2
                if not path or renamed and not original:
                    raise ValueError('empty numstat path')
                if added == deleted == '-':
                    counts = (None, None)
                elif re.fullmatch(r'[0-9]+', added) and re.fullmatch(r'[0-9]+', deleted):
                    counts = (int(added), int(deleted))
                else:
                    raise ValueError('invalid line counts')
                key = (path, original)
                if key in statistics:
                    raise ValueError('duplicate numstat entry')
                statistics[key] = counts
            if len(entries) != len(statistics) or len({(path, original) for path, original, _ in entries}) != len(entries):
                raise ValueError('inconsistent raw and numstat entries')
            return tuple(CommitFileChange(path, status, *statistics[(path, original)], original)
                         for path, original, status in entries)
        except (ValueError, IndexError, KeyError):
            raise GitError('Git zwrócił niepełną lub niespójną listę plików commita. Odśwież podgląd.') from None

    def commit_file_diff(self, repo, oids, file):
        if not isinstance(file, CommitFileChange):
            raise GitError('Wybierz plik z listy zmian commita.')
        try:
            selected = (oids,) if isinstance(oids, str) else tuple(oids)
        except TypeError:
            raise GitError('Wybierz commity do podglądu.') from None
        paths = [file.path, file.original_path]
        if len(selected) == 1:
            preview = self.commit_diff(repo, selected[0], paths=paths)
        else:
            preview = self.commit_range_diff(repo, selected, paths=paths)
        # Git's literal pathspec also selects descendants after file -> directory
        # changes. Match the known pair in the patch header to keep one file only.
        def quote_path(path):
            escapes = {'\a': r'\a', '\b': r'\b', '\t': r'\t', '\n': r'\n',
                       '\v': r'\v', '\f': r'\f', '\r': r'\r', '\\': r'\\', '"': r'\"'}
            if not any(char in escapes or ord(char) < 32 or ord(char) == 127 for char in path):
                return path
            return '"' + ''.join(escapes.get(char, f'\\{ord(char):03o}') if ord(char) < 32 or ord(char) == 127
                                  else escapes.get(char, char) for char in path) + '"'
        expected = 'diff --git ' + quote_path('a/' + (file.original_path or file.path)) + ' ' + quote_path('b/' + file.path)
        output, include = [], False
        for line in re.split(r'(?<=\n)', str(preview)):
            if line.startswith('diff --git '):
                include = line.rstrip('\r\n') == expected
            if include:
                output.append(line)
        patch = ''.join(output)
        if not patch and preview.truncated:
            patch = '… Podgląd skrócono, zanim odczytano wybrany plik.'
        return (CommitPreview(patch, preview.details, preview.truncated) if isinstance(preview, CommitPreview)
                else RangePreview(patch, preview.truncated))

    def _run_paths(self, repo, args, paths):
        """NUL-separated file arguments avoid Windows' command-line length limit."""
        temporary = None
        try:
            with tempfile.NamedTemporaryFile(prefix="gitline-paths-", suffix=".txt", delete=False) as handle:
                temporary = handle.name
                handle.write(b"\0".join(path.encode("utf-8") for path in paths) + b"\0")
            return self.run(repo, args + ["--pathspec-from-file=" + temporary, "--pathspec-file-nul"])
        finally:
            if temporary:
                try:
                    os.unlink(temporary)
                except FileNotFoundError:
                    pass

    def stage(self, repo, paths):
        selection = [paths] if isinstance(paths, (str, FileChange)) else list(paths)
        paths = self._paths(selection)
        if not paths:
            return ""
        explicit_directories = {item for item in selection if isinstance(item, str)}
        explicit_directories.update(item.path for item in selection if isinstance(item, FileChange)
                                    and (item.index_status, item.worktree_status) == ("?", "?"))
        # A rename already in the index no longer has its original path there.
        # Its old name may now be a directory containing unrelated new files.
        directories = {path for path in paths if os.path.isdir(os.path.join(repo, path))
                       and not os.path.islink(os.path.join(repo, path))}
        existing = {path for path in paths if (path not in directories or path in explicit_directories)
                    and os.path.lexists(os.path.join(repo, path))}
        tracked = set(self.run(repo, ["ls-files", "-z"]).split("\0")) if directories or len(existing) != len(paths) else set()
        # Update only an exact tracked file/gitlink at a directory path. This
        # stages a file's deletion without recursively adding its replacement.
        tracked_directories = [path for path in paths if path in directories and path in tracked]
        applicable = [path for path in paths if path not in tracked_directories and (path in existing or path in tracked)]
        results = []
        if tracked_directories:
            results.append(self._run_paths(repo, ["add", "--update"], tracked_directories))
        if applicable:
            results.append(self._run_paths(repo, ["add", "--all"], applicable))
        return "\n".join(results)

    def unstage(self, repo, paths):
        paths = self._paths(paths)
        if not paths:
            return ""
        # Include both sides even if the UI passes only the displayed rename target.
        selected = set(paths)
        for change in self.changes(repo):
            if change.path in selected and change.original_path and change.original_path not in selected:
                paths.append(change.original_path)
                selected.add(change.original_path)
        # Literal Git pathspecs still match descendants. Restoring a renamed
        # file cannot preserve indexed children under its old name, so refuse
        # before changing the index unless those children are selected too.
        selected = {os.path.normpath(path).replace(os.sep, "/") for path in paths}
        for indexed in self.run(repo, ["ls-files", "-z"]).split("\0"):
            if indexed in selected:
                continue
            ancestor = indexed.rpartition("/")[0]
            while ancestor:
                if ancestor in selected:
                    raise GitError("Cofnięcie wyboru tego pliku zmieniłoby też wybór plików w katalogu "
                                   + json.dumps(ancestor, ensure_ascii=False)
                                   + ". Najpierw cofnij ich wybór albo cofnij wybór wszystkich plików jednocześnie.")
                ancestor = ancestor.rpartition("/")[0]
        if self._has_head(repo):
            return self._run_paths(repo, ["reset", "--quiet", "HEAD"], paths)
        return self._run_paths(repo, ["rm", "--cached", "--force", "-r", "--ignore-unmatch"], paths)

    def commit(self, repo, summary, description="", *, expected_head=None):
        summary = summary.strip()
        if not summary:
            raise GitError("Najpierw wpisz tytuł commita.")
        if "\n" in summary or "\r" in summary:
            raise GitError("Tytuł commita musi mieścić się w jednym wierszu. Szczegóły wpisz w opisie.")
        if expected_head is not None:
            current_head = (self._optional(repo, ["symbolic-ref", "--quiet", "HEAD"]),
                            self._optional(repo, ["rev-parse", "--verify", "HEAD"]))
            if current_head != expected_head:
                raise GitError("Gałąź lub historia zmieniła się przed utworzeniem commita. "
                               "Odśwież widok i sprawdź wybrane pliki przed ponowną próbą.")
        args = ["commit", "-m", summary]
        if description.strip():
            args += ["-m", description.strip()]
        return self.run(repo, args, timeout=120)

    def _branch_name(self, repo, name):
        if isinstance(name, BranchRef):
            name = name.ref
        if isinstance(name, str):
            name = name.removeprefix("refs/heads/")
        if not isinstance(name, str) or not name or name.startswith("-") or name != name.strip() or name == "HEAD" or "@{" in name:
            raise GitError("Podaj prawidłową nazwę gałęzi, na przykład feature/nowy-widok.")
        self.run(repo, ["check-ref-format", "--branch", name])
        return name

    def switch_branch(self, repo, name):
        name = self._branch_name(repo, name)
        return self.run(repo, ["switch", "--no-guess", "--", name])

    def create_branch(self, repo, name):
        name = self._branch_name(repo, name)
        return self.run(repo, ["switch", "-c", name])

    def init_repo(self, path):
        path = Path(path).expanduser().resolve()
        path.mkdir(parents=True, exist_ok=True)
        if (path / ".git").exists():
            raise GitError("Ten folder zawiera już repozytorium Git. Otwórz je w aplikacji.")
        self.run(None, ["init", "--initial-branch=main", "--", str(path)])
        return str(path)

    def clone(self, url, target, account_id=None):
        url = url.strip()
        if not url or url.startswith("-") or "\0" in url or "\n" in url or "\r" in url:
            raise GitError("Podaj adres repozytorium HTTPS, SSH lub ścieżkę lokalną.")
        target = Path(target).expanduser().resolve()
        if target.exists() and (not target.is_dir() or any(target.iterdir())):
            raise GitError("Wybierz pusty folder docelowy do sklonowania repozytorium.")
        target.parent.mkdir(parents=True, exist_ok=True)
        backend = self.with_account(account_id) if account_id is not None else self
        backend._with_remote("origin").run(None, ["clone", "--", url, str(target)], timeout=300)
        return str(target)

    def fetch(self, repo):
        repo = self.root(repo)
        results = []
        for remote in self.run(repo, ["remote"]).splitlines():
            if self._optional(repo, ["config", "--type=bool", "--get", f"remote.{remote}.skipFetchAll"]) == "true":
                continue
            results.append(self._with_remote(remote).run(repo, ["fetch", "--prune", "--", remote], timeout=120))
        return "\n".join(results)

    def pull(self, repo):
        repo = self.root(repo)
        if not self._optional(repo, ["rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{upstream}"]):
            raise GitError("Ta gałąź nie ma gałęzi śledzonej. Najpierw opublikuj ją przyciskiem Wyślij lub skonfiguruj śledzenie w Git.")
        branch = self._optional(repo, ["symbolic-ref", "--quiet", "HEAD"]).removeprefix("refs/heads/")
        remote = self._optional(repo, ["config", "--get", f"branch.{branch}.remote"])
        return self._with_remote(remote).run(repo, ["pull", "--ff-only"], timeout=120)

    def _config_values(self, repo, key):
        code, value = self._execute(repo, ["config", "--null", "--get-all", key], allowed=(0, 1))
        return tuple(value.removesuffix("\0").split("\0")) if code == 0 else ()

    def _destination_ref(self, repo, destination):
        if not isinstance(destination, str) or (destination.startswith("refs/") and not destination.startswith("refs/heads/")):
            raise GitError("Wybierz gałąź docelową, na przykład main lub refs/heads/main.")
        return "refs/heads/" + self._branch_name(repo, destination)

    @staticmethod
    def _pin_push_url(repo, url):
        # Git resolves ordinary paths against -C, while scheme and scp URLs
        # retain their transport syntax. In particular, C:\ is a local drive.
        is_drive = bool(os.path.splitdrive(url)[0])
        first_slash = len(url) if "/" not in url else url.index("/")
        is_transport = bool(re.match(r"^[A-Za-z][A-Za-z0-9+.-]*://", url))
        is_scp = ":" in url[:first_slash] and not is_drive
        return url if is_transport or is_scp else str((Path(repo) / url).resolve())

    def resolve_push_plan(self, repo, remote=None, destination=None):
        """Resolve only the current branch, without fetching or changing Git config."""
        repo = str(Path(self.root(repo)).resolve())
        source_ref = self._optional(repo, ["symbolic-ref", "--quiet", "HEAD"])
        if not source_ref.startswith("refs/heads/"):
            raise GitError("Przed wysłaniem zmian utwórz gałąź lub przełącz się na istniejącą gałąź.")
        branch = source_ref.removeprefix("refs/heads/")
        head_oid = self._optional(repo, ["rev-parse", "--verify", "HEAD"])
        if not head_oid:
            raise GitError("Przed opublikowaniem tej gałęzi utwórz pierwszy commit.")
        signature = []
        def values(key):
            result = self._config_values(repo, key)
            signature.append((key, result))
            return result
        def scalar(key):
            result = values(key)
            return result[-1] if result else ""

        branch_push_remote = scalar(f"branch.{branch}.pushRemote")
        default_remote = scalar("remote.pushDefault")
        pull_remote = scalar(f"branch.{branch}.remote")
        pull_refs = values(f"branch.{branch}.merge")
        if len(pull_refs) > 1:
            raise GitError("Ta gałąź ma kilka gałęzi śledzonych. Przed wysłaniem zmian skonfiguruj jedną gałąź śledzoną.")
        pull_ref = pull_refs[0] if pull_refs else ""
        if bool(pull_remote) != bool(pull_ref):
            raise GitError("Konfiguracja śledzenia tej gałęzi jest niepełna. Przed wysłaniem zmian ustaw zdalne repozytorium i gałąź śledzoną.")
        remotes = tuple(self.run(repo, ["remote"]).splitlines())
        signature.append(("available-remotes", remotes))
        remote_name = remote if remote is not None else (branch_push_remote or default_remote or pull_remote)
        if not remote_name:
            if "origin" in remotes:
                remote_name = "origin"
            elif len(remotes) == 1:
                remote_name = remotes[0]
            elif not remotes:
                raise GitError("To repozytorium nie ma zdalnego repozytorium. Dodaj je w Git lub sklonuj istniejące repozytorium.")
            else:
                raise GitError("Skonfigurowano kilka zdalnych repozytoriów. Wybierz, gdzie opublikować tę gałąź.")
        if remote_name not in remotes:
            raise GitError("Wybrane zdalne repozytorium nie jest skonfigurowane. Wybierz jedno z dostępnych repozytoriów.")

        values(f"remote.{remote_name}.url")
        values(f"remote.{remote_name}.pushurl")
        values(f"remote.{remote_name}.fetch")
        for option in ("proxy", "proxyAuthMethod", "receivepack"):
            values(f"remote.{remote_name}.{option}")
        mirror_values = values(f"remote.{remote_name}.mirror")
        mirror = mirror_values[-1].lower() if mirror_values else "false"
        if mirror in ("true", "yes", "on", "1", ""):
            raise GitError("To zdalne repozytorium działa w trybie lustrzanym. Wyłącz tryb mirror przed opublikowaniem pojedynczej gałęzi.")
        if mirror not in ("false", "no", "off", "0"):
            raise GitError("Ustawienie mirror tego zdalnego repozytorium jest nieprawidłowe. Przed wysłaniem zmian ustaw je na false.")
        configured_push = values(f"remote.{remote_name}.push")
        mode = scalar("push.default") or "simple"
        push_urls = tuple(self.run(repo, ["remote", "get-url", "--push", "--all", remote_name]).splitlines())
        if not push_urls or any(not url or any(c in url for c in "\0\r\n") for url in push_urls):
            raise GitError("Adres do wysyłania zmian jest nieprawidłowy. Popraw push URL tego zdalnego repozytorium.")
        push_urls = tuple(self._pin_push_url(repo, url) for url in push_urls)
        if destination is not None:
            destination_ref = self._destination_ref(repo, destination)
        elif configured_push:
            if len(configured_push) != 1:
                raise GitError("To zdalne repozytorium ma kilka reguł wysyłania zmian. Wybierz jedną gałąź docelową.")
            refspec = configured_push[0]
            if refspec.startswith("+") or "*" in refspec or refspec.startswith(":"):
                raise GitError("Reguła wysyłania wymusza zmiany, używa wzorca lub usuwa gałąź. Wybierz konkretną gałąź docelową.")
            source, separator, target = refspec.partition(":")
            if source not in ("HEAD", branch, source_ref) or separator and not target:
                raise GitError("Reguła wysyłania nie wskazuje bieżącej gałęzi. Wybierz konkretną gałąź docelową.")
            destination_ref = self._destination_ref(repo, target if separator else branch)
        elif mode in ("matching", "nothing"):
            raise GitError("Wybrany tryb wysyłania nie wskazuje jednego celu. Wybierz konkretną gałąź docelową.")
        elif mode in ("upstream", "tracking"):
            if not pull_ref or remote_name != pull_remote:
                raise GitError("Tryb wysyłania upstream wymaga repozytorium gałęzi śledzonej. Wybierz konkretną gałąź docelową.")
            destination_ref = self._destination_ref(repo, pull_ref)
        elif mode == "simple":
            if remote_name == pull_remote and pull_ref and pull_ref != source_ref:
                raise GitError("Gałąź śledzona ma inną nazwę. Wybierz konkretną gałąź docelową.")
            destination_ref = source_ref
        elif mode == "current":
            destination_ref = source_ref
        else:
            raise GitError("Wartość push.default nie jest obsługiwana. Wybierz konkretną gałąź docelową.")
        return PushPlan(repo, head_oid, source_ref, remote_name, push_urls, destination_ref,
                        not pull_remote and not pull_ref, pull_remote, pull_ref, remote, destination, tuple(signature))

    def push_tracking_state(self, repo, plan=None):
        """Inspect the selected push target's local tracking ref; never fetch."""
        if plan is None:
            plan = self.resolve_push_plan(repo)
        if not isinstance(plan, PushPlan) or self.resolve_push_plan(
                repo, plan.remote_override, plan.destination_override) != plan:
            raise GitError("Zmienił się podgląd wysyłania. Sprawdź bieżącą gałąź i cel.")
        unknown = dict(tracking_ref="", oid="", requires_force=False, reason="")
        if len(plan.push_urls) != 1:
            return dict(unknown, reason="Wymuszone wysyłanie wymaga jednego adresu docelowego.")
        fetch_urls = tuple(self._pin_push_url(plan.repo, value) for value in self.run(
            plan.repo, ["remote", "get-url", "--all", plan.remote_name]).splitlines())
        if fetch_urls != plan.push_urls:
            return dict(unknown, reason="Adres pobierania różni się od adresu wysyłania; lokalna gałąź śledzona nie potwierdza tego celu.")

        def matched(pattern, ref):
            if "*" not in pattern:
                return "" if pattern == ref else None
            if pattern.count("*") != 1:
                return None
            prefix, suffix = pattern.split("*")
            if ref.startswith(prefix) and ref.endswith(suffix) and len(ref) >= len(prefix) + len(suffix):
                return ref[len(prefix):len(ref) - len(suffix) if suffix else None]
            return None

        candidates = set()
        refspecs = dict(plan.config_signature).get(f"remote.{plan.remote_name}.fetch", ())
        for refspec in refspecs:
            if refspec.startswith("^"):
                if matched(refspec[1:], plan.destination_ref) is not None:
                    return dict(unknown, reason="Wybrana gałąź jest wyłączona z pobierania.")
                continue
            source, separator, target = refspec.removeprefix("+").partition(":")
            middle = matched(source, plan.destination_ref)
            if separator and middle is not None:
                if source.count("*") != target.count("*") or target.count("*") > 1:
                    return dict(unknown, reason="Reguła pobierania ma niejednoznaczne mapowanie gałęzi.")
                candidates.add(target.replace("*", middle))
        if len(candidates) != 1:
            return dict(unknown, reason="Nie znaleziono jednoznacznej gałęzi śledzonej dla tego celu.")
        tracking_ref = candidates.pop()
        if not tracking_ref.startswith("refs/remotes/"):
            return dict(unknown, reason="Reguła pobierania nie wskazuje zdalnej gałęzi śledzonej.")
        self.run(plan.repo, ["check-ref-format", tracking_ref])
        if self._optional(plan.repo, ["symbolic-ref", "--quiet", tracking_ref]):
            return dict(unknown, reason="Gałąź śledzona jest odsyłaczem symbolicznym; jej stan wymaga sprawdzenia.")
        oid = self._optional(plan.repo, ["rev-parse", "--verify", "--end-of-options", tracking_ref + "^{commit}"])
        if not oid:
            return dict(unknown, reason="Nie ma lokalnie zapisanego commita tej zdalnej gałęzi.")
        code, _ = self._execute(plan.repo, ["merge-base", "--is-ancestor", oid, plan.head_oid], allowed=(0, 1))
        return dict(tracking_ref=tracking_ref, oid=oid, requires_force=code == 1, reason="")

    def _force_push_oid(self, plan, expected_remote_oid):
        if (not isinstance(expected_remote_oid, str)
                or not re.fullmatch(r"(?:[0-9a-fA-F]{40}|[0-9a-fA-F]{64})", expected_remote_oid)
                or len(expected_remote_oid) != len(plan.head_oid)):
            raise GitError("Wymuszone wysyłanie wymaga pełnego OID zdalnej gałęzi zapisanego przed przepisaniem historii.")
        expected_remote_oid = expected_remote_oid.lower()
        if self.run(plan.repo, ["cat-file", "-t", expected_remote_oid]).strip() != "commit":
            raise GitError("Oczekiwany stan zdalnej gałęzi musi wskazywać znany lokalnie commit.")
        return expected_remote_oid

    def prepare_force_push(self, repo, expected_remote_oid, remote=None, destination=None):
        """Use only a caller-reviewed lease saved before rewriting; never refresh it."""
        plan = self.resolve_push_plan(repo, remote, destination)
        if len(plan.push_urls) != 1:
            raise GitError("Wymuszone wysyłanie obsługuje jeden adres docelowy. Skonfiguruj osobne zdalne repozytoria dla wielu adresów.")
        return ForcePushPlan(plan, self._force_push_oid(plan, expected_remote_oid))

    def force_push(self, repo, plan, progress=None):
        if not isinstance(plan, ForcePushPlan) or not isinstance(plan.push_plan, PushPlan):
            raise GitError("Przed wymuszonym wysłaniem sprawdź podgląd celu i oczekiwany OID zdalnej gałęzi.")
        reviewed = plan.push_plan
        current = self.resolve_push_plan(repo, reviewed.remote_override, reviewed.destination_override)
        if current != reviewed:
            raise GitError("Zmieniła się gałąź, commit lub konfiguracja wysyłania. Sprawdź nowy podgląd przed kontynuowaniem.")
        if len(reviewed.push_urls) != 1:
            raise GitError("Wymuszone wysyłanie wymaga dokładnie jednego adresu docelowego.")
        expected = self._force_push_oid(reviewed, plan.expected_remote_oid)
        return self._push_reviewed(reviewed, expected, progress=progress)

    def push(self, repo, plan=None, progress=None):
        if plan is None:
            plan = self.resolve_push_plan(repo)
        if not isinstance(plan, PushPlan):
            raise GitError("Przed opublikowaniem gałęzi przygotuj podgląd wysyłania.")
        current = self.resolve_push_plan(repo, plan.remote_override, plan.destination_override)
        if current != plan:
            raise GitError("Zmieniła się gałąź, commit lub konfiguracja wysyłania. Sprawdź nowy podgląd przed kontynuowaniem.")
        return self._push_reviewed(plan, progress=progress)

    def _push_reviewed(self, plan, expected_remote_oid=None, progress=None):
        import uuid
        configuration = dict(plan.config_signature)
        # A random alias is rewritten exactly once to the reviewed endpoint.
        # Empty url/pushurl values clear their lists before adding that alias.
        # The real remote name preserves pre-push hooks and native tracking refs.
        results = []
        for endpoint_index, endpoint in enumerate(plan.push_urls, 1):
            def report(value, index=endpoint_index):
                _notify_git_progress(progress, dataclasses.replace(value, endpoint_index=index,
                                                                  endpoint_total=len(plan.push_urls)))
            if progress is not None:
                report(GitProgress('connecting'))
            alias = "gitline-push-" + uuid.uuid4().hex + ":"
            prefix = f"remote.{plan.remote_name}."
            options = ["-c", f"url.{endpoint}.insteadOf={alias}",
                       "-c", prefix + "url=", "-c", prefix + "url=" + alias,
                       "-c", prefix + "pushurl=", "-c", prefix + "pushurl=" + alias,
                       "-c", prefix + "mirror=false"]
            for option in ("proxy", "proxyAuthMethod", "receivepack"):
                setting = configuration.get(f"remote.{plan.remote_name}.{option}", ())
                if setting:
                    options += ["-c", f"{prefix}{option}={setting[-1]}"]
            try:
                scoped = self._with_remote(plan.remote_name)
                effective = scoped.run(plan.repo, options + ["remote", "get-url", "--push", "--all", plan.remote_name]).splitlines()
                if effective != [endpoint]:
                    raise GitError("Ta wersja lub konfiguracja Gita nie pozwala bezpiecznie przypiąć adresu wysyłania. Zaktualizuj Git i ponownie sprawdź konfigurację repozytorium.")
                lease = ([f"--force-with-lease={plan.destination_ref}:{expected_remote_oid}"]
                         if expected_remote_oid is not None else [])
                args = options + ["push", "--no-force"] + lease
                if progress is not None:
                    args.append('--progress')
                args += ["--no-follow-tags", "--recurse-submodules=no", "--",
                         plan.remote_name, f"{plan.head_oid}:{plan.destination_ref}"]
                if progress is None:
                    results.append(scoped.run(plan.repo, args, timeout=120))
                else:
                    results.append(scoped._execute(plan.repo, args, timeout=120, progress=report)[1])
            except GitError as error:
                if results:
                    raise GitError(f"Zmiany wysłano do {len(results)} z {len(plan.push_urls)} adresów. Pozostałe wysyłanie nie powiodło się:\n{error}") from None
                raise
        if plan.set_upstream:
            branch = plan.source_ref.removeprefix("refs/heads/")
            if not self._config_values(plan.repo, f"branch.{branch}.remote") and not self._config_values(plan.repo, f"branch.{branch}.merge"):
                self.run(plan.repo, ["config", "--local", f"branch.{branch}.remote", plan.remote_name])
                self.run(plan.repo, ["config", "--local", f"branch.{branch}.merge", plan.destination_ref])
        return "\n".join(results)

    def _history_membership(self, repo, oids, tip):
        """One bounded ancestry walk for all displayed commits, never one per row."""
        candidates = tuple(dict.fromkeys(oids))
        if not candidates:
            return {}
        if any(not isinstance(oid, str) or not re.fullmatch(r'[0-9a-f]{40}|[0-9a-f]{64}', oid)
               for oid in (*candidates, tip)):
            return {}
        try:
            data = ('\n'.join(candidates) + '\n^' + tip + '\n').encode('ascii')
            raw = self._squash_git(repo, ['rev-list', '--max-count=100001', '--stdin'], data, limit=8 * 1024 * 1024)
            local = raw.decode('ascii').splitlines()
            if len(local) > 100000:
                return {}
            local = set(local)
            return {oid: oid not in local for oid in candidates}
        except (GitError, UnicodeError, ValueError, OSError):
            return {}

    def squash_provenance(self, repo, record, provenance=None):
        """Recover legacy squash boundaries from retained objects, without writes."""
        unknown = dict(version=1, complete=False, entries=[])
        if not isinstance(record, dict):
            return unknown
        old, new, expected = (record.get(name) for name in ('old_head', 'new_head', 'expected_remote_oid'))
        if any(not isinstance(oid, str) or not re.fullmatch(r'[0-9a-f]{40}|[0-9a-f]{64}', oid)
               for oid in (old, new, expected)):
            return unknown
        saved = _clean_squash_provenance(provenance, len(new))
        if saved is not None:
            return saved
        try:
            chains = []
            for head in (old, new):
                raw = self._squash_git(repo, ['rev-list', '--first-parent', '--parents', '--max-count=2001', head])
                chain = [line.split() for line in raw.decode('ascii').splitlines()]
                if not chain or chain[0][0] != head:
                    return unknown
                chains.append(chain)
            before, after = chains
            positions = {fields[0]: index for index, fields in enumerate(before)}
            common = next(((index, positions[fields[0]]) for index, fields in enumerate(after)
                           if fields[0] in positions), None)
            if common is None:
                if len(before[-1]) != 1 or len(after[-1]) != 1 or max(len(before), len(after)) > 2000:
                    return unknown
                new_count, old_count = len(after), len(before)
            else:
                new_count, old_count = common
            descendants = new_count - 1
            if (descendants < 0 or old_count - descendants < 2
                    or any(len(fields) > 2 for fields in before[:old_count] + after[:new_count])):
                return unknown
            oids = tuple(fields[0] for fields in before[:old_count] + after[:new_count])
            objects = dict(zip(oids, self._squash_commits(repo, oids)))
            for index in range(descendants):
                previous, replayed = objects[before[index][0]], objects[after[index][0]]
                if (previous[1:3] != replayed[1:3]
                        or dataclasses.replace(previous[0], oid=replayed[0].oid, parents=replayed[0].parents) != replayed[0]):
                    return unknown
            combined = objects[after[descendants][0]]
            newest, oldest = objects[before[descendants][0]], objects[before[old_count - 1][0]]
            if (combined[1] != newest[1]
                    or (combined[0].author, combined[0].author_email, combined[0].author_date)
                    != (oldest[0].author, oldest[0].author_email, oldest[0].author_date)):
                return unknown
            # If the previous tip already rewrote the pinned server tip, an old
            # lease alone cannot expand earlier squashes into their originals.
            complete = old == expected or self._optional(repo, ['merge-base', '--all', expected, old]) == expected
            originals = [fields[0] for fields in reversed(before[descendants:old_count])] if complete else None
            entries = [dict(oid=combined[0].oid, original_oids=originals, is_squash=True)]
            entries.extend(dict(oid=after[index][0], original_oids=[before[index][0]] if complete else None,
                                is_squash=False) for index in range(descendants))
            return dict(version=1, complete=complete, entries=entries)
        except (GitError, OSError, ValueError, UnicodeError, KeyError, IndexError, TypeError):
            return unknown

    @staticmethod
    def rewrite_squash_provenance(plan, result, prepared=None):
        """Expand nested squashes and carry their identities through replay."""
        known = (dict(version=1, complete=True, entries=[]) if prepared is None
                 else _clean_squash_provenance(prepared, len(result.new_head)))
        known = known or dict(version=1, complete=False, entries=[])
        selected = {commit.oid for commit in plan.selected}
        old_entries = {entry['oid']: entry for entry in known['entries']}
        mapping = dict(result.rewritten_oids)
        originals, complete = [], known['complete']
        for commit in plan.selected:
            source = old_entries[commit.oid]['original_oids'] if commit.oid in old_entries else [commit.oid]
            if source is None:
                complete = False
            else:
                originals.extend(source)
        if len(set(originals)) != len(originals):
            complete = False
        entries = [dict(entry, oid=mapping.get(oid, oid))
                   for oid, entry in old_entries.items() if oid not in selected]
        entries.extend(dict(oid=mapping[commit.oid], original_oids=[commit.oid] if known['complete'] else None,
                            is_squash=False) for commit in plan.descendants if commit.oid not in old_entries)
        entries.append(dict(oid=result.squash_oid, original_oids=originals if complete else None, is_squash=True))
        value = _clean_squash_provenance(dict(version=1, complete=known['complete'], entries=entries), len(result.new_head))
        return value or dict(version=1, complete=False, entries=[dict(oid=result.squash_oid, original_oids=None, is_squash=True)])

    @staticmethod
    def rewrite_reword_provenance(result, prepared=None):
        """Carry existing squash identities through a message-only HEAD rewrite."""
        unknown = dict(version=1, complete=False, entries=[])
        old, new = result.old_head, result.new_head
        if (any(not isinstance(oid, str) or not re.fullmatch(r'[0-9a-f]{40}|[0-9a-f]{64}', oid)
                for oid in (old, new)) or len(old) != len(new)):
            return unknown
        known = (dict(version=1, complete=True, entries=[]) if prepared is None
                 else _clean_squash_provenance(prepared, len(new))) or unknown
        entries = [dict(entry, oid=new if entry['oid'] == old else entry['oid'])
                   for entry in known['entries']]
        if not any(entry['oid'] == old for entry in known['entries']):
            entries.append(dict(oid=new, original_oids=[old] if known['complete'] else None,
                                is_squash=False))
        return _clean_squash_provenance(
            dict(version=1, complete=known['complete'], entries=entries), len(new)) or unknown

    def history_publication(self, repo, commits, record=None, plan=None, provenance=None):
        """Advisory publication state for a whole history snapshot; never fetch."""
        import hashlib
        oids = tuple(dict.fromkeys(commit if isinstance(commit, str) else commit.oid for commit in commits))
        result = {oid: dict(status='unknown', is_squash=False, original_count=None,
                            published_count=None, local_count=None) for oid in oids}
        if not oids:
            return result
        tip = ''
        try:
            if plan is None:
                plan = self.resolve_push_plan(repo, record.get('remote_name') if record else None,
                                              record.get('destination_ref') if record else None)
            route_matches = (isinstance(plan, PushPlan) and (not record or
                (record.get('repo') == os.path.normcase(str(Path(plan.repo).expanduser().resolve()))
                 and record.get('source_ref') == plan.source_ref and record.get('remote_name') == plan.remote_name
                 and record.get('destination_ref') == plan.destination_ref
                 and record.get('push_url_hashes') == [hashlib.sha256(url.encode('utf-8')).hexdigest() for url in plan.push_urls])))
            if route_matches:
                tip = self.push_tracking_state(repo, plan)['oid']
        except (GitError, OSError, ValueError):
            pass
        if tip:
            for oid, published in self._history_membership(repo, oids, tip).items():
                result[oid]['status'] = 'published' if published else 'local'
        if not record:
            return result
        old_head, new_head = record.get('old_head'), record.get('new_head')
        if all(isinstance(oid, str) and re.fullmatch(r'[0-9a-f]{40}|[0-9a-f]{64}', oid)
               for oid in (old_head, new_head)):
            try:
                rewritten = self._squash_git(repo, ['rev-list', '--max-count=2001', new_head, '^' + old_head]).decode('ascii').splitlines()
                if len(rewritten) <= 2000:
                    for oid in rewritten:
                        if oid in result and result[oid]['status'] != 'published':
                            result[oid]['status'] = 'rewrite_pending'
            except (GitError, OSError, UnicodeError, ValueError):
                pass
        metadata = self.squash_provenance(repo, record, provenance)
        entries = [entry for entry in metadata['entries'] if entry['oid'] in result]
        originals = [oid for entry in entries if entry.get('is_squash', True) for oid in (entry['original_oids'] or [])]
        membership = self._history_membership(repo, originals, record.get('expected_remote_oid'))
        for entry in entries:
            row, source = result[entry['oid']], entry['original_oids']
            row['is_squash'] = entry.get('is_squash', True)
            if row['status'] != 'published':
                row['status'] = 'rewrite_pending'
            if row['is_squash'] and source is not None:
                row['original_count'] = len(source)
                if all(oid in membership for oid in source):
                    row['published_count'] = sum(membership[oid] for oid in source)
                    row['local_count'] = len(source) - row['published_count']
        return result

    def _squash_git(self, repo, args, data=None, identity=None, limit=16 * 1024 * 1024):
        """Bounded binary plumbing; never selects or writes a worktree/index."""
        environment = os.environ.copy()
        for key, value in self.environment.items():
            if value is None:
                environment.pop(key, None)
            else:
                environment[key] = str(value)
        for key in tuple(environment):
            if key in {'GIT_DIR', 'GIT_WORK_TREE', 'GIT_INDEX_FILE', 'GIT_COMMON_DIR',
                       'GIT_OBJECT_DIRECTORY', 'GIT_ALTERNATE_OBJECT_DIRECTORIES', 'GIT_NAMESPACE',
                       'GIT_REPLACE_REF_BASE', 'GIT_CURL_VERBOSE'} or key.startswith(('GIT_TRACE', 'GCM_TRACE')):
                environment.pop(key, None)
        environment.update(GIT_OPTIONAL_LOCKS='0', GIT_NO_REPLACE_OBJECTS='1',
                           GIT_TERMINAL_PROMPT='0', GCM_INTERACTIVE='never')
        environment.update(identity or {})
        command = [self.git_exe, '--no-pager', '-c', 'color.ui=false', '-c', 'core.quotepath=false',
                   *self.auth_options, '-C', str(repo), *args]
        try:
            with tempfile.TemporaryFile() as output:
                flags = subprocess.CREATE_NO_WINDOW if os.name == 'nt' else 0
                if _task_cancel_event() is not None:
                    result = _cancellable_read_process(command, output=output, environment=environment,
                                                       timeout=120, flags=flags, data=data)
                else:
                    result = subprocess.run(command, input=data, stdin=subprocess.DEVNULL if data is None else None,
                                            stdout=output, stderr=subprocess.PIPE,
                                            env=environment, timeout=120, shell=False, creationflags=flags)
                output.seek(0); raw = output.read(limit + 1)
        except (OSError, subprocess.TimeoutExpired) as error:
            raise GitError(_git_safe_text(f'Operacja scalania historii nie została potwierdzona: {error}')) from None
        if result.returncode:
            raise GitError(_git_safe_text(result.stderr.decode('utf-8', 'replace').strip()
                                         or 'Git odrzucił operację scalania historii.')[:6000])
        if len(raw) > limit:
            raise GitError('Historia przekracza limit bezpiecznego przetwarzania. Wybierz krótszy zakres.')
        return raw

    def _revert_context(self, repo):
        source_ref = self._optional(repo, ['symbolic-ref', '--quiet', 'HEAD'])
        head_oid = self._optional(repo, ['rev-parse', '--verify', 'HEAD'])
        if not source_ref.startswith('refs/heads/') or not head_oid:
            raise GitError('Revert wymaga aktywnej lokalnej gałęzi z co najmniej jednym commitem.')
        return source_ref, head_oid

    def _revert_operation(self, repo, *, pending=False):
        git_dir = Path(self.run(repo, ['rev-parse', '--absolute-git-dir']).strip())
        markers = ('rebase-merge', 'rebase-apply', 'MERGE_HEAD', 'CHERRY_PICK_HEAD',
                   'BISECT_LOG', 'index.lock', 'HEAD.lock')
        if not pending:
            markers += ('REVERT_HEAD', 'sequencer')
        if any((git_dir / marker).exists() for marker in markers):
            raise GitError('Zakończ bieżącą operację Git przed rozpoczęciem lub anulowaniem revertu.')
        return git_dir

    def prepare_revert(self, repo, oid):
        """Pin one reachable commit and its branch before creating an inverse commit."""
        if not isinstance(oid, str) or not re.fullmatch(r'[0-9a-fA-F]{40}|[0-9a-fA-F]{64}', oid):
            raise GitError('Wybierz jeden commit do revertu.')
        repo = self.root(repo)
        source_ref, head_oid = self._revert_context(repo)
        self._revert_operation(repo)
        if self.run(repo, ['status', '--porcelain=v1', '-z', '--untracked-files=all', '--ignore-submodules=none']):
            raise GitError('Przed revertem zapisz lub odłóż wszystkie zmiany, także nowe pliki i konflikty.')
        oid = oid.lower()
        if self._execute(repo, ['merge-base', '--is-ancestor', oid, head_oid], allowed=(0, 1))[0]:
            raise GitError('Wybrany commit nie należy do historii bieżącej gałęzi. Odśwież historię i wybierz commit ponownie.')
        commit = self.commit_diff(repo, oid).details
        return RevertPlan(repo, source_ref, head_oid, commit, 1 if len(commit.parents) > 1 else None)

    def prepare_revert_abort(self, repo):
        """Review the one pending revert, including one found after restarting the app."""
        repo = self.root(repo)
        source_ref, head_oid = self._revert_context(repo)
        git_dir = self._revert_operation(repo, pending=True)
        oid = self._optional(repo, ['rev-parse', '--verify', 'REVERT_HEAD'])
        if not re.fullmatch(r'[0-9a-f]{40}|[0-9a-f]{64}', oid):
            raise GitError('Nie znaleziono trwającego revertu. Odśwież stan repozytorium.')
        sequencer = git_dir / 'sequencer'
        if sequencer.exists():
            try:
                original = (sequencer / 'head').read_text(encoding='ascii').strip()
                safety = (sequencer / 'abort-safety').read_text(encoding='ascii').strip()
                todo = [line.split() for line in (sequencer / 'todo').read_text(encoding='utf-8').splitlines()
                        if line.strip() and not line.lstrip().startswith('#')]
                valid = (original == safety == head_oid and len(todo) == 1 and len(todo[0]) >= 2
                         and todo[0][0] == 'revert' and re.fullmatch(r'[0-9a-fA-F]{4,64}', todo[0][1]))
                if valid:
                    valid = self._optional(repo, ['rev-parse', '--verify', todo[0][1] + '^{commit}']) == oid
            except (OSError, UnicodeError):
                valid = False
            if not valid:
                raise GitError('Trwająca sekwencja Git obejmuje inny stan lub więcej commitów. Dokończ ją albo anuluj w Git.')
        commit = self.commit_diff(repo, oid).details
        return RevertPlan(repo, source_ref, head_oid, commit, 1 if len(commit.parents) > 1 else None)

    def revert(self, repo, plan):
        if not isinstance(plan, RevertPlan):
            raise GitError('Najpierw przygotuj podgląd revertu jednego commita.')
        if self.prepare_revert(repo, plan.commit.oid) != plan:
            raise GitError('Gałąź lub historia zmieniła się od podglądu revertu. Otwórz podgląd ponownie.')
        args = ['revert', '--no-edit']
        if plan.mainline is not None:
            args += ['--mainline', str(plan.mainline)]
        args += ['--', plan.commit.oid]

        def paused(output):
            try:
                pending = self.prepare_revert_abort(repo)
            except GitError:
                return None
            if pending != plan:
                return None
            message = ('Revert nie został zakończony. Rozwiąż konflikty i utwórz commit albo wybierz „Anuluj revert”.'
                       + ('\n\n' + _git_safe_text(output).strip()[-6000:] if output else ''))
            return RevertResult(plan.head_oid, plan.head_oid, plan.commit.oid, True, message)

        try:
            code, output = self._execute(repo, args, timeout=120, allowed=(0, 1, 128))
        except GitError as error:
            result = paused(str(error))
            if result is not None:
                return result
            raise
        if code:
            result = paused(output)
            if result is not None:
                return result
            raise GitError(_git_safe_text(output).strip()[-6000:] or 'Git nie zakończył revertu. Odśwież stan repozytorium.')
        source_ref, new_head = self._revert_context(repo)
        parent = self._optional(repo, ['rev-parse', '--verify', new_head + '^'])
        if source_ref != plan.source_ref or new_head == plan.head_oid or parent != plan.head_oid:
            raise GitError('Git zakończył revert, ale gałąź zmieniła się podczas operacji. Odśwież historię przed kolejną próbą.')
        return RevertResult(plan.head_oid, new_head, plan.commit.oid)

    def abort_revert(self, repo, plan):
        if not isinstance(plan, RevertPlan) or self.prepare_revert_abort(repo) != plan:
            raise GitError('Trwający revert lub gałąź zmieniły się od podglądu. Nie anulowano innej operacji Git.')
        result = self.run(repo, ['revert', '--abort'], timeout=120)
        if (self._revert_context(repo) != (plan.source_ref, plan.head_oid)
                or self._optional(repo, ['rev-parse', '--verify', 'REVERT_HEAD'])):
            raise GitError('Git nie potwierdził anulowania revertu. Odśwież stan repozytorium.')
        return result

    def _squash_state(self, repo):
        def read(args):
            return self._squash_git(repo, args).decode('utf-8', 'strict').strip()
        source_ref = read(['symbolic-ref', '--quiet', 'HEAD'])
        if not source_ref.startswith('refs/heads/'):
            raise GitError('Scalanie wymaga aktywnej lokalnej gałęzi, nie detached HEAD.')
        head = read(['rev-parse', '--verify', 'HEAD'])
        git_dir = Path(read(['rev-parse', '--absolute-git-dir']))
        common_dir = Path(read(['rev-parse', '--path-format=absolute', '--git-common-dir']))
        markers = ('rebase-merge', 'rebase-apply', 'MERGE_HEAD', 'CHERRY_PICK_HEAD',
                   'REVERT_HEAD', 'BISECT_LOG', 'sequencer', 'index.lock', 'HEAD.lock')
        if any((git_dir / marker).exists() for marker in markers):
            raise GitError('Zakończ bieżącą operację Git przed scaleniem historii.')
        if (common_dir / 'info' / 'grafts').exists() or read(['for-each-ref', '--format=%(refname)', 'refs/replace/']):
            raise GitError('Scalanie historii z grafts lub replace refs nie jest obsługiwane.')
        if read(['rev-parse', '--is-shallow-repository']) == 'true':
            raise GitError('Najpierw pobierz pełną historię płytkiego repozytorium.')
        if read(['rev-parse', '--show-ref-format']) != 'files':
            raise GitError('Scalanie wymaga repozytorium z klasycznym formatem refs=files i aktualnego Gita.')
        status = self._squash_git(repo, ['status', '--porcelain=v1', '-z', '--untracked-files=all', '--ignore-submodules=none'])
        if status:
            entries, paths, count = iter(status.split(b'\0')), [], 0
            for entry in entries:
                if not entry:
                    continue
                if len(entry) < 4 or entry[2:3] != b' ':
                    raise GitError('Przed scaleniem zapisz lub odłóż wszystkie zmiany, także nowe pliki i konflikty.')
                # Porcelain -z gives a rename's destination first, then its
                # original path as a separate NUL-delimited field. JSON quotes
                # keep newlines and other control characters inside a filename.
                path = json.dumps(entry[3:].decode('utf-8', 'replace'), ensure_ascii=False)
                if b'R' in entry[:2] or b'C' in entry[:2]:
                    original = next(entries, b'')
                    path = json.dumps(original.decode('utf-8', 'replace'), ensure_ascii=False) + ' → ' + path
                count += 1
                if len(paths) < 8:
                    paths.append('- ' + path)
            details = f'Zmienione lub nowe pliki: {count}.\n' + '\n'.join(paths)
            if count > len(paths):
                details += f'\n… i jeszcze {count - len(paths)}.'
            raise GitError('Przed scaleniem zapisz lub odłóż wszystkie zmiany, także nowe pliki i konflikty.\n\n' + details)
        return source_ref, head

    def _squash_commits(self, repo, oids):
        """Read exact messages and identities in one bounded cat-file batch."""
        raw = self._squash_git(repo, ['cat-file', '--batch'], ''.join(oid + '\n' for oid in oids).encode('ascii'))
        records, position = [], 0
        try:
            for expected in oids:
                end = raw.index(b'\n', position)
                oid, kind, size = raw[position:end].split()
                size = int(size); position = end + 1
                if oid.decode('ascii') != expected or kind != b'commit' or size > 1024 * 1024 or size < 0:
                    raise ValueError('unsupported object')
                payload = raw[position:position + size]; position += size
                if len(payload) != size or raw[position:position + 1] != b'\n':
                    raise ValueError('incomplete object')
                position += 1
                headers, message = payload.split(b'\n\n', 1)
                fields, last_key = {}, None
                for line in headers.split(b'\n'):
                    if line.startswith(b' ') and last_key in (b'gpgsig', b'gpgsig-sha256'):
                        continue
                    key, value = line.split(b' ', 1); last_key = key
                    if key not in (b'tree', b'parent', b'author', b'committer', b'encoding', b'gpgsig', b'gpgsig-sha256'):
                        raise ValueError('unsupported commit header')
                    fields.setdefault(key, []).append(value)
                encoding = fields.get(b'encoding', [b'UTF-8'])
                if len(encoding) != 1 or encoding[0].lower().replace(b'-', b'') != b'utf8':
                    raise ValueError('non-UTF-8 commit')
                tree, = fields[b'tree']
                tree = tree.decode('ascii')
                parents = tuple(value.decode('ascii') for value in fields.get(b'parent', []))
                if not all(re.fullmatch(r'[0-9a-f]{40}|[0-9a-f]{64}', value) for value in (tree, *parents)):
                    raise ValueError('invalid object id')
                identities = []
                for key in (b'author', b'committer'):
                    value, = fields[key]
                    match = re.fullmatch(rb'([^\r\n<>]*) <([^\r\n<>]*)> (-?\d+) ([+-]\d{4})', value)
                    if not match:
                        raise ValueError('invalid identity')
                    name, email = match[1].decode('utf-8'), match[2].decode('utf-8')
                    seconds, zone = int(match[3]), match[4].decode('ascii')
                    hours, minutes = int(zone[1:3]), int(zone[3:])
                    if hours > 23 or minutes > 59:
                        raise ValueError('invalid timezone')
                    offset = datetime.timedelta(minutes=(hours * 60 + minutes) * (1 if zone[0] == '+' else -1))
                    date = datetime.datetime.fromtimestamp(seconds, datetime.timezone(offset)).isoformat()
                    identities.append((name, email, date))
                text = message.decode('utf-8')
                if '\0' in text or not all(name and email for name, email, _ in identities):
                    raise ValueError('unsupported identity/message')
                details = CommitDetails(expected, *identities[0], *identities[1], parents, text)
                records.append((details, tree, message, bool(fields.get(b'gpgsig') or fields.get(b'gpgsig-sha256'))))
            if position != len(raw):
                raise ValueError('unexpected batch data')
        except (ValueError, KeyError, UnicodeError, OverflowError, OSError):
            raise GitError('Commit ma nieobsługiwane metadane, kodowanie lub zbyt długi opis. Historia pozostała bez zmian.') from None
        return tuple(records)

    def prepare_squash(self, repo, oids):
        if isinstance(oids, (str, bytes)):
            raise GitError('Wybierz co najmniej dwa kolejne commity.')
        selected_oids = tuple(oids)
        if not 2 <= len(selected_oids) <= 500 or any(not isinstance(oid, str) or
                not re.fullmatch(r'[0-9a-fA-F]{40}|[0-9a-fA-F]{64}', oid) for oid in selected_oids):
            raise GitError('Wybierz od 2 do 500 kolejnych commitów z historii bieżącej gałęzi.')
        selected_oids = tuple(oid.lower() for oid in selected_oids)
        if len(set(selected_oids)) != len(selected_oids):
            raise GitError('Zakres scalania zawiera powtórzone commity.')
        repo = self.root(repo)
        source_ref, head_oid = self._squash_state(repo)
        history = self._squash_git(repo, ['rev-list', '--first-parent', '--parents', '--max-count=2001', head_oid]).decode('ascii').splitlines()
        chain = [line.split() for line in history]
        positions = {fields[0]: index for index, fields in enumerate(chain)}
        if any(oid not in positions for oid in selected_oids):
            raise GitError('Wybrane commity nie tworzą zakresu w ostatnich 2000 commitach pierwszej linii rodziców tej gałęzi.')
        indexes = sorted(positions[oid] for oid in selected_oids)
        if indexes != list(range(indexes[0], indexes[-1] + 1)) or indexes[-1] >= 2000:
            raise GitError('Wybierz ciągły zakres commitów bez przerw, blisko końca historii.')
        affected = chain[:indexes[-1] + 1]
        if any(len(fields) > 2 for fields in affected):
            raise GitError('Zakres scalania ani późniejsze commity do HEAD nie mogą zawierać merge commitów.')
        ordered = tuple(fields[0] for fields in reversed(affected))
        records = self._squash_commits(repo, ordered)
        for previous, current in zip(records, records[1:]):
            if current[0].parents != (previous[0].oid,):
                raise GitError('Historia nie jest liniowa. Odśwież zakres przed scaleniem.')
        count = len(selected_oids)
        selected = tuple(record[0] for record in records[:count])
        descendants = tuple(record[0] for record in records[count:])
        base_oid = selected[0].parents[0] if selected[0].parents else ''
        if len(selected[0].parents) > 1 or {item.oid for item in selected} != set(selected_oids):
            raise GitError('Zakres scalania nie odpowiada bieżącej historii.')
        default = '\n\n'.join(item.message.rstrip('\n') for item in selected).strip()
        return SquashPlan(repo, head_oid, source_ref, base_oid, selected, descendants,
                          tuple(record[1] for record in records), default,
                          tuple(record[0].oid for record in records if record[3]))

    def squash(self, repo, plan, message, before_update=None):
        """Rewrite linear commit objects, then atomically move only the branch ref."""
        import uuid
        if not isinstance(plan, SquashPlan):
            raise GitError('Najpierw przygotuj podgląd scalania commitów.')
        if not isinstance(message, str) or not message.strip() or '\0' in message or len(message.encode('utf-8')) > 1024 * 1024:
            raise GitError('Podaj niepusty opis nowego commita, nie dłuższy niż 1 MB.')
        current = self.prepare_squash(repo, tuple(item.oid for item in plan.selected))
        if current != plan:
            raise GitError('Gałąź lub historia zmieniła się od przygotowania podglądu. Wybierz zakres ponownie.')
        records = self._squash_commits(plan.repo, tuple(item.oid for item in plan.selected + plan.descendants))
        parent, rewritten = plan.base_oid, []
        create = [(records[0][0], plan.trees[len(plan.selected) - 1], message.strip().encode('utf-8') + b'\n', False)]
        create.extend((details, tree, raw_message, True) for details, tree, raw_message, _ in records[len(plan.selected):])
        squash_oid = ''
        for details, tree, raw_message, replay in create:
            identity = {'GIT_AUTHOR_NAME': details.author, 'GIT_AUTHOR_EMAIL': details.author_email,
                        'GIT_AUTHOR_DATE': details.author_date}
            if replay:
                identity.update(GIT_COMMITTER_NAME=details.committer, GIT_COMMITTER_EMAIL=details.committer_email,
                                GIT_COMMITTER_DATE=details.commit_date)
            args = ['-c', 'i18n.commitEncoding=UTF-8', 'commit-tree', tree, '--no-gpg-sign']
            if parent:
                args += ['-p', parent]
            oid = self._squash_git(plan.repo, args, raw_message, identity).decode('ascii').strip()
            if not re.fullmatch(r'[0-9a-f]{40}|[0-9a-f]{64}', oid):
                raise GitError('Git nie potwierdził utworzenia nowego commita. Gałąź pozostała bez zmian.')
            if not squash_oid:
                squash_oid = oid
                rewritten.extend((item.oid, oid) for item in plan.selected)
            else:
                rewritten.append((details.oid, oid))
            parent = oid
        final_tree = self._squash_git(plan.repo, ['rev-parse', parent + '^{tree}']).decode('ascii').strip()
        if final_tree != plan.trees[-1] or self._squash_state(plan.repo) != (plan.source_ref, plan.head_oid):
            raise GitError('Stan repozytorium zmienił się podczas scalania. Gałąź pozostała bez zmian.')
        backup = 'refs/gitline/undo/squash/' + datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ-') + uuid.uuid4().hex
        git_dir = Path(self._squash_git(plan.repo, ['rev-parse', '--absolute-git-dir']).decode('utf-8').strip()).resolve()
        common_dir = Path(self._squash_git(plan.repo, ['rev-parse', '--path-format=absolute', '--git-common-dir']).decode('utf-8').strip()).resolve()
        transaction = (f'start\noption no-deref\ncreate {backup} {plan.head_oid}\n'
                       f'update {plan.source_ref} {parent} {plan.head_oid}\nprepare\ncommit\n')
        result = SquashResult(plan.head_oid, parent, squash_oid, backup, tuple(rewritten))
        if before_update is not None:
            before_update(result)
        try:
            # Git otherwise adds an implicit HEAD reflog update for the current
            # branch, conflicting with explicit symref verification. A detached
            # temporary Git directory shares objects/refs but has no index.
            head_lock = git_dir / 'HEAD.lock'
            acquired = False
            try:
                # A native files-backend HEAD lock also excludes Git checkout.
                # The detached plumbing context avoids a second implicit lock.
                with head_lock.open('xb'):
                    acquired = True
                    actual_head = (git_dir / 'HEAD').read_bytes().rstrip(b'\r\n')
                    if actual_head != ('ref: ' + plan.source_ref).encode('utf-8'):
                        raise GitError('Aktywna gałąź zmieniła się podczas scalania. Historia pozostała bez zmian.')
                    with tempfile.TemporaryDirectory(prefix='gitline-squash-refs-') as temporary:
                        isolated = Path(temporary)
                        (isolated / 'HEAD').write_text(plan.head_oid + '\n', encoding='ascii')
                        (isolated / 'commondir').write_text(common_dir.as_posix() + '\n', encoding='utf-8')
                        self._squash_git(plan.repo, ['--git-dir=' + str(isolated), 'update-ref', '--stdin', '--create-reflog',
                                                     '-m', 'Gitline: squash commits'], transaction.encode('utf-8'))
            except OSError as error:
                raise GitError(_git_safe_text(f'Nie udało się zablokować HEAD podczas scalania: {error}')) from None
            finally:
                if acquired:
                    try:
                        head_lock.unlink()
                    except OSError:
                        pass
        except GitError as error:
            # A timeout after commit acknowledgement must not report a rollback.
            try:
                actual = self._squash_git(plan.repo, ['rev-parse', '--verify', plan.source_ref]).decode('ascii').strip()
                saved = self._squash_git(plan.repo, ['rev-parse', '--verify', backup]).decode('ascii').strip()
            except GitError:
                raise GitError(f'Nie potwierdzono zmiany historii. Odśwież repozytorium; punkt odzyskiwania: {backup}\n{error}') from None
            if actual != parent or saved != plan.head_oid:
                raise GitError(f'Git nie potwierdził scalania. Sprawdź bieżącą gałąź; punkt odzyskiwania: {backup}\n{error}') from None
        return result

    def _undo_state(self, repo, *, locked=False, operation='Undo'):
        """Inspect history safety without refreshing or modifying the index."""
        def read(args):
            return self._squash_git(repo, args).decode('utf-8', 'strict').strip()
        source = self._optional(repo, ['symbolic-ref', '--quiet', '--no-recurse', 'HEAD'])
        if not source.startswith('refs/heads/') or self._optional(repo, ['symbolic-ref', '--quiet', source]):
            raise GitError(f'Operacja „{operation}” wymaga aktywnej lokalnej gałęzi, nie detached HEAD ani odsyłacza do innej gałęzi.')
        head = self._optional(repo, ['rev-parse', '--verify', 'HEAD^{commit}'])
        if not head:
            raise GitError('Ta gałąź nie ma jeszcze commita.')
        git_dir = Path(read(['rev-parse', '--absolute-git-dir'])).resolve()
        common_dir = Path(read(['rev-parse', '--path-format=absolute', '--git-common-dir'])).resolve()
        markers = ('rebase-merge', 'rebase-apply', 'MERGE_HEAD', 'CHERRY_PICK_HEAD',
                   'REVERT_HEAD', 'BISECT_LOG', 'sequencer') + (() if locked else ('index.lock', 'HEAD.lock'))
        if any((git_dir / marker).exists() for marker in markers):
            raise GitError(f'Zakończ bieżącą operację Git przed operacją „{operation}”.')
        if self._squash_git(repo, ['ls-files', '--unmerged', '-z']):
            raise GitError(f'Rozwiąż konflikty w indeksie przed operacją „{operation}”.')
        if read(['rev-parse', '--is-shallow-repository']) == 'true':
            raise GitError(f'Przed operacją „{operation}” pobierz pełną historię płytkiego repozytorium.')
        if (common_dir / 'info' / 'grafts').exists() or read(['for-each-ref', '--format=%(refname)', 'refs/replace/']):
            raise GitError(f'Operacja „{operation}” nie obsługuje historii zmienionej przez grafts lub replace refs.')
        if read(['rev-parse', '--show-ref-format']) != 'files':
            raise GitError(f'Operacja „{operation}” wymaga aktualnego Gita i repozytorium z klasycznym formatem refs=files.')
        return source, head, git_dir, common_dir

    def prepare_reword(self, repo, oid):
        """Review a message-only edit of the current branch tip, even when dirty."""
        if not isinstance(oid, str) or not re.fullmatch(r'[0-9a-fA-F]{40}|[0-9a-fA-F]{64}', oid):
            raise GitError('Wybierz jeden, ostatni commit bieżącej gałęzi do zmiany opisu.')
        repo = self.root(repo)
        source, head, _, _ = self._undo_state(repo, operation='Zmień nazwę i opis')
        if oid.lower() != head:
            raise GitError('Zmiana nazwy i opisu działa tylko na ostatnim commicie bieżącej gałęzi (HEAD).')
        commit, tree, _, signed = self._squash_commits(repo, (head,))[0]
        return RewordPlan(repo, source, head, commit, tree, signed)

    def reword(self, repo, plan, message, before_update=None):
        """Replace only HEAD's message; keep its tree, parents and author intact."""
        import uuid
        if not isinstance(plan, RewordPlan):
            raise GitError('Najpierw przygotuj zmianę nazwy i opisu ostatniego commita.')
        try:
            raw_message = message.strip().encode('utf-8') + b'\n' if isinstance(message, str) else b''
        except UnicodeError:
            raw_message = b''
        if not raw_message.strip() or b'\0' in raw_message or len(raw_message) > 1024 * 1024:
            raise GitError('Podaj niepustą nazwę i opis commita, nie dłuższe niż 1 MB.')
        current = self.prepare_reword(repo, plan.head_oid)
        if current != plan:
            raise GitError('Gałąź lub commit zmieniły się od otwarcia okna. Otwórz zmianę opisu ponownie.')
        args = ['-c', 'i18n.commitEncoding=UTF-8', 'commit-tree', plan.tree_oid, '--no-gpg-sign']
        for parent in plan.commit.parents:
            args += ['-p', parent]
        identity = {'GIT_AUTHOR_NAME': plan.commit.author, 'GIT_AUTHOR_EMAIL': plan.commit.author_email,
                    'GIT_AUTHOR_DATE': plan.commit.author_date}
        new_head = self._squash_git(plan.repo, args, raw_message, identity).decode('ascii').strip()
        if not re.fullmatch(r'[0-9a-f]{40}|[0-9a-f]{64}', new_head):
            raise GitError('Git nie potwierdził utworzenia commita z nowym opisem. Historia pozostała bez zmian.')
        replacement = self._squash_commits(plan.repo, (new_head,))[0]
        if (replacement[1] != plan.tree_oid or replacement[0].parents != plan.commit.parents
                or (replacement[0].author, replacement[0].author_email, replacement[0].author_date)
                != (plan.commit.author, plan.commit.author_email, plan.commit.author_date)):
            raise GitError('Nie potwierdzono zachowania zawartości i autora commita. Historia pozostała bez zmian.')
        _, _, git_dir, common_dir = self._undo_state(plan.repo, operation='Zmień nazwę i opis')
        backup = 'refs/gitline/undo/reword/' + datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ-') + uuid.uuid4().hex
        transaction = (f'start\noption no-deref\ncreate {backup} {plan.head_oid}\n'
                       f'update {plan.source_ref} {new_head} {plan.head_oid}\nprepare\ncommit\n')
        result = RewordResult(plan.head_oid, new_head, backup)
        if before_update is not None:
            before_update(result)
        acquired, attempted = [], False
        try:
            with contextlib.ExitStack() as locks:
                for name in ('HEAD.lock', 'index.lock'):
                    path = git_dir / name
                    locks.enter_context(path.open('xb')); acquired.append(path)
                state = self._undo_state(plan.repo, locked=True, operation='Zmień nazwę i opis')
                actual_head = (git_dir / 'HEAD').read_bytes().rstrip(b'\r\n')
                if (state[:2] != (plan.source_ref, plan.head_oid)
                        or actual_head != ('ref: ' + plan.source_ref).encode('utf-8')):
                    raise GitError('Aktywna gałąź lub HEAD zmieniły się podczas edycji opisu. Historia pozostała bez zmian.')
                # The detached plumbing directory shares only objects/refs.
                # Native locks protect the real HEAD and exact index bytes.
                with tempfile.TemporaryDirectory(prefix='gitline-reword-refs-') as temporary:
                    isolated = Path(temporary)
                    (isolated / 'HEAD').write_text(plan.head_oid + '\n', encoding='ascii')
                    (isolated / 'commondir').write_text(common_dir.as_posix() + '\n', encoding='utf-8')
                    attempted = True
                    self._squash_git(plan.repo, ['--git-dir=' + str(isolated), 'update-ref', '--stdin',
                                                '--create-reflog', '-m', 'Gitline: edit commit message'], transaction.encode('utf-8'))
        except (GitError, OSError) as error:
            if attempted:
                actual = self._optional(plan.repo, ['rev-parse', '--verify', plan.source_ref])
                saved = self._optional(plan.repo, ['rev-parse', '--verify', backup])
                if actual == new_head and saved == plan.head_oid:
                    return result
                raise GitError(f'Nie potwierdzono zmiany opisu. Odśwież historię; punkt odzyskiwania: {backup}\n{error}') from None
            if isinstance(error, GitError):
                raise
            raise GitError(_git_safe_text(f'Nie udało się zablokować repozytorium do zmiany opisu: {error}')) from None
        finally:
            for path in reversed(acquired):
                try: path.unlink()
                except OSError: pass
        return result

    def _undo_publication_notice(self, repo, head):
        published = self._squash_git(repo, ['for-each-ref', '--contains=' + head,
                                          '--format=%(refname)', 'refs/remotes/']).strip()
        if published:
            raise GitError('Ten commit jest opublikowany według ostatnio pobranego stanu serwera. Użyj Revert, aby zachować wspólną historię.')
        if not self.run(repo, ['remote']).strip():
            return 'Repozytorium nie ma skonfigurowanych serwerów; Undo zmieni wyłącznie lokalną gałąź.'
        unknown = ('Nie można potwierdzić, że ten commit jest lokalny dla wybranego celu wysyłania. '
                   'Pobierz zmiany (Fetch), sprawdź serwer i gałąź śledzoną albo użyj Revert.')
        try:
            push_plan = self.resolve_push_plan(repo)
            if push_plan.head_oid != head:
                raise GitError(unknown)
            tracking = self.push_tracking_state(repo, push_plan)
            if not tracking['oid'] or self._history_membership(repo, [head], tracking['oid']).get(head) is not False:
                raise GitError(unknown)
        except GitError:
            raise GitError(unknown) from None
        return 'Commit jest lokalny dla wybranego celu wysyłania według ostatnio pobranego stanu serwera. Undo nie zmieni serwera.'

    def prepare_undo(self, repo, oid):
        """Review removal of exactly the current commit, retaining all file state."""
        if not isinstance(oid, str) or not re.fullmatch(r'[0-9a-fA-F]{40}|[0-9a-fA-F]{64}', oid):
            raise GitError('Wybierz jeden commit do Undo.')
        repo = self.root(repo)
        source, head, _, _ = self._undo_state(repo)
        if oid.lower() != head:
            raise GitError('Undo działa tylko na ostatnim commicie bieżącej gałęzi (HEAD). Dla wcześniejszego commita użyj Revert.')
        format_ = '%H%x00%an%x00%ae%x00%aI%x00%cn%x00%ce%x00%cI%x00%P%x00%B'
        fields = self._squash_git(repo, ['show', '--no-patch', '--no-notes', '--encoding=UTF-8',
                                       '--format=format:' + format_, head, '--']).decode('utf-8', 'replace').split('\0', 8)
        if len(fields) != 9 or fields[0] != head:
            raise GitError('Nie udało się odczytać commita do Undo. Odśwież historię.')
        commit = CommitDetails(*fields[:7], tuple(fields[7].split()), fields[8].strip())
        target = commit.parents[0] if commit.parents else ''
        if target:
            self._squash_git(repo, ['cat-file', '-e', target + '^{commit}'])
        notice = self._undo_publication_notice(repo, head)
        return UndoPlan(repo, source, head, commit, target, notice)

    def undo(self, repo, plan, before_update=None):
        """Atomically back up and move HEAD's branch; never write file contents."""
        import uuid
        if not isinstance(plan, UndoPlan):
            raise GitError('Najpierw przygotuj podgląd Undo jednego commita.')
        current = self.prepare_undo(repo, plan.head_oid)
        if current != plan:
            raise GitError('Gałąź, commit lub stan publikacji zmieniły się od podglądu. Przygotuj Undo ponownie.')
        _, _, git_dir, common_dir = self._undo_state(plan.repo)
        backup = 'refs/gitline/undo/commit/' + datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ-') + uuid.uuid4().hex
        move = (f'update {plan.source_ref} {plan.target_oid} {plan.head_oid}\n' if plan.target_oid
                else f'delete {plan.source_ref} {plan.head_oid}\n')
        transaction = f'start\noption no-deref\ncreate {backup} {plan.head_oid}\n' + move + 'prepare\ncommit\n'
        result = UndoResult(plan.head_oid, plan.target_oid, backup)
        if before_update is not None:
            before_update(result)
        acquired, attempted = [], False
        try:
            with contextlib.ExitStack() as locks:
                for name in ('HEAD.lock', 'index.lock'):
                    path = git_dir / name
                    locks.enter_context(path.open('xb')); acquired.append(path)
                state = self._undo_state(plan.repo, locked=True)
                actual_head = (git_dir / 'HEAD').read_bytes().rstrip(b'\r\n')
                if (state[:2] != (plan.source_ref, plan.head_oid)
                        or actual_head != ('ref: ' + plan.source_ref).encode('utf-8')):
                    raise GitError('Aktywna gałąź lub HEAD zmieniły się podczas Undo. Historia pozostała bez zmian.')
                self._undo_publication_notice(plan.repo, plan.head_oid)
                # A detached plumbing directory avoids Git's implicit second
                # HEAD lock; the real HEAD/index stay locked throughout the CAS.
                with tempfile.TemporaryDirectory(prefix='gitline-undo-refs-') as temporary:
                    isolated = Path(temporary)
                    (isolated / 'HEAD').write_text(plan.head_oid + '\n', encoding='ascii')
                    (isolated / 'commondir').write_text(common_dir.as_posix() + '\n', encoding='utf-8')
                    attempted = True
                    self._squash_git(plan.repo, ['--git-dir=' + str(isolated), 'update-ref', '--stdin',
                                                '--create-reflog', '-m', 'Gitline: undo commit'], transaction.encode('utf-8'))
        except (GitError, OSError) as error:
            if attempted:
                actual = self._optional(plan.repo, ['rev-parse', '--verify', plan.source_ref])
                saved = self._optional(plan.repo, ['rev-parse', '--verify', backup])
                if actual == plan.target_oid and saved == plan.head_oid:
                    return result
                raise GitError(f'Nie potwierdzono Undo. Odśwież historię; punkt odzyskiwania: {backup}\n{error}') from None
            if isinstance(error, GitError):
                raise
            raise GitError(_git_safe_text(f'Nie udało się zablokować repozytorium do Undo: {error}')) from None
        finally:
            for path in reversed(acquired):
                try: path.unlink()
                except OSError: pass
        return result

    def stash(self, repo, message=""):
        if not self._has_head(repo):
            raise GitError("Przed odłożeniem zmian utwórz pierwszy commit.")
        return self.run(repo, ["stash", "push", "--include-untracked", "-m", message.strip() or f"{APP_NAME} stash"])

    def stash_pop(self, repo):
        return self.run(repo, ["stash", "pop"])

    def set_identity(self, repo, name, email):
        name, email = name.strip(), email.strip()
        if not name or not email or any(character in name + email for character in "\r\n\0<>"):
            raise GitError("Podaj nazwę autora i adres e-mail bez znaków nowego wiersza oraz nawiasów < i >.")
        self.run(repo, ["config", "--local", "user.name", name])
        self.run(repo, ["config", "--local", "user.email", email])


def self_test_revert():
    """Revert one commit in disposable repositories, including conflict recovery."""
    checks = []
    def checked(name, condition):
        if not condition: raise AssertionError(name)
        checks.append(name)

    with tempfile.TemporaryDirectory(prefix='gitline-revert-test-') as directory:
        test_root = Path(directory).resolve()
        backend = GitBackend(
            auth_options=['-c', 'core.hooksPath=' + str(test_root / 'no-hooks'),
                          '-c', 'commit.gpgSign=false', '-c', 'core.autocrlf=false', '-c', 'rerere.enabled=false',
                          '-c', 'init.templateDir=' + str(test_root / 'no-templates')],
            environment={'GIT_CONFIG_GLOBAL': str(test_root / 'empty-config'),
                         'GIT_CONFIG_SYSTEM': str(test_root / 'empty-config'),
                         'GIT_CONFIG_NOSYSTEM': '1', 'GIT_CONFIG_COUNT': '0',
                         'GIT_CONFIG_PARAMETERS': None, 'GIT_CONFIG': None,
                         'GIT_AUTHOR_NAME': 'Gitline Test', 'GIT_AUTHOR_EMAIL': 'gitline-test@example.invalid',
                         'GIT_COMMITTER_NAME': 'Gitline Test', 'GIT_COMMITTER_EMAIL': 'gitline-test@example.invalid'})
        def git(repo, *args):
            return backend.run(repo, list(args)).strip()
        def build(name, versions=('base', 'selected')):
            repo = Path(backend.init_repo(test_root / name))
            oids = []
            for text in versions:
                (repo / 'value.txt').write_text(text + '\n', encoding='utf-8')
                backend.stage(repo, ['value.txt']); backend.commit(repo, text)
                oids.append(git(repo, 'rev-parse', 'HEAD'))
            return repo, oids
        def fingerprint(repo):
            return (git(repo, 'symbolic-ref', 'HEAD'), git(repo, 'show-ref'),
                    (repo / '.git' / 'index').read_bytes(),
                    tuple((path.name, path.read_bytes()) for path in sorted(repo.iterdir()) if path.is_file()))
        def rejected(name, repo, action):
            before = fingerprint(repo)
            try:
                action()
                raise AssertionError(name)
            except GitError:
                checked(name, fingerprint(repo) == before)

        repo, oids = build('tip')
        plan = backend.prepare_revert(repo, oids[-1])
        result = backend.revert(repo, plan)
        checked('tip revert creates one inverse commit and retains the original history',
                not result.conflicted and result.old_head == oids[-1]
                and git(repo, 'rev-parse', 'HEAD^') == oids[-1]
                and git(repo, 'rev-parse', 'HEAD^{tree}') == git(repo, 'rev-parse', oids[0] + '^{tree}')
                and git(repo, 'rev-list', '--count', 'HEAD') == '3')

        repo, oids = build('older-published')
        (repo / 'later.txt').write_text('later unrelated work\n', encoding='utf-8')
        backend.stage(repo, ['later.txt']); backend.commit(repo, 'Later commit')
        old_head = git(repo, 'rev-parse', 'HEAD')
        git(repo, 'update-ref', 'refs/remotes/origin/main', old_head)
        result = backend.revert(repo, backend.prepare_revert(repo, oids[-1]))
        checked('reverting an older published commit keeps newer unrelated changes',
                not result.conflicted and git(repo, 'rev-parse', 'HEAD^') == old_head
                and (repo / 'value.txt').read_text(encoding='utf-8') == 'base\n'
                and (repo / 'later.txt').read_text(encoding='utf-8') == 'later unrelated work\n'
                and git(repo, 'rev-parse', 'refs/remotes/origin/main') == old_head)

        repo, oids = build('root', ('root',))
        plan = backend.prepare_revert(repo, oids[0])
        result = backend.revert(repo, plan)
        checked('root commit revert creates a child with an empty tree',
                plan.mainline is None and not result.conflicted and not git(repo, 'ls-files')
                and git(repo, 'rev-parse', 'HEAD^') == oids[0])

        repo, oids = build('merge', ('base',))
        git(repo, 'switch', '--quiet', '-c', 'side')
        (repo / 'side.txt').write_text('side\n', encoding='utf-8')
        backend.stage(repo, ['side.txt']); backend.commit(repo, 'Side')
        git(repo, 'switch', '--quiet', 'main')
        (repo / 'main.txt').write_text('main\n', encoding='utf-8')
        backend.stage(repo, ['main.txt']); backend.commit(repo, 'Main')
        first_parent = git(repo, 'rev-parse', 'HEAD')
        git(repo, 'merge', '--no-ff', '--no-edit', 'side')
        merge_oid = git(repo, 'rev-parse', 'HEAD')
        plan = backend.prepare_revert(repo, merge_oid)
        result = backend.revert(repo, plan)
        checked('merge revert explicitly uses the first parent and preserves mainline work',
                plan.mainline == 1 and len(plan.commit.parents) == 2 and not result.conflicted
                and git(repo, 'rev-parse', 'HEAD^') == merge_oid
                and git(repo, 'rev-parse', 'HEAD^{tree}') == git(repo, 'rev-parse', first_parent + '^{tree}')
                and (repo / 'main.txt').is_file() and not (repo / 'side.txt').exists())

        repo, oids = build('guards')
        plan = backend.prepare_revert(repo, oids[-1])
        (repo / 'value.txt').write_text('unstaged draft\n', encoding='utf-8')
        rejected('revert rejects worktree changes introduced after its preview', repo, lambda: backend.revert(repo, plan))
        backend.stage(repo, ['value.txt'])
        rejected('revert rejects staged changes without modifying the index', repo,
                 lambda: backend.prepare_revert(repo, oids[-1]))
        git(repo, 'restore', '--source=HEAD', '--staged', '--worktree', '--', 'value.txt')
        (repo / 'new.txt').write_text('untracked draft\n', encoding='utf-8')
        rejected('revert protects untracked files', repo, lambda: backend.prepare_revert(repo, oids[-1]))
        (repo / 'new.txt').unlink()
        git(repo, 'switch', '--quiet', '-c', 'other')
        rejected('revert refuses a switched branch even at the same commit', repo, lambda: backend.revert(repo, plan))
        plan = backend.prepare_revert(repo, oids[-1])
        git(repo, 'commit', '--quiet', '--allow-empty', '-m', 'External commit')
        rejected('revert refuses a plan after HEAD advances', repo, lambda: backend.revert(repo, plan))
        marker = repo / '.git' / 'CHERRY_PICK_HEAD'
        marker.write_text(oids[-1] + '\n', encoding='ascii')
        rejected('revert refuses an unrelated in-progress operation', repo,
                 lambda: backend.prepare_revert(repo, oids[-1]))
        marker.unlink()
        git(repo, 'switch', '--quiet', '-c', 'unrelated', oids[0])
        (repo / 'foreign.txt').write_text('foreign\n', encoding='utf-8')
        backend.stage(repo, ['foreign.txt']); backend.commit(repo, 'Foreign')
        foreign = git(repo, 'rev-parse', 'HEAD')
        git(repo, 'switch', '--quiet', 'other')
        rejected('revert rejects a commit outside the current branch history', repo,
                 lambda: backend.prepare_revert(repo, foreign))
        rejected('revert accepts exactly one commit, not a range or list', repo,
                 lambda: backend.prepare_revert(repo, oids))

        repo, oids = build('conflict', ('base', 'selected', 'later conflicting work'))
        plan = backend.prepare_revert(repo, oids[1])
        original_tree, original_refs = git(repo, 'write-tree'), git(repo, 'show-ref')
        result = backend.revert(repo, plan)
        checked('a conflicting revert returns an actionable pending result without moving HEAD',
                result.conflicted and 'Anuluj revert' in result.message and result.new_head == oids[-1]
                and git(repo, 'rev-parse', 'REVERT_HEAD') == oids[1] and bool(git(repo, 'ls-files', '--unmerged')))
        recovery = backend.prepare_revert_abort(repo)
        checked('a restarted application can review the exact pending revert without a clean tree', recovery == plan)
        wrong = dataclasses.replace(plan, commit=backend.commit_diff(repo, oids[0]).details)
        rejected('abort refuses a different pending commit without changing conflict resolutions', repo,
                 lambda: backend.abort_revert(repo, wrong))
        wrong = dataclasses.replace(plan, source_ref='refs/heads/different')
        rejected('abort refuses a changed branch context', repo, lambda: backend.abort_revert(repo, wrong))
        marker = repo / '.git' / 'CHERRY_PICK_HEAD'
        marker.write_text(oids[0] + '\n', encoding='ascii')
        rejected('abort cannot cancel an unrelated operation', repo, lambda: backend.abort_revert(repo, plan))
        marker.unlink()
        note = repo / 'unrelated-note.txt'
        note.write_text('keep this new note\n', encoding='utf-8')
        backend.abort_revert(repo, recovery)
        checked('abort restores the original tree and refs while preserving unrelated new files',
                git(repo, 'write-tree') == original_tree and git(repo, 'show-ref') == original_refs
                and (repo / 'value.txt').read_text(encoding='utf-8') == 'later conflicting work\n'
                and note.read_text(encoding='utf-8') == 'keep this new note\n'
                and not backend._optional(repo, ['rev-parse', '--verify', 'REVERT_HEAD']))
        rejected('a finished abort cannot be applied again', repo, lambda: backend.abort_revert(repo, recovery))
        note.unlink()
        result = backend.revert(repo, backend.prepare_revert(repo, oids[1]))
        checked('the same commit can be reviewed again after abort', result.conflicted)
        (repo / 'value.txt').write_text('manual resolution\n', encoding='utf-8')
        backend.stage(repo, ['value.txt']); backend.commit(repo, 'Resolved revert')
        rejected('abort refuses conflict-resolution changes already committed by the user', repo,
                 lambda: backend.abort_revert(repo, plan))
    return f'Revert self-test passed: {len(checks)} checks.'


def self_test_squash():
    """Check history rewriting against real, disposable repositories only."""
    import stat
    test_root = Path(tempfile.mkdtemp(prefix='gitline-squash-test-'))
    backend = GitBackend(
        auth_options=['-c', 'core.hooksPath=' + str(test_root / 'no-hooks'),
                      '-c', 'commit.gpgSign=false', '-c', 'init.templateDir=' + str(test_root / 'no-template')],
        environment={'GIT_CONFIG_GLOBAL': str(test_root / 'empty-config'),
                     'GIT_CONFIG_SYSTEM': str(test_root / 'empty-config'),
                     'GIT_CONFIG_NOSYSTEM': '1', 'GIT_CONFIG_COUNT': '0',
                     'GIT_CONFIG_PARAMETERS': None, 'GIT_CONFIG': None,
                     'GIT_AUTHOR_NAME': 'Original Author', 'GIT_AUTHOR_EMAIL': 'author@example.invalid',
                     'GIT_COMMITTER_NAME': 'Original Committer', 'GIT_COMMITTER_EMAIL': 'committer@example.invalid'})
    checks = []

    def git(repo, *args):
        return backend.run(repo, list(args)).strip()

    def checked(name, condition):
        if not condition:
            raise AssertionError(name)
        checks.append(name)

    def rejected(name, action):
        try:
            action()
        except GitError:
            checks.append(name)
        else:
            raise AssertionError(name)

    def build(name, count=5):
        repo = test_root / name
        repo.mkdir()
        git(repo, 'init', '--quiet', '--initial-branch=main')
        oids = []
        for number in range(count):
            (repo / 'file.txt').write_text(f'version {number}\n', encoding='utf-8')
            git(repo, 'add', '--', 'file.txt')
            git(repo, 'commit', '--quiet', '-m', f'Commit {number}\n\nBody {number}')
            oids.append(git(repo, 'rev-parse', 'HEAD'))
        return repo, oids

    def fingerprint(repo):
        index = Path(git(repo, 'rev-parse', '--path-format=absolute', '--git-path', 'index'))
        return index.read_bytes(), (repo / 'file.txt').read_bytes()

    def backups(repo):
        return git(repo, 'for-each-ref', '--format=%(refname)', 'refs/gitline/')

    try:
        repo, oids = build('middle')
        before = fingerprint(repo)
        plan = backend.prepare_squash(repo, [oids[2], oids[1]])
        checked('squash sorts range and pins descendants',
                tuple(item.oid for item in plan.selected) == tuple(oids[1:3])
                and tuple(item.oid for item in plan.descendants) == tuple(oids[3:]))
        original_tree = git(repo, 'rev-parse', 'HEAD^{tree}')
        metadata_format = '%an%x00%ae%x00%aI%x00%cn%x00%ce%x00%cI'
        original_identity = git(repo, 'log', '-1', '--format=' + metadata_format)
        result = backend.squash(repo, plan, 'Combined middle\n\nDescription')
        checked('squash middle range becomes one commit', git(repo, 'rev-list', '--count', 'HEAD') == '4')
        checked('squash preserves tree, worktree and exact index',
                git(repo, 'rev-parse', 'HEAD^{tree}') == original_tree and fingerprint(repo) == before)
        checked('squash backup and new HEAD are correct',
                git(repo, 'rev-parse', result.backup_ref) == oids[-1] and git(repo, 'rev-parse', 'HEAD') == result.new_head)
        checked('squash preserves descendant message', git(repo, 'log', '-1', '--format=%B') == 'Commit 4\n\nBody 4')
        checked('squash preserves descendant identities', git(repo, 'log', '-1', '--format=' + metadata_format) == original_identity)
        checked('squash preserves base', git(repo, 'rev-parse', result.squash_oid + '^') == oids[0])
        checked('squash leaves a clean worktree', not git(repo, 'status', '--porcelain'))
        rejected('squash refuses stale plan', lambda: backend.squash(repo, plan, 'Again'))

        repo, oids = build('root')
        before = fingerprint(repo)
        result = backend.squash(repo, backend.prepare_squash(repo, oids[:2]), 'New root')
        checked('squash supports root without synthetic parent', not git(repo, 'show', '-s', '--format=%P', result.squash_oid))
        checked('squash root replays descendants without file writes',
                git(repo, 'rev-list', '--count', 'HEAD') == '4' and fingerprint(repo) == before)
        repo, oids = build('head')
        result = backend.squash(repo, backend.prepare_squash(repo, oids[-2:]), 'New tip')
        checked('squash supports HEAD range', result.squash_oid == result.new_head and git(repo, 'rev-list', '--count', 'HEAD') == '4')

        repo, oids = build('guards')
        plan = backend.prepare_squash(repo, oids[1:3])
        old = git(repo, 'rev-parse', 'HEAD')
        rejected('squash rejects noncontiguous range', lambda: backend.prepare_squash(repo, [oids[0], oids[2]]))
        rejected('squash rejects duplicate selection', lambda: backend.prepare_squash(repo, [oids[1], oids[1]]))
        (repo / 'file.txt').write_text('dirty\n', encoding='utf-8')
        rejected('squash rejects dirty worktree', lambda: backend.prepare_squash(repo, oids[1:3]))
        git(repo, 'restore', '--', 'file.txt')
        (repo / 'extra.txt').write_text('untracked', encoding='utf-8')
        rejected('squash rejects untracked file', lambda: backend.prepare_squash(repo, oids[1:3]))
        (repo / 'extra.txt').unlink()
        (repo / 'file.txt').write_text('staged\n', encoding='utf-8')
        git(repo, 'add', '--', 'file.txt')
        rejected('squash rejects dirty index', lambda: backend.squash(repo, plan, 'Changed'))
        git(repo, 'reset', '--hard', '--quiet', old)
        git(repo, 'checkout', '--detach', '--quiet')
        rejected('squash rejects detached HEAD', lambda: backend.prepare_squash(repo, oids[1:3]))
        git(repo, 'checkout', '--quiet', 'main')
        (repo / '.git/MERGE_HEAD').write_text(oids[0] + '\n', encoding='ascii')
        rejected('squash rejects unfinished merge', lambda: backend.prepare_squash(repo, oids[1:3]))
        (repo / '.git/MERGE_HEAD').unlink()
        plan = backend.prepare_squash(repo, oids[1:3])
        before = fingerprint(repo)

        def refuse(result):
            raise RuntimeError('Injected persistence failure')

        try:
            backend.squash(repo, plan, 'No commit', before_update=refuse)
        except RuntimeError:
            pass
        else:
            raise AssertionError('squash must propagate callback failure')
        checked('squash callback failure leaves refs/index/worktree unchanged',
                git(repo, 'rev-parse', 'HEAD') == old and fingerprint(repo) == before and not backups(repo))

        def race(result):
            git(repo, 'update-ref', 'refs/heads/main', oids[-2], old)

        rejected('squash CAS rejects branch change', lambda: backend.squash(repo, plan, 'Ref race', before_update=race))
        checked('squash CAS does not overwrite concurrent ref or create backup',
                git(repo, 'rev-parse', 'HEAD') == oids[-2] and not backups(repo))
        git(repo, 'update-ref', 'refs/heads/main', old, oids[-2])

        def switch(result):
            git(repo, 'branch', 'other', old)
            git(repo, 'symbolic-ref', 'HEAD', 'refs/heads/other')

        rejected('squash rejects switched symbolic HEAD', lambda: backend.squash(repo, plan, 'HEAD race', before_update=switch))
        checked('squash HEAD race leaves original branch and clears own lock',
                git(repo, 'rev-parse', 'refs/heads/main') == old and not backups(repo) and not (repo / '.git/HEAD.lock').exists())
        git(repo, 'symbolic-ref', 'HEAD', 'refs/heads/main')
        original_plumbing = backend._squash_git

        def fail_commit(path, args, *arguments, **keywords):
            if 'commit-tree' in args:
                raise GitError('Injected commit creation failure')
            return original_plumbing(path, args, *arguments, **keywords)

        try:
            backend._squash_git = fail_commit
            rejected('squash propagates object creation failure', lambda: backend.squash(repo, plan, 'Commit failure'))
        finally:
            backend._squash_git = original_plumbing
        checked('squash object failure leaves refs/index/worktree unchanged',
                git(repo, 'rev-parse', 'HEAD') == old and fingerprint(repo) == before and not backups(repo))

        repo, oids = build('merge', 3)
        git(repo, 'checkout', '--quiet', '-b', 'side', oids[0])
        (repo / 'side.txt').write_text('side\n', encoding='utf-8')
        git(repo, 'add', '--', 'side.txt')
        git(repo, 'commit', '--quiet', '-m', 'Side')
        git(repo, 'checkout', '--quiet', 'main')
        git(repo, 'merge', '--no-ff', '--no-edit', 'side')
        rejected('squash rejects merge descendant', lambda: backend.prepare_squash(repo, oids[1:3]))
        tip = git(repo, 'rev-parse', 'HEAD')
        rejected('squash rejects selected merge', lambda: backend.prepare_squash(repo, [oids[-1], tip]))
        repo, oids = build('linked-main', 3)
        linked = test_root / 'linked'
        git(repo, 'worktree', 'add', '--quiet', '-b', 'linked-branch', str(linked), 'HEAD')
        before, main_head = fingerprint(linked), git(repo, 'rev-parse', 'HEAD')
        backend.squash(linked, backend.prepare_squash(linked, oids[:2]), 'Linked squash')
        checked('squash supports linked worktree without index changes',
                git(linked, 'rev-list', '--count', 'HEAD') == '2' and fingerprint(linked) == before)
        checked('squash leaves other worktree branch untouched', git(repo, 'rev-parse', 'HEAD') == main_head)
        print('Squash self-test passed: ' + str(len(checks)) + ' checks.')
        return checks
    finally:
        def remove_readonly(function, path, exception):
            os.chmod(path, stat.S_IWRITE | stat.S_IREAD)
            function(path)
        if not test_root.resolve().is_relative_to(Path(tempfile.gettempdir()).resolve()) or not test_root.name.startswith('gitline-squash-test-'):
            raise RuntimeError('Refusing to remove a squash test directory outside the temporary folder.')
        shutil.rmtree(test_root, onerror=remove_readonly)


def self_test_undo():
    """Undo changes only the reviewed branch in disposable real repositories."""
    import stat
    test_root = Path(tempfile.mkdtemp(prefix='gitline-undo-test-')).resolve()
    backend = GitBackend(
        auth_options=['-c', 'core.hooksPath=' + str(test_root / 'no-hooks'),
                      '-c', 'commit.gpgSign=false', '-c', 'init.templateDir=' + str(test_root / 'no-template')],
        environment={'GIT_CONFIG_GLOBAL': str(test_root / 'empty-config'),
                     'GIT_CONFIG_SYSTEM': str(test_root / 'empty-config'), 'GIT_CONFIG_NOSYSTEM': '1',
                     'GIT_CONFIG_COUNT': '0', 'GIT_CONFIG_PARAMETERS': None, 'GIT_CONFIG': None,
                     'GIT_AUTHOR_NAME': 'Undo Test', 'GIT_AUTHOR_EMAIL': 'undo@example.invalid',
                     'GIT_COMMITTER_NAME': 'Undo Test', 'GIT_COMMITTER_EMAIL': 'undo@example.invalid'})
    checks = []
    def git(repo, *args):
        return backend.run(repo, list(args)).strip()
    def check(condition, name):
        if not condition: raise AssertionError(name)
        checks.append(name)
    def rejected(name, action):
        try: action()
        except GitError: checks.append(name)
        else: raise AssertionError(name)
    def build(name, count=3):
        repo = Path(backend.init_repo(test_root / name)); oids = []
        for number in range(count):
            (repo / 'file.txt').write_text(f'version {number}\n', encoding='utf-8')
            git(repo, 'add', '--', 'file.txt'); git(repo, 'commit', '--quiet', '-m', f'Commit {number}')
            oids.append(git(repo, 'rev-parse', 'HEAD'))
        return repo, oids
    def fingerprint(repo):
        index = Path(git(repo, 'rev-parse', '--path-format=absolute', '--git-path', 'index'))
        return index.read_bytes(), (repo / 'file.txt').read_bytes()
    def backups(repo):
        return git(repo, 'for-each-ref', '--format=%(refname)', 'refs/gitline/undo/commit/')
    try:
        repo, oids = build('dirty')
        (repo / 'file.txt').write_text('staged edit\n', encoding='utf-8'); git(repo, 'add', '--', 'file.txt')
        (repo / 'file.txt').write_text('unstaged edit\n', encoding='utf-8')
        (repo / 'untracked.txt').write_text('keep this\n', encoding='utf-8')
        before = fingerprint(repo)
        rejected('undo rejects a previous commit', lambda: backend.prepare_undo(repo, oids[-2]))
        rejected('undo rejects multiple commits', lambda: backend.prepare_undo(repo, oids[-2:]))
        plan = backend.prepare_undo(repo, oids[-1])
        check(plan.commit.oid == oids[-1] and plan.target_oid == oids[-2], 'undo reviews exactly HEAD and its first parent')
        result = backend.undo(repo, plan)
        check(git(repo, 'rev-parse', 'HEAD') == oids[-2] and git(repo, 'rev-parse', result.backup_ref) == oids[-1],
              'undo atomically moves branch and retains a recovery ref')
        check(fingerprint(repo) == before and (repo / 'untracked.txt').read_text(encoding='utf-8') == 'keep this\n',
              'undo preserves exact staged index, unstaged content and untracked files')
        rejected('undo rejects a stale reviewed HEAD', lambda: backend.undo(repo, plan))
        check(not (repo / '.git' / 'HEAD.lock').exists() and not (repo / '.git' / 'index.lock').exists(),
              'undo releases its native locks')

        root, root_oids = build('root', 1)
        before = fingerprint(root); root_plan = backend.prepare_undo(root, root_oids[0]); result = backend.undo(root, root_plan)
        check(not result.new_head and not backend._has_head(root) and git(root, 'symbolic-ref', 'HEAD') == 'refs/heads/main'
              and git(root, 'rev-parse', result.backup_ref) == root_oids[0], 'undo root leaves the branch unborn with a recovery ref')
        check(fingerprint(root) == before and backend.changes(root)[0].staged, 'undo root retains files in the index and worktree')

        blocked, blocked_oids = build('blocked')
        (blocked / '.git' / 'MERGE_HEAD').write_text(blocked_oids[0] + '\n', encoding='ascii')
        rejected('undo blocks an active Git operation', lambda: backend.prepare_undo(blocked, blocked_oids[-1]))
        (blocked / '.git' / 'MERGE_HEAD').unlink()
        index = blocked / '.git' / 'index'; saved_index = index.read_bytes()
        blob = git(blocked, 'rev-parse', 'HEAD:file.txt')
        conflict = f'0 {"0" * len(blob)}\tfile.txt\n100644 {blob} 1\tfile.txt\n'
        backend._squash_git(blocked, ['update-index', '--index-info'], conflict.encode('ascii'))
        rejected('undo blocks unmerged index entries without an operation marker', lambda: backend.prepare_undo(blocked, blocked_oids[-1]))
        index.write_bytes(saved_index)
        git(blocked, 'switch', '--detach', 'HEAD')
        rejected('undo blocks detached HEAD', lambda: backend.prepare_undo(blocked, blocked_oids[-1]))
        git(blocked, 'switch', 'main')
        plan = backend.prepare_undo(blocked, blocked_oids[-1]); before = fingerprint(blocked)
        git(blocked, 'branch', 'other')
        rejected('undo detects a switched HEAD after review', lambda: backend.undo(blocked, plan,
                 before_update=lambda result: git(blocked, 'symbolic-ref', 'HEAD', 'refs/heads/other')))
        check(git(blocked, 'rev-parse', 'main') == blocked_oids[-1] and not backups(blocked) and fingerprint(blocked) == before,
              'rejected undo leaves branch, index, files and backup namespace untouched')
        git(blocked, 'symbolic-ref', 'HEAD', 'refs/heads/main')
        rejected('undo rejects a concurrently moved branch', lambda: backend.undo(blocked, plan,
                 before_update=lambda result: git(blocked, 'update-ref', 'refs/heads/main', blocked_oids[-2])))
        check(git(blocked, 'rev-parse', 'HEAD') == blocked_oids[-2] and not backups(blocked), 'undo never overwrites a concurrent branch update')

        published, published_oids = build('publication')
        git(published, 'update-ref', 'refs/remotes/other/main', published_oids[-1])
        rejected('undo blocks publication through any remote tracking ref', lambda: backend.prepare_undo(published, published_oids[-1]))
        git(published, 'update-ref', '-d', 'refs/remotes/other/main')
        git(published, 'remote', 'add', 'origin', str(test_root / 'not-contacted.git'))
        rejected('undo blocks an unknown configured remote target', lambda: backend.prepare_undo(published, published_oids[-1]))
        git(published, 'update-ref', 'refs/remotes/origin/main', published_oids[-2])
        plan = backend.prepare_undo(published, published_oids[-1])
        check('według ostatnio pobranego stanu serwera' in plan.publication_notice,
              'undo labels known local publication using the last fetched state')
        git(published, 'update-ref', 'refs/remotes/origin/main', published_oids[-1])
        rejected('undo rechecks publication before applying a reviewed plan', lambda: backend.undo(published, plan))
        check(git(published, 'rev-parse', 'HEAD') == published_oids[-1] and not backups(published), 'published commit rejection never rewrites history')

        merged, merge_oids = build('merge')
        git(merged, 'branch', 'side', merge_oids[0]); git(merged, 'switch', 'side')
        (merged / 'side.txt').write_text('side\n', encoding='utf-8'); git(merged, 'add', '--', 'side.txt')
        git(merged, 'commit', '--quiet', '-m', 'Side commit'); git(merged, 'switch', 'main')
        git(merged, 'merge', '--no-ff', '--no-edit', 'side')
        merge_head = git(merged, 'rev-parse', 'HEAD'); before = fingerprint(merged)
        plan = backend.prepare_undo(merged, merge_head); result = backend.undo(merged, plan)
        check(len(plan.commit.parents) == 2 and result.new_head == merge_oids[-1]
              and fingerprint(merged) == before and (merged / 'side.txt').read_text(encoding='utf-8') == 'side\n',
              'undo merge uses the first parent and preserves the complete merged file state')
        return f'Undo self-test passed: {len(checks)} checks.'
    finally:
        def remove_readonly(function, path, error):
            os.chmod(path, stat.S_IWRITE | stat.S_IREAD); function(path)
        if not test_root.is_relative_to(Path(tempfile.gettempdir()).resolve()) or not test_root.name.startswith('gitline-undo-test-'):
            raise RuntimeError('Refusing to remove an undo-test directory outside the temporary folder.')
        shutil.rmtree(test_root, onerror=remove_readonly)


def self_test_reword():
    """Edit only HEAD metadata in disposable real repositories, including races."""
    import stat
    test_root = Path(tempfile.mkdtemp(prefix='gitline-reword-test-')).resolve()
    backend = GitBackend(
        auth_options=['-c', 'core.hooksPath=' + str(test_root / 'no-hooks'),
                      '-c', 'commit.gpgSign=false', '-c', 'core.autocrlf=false',
                      '-c', 'init.templateDir=' + str(test_root / 'no-template')],
        environment={'GIT_CONFIG_GLOBAL': str(test_root / 'empty-config'),
                     'GIT_CONFIG_SYSTEM': str(test_root / 'empty-config'), 'GIT_CONFIG_NOSYSTEM': '1',
                     'GIT_CONFIG_COUNT': '0', 'GIT_CONFIG_PARAMETERS': None, 'GIT_CONFIG': None,
                     'GIT_AUTHOR_NAME': 'Original Author', 'GIT_AUTHOR_EMAIL': 'author@example.invalid',
                     'GIT_AUTHOR_DATE': '2020-05-06T07:08:09+02:00',
                     'GIT_COMMITTER_NAME': 'Reword Test', 'GIT_COMMITTER_EMAIL': 'reword@example.invalid'})
    checks = []
    def git(repo, *args):
        return backend.run(repo, list(args)).strip()
    def check(condition, name):
        if not condition: raise AssertionError(name)
        checks.append(name)
    def rejected(name, action):
        try: action()
        except GitError: checks.append(name)
        else: raise AssertionError(name)
    def build(name, count=2):
        repo = Path(backend.init_repo(test_root / name)); oids = []
        for number in range(count):
            (repo / 'file.txt').write_text(f'version {number}\n', encoding='utf-8')
            git(repo, 'add', '--', 'file.txt'); git(repo, 'commit', '--quiet', '-m', f'Title {number}', '-m', 'Original body')
            oids.append(git(repo, 'rev-parse', 'HEAD'))
        return repo, oids
    def fingerprint(repo):
        index = Path(git(repo, 'rev-parse', '--path-format=absolute', '--git-path', 'index'))
        return index.read_bytes(), tuple((path.name, path.read_bytes()) for path in sorted(repo.iterdir()) if path.is_file())
    def backups(repo):
        return git(repo, 'for-each-ref', '--format=%(refname)', 'refs/gitline/undo/reword/')
    try:
        repo, oids = build('dirty')
        (repo / 'file.txt').write_text('staged change\n', encoding='utf-8'); git(repo, 'add', '--', 'file.txt')
        (repo / 'file.txt').write_text('unstaged change\n', encoding='utf-8')
        (repo / 'untracked.txt').write_text('keep untracked\n', encoding='utf-8')
        before = fingerprint(repo)
        plan = backend.prepare_reword(repo, oids[-1])
        check(plan.commit.message == 'Title 1\n\nOriginal body\n' and plan.selected == (plan.commit,)
              and not plan.signed and fingerprint(repo) == before, 'reword preview reads the full message without touching the index')
        rejected('reword rejects an older commit', lambda: backend.prepare_reword(repo, oids[0]))
        rejected('reword rejects multiple commits', lambda: backend.prepare_reword(repo, oids))
        rejected('reword rejects malformed object ids', lambda: backend.prepare_reword(repo, 'HEAD'))
        for invalid in ('', ' \n\t', 'name\0body', 'x' * (1024 * 1024), '\ud800', None):
            rejected('reword rejects invalid message ' + repr(invalid)[:35], lambda value=invalid: backend.reword(repo, plan, value))
        rejected('reword rejects a forged plan', lambda: backend.reword(repo, dataclasses.replace(plan, tree_oid=oids[0]), 'New title'))
        callback_results = []
        result = backend.reword(repo, plan, 'Nowa nazwa żółć\n\nNowy opis\nDrugi wiersz', before_update=callback_results.append)
        changed = backend._squash_commits(repo, (result.new_head,))[0]
        check(changed[0].message == 'Nowa nazwa żółć\n\nNowy opis\nDrugi wiersz\n'
              and changed[1] == plan.tree_oid and changed[0].parents == plan.commit.parents,
              'reword edits title and body while preserving the committed tree and parents')
        check((changed[0].author, changed[0].author_email, changed[0].author_date)
              == (plan.commit.author, plan.commit.author_email, plan.commit.author_date), 'reword preserves the original author and timestamp')
        check(fingerprint(repo) == before, 'reword preserves exact index bytes, partial staging, worktree and untracked files')
        check(git(repo, 'rev-parse', 'HEAD') == result.new_head and git(repo, 'rev-parse', result.backup_ref) == oids[-1]
              and callback_results == [result], 'reword atomically backs up the old commit and calls the lease callback before updating')
        rejected('reword rejects a stale dialog plan', lambda: backend.reword(repo, plan, 'Stale name'))

        blocked, blocked_oids = build('blocked'); plan = backend.prepare_reword(blocked, blocked_oids[-1])
        original = fingerprint(blocked); git_dir = blocked / '.git'
        def refuse(result):
            raise GitError('Simulated lease persistence failure')
        rejected('reword respects refusal from the pre-update callback', lambda: backend.reword(blocked, plan, 'Refused', refuse))
        check(git(blocked, 'rev-parse', 'HEAD') == plan.head_oid and not backups(blocked) and fingerprint(blocked) == original,
              'callback refusal preserves refs, backup namespace, index and worktree')
        for marker in ('MERGE_HEAD', 'index.lock', 'HEAD.lock'):
            marker_path = git_dir / marker; marker_path.write_text(plan.head_oid + '\n', encoding='ascii')
            try:
                rejected('reword rejects an active ' + marker, lambda: backend.prepare_reword(blocked, plan.head_oid))
            finally:
                marker_path.unlink()
        index = git_dir / 'index'; saved_index = index.read_bytes()
        blob = git(blocked, 'rev-parse', 'HEAD:file.txt')
        conflict = f'0 {"0" * len(blob)}\tfile.txt\n100644 {blob} 2\tfile.txt\n100644 {blob} 3\tfile.txt\n'
        backend._squash_git(blocked, ['update-index', '--index-info'], conflict.encode('ascii'))
        rejected('reword rejects an unmerged index without operation markers', lambda: backend.prepare_reword(blocked, plan.head_oid))
        index.write_bytes(saved_index)
        git(blocked, 'switch', '--detach', 'HEAD')
        rejected('reword rejects detached HEAD', lambda: backend.prepare_reword(blocked, plan.head_oid))
        git(blocked, 'switch', 'main'); git(blocked, 'branch', 'other')
        original = fingerprint(blocked)
        rejected('reword detects a branch switch after review', lambda: backend.reword(blocked, plan, 'Switched',
                 before_update=lambda result: git(blocked, 'symbolic-ref', 'HEAD', 'refs/heads/other')))
        check(git(blocked, 'rev-parse', 'main') == plan.head_oid and not backups(blocked) and fingerprint(blocked) == original,
              'branch switch rejection preserves the reviewed branch, index and worktree')
        git(blocked, 'symbolic-ref', 'HEAD', plan.source_ref)
        rejected('reword detects a moved HEAD after review', lambda: backend.reword(blocked, plan, 'Moved',
                 before_update=lambda result: git(blocked, 'update-ref', plan.source_ref, blocked_oids[0])))
        check(git(blocked, 'rev-parse', 'HEAD') == blocked_oids[0] and not backups(blocked), 'reword never overwrites a concurrent branch update')
        git(blocked, 'update-ref', plan.source_ref, plan.head_oid)
        original_plumbing = backend._squash_git
        def move_at_transaction(path, args, data=None, identity=None, limit=16 * 1024 * 1024):
            if args[0].startswith('--git-dir=') and 'update-ref' in args and '--stdin' in args:
                original_plumbing(path, [args[0], 'update-ref', plan.source_ref, blocked_oids[0]])
            return original_plumbing(path, args, data, identity, limit)
        backend._squash_git = move_at_transaction
        try:
            rejected('reword CAS catches a branch move immediately before the ref transaction', lambda: backend.reword(blocked, plan, 'CAS race'))
        finally:
            backend._squash_git = original_plumbing
        check(git(blocked, 'rev-parse', 'HEAD') == blocked_oids[0] and not backups(blocked)
              and not (git_dir / 'HEAD.lock').exists() and not (git_dir / 'index.lock').exists(),
              'failed reword transaction creates no backup and releases its native locks')

        root_repo, root_oids = build('root', 1); root_plan = backend.prepare_reword(root_repo, root_oids[0])
        root_result = backend.reword(root_repo, root_plan, 'Renamed first commit')
        check(not backend._squash_commits(root_repo, (root_result.new_head,))[0][0].parents
              and git(root_repo, 'rev-parse', 'HEAD^{tree}') == root_plan.tree_oid, 'reword supports the first commit without inventing a parent')
        git(root_repo, 'update-ref', 'refs/remotes/origin/main', root_result.new_head)
        published_plan = backend.prepare_reword(root_repo, root_result.new_head)
        published = backend.reword(root_repo, published_plan, 'Published commit with reviewed lease')
        check(published.new_head != published_plan.head_oid
              and git(root_repo, 'rev-parse', 'refs/remotes/origin/main') == published_plan.head_oid,
              'reword leaves publication authorization to its caller and never changes remote tracking refs')

        merged, merge_oids = build('merge')
        git(merged, 'branch', 'side', merge_oids[0]); git(merged, 'switch', 'side')
        (merged / 'side.txt').write_text('side\n', encoding='utf-8'); git(merged, 'add', '--', 'side.txt')
        git(merged, 'commit', '--quiet', '-m', 'Side commit'); git(merged, 'switch', 'main')
        git(merged, 'merge', '--no-ff', '--no-edit', 'side')
        merge_plan = backend.prepare_reword(merged, git(merged, 'rev-parse', 'HEAD')); before = fingerprint(merged)
        merge_result = backend.reword(merged, merge_plan, 'Renamed merge\n\nNew merge details')
        merge_record = backend._squash_commits(merged, (merge_result.new_head,))[0]
        check(len(merge_plan.commit.parents) == 2 and merge_record[0].parents == merge_plan.commit.parents
              and merge_record[1] == merge_plan.tree_oid and fingerprint(merged) == before,
              'reword preserves every merge parent, merged tree and exact file state')
        payload = backend._squash_git(merged, ['cat-file', 'commit', merge_result.new_head])
        headers, body = payload.split(b'\n\n', 1)
        signed_payload = headers + b'\ngpgsig -----BEGIN PGP SIGNATURE-----\n test fixture only\n -----END PGP SIGNATURE-----\n\n' + body
        signed_oid = backend._squash_git(merged, ['hash-object', '-t', 'commit', '-w', '--stdin'], signed_payload).decode('ascii').strip()
        git(merged, 'update-ref', 'refs/heads/main', signed_oid)
        signed_plan = backend.prepare_reword(merged, signed_oid)
        signed_result = backend.reword(merged, signed_plan, 'Edited signed commit')
        check(signed_plan.signed and not backend._squash_commits(merged, (signed_result.new_head,))[0][3],
              'reword exposes an old signature for review and removes its invalidated signature')
        unsupported = headers + b'\nencoding ISO-8859-1\n\n' + body
        unsupported_oid = backend._squash_git(merged, ['hash-object', '-t', 'commit', '-w', '--stdin'], unsupported).decode('ascii').strip()
        git(merged, 'update-ref', 'refs/heads/main', unsupported_oid)
        rejected('reword rejects unsupported commit metadata', lambda: backend.prepare_reword(merged, unsupported_oid))
        return f'Reword self-test passed: {len(checks)} checks.'
    finally:
        def remove_readonly(function, path, error):
            os.chmod(path, stat.S_IWRITE | stat.S_IREAD); function(path)
        if not test_root.is_relative_to(Path(tempfile.gettempdir()).resolve()) or not test_root.name.startswith('gitline-reword-test-'):
            raise RuntimeError('Refusing to remove a reword-test directory outside the temporary folder.')
        shutil.rmtree(test_root, onerror=remove_readonly)


def self_test_reword_publication():
    """Exercise published message edits and retained leases using local remotes."""
    import stat
    from types import SimpleNamespace
    test_root = Path(tempfile.mkdtemp(prefix='gitline-reword-publication-')).resolve()
    backend = GitBackend(
        auth_options=['-c', 'core.hooksPath=' + str(test_root / 'no-hooks'),
                      '-c', 'commit.gpgSign=false', '-c', 'core.autocrlf=false',
                      '-c', 'init.templateDir=' + str(test_root / 'no-template')],
        environment={'GIT_CONFIG_GLOBAL': str(test_root / 'empty-config'),
                     'GIT_CONFIG_SYSTEM': str(test_root / 'empty-config'), 'GIT_CONFIG_NOSYSTEM': '1',
                     'GIT_CONFIG_COUNT': '0', 'GIT_CONFIG_PARAMETERS': None, 'GIT_CONFIG': None,
                     'GIT_AUTHOR_NAME': 'Publication Test', 'GIT_AUTHOR_EMAIL': 'test@example.invalid',
                     'GIT_COMMITTER_NAME': 'Publication Test', 'GIT_COMMITTER_EMAIL': 'test@example.invalid'})
    leases = RewriteLeaseStore(None)
    owner = SimpleNamespace(backend=backend, rewrite_leases=leases, _approved_routes={})
    checks = []
    def git(repo, *args):
        return backend.run(repo, list(args)).strip()
    def check(condition, name):
        if not condition: raise AssertionError(name)
        checks.append(name)
    def rejected(name, action):
        try: action()
        except GitError: checks.append(name)
        else: raise AssertionError(name)
    def edit(repo, message):
        plan = backend.prepare_reword(repo, git(repo, 'rev-parse', 'HEAD'))
        push, record, notice = MainWindow.squash_publication(owner, plan)
        check(record is not None and 'Force push' in notice, 'published edit reviews its force-push requirement')
        prepared = (backend.squash_provenance(repo, record, leases.get_provenance(record))
                    if record.get('new_head') else None)
        saved = None
        def before_update(result):
            nonlocal saved
            if backend.resolve_push_plan(repo, push.remote_override, push.destination_override) != push:
                raise GitError('Changed reviewed route')
            if record.get('new_head') and leases.active(backend, repo, plan.source_ref, plan.head_oid) != record:
                raise GitError('Changed reviewed lease')
            saved = dict(record, old_head=result.old_head, new_head=result.new_head)
            leases.save(saved, previous=record if record.get('new_head') else None)
            leases.save_provenance(saved, backend.rewrite_reword_provenance(result, prepared))
            check(git(repo, 'rev-parse', 'HEAD') == result.old_head,
                  'lease and annotations are saved before the branch reference changes')
        result = backend.reword(repo, plan, message, before_update=before_update)
        return result, saved
    try:
        repo = Path(backend.init_repo(test_root / 'source'))
        remote, other = test_root / 'remote.git', test_root / 'other.git'
        for destination in (remote, other):
            git(None, 'init', '--bare', '--initial-branch=main', str(destination))
        git(repo, 'remote', 'add', 'origin', str(remote))
        for number in range(2):
            (repo / 'file.txt').write_text(f'Content {number}\n', encoding='utf-8')
            git(repo, 'add', '--', 'file.txt'); git(repo, 'commit', '--quiet', '-m', f'Original {number}')
        backend.push(repo)
        original = git(repo, 'rev-parse', 'HEAD')
        first, record = edit(repo, 'First revised title\n\nFirst revised body')
        active = leases.active(backend, repo, record['source_ref'], first.new_head)
        check(active == record and active['expected_remote_oid'] == original
              and git(repo, 'rev-parse', first.backup_ref) == original,
              'first published edit saves its original server lease and backup')
        first_metadata = leases.get_provenance(active)
        annotation = backend.history_publication(repo, (first.new_head,), record=active, provenance=first_metadata)[first.new_head]
        check(annotation['status'] == 'rewrite_pending' and not annotation['is_squash']
              and annotation['original_count'] is None,
              'published message edit has a generic rewritten annotation without squash counts')
        second, record = edit(repo, 'Second revised title\n\nSecond revised body')
        active = leases.active(backend, repo, record['source_ref'], second.new_head)
        stored = leases.get(repo, record['source_ref'])
        metadata = leases.get_provenance(active)
        check(active['expected_remote_oid'] == original and stored['previous']['new_head'] == first.new_head
              and active['push_url_hashes'] == stored['previous']['push_url_hashes'],
              'repeated edit retains the initial remote lease and recoverable previous record')
        check(metadata == dict(version=1, complete=True, entries=[
                  dict(oid=second.new_head, original_oids=[original], is_squash=False)]),
              'repeated edit preserves original provenance without inventing a squash')
        annotation = backend.history_publication(repo, (second.new_head,), record=active, provenance=metadata)[second.new_head]
        check(annotation['status'] == 'rewrite_pending' and not annotation['is_squash'],
              'repeated published edit remains a generic pending rewrite')
        rejected('ordinary push cannot publish the rewritten HEAD', lambda: backend.push(repo))
        force = backend.prepare_force_push(repo, original, active['remote_name'], active['destination_ref'])
        check(force.push_plan.head_oid == second.new_head and force.expected_remote_oid == original
              and leases.matches(active, force.push_plan),
              'force review uses the final HEAD and the initial remote lease')
        git(repo, 'config', 'remote.origin.pushurl', str(other))
        rejected('force refuses a changed remote endpoint', lambda: backend.force_push(repo, force))
        git(repo, 'config', '--unset', 'remote.origin.pushurl')
        tree = git(remote, 'rev-parse', original + '^{tree}')
        advanced = git(remote, 'commit-tree', tree, '-p', original, '-m', 'Someone else advanced the remote')
        git(remote, 'update-ref', 'refs/heads/main', advanced, original)
        rejected('force refuses a remote commit added after reword review', lambda: backend.force_push(repo, force))
        backend.fetch(repo)
        _, reviewed_after_fetch, _ = MainWindow.squash_publication(
            owner, backend.prepare_reword(repo, second.new_head))
        check(reviewed_after_fetch == active and reviewed_after_fetch['expected_remote_oid'] == original,
              'fetch cannot replace the original lease while reviewing another message edit')
        rejected('fetch cannot relax the force lease', lambda: backend.force_push(repo, force))
        check(git(remote, 'rev-parse', 'refs/heads/main') == advanced,
              'rejected requests preserve the new remote commit')
        git(remote, 'update-ref', 'refs/heads/main', original, advanced)
        backend.force_push(repo, force)
        check(git(remote, 'rev-parse', 'refs/heads/main') == second.new_head
              and leases.active(backend, repo, record['source_ref'], second.new_head) is None,
              'matching original lease publishes the final message and expires pending state')
        return f'Reword publication self-test passed: {len(checks)} checks.'
    finally:
        def remove_readonly(function, path, error):
            os.chmod(path, stat.S_IWRITE | stat.S_IREAD); function(path)
        if not test_root.is_relative_to(Path(tempfile.gettempdir()).resolve()) or not test_root.name.startswith('gitline-reword-publication-'):
            raise RuntimeError('Refusing to remove a publication-test directory outside the temporary folder.')
        shutil.rmtree(test_root, onerror=remove_readonly)


def self_test_force_push():
    """Exercise explicit leases using disposable local remotes and no user config."""
    import shlex
    import stat
    test_root = Path(tempfile.mkdtemp(prefix="gitline-force-test-"))
    backend = GitBackend(
        auth_options=["-c", "core.hooksPath=" + str(test_root / "no-hooks"),
                      "-c", "commit.gpgSign=false", "-c", "tag.gpgSign=false",
                      "-c", "init.templateDir=" + str(test_root / "no-templates")],
        environment={"GIT_CONFIG_GLOBAL": str(test_root / "empty-config"),
                     "GIT_CONFIG_SYSTEM": str(test_root / "empty-config"),
                     "GIT_CONFIG_NOSYSTEM": "1", "GIT_CONFIG_COUNT": "0",
                     "GIT_CONFIG_PARAMETERS": None, "GIT_CONFIG": None})
    checks = []

    def checked(name, condition):
        if not condition:
            raise AssertionError(name)
        checks.append(name)

    def rejected(name, action):
        try:
            action()
        except GitError:
            checks.append(name)
        else:
            raise AssertionError(name)

    try:
        repo = Path(backend.init_repo(test_root / "source"))
        backend.set_identity(repo, "Gitline Test", "gitline-test@example.invalid")
        remote, other = test_root / "remote.git", test_root / "other.git"
        for target in (remote, other):
            backend.run(None, ["init", "--bare", "--initial-branch=main", str(target)])
            backend.set_identity(target, "Gitline Test", "gitline-test@example.invalid")
        backend.run(repo, ["remote", "add", "origin", str(remote)])
        for number in range(3):
            (repo / "history.txt").write_text(f"revision {number}\n", encoding="utf-8")
            backend.stage(repo, ["history.txt"])
            backend.commit(repo, f"Original {number}")
        checked("force tracking unknown before first publication", not backend.push_tracking_state(repo)["oid"])
        backend.push(repo)
        original = backend.resolve_push_plan(repo)
        expected = original.head_oid
        tracking = backend.push_tracking_state(repo, original)
        checked("force lease captured from selected tracking target",
                tracking == dict(tracking_ref="refs/remotes/origin/main", oid=expected, requires_force=False, reason=""))
        backend.run(repo, ["config", "remote.origin.pushurl", str(other)])
        checked("force tracking refuses separate fetch and push endpoints", not backend.push_tracking_state(repo)["oid"])
        backend.run(repo, ["config", "--unset", "remote.origin.pushurl"])
        backend.run(repo, ["config", "--add", "remote.origin.fetch", "^refs/heads/main"])
        checked("force tracking respects negative fetch refspec", not backend.push_tracking_state(repo)["oid"])
        backend.run(repo, ["config", "--replace-all", "remote.origin.fetch", "+refs/heads/*:refs/remotes/custom/*"])
        backend.run(repo, ["update-ref", "refs/remotes/custom/main", expected])
        checked("force tracking maps custom fetch refspec", backend.push_tracking_state(repo)["tracking_ref"] == "refs/remotes/custom/main")
        backend.run(repo, ["config", "remote.origin.fetch", "+refs/heads/*:refs/remotes/origin/*"])
        backend.run(repo, ["symbolic-ref", "refs/remotes/origin/main", "refs/heads/main"])
        checked("force tracking refuses symbolic tracking ref", not backend.push_tracking_state(repo)["oid"])
        backend.run(repo, ["update-ref", "--no-deref", "refs/remotes/origin/main", expected])

        base = backend.run(repo, ["rev-parse", "HEAD~2"]).strip()
        tree = backend.run(repo, ["rev-parse", "HEAD^{tree}"]).strip()
        rewritten = backend.run(repo, ["commit-tree", tree, "-p", base, "-m", "Squashed history"]).strip()
        backend.run(repo, ["update-ref", "refs/heads/main", rewritten, expected])
        checked("force label detects rewritten published history", backend.push_tracking_state(repo)["requires_force"])
        rejected("ordinary push rejects rewritten history", lambda: backend.push(repo))
        for value in ("", "HEAD", expected[:12], "0" * len(expected), tree, expected + "\n"):
            rejected("force rejects invalid or noncommit lease " + repr(value), lambda value=value: backend.prepare_force_push(repo, value))
        backend.run(repo, ["config", "--add", "remote.origin.pushurl", str(remote)])
        backend.run(repo, ["config", "--add", "remote.origin.pushurl", str(other)])
        rejected("force refuses multiple push endpoints", lambda: backend.prepare_force_push(repo, expected))
        backend.run(repo, ["config", "--unset-all", "remote.origin.pushurl"])

        hooks = test_root / "hooks"
        hooks.mkdir()
        hook_output = test_root / "pre-push.txt"
        hook = hooks / "pre-push"
        hook.write_text("#!/bin/sh\nprintf '%s\\n' \"$1\" \"$2\" \"$GITLINE_ACCOUNT_ID\" \"$GITLINE_REMOTE\" > "
                        + shlex.quote(hook_output.as_posix()) + "\n", encoding="utf-8", newline="\n")
        hook.chmod(0o700)
        scoped = GitBackend(backend.git_exe, backend.auth_options + ["-c", "core.hooksPath=" + str(hooks)],
                            backend.environment).with_account("force-test-account")
        plan = scoped.prepare_force_push(repo, expected)
        rejected("ordinary push cannot accept force plan", lambda: scoped.push(repo, plan))
        backend.run(repo, ["config", "remote.origin.pushurl", str(other)])
        rejected("force rejects changed endpoint", lambda: scoped.force_push(repo, plan))
        backend.run(repo, ["config", "--unset", "remote.origin.pushurl"])
        unreviewed = backend.run(repo, ["commit-tree", tree, "-p", rewritten, "-m", "Unreviewed history"]).strip()
        backend.run(repo, ["update-ref", "refs/heads/main", unreviewed, rewritten])
        rejected("force rejects changed HEAD", lambda: scoped.force_push(repo, plan))
        backend.run(repo, ["update-ref", "refs/heads/main", rewritten, unreviewed])
        scoped.force_push(repo, plan)
        checked("force sends reviewed rewritten object with exact lease",
                backend.run(remote, ["rev-parse", "refs/heads/main"]).strip() == rewritten)
        checked("force preserves real remote hook arguments and account",
                hook_output.read_text(encoding="utf-8").splitlines()
                == ["origin", str(remote), "force-test-account", "origin"])
        checked("force updates native tracking state", backend.push_tracking_state(repo)["oid"] == rewritten)

        second = backend.run(repo, ["commit-tree", tree, "-p", base, "-m", "Another rewrite"]).strip()
        backend.run(repo, ["update-ref", "refs/heads/main", second, rewritten])
        stale = backend.prepare_force_push(repo, expected)
        rejected("force rejects stale explicit lease", lambda: backend.force_push(repo, stale))
        pending = backend.prepare_force_push(repo, rewritten)
        remote_commit = backend.run(remote, ["commit-tree", tree, "-p", rewritten, "-m", "Someone else's commit"]).strip()
        backend.run(remote, ["update-ref", "refs/heads/main", remote_commit, rewritten])
        rejected("force preserves a new remote commit", lambda: backend.force_push(repo, pending))
        backend.fetch(repo)
        checked("fetch observes new remote commit", backend.push_tracking_state(repo)["oid"] == remote_commit)
        rejected("background fetch cannot relax an explicit lease", lambda: backend.force_push(repo, pending))
        checked("stale attempts leave remote unchanged", backend.run(remote, ["rev-parse", "refs/heads/main"]).strip() == remote_commit)

        backend.run(remote, ["update-ref", "refs/heads/main", rewritten, remote_commit])
        pinned = backend.prepare_force_push(repo, rewritten)
        original_resolve = backend.resolve_push_plan

        def replace_endpoint_after_validation(*args, **kwargs):
            reviewed = original_resolve(*args, **kwargs)
            backend.run(repo, ["config", "--add", "remote.origin.pushurl", str(other)])
            backend.run(repo, ["config", f"url.{other}.insteadOf", str(remote)])
            backend.run(repo, ["config", f"url.{other}.pushInsteadOf", "gitline-push-"])
            return reviewed

        try:
            backend.resolve_push_plan = replace_endpoint_after_validation
            backend.force_push(repo, pinned)
            checked("force pins endpoint across post-validation rewrites",
                    backend.run(remote, ["rev-parse", "refs/heads/main"]).strip() == second
                    and not backend._optional(other, ["rev-parse", "--verify", "refs/heads/main"]))
        finally:
            backend.resolve_push_plan = original_resolve
            backend.run(repo, ["config", "--unset-all", "remote.origin.pushurl"])
            backend.run(repo, ["config", "--unset-all", f"url.{other}.insteadOf"])
            backend.run(repo, ["config", "--unset-all", f"url.{other}.pushInsteadOf"])
        backend.run(repo, ["config", "--add", "remote.origin.pushurl", str(remote)])
        backend.run(repo, ["config", "--add", "remote.origin.pushurl", str(other)])
        backend.push(repo)
        checked("ordinary push still supports multiple endpoints",
                all(backend.run(target, ["rev-parse", "refs/heads/main"]).strip() == second for target in (remote, other)))
        backend.run(repo, ["config", "remote.origin.push", "+refs/heads/main:refs/heads/main"])
        rejected("ordinary push still rejects force refspec config", lambda: backend.resolve_push_plan(repo))
        print("Force push self-test passed: " + str(len(checks)) + " checks.")
        return checks
    finally:
        def remove_readonly(function, path, exception):
            os.chmod(path, stat.S_IWRITE | stat.S_IREAD)
            function(path)
        if not test_root.resolve().is_relative_to(Path(tempfile.gettempdir()).resolve()) or not test_root.name.startswith("gitline-force-test-"):
            raise RuntimeError("Refusing to remove a force test directory outside the temporary folder.")
        shutil.rmtree(test_root, onerror=remove_readonly)


def commit_context_self_test():
    """Check queued-commit context against real Git without user config or repositories."""
    checks = []
    def checked(name, condition):
        if not condition: raise AssertionError(name)
        checks.append(name)

    with tempfile.TemporaryDirectory(prefix='gitline-commit-context-test-') as directory:
        test_root = Path(directory).resolve()
        backend = GitBackend(
            auth_options=['-c', 'core.hooksPath=' + str(test_root / 'no-hooks'),
                          '-c', 'commit.gpgSign=false', '-c', 'core.autocrlf=false',
                          '-c', 'init.templateDir=' + str(test_root / 'no-templates')],
            environment={'GIT_CONFIG_GLOBAL': str(test_root / 'empty-config'),
                         'GIT_CONFIG_SYSTEM': str(test_root / 'empty-config'),
                         'GIT_CONFIG_NOSYSTEM': '1', 'GIT_CONFIG_COUNT': '0',
                         'GIT_CONFIG_PARAMETERS': None, 'GIT_CONFIG': None,
                         'GIT_AUTHOR_NAME': 'Gitline Test', 'GIT_AUTHOR_EMAIL': 'gitline-test@example.invalid',
                         'GIT_COMMITTER_NAME': 'Gitline Test', 'GIT_COMMITTER_EMAIL': 'gitline-test@example.invalid'})
        def git(*args):
            return backend.run(repo, list(args)).strip()
        def context():
            return (backend._optional(repo, ['symbolic-ref', '--quiet', 'HEAD']),
                    backend._optional(repo, ['rev-parse', '--verify', 'HEAD']))
        def stage(text):
            (repo / 'selected.txt').write_text(text, encoding='utf-8')
            backend.stage(repo, ['selected.txt'])
        def rejected(name, expected):
            before_head = context()
            before_refs = git('show-ref')
            before_index = (repo / '.git' / 'index').read_bytes()
            try:
                backend.commit(repo, 'This commit must not be created', expected_head=expected)
                raise AssertionError(name)
            except GitError as error:
                checked(name, 'Odśwież widok' in str(error) and context() == before_head
                        and git('show-ref') == before_refs and (repo / '.git' / 'index').read_bytes() == before_index)

        repo = Path(backend.init_repo(test_root / 'repo'))
        unborn = context()
        checked('unborn branch has a symbolic ref and no commit oid', unborn == ('refs/heads/main', ''))
        stage('first\n')
        backend.commit(repo, 'First guarded commit', expected_head=unborn)
        first = git('rev-parse', 'HEAD')
        checked('guarded initial commit supports an unborn branch',
                git('rev-list', '--count', 'HEAD') == '1' and context() == ('refs/heads/main', first))

        stage('first\nsecond\n')
        expected = context()
        backend.commit(repo, 'Unchanged context', 'Description retained', expected_head=expected)
        checked('matching branch and HEAD allow a normal staged commit',
                git('rev-parse', 'HEAD^') == first
                and git('log', '-1', '--format=%B') == 'Unchanged context\n\nDescription retained'
                and not git('diff', '--cached', '--name-only'))

        expected = context()
        stage('first\nsecond\nqueued change\n')
        git('switch', '--quiet', '-c', 'other')
        rejected('switching branches at the same oid rejects the queued commit without changing refs or index', expected)

        expected = context()
        newer = git('commit-tree', 'HEAD^{tree}', '-p', expected[1], '-m', 'External commit')
        git('update-ref', expected[0], newer, expected[1])
        rejected('an external newer HEAD rejects the queued commit without changing refs or index', expected)

        git('checkout', '--quiet', '--detach', 'HEAD')
        detached = context()
        checked('detached HEAD has an oid and no symbolic ref', detached == ('', newer))
        backend.commit(repo, 'Detached guarded commit', expected_head=detached)
        checked('guarded commits preserve detached HEAD semantics and leave branch refs untouched',
                context()[0] == '' and git('rev-parse', 'HEAD^') == newer
                and git('rev-parse', 'refs/heads/other') == newer
                and not git('diff', '--cached', '--name-only'))
    return f'Commit context self-test passed: {len(checks)} checks.'


def repository_root_self_test():
    """Check discovery path handling without Git processes or user repositories."""
    from unittest.mock import Mock, patch
    checks = []
    with tempfile.TemporaryDirectory(prefix='gitline-root-test-') as directory:
        root = Path(directory).resolve()
        file = root / 'tracked.txt'; file.write_text('test', encoding='utf-8')
        backend = GitBackend.__new__(GitBackend)
        backend.run = Mock(return_value=str(root) + '\n')
        for path in (root, file):
            if backend.root(path) != str(root): raise AssertionError('Discovery changed the Git root')
            backend.run.assert_called_with(root, ['rev-parse', '--show-toplevel'])
            checks.append('Directory discovery' if path == root else 'Existing file discovers its parent')
        for name, path in (('Missing directory', root / 'missing'), ('Removed directory', root / 'removed')):
            if name == 'Removed directory': path.mkdir(); path.rmdir()
            backend.run.reset_mock()
            try: backend.root(path)
            except GitError as error:
                if str(error) != repository_unavailable_message(path): raise AssertionError(name + ': raw error')
            else: raise AssertionError(name + ': missing folder accepted')
            backend.run.assert_not_called(); checks.append(name + ' explains unavailable folder before Git')
        backend.run.reset_mock()
        with patch.object(Path, 'is_dir', side_effect=PermissionError('access denied')):
            try: backend.root(root)
            except GitError as error:
                if str(error) != repository_unavailable_message(root): raise AssertionError('Inaccessible folder: raw error')
            else: raise AssertionError('Inaccessible folder accepted')
        backend.run.assert_not_called(); checks.append('Inaccessible directory explains unavailable folder before Git')
    return {'passed': len(checks), 'checks': checks}


def self_test_backend():
    """Exercise real Git in disposable repositories; never touch user Git config."""
    import stat
    import shlex
    test_root = Path(tempfile.mkdtemp(prefix="gitline-self-test-")).resolve()
    backend = GitBackend(
        auth_options=["-c", "core.hooksPath=" + str(test_root / "no-hooks"),
                      "-c", "commit.gpgSign=false", "-c", "tag.gpgSign=false",
                      "-c", "init.templateDir=" + str(test_root / "no-templates")],
        environment={"GIT_CONFIG_GLOBAL": str(test_root / "empty-config"),
                     "GIT_CONFIG_SYSTEM": str(test_root / "empty-config"),
                     "GIT_CONFIG_NOSYSTEM": "1", "GIT_CONFIG_COUNT": "0",
                     "GIT_CONFIG_PARAMETERS": None, "GIT_CONFIG": None})
    checks = []
    checks.extend(repository_root_self_test()['checks'])
    def checked(name, condition):
        if not condition:
            raise AssertionError(name)
        checks.append(name)
    def rejected(name, action):
        try:
            action()
        except GitError:
            checks.append(name)
        else:
            raise AssertionError(name)
    try:
        repo = Path(backend.init_repo(test_root / "source"))
        backend.set_identity(repo, "Gitline Test", "gitline-test@example.invalid")
        backend.run(repo, ["config", "core.autocrlf", "false"])
        backend.run(repo, ["config", "commit.gpgSign", "false"])
        backend.run(repo, ["config", "core.hooksPath", str(test_root / "no-hooks")])
        checked("unborn snapshot", backend.snapshot(repo).branch == "main" and not backend.snapshot(repo).commits)
        account_environment = {key: os.environ.get(key) for key in ("GITLINE_ACCOUNT_ID", "GITLINE_REPOSITORY", "GITLINE_REMOTE")}
        scoped = backend.with_account("self-test-account")._with_remote("origin")
        environment_output = scoped.run(repo, ["-c", "alias.gitline-test-env=!printf '%s\\n' \"$GITLINE_ACCOUNT_ID\" \"$GITLINE_REPOSITORY\" \"$GITLINE_REMOTE\"", "gitline-test-env"])
        checked("account and remote environment scoped to Git process",
                environment_output.splitlines() == ["self-test-account", str(repo.resolve()), "origin"]
                and "GITLINE_ACCOUNT_ID" not in backend.environment
                and account_environment == {key: os.environ.get(key) for key in account_environment})
        bulk_names = [f"bulk-{number:04d}-[literal]-" + "long-name-" * 6 + ".txt" for number in range(600)]
        for filename in bulk_names:
            (repo / filename).write_text("bulk stage\n", encoding="utf-8")
        backend.stage(repo, bulk_names)
        checked("stage beyond Windows argv limit", sum(change.staged for change in backend.snapshot(repo).changes) == len(bulk_names))
        backend.unstage(repo, bulk_names)
        checked("unstage beyond Windows argv limit", not any(change.staged for change in backend.snapshot(repo).changes))
        for filename in bulk_names:
            (repo / filename).unlink()
        strange = "zażółć [1] # file.txt"
        (repo / strange).write_text("one\ntwo\n", encoding="utf-8")
        (repo / "--literal.txt").write_text("literal\n", encoding="utf-8")
        checked("Unicode and literal filenames", {c.path for c in backend.snapshot(repo).changes} == {strange, "--literal.txt"})
        checked("untracked preview", "+one" in backend.diff(repo, strange))
        backend.stage(repo, [strange])
        checked("stage", next(c for c in backend.snapshot(repo).changes if c.path == strange).staged)
        (repo / strange).write_text("one\ntwo\nthree\n", encoding="utf-8")
        change = next(c for c in backend.snapshot(repo).changes if c.path == strange)
        checked("staged and unstaged", change.staged and change.unstaged)
        backend.unstage(repo, [strange])
        checked("unborn unstage keeps file", (repo / strange).exists() and not any(c.staged for c in backend.snapshot(repo).changes))
        backend.stage(repo, [strange, "--literal.txt"])
        backend.commit(repo, "First commit", "Test description")
        snapshot = backend.snapshot(repo)
        checked("commit history", len(snapshot.commits) == 1 and snapshot.commits[0].subject == "First commit")
        commit_preview = backend.commit_diff(repo, snapshot.commits[0].oid)
        checked("commit preview separates metadata from patch",
                commit_preview.details.message == "First commit\n\nTest description" and "diff --git" in commit_preview
                and "Author:" not in commit_preview)
        first_oid = snapshot.commits[0].oid
        commit_files = {item.path: item for item in backend.commit_files(repo, [first_oid])}
        checked("root commit per-file line statistics", set(commit_files) == {strange, '--literal.txt'}
                and (commit_files[strange].status, commit_files[strange].additions, commit_files[strange].deletions) == ('A', 3, 0))
        file_preview = backend.commit_file_diff(repo, [first_oid], commit_files[strange])
        checked("single-file commit preview retains metadata", file_preview.details == commit_preview.details
                and '+three' in file_preview and '--literal.txt' not in file_preview)
        renamed = "renamed żółć [2].txt"
        (repo / strange).rename(repo / renamed)
        backend.stage(repo, [strange, renamed])
        change = next(c for c in backend.snapshot(repo).changes if c.path == renamed)
        checked("rename parsing", change.original_path == strange and change.index_status == "R")
        backend.unstage(repo, [renamed])
        checked("rename unstage includes source", not any(c.staged for c in backend.snapshot(repo).changes))
        backend.stage(repo, [strange, renamed])
        backend.commit(repo, "Rename file")
        rename_oid = backend.run(repo, ['rev-parse', 'HEAD']).strip()
        rename_files = backend.commit_files(repo, [rename_oid])
        checked("rename file statistics preserve both paths", len(rename_files) == 1
                and (rename_files[0].path, rename_files[0].original_path, rename_files[0].status,
                     rename_files[0].additions, rename_files[0].deletions) == (renamed, strange, 'R', 0, 0))
        combined_files = backend.commit_files(repo, [rename_oid, first_oid])
        checked("range file statistics show final net effect", {item.path for item in combined_files} == {renamed, '--literal.txt'}
                and sum(item.additions for item in combined_files) == 4 and sum(item.deletions for item in combined_files) == 0)
        directory_repo = Path(backend.init_repo(test_root / "rename-directory"))
        backend.set_identity(directory_repo, "Gitline Test", "gitline-test@example.invalid")
        (directory_repo / "old.txt").write_text("one\ntwo\nthree\n", encoding="utf-8")
        backend.stage(directory_repo, ["old.txt"])
        backend.commit(directory_repo, "Rename directory baseline")
        backend.run(directory_repo, ["mv", "old.txt", "new.txt"])
        (directory_repo / "new.txt").write_text("one\ntwo\nthree\nfour\n", encoding="utf-8")
        (directory_repo / "old.txt").mkdir()
        unrelated = directory_repo / "old.txt" / "unrelated.txt"
        unrelated.write_text("not selected\n", encoding="utf-8")
        rename = next(change for change in backend.changes(directory_repo) if change.original_path)
        backend.stage(directory_repo, [rename])
        directory_changes = {change.path: change for change in backend.changes(directory_repo)}
        checked("rename staging leaves source-directory children untracked",
                directory_changes["new.txt"].staged and not directory_changes["new.txt"].unstaged
                and directory_changes["old.txt/unrelated.txt"].index_status == "?")
        backend.stage(directory_repo, ["old.txt/unrelated.txt"])
        saved_index = backend.run(directory_repo, ["ls-files", "--stage", "-z"])
        rejected("rename unstage refuses unselected indexed descendants",
                 lambda: backend.unstage(directory_repo, ["new.txt"]))
        checked("rejected rename unstage preserves index and worktree",
                backend.run(directory_repo, ["ls-files", "--stage", "-z"]) == saved_index
                and unrelated.read_text(encoding="utf-8") == "not selected\n")
        backend.unstage(directory_repo, ["new.txt", "old.txt/unrelated.txt"])
        checked("rename and explicitly selected descendants unstage together",
                not any(change.staged for change in backend.changes(directory_repo))
                and unrelated.read_text(encoding="utf-8") == "not selected\n")
        backend.stage(directory_repo, ["old.txt"])
        directory_changes = {change.path: change for change in backend.changes(directory_repo)}
        checked("file-to-directory staging selects only the tracked deletion",
                directory_changes["old.txt"].index_status == "D"
                and directory_changes["old.txt/unrelated.txt"].index_status == "?"
                and directory_changes["new.txt"].index_status == "?")
        embedded_repo = Path(backend.init_repo(directory_repo / "embedded"))
        backend.set_identity(embedded_repo, "Gitline Test", "gitline-test@example.invalid")
        backend.run(embedded_repo, ["commit", "--allow-empty", "-m", "Embedded baseline"])
        embedded_change = next(change for change in backend.changes(directory_repo) if change.path == "embedded/")
        backend.stage(directory_repo, [embedded_change])
        checked("explicitly selected embedded repository still stages as a gitlink",
                backend.run(directory_repo, ["ls-files", "--stage", "--", "embedded"]).startswith("160000 "))
        backend.create_branch(repo, "feature/test")
        checked("create branch", backend.snapshot(repo).branch == "feature/test")
        backend.switch_branch(repo, "main")
        checked("switch branch", backend.snapshot(repo).branch == "main")
        (repo / "stash.txt").write_text("keep me", encoding="utf-8")
        backend.stash(repo)
        checked("stash includes untracked", backend.snapshot(repo).stash_count == 1 and not (repo / "stash.txt").exists())
        backend.stash_pop(repo)
        checked("stash restore", (repo / "stash.txt").read_text(encoding="utf-8") == "keep me")
        (repo / "stash.txt").unlink()
        bare = test_root / "remote.git"
        backend.run(None, ["init", "--bare", "--initial-branch=main", str(bare)])
        backend.run(repo, ["remote", "add", "origin", str(bare)])
        hook_directory = test_root / "push-hooks"
        hook_directory.mkdir()
        hook_output = test_root / "push-hook-arguments.txt"
        hook = hook_directory / "pre-push"
        hook.write_text("#!/bin/sh\nprintf '%s\\n' \"$1\" \"$2\" > " + shlex.quote(hook_output.as_posix())
                        + "\ncat >/dev/null\n", encoding="utf-8")
        hook.chmod(hook.stat().st_mode | stat.S_IXUSR)
        hook_backend = GitBackend(backend.git_exe, backend.auth_options + ["-c", "core.hooksPath=" + str(hook_directory)], backend.environment)
        hook_backend.push(repo)
        hook_arguments = hook_output.read_text(encoding="utf-8").splitlines()
        checked("pre-push hook preserves reviewed remote and endpoint",
                len(hook_arguments) == 2 and hook_arguments[0] == "origin"
                and Path(hook_arguments[1]).resolve() == bare.resolve())
        checked("push establishes upstream", backend.snapshot(repo).upstream == "origin/main")
        backend.run(repo, ["tag", "main"])
        collision_state = backend.snapshot(repo)
        main_ref = next(item for item in collision_state.branches if item.ref == "refs/heads/main")
        checked("tag collision preserves branch identity", collision_state.branch == "main" and main_ref.name == "main")
        backend.switch_branch(repo, "feature/test")
        backend.switch_branch(repo, main_ref)
        backend.push(repo)
        checked("tag collision switch and push", backend.snapshot(repo).head_ref == "refs/heads/main")
        backend.run(repo, ["tag", "-d", "main"])

        fork = test_root / "fork.git"
        push_endpoint = test_root / "fork-push.git"
        for target in (fork, push_endpoint):
            backend.run(None, ["init", "--bare", "--initial-branch=main", str(target)])
        backend.run(repo, ["remote", "add", "fork", str(fork)])
        backend.run(repo, ["config", "remote.fork.pushurl", str(push_endpoint)])
        backend.create_branch(repo, "publish/test")
        backend.run(repo, ["config", "branch.publish/test.remote", "origin"])
        backend.run(repo, ["config", "branch.publish/test.merge", "refs/heads/main"])
        backend.run(repo, ["config", "remote.pushDefault", "fork"])
        checked("remote.pushDefault selects fork", backend.resolve_push_plan(repo).remote_name == "fork")
        backend.run(repo, ["config", "branch.publish/test.pushRemote", "origin"])
        checked("branch pushRemote wins", backend.resolve_push_plan(repo, destination="publish/test").remote_name == "origin")
        backend.run(repo, ["config", "branch.publish/test.pushRemote", "fork"])
        (repo / "fork-only.txt").write_text("publish only to fork\n", encoding="utf-8")
        backend.stage(repo, ["fork-only.txt"])
        backend.commit(repo, "Fork-only commit")
        plan = backend.resolve_push_plan(repo)
        checked("push plan resolves pushurl", plan.push_urls == (str(push_endpoint),) and not plan.set_upstream)
        origin_before = backend.run(bare, ["rev-parse", "refs/heads/main"]).strip()
        backend.push(repo, plan)
        checked("fork push keeps pull upstream", backend.snapshot(repo).upstream == "origin/main")
        checked("push uses fork pushurl only",
                backend.run(push_endpoint, ["rev-parse", "refs/heads/publish/test"]).strip() == plan.head_oid
                and backend.run(bare, ["rev-parse", "refs/heads/main"]).strip() == origin_before
                and not backend._optional(fork, ["rev-parse", "--verify", "refs/heads/publish/test"]))
        original_resolve = backend.resolve_push_plan
        def replace_endpoint_after_validation(*args, **kwargs):
            reviewed = original_resolve(*args, **kwargs)
            backend.run(repo, ["config", "--add", "remote.fork.pushurl", str(fork)])
            backend.run(repo, ["config", "--add", "remote.fork.url", str(push_endpoint)])
            backend.run(repo, ["config", f"url.{fork}.insteadOf", str(push_endpoint)])
            backend.run(repo, ["config", f"url.{fork}.pushInsteadOf", "gitline-push-"])
            return reviewed
        try:
            backend.resolve_push_plan = replace_endpoint_after_validation
            backend.push(repo, plan)
            checked("push pins endpoint across post-validation config changes",
                    not backend._optional(fork, ["rev-parse", "--verify", "refs/heads/publish/test"])
                    and backend.run(push_endpoint, ["rev-parse", "refs/heads/publish/test"]).strip() == plan.head_oid)
        finally:
            backend.resolve_push_plan = original_resolve
            backend.run(repo, ["config", "--replace-all", "remote.fork.pushurl", str(push_endpoint)])
            backend.run(repo, ["config", "--replace-all", "remote.fork.url", str(fork)])
            backend.run(repo, ["config", "--unset-all", f"url.{fork}.insteadOf"])
            backend.run(repo, ["config", "--unset-all", f"url.{fork}.pushInsteadOf"])
        backend.run(repo, ["config", "remote.fork.pushurl", "../fork-push.git"])
        checked("push plan pins relative local URLs", backend.resolve_push_plan(repo).push_urls == (str(push_endpoint.resolve()),))
        backend.run(repo, ["config", "remote.fork.pushurl", str(push_endpoint)])
        backend.run(repo, ["config", "remote.fork.pushurl", str(fork)])
        rejected("push rejects changed endpoint", lambda: backend.push(repo, plan))
        backend.run(repo, ["config", "remote.fork.pushurl", str(push_endpoint)])
        backend.run(repo, ["config", "remote.fork.push", "refs/heads/*:refs/heads/*"])
        rejected("push refuses wildcard refspec", lambda: backend.resolve_push_plan(repo))
        checked("explicit destination resolves configured ambiguity",
                backend.resolve_push_plan(repo, destination="review/topic").destination_ref == "refs/heads/review/topic")
        backend.run(repo, ["config", "--unset", "remote.fork.push"])
        (repo / "fork-only.txt").write_text("another unreviewed commit\n", encoding="utf-8")
        backend.stage(repo, ["fork-only.txt"])
        backend.commit(repo, "Unreviewed commit")
        rejected("push rejects changed HEAD", lambda: backend.push(repo, plan))
        checked("rejected plan leaves remote unchanged", backend.run(push_endpoint, ["rev-parse", "refs/heads/publish/test"]).strip() == plan.head_oid)
        backend.switch_branch(repo, "main")
        backend.run(repo, ["config", "--unset", "remote.pushDefault"])
        backend.run(repo, ["remote", "remove", "fork"])
        clone = Path(backend.clone(str(bare), test_root / "clone"))
        backend.set_identity(clone, "Gitline Test", "gitline-test@example.invalid")
        backend.run(clone, ["config", "commit.gpgSign", "false"])
        backend.run(clone, ["config", "core.hooksPath", str(test_root / "no-hooks")])
        (clone / "remote.txt").write_text("from clone\n", encoding="utf-8")
        backend.stage(clone, ["remote.txt"])
        backend.commit(clone, "Remote commit")
        backend.push(clone)
        backend.fetch(repo)
        checked("fetch behind count", backend.snapshot(repo).behind == 1)
        backend.pull(repo)
        checked("fast-forward pull", (repo / "remote.txt").exists() and backend.snapshot(repo).behind == 0)
        # Verify divergence cannot create an implicit merge commit.
        (repo / "local.txt").write_text("local", encoding="utf-8")
        backend.stage(repo, ["local.txt"])
        backend.commit(repo, "Local diverging commit")
        (clone / "second.txt").write_text("remote", encoding="utf-8")
        backend.stage(clone, ["second.txt"])
        backend.commit(clone, "Remote diverging commit")
        backend.push(clone)
        backend.fetch(repo)
        diverged = backend.snapshot(repo)
        checked("divergence counts", diverged.ahead == 1 and diverged.behind == 1)
        old_head = backend.run(repo, ["rev-parse", "HEAD"]).strip()
        try:
            backend.pull(repo)
            raise AssertionError("Diverging pull should fail")
        except GitError:
            pass
        checked("pull never implicitly merges", backend.run(repo, ["rev-parse", "HEAD"]).strip() == old_head)
        remote_before = backend.run(bare, ["rev-parse", "refs/heads/main"]).strip()
        rejected("push never forces divergent history", lambda: backend.push(repo))
        checked("rejected push keeps remote history", backend.run(bare, ["rev-parse", "refs/heads/main"]).strip() == remote_before)
        backend.run(repo, ["switch", "--detach", old_head])
        checked("detached state", backend.snapshot(repo).branch.startswith("Poza gałęzią"))
        backend.switch_branch(repo, "main")
        (repo / "binary.bin").write_bytes(b"\0\1\2\3")
        checked("binary preview", "Plik binarny" in backend.diff(repo, "binary.bin"))
        (repo / "large.txt").write_text("line\n" * 70_000, encoding="utf-8")
        checked("large preview bounded", backend.diff(repo, "large.txt").truncated)
        (repo / "large-utf8.txt").write_bytes(b"a" * (backend.DIFF_LIMIT - 1) + "ą".encode("utf-8") + b"\n")
        utf8_preview = backend.diff(repo, "large-utf8.txt")
        checked("UTF-8 truncation keeps valid preview", utf8_preview.startswith("diff --git") and utf8_preview.truncated and "\ufffd" not in utf8_preview)
        checked("diff parser retains truncation metadata", parse_diff_document(utf8_preview).truncated)
        (repo / "large-utf8.txt").unlink()
        parsed = parse_diff_document("diff --git a/f b/f\n--- a/f\n+++ b/f\n@@ -10,2 +20,2 @@\n--- source text\n+++ source text\n context\n\\ No newline at end of file\n"
                                     "diff --git a/g b/g\n--- a/g\n+++ b/g\n@@ -0,0 +1 @@\n+new\n")
        checked("diff parser distinguishes headers from content",
                parsed.lines[1].kind == "meta" and parsed.lines[2].kind == "meta"
                and parsed.lines[4] == DiffLine("delete", 10, None, "--- source text")
                and parsed.lines[5] == DiffLine("add", None, 20, "+++ source text"))
        checked("diff parser resets hunk coordinates",
                parsed.lines[6] == DiffLine("context", 11, 21, " context")
                and parsed.lines[-1] == DiffLine("add", None, 1, "+new")
                and parsed.lines[7].kind == "note")
        unicode_lines = parse_diff_document("@@ -0,0 +1 @@\n+left\u2028right\n")
        checked("diff parser preserves Unicode line separators in source",
                len(unicode_lines.lines) == 2 and unicode_lines.lines[1] == DiffLine("add", None, 1, "+left\u2028right"))
        try:
            backend.diff(repo, "../outside.txt")
            raise AssertionError("A path outside the repository should fail")
        except GitError:
            checks.append("path traversal rejected")
        checked("credentials redacted", "secret" not in _git_safe_text("https://person:secret@example.com/repo"))
        (repo / "binary.bin").unlink()
        (repo / "large.txt").unlink()
        backend.create_branch(repo, "conflict/test")
        (repo / renamed).write_text("conflict branch\n", encoding="utf-8")
        backend.stage(repo, [renamed])
        backend.commit(repo, "Conflict branch change")
        backend.switch_branch(repo, "main")
        (repo / renamed).write_text("main branch\n", encoding="utf-8")
        backend.stage(repo, [renamed])
        backend.commit(repo, "Main branch change")
        try:
            backend.run(repo, ["merge", "--no-edit", "conflict/test"])
            raise AssertionError("Conflicting merge should fail")
        except GitError:
            pass
        conflicted = backend.snapshot(repo)
        checked("conflict and operation parsing", conflicted.operation == "merge" and any(change.conflicted for change in conflicted.changes))
        numeric = parse_git_progress('Writing objects: 50% (1/2), 1.50 KiB | 2.00 MiB/s')
        checked("push progress parses numeric transfer units and padded percentages", numeric == GitProgress(
            'writing', 1, 2, 50, transferred_bytes=1536, bytes_per_second=2097152)
            and [parse_git_progress(f'Writing objects: {percent:3d}% ({percent}/100)').percent
                 for percent in (1, 50, 100)] == [1, 50, 100])
        checked("push progress rejects arbitrary hook output and invalid counters",
                all(parse_git_progress(line) is None for line in (
                    'remote: custom hook output', 'Counting objects: 101% (1/2)',
                    'Counting objects: 50% (1/2), custom hook output')))
        progress_events = []
        stream = _GitProgressStream(progress_events.append)
        stream.feed(b'Writing obj'); stream.feed(b'ects: 50% (1/2)\r')
        stream.feed(b'Writing objects: 100% (2/2), done.\r\n'); stream.finish()
        checked("CR-delimited progress waits for server after the writing phase reaches 100",
                [event.phase for event in progress_events] == ['writing', 'writing', 'awaiting_server']
                and [event.percent for event in progress_events] == [50, 100, None])
        print("Backend self-test passed: " + str(len(checks)) + " checks.")
        return checks
    finally:
        def remove_readonly(function, path, exception):
            os.chmod(path, stat.S_IWRITE | stat.S_IREAD)
            function(path)
        if not test_root.resolve().is_relative_to(Path(tempfile.gettempdir()).resolve()) or not test_root.name.startswith("gitline-self-test-"):
            raise RuntimeError("Refusing to remove a self-test directory outside the temporary folder.")
        shutil.rmtree(test_root, onerror=remove_readonly)

# --- Accounts: credentials stay in the operating system vault. ---
import contextlib as auth_contextlib
import hashlib as auth_hashlib
import ipaddress as auth_ipaddress
import json as auth_json
import os as auth_os
from pathlib import Path as AuthPath
import re as auth_re
import shlex as auth_shlex
import shutil as auth_shutil
import subprocess as auth_subprocess
import sys as auth_sys
auth_sys.dont_write_bytecode = True
import tempfile as auth_tempfile
import threading as auth_threading
import time as auth_time
from urllib import error as auth_urlerror, parse as auth_urlparse, request as auth_urlrequest
import uuid as auth_uuid

_pulse_early_gui()


class AuthError(Exception):
    """A user-facing error whose text never contains a credential or HTTP body."""


def auth_normalize_host(value):
    value = str(value).strip()
    if not value or any(ord(c) < 33 for c in value) or "\\" in value:
        raise AuthError("Wpisz poprawny adres serwera HTTPS, np. https://gitlab.com.")
    if "://" not in value:
        value = "https://" + value
    try:
        parsed = auth_urlparse.urlsplit(value)
        if (parsed.scheme.lower() != "https" or not parsed.hostname or parsed.username is not None
                or parsed.password is not None or parsed.path not in ("", "/") or parsed.query or parsed.fragment):
            raise ValueError()
        hostname = parsed.hostname.encode("idna").decode("ascii").lower().rstrip(".")
        port = parsed.port
        if ":" in hostname:
            auth_ipaddress.IPv6Address(hostname)
            hostname = "[" + hostname + "]"
        elif (len(hostname) > 253 or not all(auth_re.fullmatch(r"[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?", part)
                                            for part in hostname.split("."))):
            raise ValueError()
        if port is not None and not 1 <= port <= 65535:
            raise ValueError()
    except (ValueError, UnicodeError):
        raise AuthError("Podaj sam adres serwera HTTPS, bez loginu, hasła ani ścieżki.") from None
    return "https://" + hostname + (":" + str(port) if port and port != 443 else "")


def auth_validate_clone_url(value):
    """Validate an API-provided HTTPS remote before returning it to the UI."""
    if not isinstance(value, str) or any(ord(c) < 33 for c in value) or "\\" in value:
        raise AuthError("Serwer zwrócił niepoprawny adres repozytorium.")
    try:
        parsed = auth_urlparse.urlsplit(value)
        if parsed.scheme != "https" or parsed.username is not None or parsed.password is not None or parsed.query or parsed.fragment:
            raise ValueError()
        auth_normalize_host("https://" + parsed.netloc)
    except (ValueError, AuthError):
        raise AuthError("Adres repozytorium musi używać HTTPS i nie może zawierać poświadczeń.") from None
    return value


class AuthNoRedirect(auth_urlrequest.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        # Never forward a token to another origin, even if a server redirects.
        raise AuthError("Serwer przekierował API. Wpisz jego końcowy adres HTTPS i spróbuj ponownie.")


class AccountStore:
    SERVICE = "Gitline/accounts/v1"

    def __init__(self, data_dir=None, keyring_backend=None, request_function=None):
        self._central = data_dir is None
        self.data_dir = AuthPath(APP_DATA if self._central else data_dir)
        self.path = _config_path() if self._central else self.data_dir / "accounts.json"
        self._backend = keyring_backend
        self._request_function = request_function
        self._lock = auth_threading.RLock()

    @auth_contextlib.contextmanager
    def _file_lock(self, name, timeout=240):
        """Separate open-file locks coordinate GUI instances and credential helpers."""
        directory = self.data_dir / "account-locks"
        try:
            directory.mkdir(parents=True, exist_ok=True)
            path = directory / (auth_hashlib.sha256(name.encode("utf-8")).hexdigest() + ".lock")
            descriptor = auth_os.open(str(path), auth_os.O_RDWR | auth_os.O_CREAT, 0o600)
        except OSError:
            raise AuthError("Nie można zablokować danych kont. Sprawdź dostęp do folderu aplikacji.") from None
        acquired = False
        try:
            if auth_os.fstat(descriptor).st_size == 0:
                auth_os.write(descriptor, b"0")
            deadline = auth_time.monotonic() + timeout
            while not acquired:
                _check_task_cancelled()
                try:
                    auth_os.lseek(descriptor, 0, auth_os.SEEK_SET)
                    if auth_os.name == "nt":
                        import msvcrt
                        msvcrt.locking(descriptor, msvcrt.LK_NBLCK, 1)
                    else:
                        import fcntl
                        fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
                    acquired = True
                except OSError:
                    if auth_time.monotonic() >= deadline:
                        raise AuthError("Konto jest zajęte przez inną operację. Spróbuj ponownie za chwilę.") from None
                    auth_time.sleep(0.05)
            yield
        finally:
            if acquired:
                auth_os.lseek(descriptor, 0, auth_os.SEEK_SET)
                if auth_os.name == "nt":
                    import msvcrt
                    msvcrt.locking(descriptor, msvcrt.LK_UNLCK, 1)
                else:
                    import fcntl
                    fcntl.flock(descriptor, fcntl.LOCK_UN)
            auth_os.close(descriptor)

    @auth_contextlib.contextmanager
    def _metadata(self):
        # Never hold this lock while calling an API, GCM, or the password vault.
        try:
            with self._lock, (_config_lock() if self._central else self._file_lock("metadata", timeout=15)):
                yield
        except (OSError, ValueError, RuntimeError):
            raise AuthError("Nie można odczytać lub zapisać konfiguracji kont. Sprawdź plik gitline.json i dostęp do jego folderu.") from None

    def _account_lock(self, account_id):
        return self._file_lock("account:" + account_id)

    @staticmethod
    def _generation(account):
        return account.get("generation", "legacy")

    @staticmethod
    def _credential_id(account):
        return account.get("credential_id", account["id"])

    @staticmethod
    def _binding_key(repo, remote, host):
        path = auth_os.path.normcase(str(AuthPath(repo).expanduser().resolve()))
        return auth_json.dumps([path, str(remote or "origin"), auth_normalize_host(host)], ensure_ascii=False)

    def get_repository_account(self, repo, remote, host):
        key = self._binding_key(repo, remote, host)
        with self._metadata():
            data = self._read()
            # Retain an explicit binding after disconnect. Silently falling back to
            # another host account could push a repository as the wrong person.
            return data["bindings"].get(key)

    def set_repository_account(self, repo, remote, host, account_id):
        host = auth_normalize_host(host)
        key = self._binding_key(repo, remote, host)
        with self._metadata():
            data = self._read()
            if account_id is None:
                data["bindings"].pop(key, None)
            else:
                if not any(item["id"] == account_id and item["host"] == host
                           and item.get("state", "active") == "active" for item in data["accounts"]):
                    raise AuthError("Wybrane konto nie jest dostępne dla tego serwera.")
                data["bindings"][key] = account_id
            self._write(data)

    def _vault(self):
        if self._backend is not None:
            return self._backend
        try:
            import keyring
            backend = keyring.get_keyring()
            candidates = list(getattr(backend, "backends", [])) or [backend]
            secure_modules = ("keyring.backends.Windows", "keyring.backends.macOS", "keyring.backends.SecretService",
                              "keyring.backends.libsecret", "keyring.backends.kwallet")
            for candidate in candidates:
                if type(candidate).__module__.startswith(secure_modules) and candidate.priority > 0:
                    self._backend = candidate
                    return candidate
        except Exception:
            pass
        raise AuthError("Nie można otworzyć systemowego magazynu haseł. Odblokuj go i spróbuj ponownie.")

    def _read(self):
        if not self._central:
            return self._read_document(self.path)
        try:
            with _config_lock():
                if not _config_has_section("accounts"):
                    _set_config_section("accounts", {"version": 1, "accounts": [], "defaults": {}, "bindings": {}, "cleanup": []})
                return self._read_document(None)
        except (OSError, ValueError, RuntimeError):
            raise AuthError("Nie można odczytać zapisanych kont. Plik gitline.json jest niedostępny lub uszkodzony.") from None

    def _read_document(self, path):
        if path is not None and not path.exists():
            return {"version": 1, "accounts": [], "defaults": {}, "bindings": {}, "cleanup": []}
        try:
            data = _config_section("accounts") if path is None else auth_json.loads(path.read_text(encoding="utf-8"))
            if not isinstance(data, dict) or data.get("version") != 1 or not isinstance(data.get("accounts"), list):
                raise ValueError()
            accounts = []
            for item in data["accounts"]:
                if (not isinstance(item, dict) or not all(isinstance(item.get(k), str) for k in
                       ("id", "provider", "host", "username", "display_name")) or item["provider"] not in ("github", "gitlab")):
                    raise ValueError()
                if auth_normalize_host(item["host"]) != item["host"] or any(c in item["username"] for c in "\r\n\x00"):
                    raise ValueError()
                if (item.get("state", "active") not in ("active", "removing")
                        or item.get("auth_kind", "token") not in ("token", "gcm")
                        or any(key in item and not isinstance(item[key], str)
                               for key in ("generation", "credential_id", "gcm_namespace", "git_exe"))
                        or item.get("auth_kind") == "gcm" and not item.get("gcm_namespace")):
                    raise ValueError()
                accounts.append(dict(item))
            defaults = data.get("defaults", {})
            if not isinstance(defaults, dict):
                raise ValueError()
            bindings, cleanup = data.get("bindings", {}), data.get("cleanup", [])
            if (not isinstance(bindings, dict) or not all(isinstance(k, str) and isinstance(v, str)
                    for k, v in bindings.items()) or not isinstance(cleanup, list)):
                raise ValueError()
            for entry in cleanup:
                if (not isinstance(entry, dict) or not isinstance(entry.get("cleanup_id"), str)
                        or not isinstance(entry.get("account"), dict)
                        or not all(isinstance(entry["account"].get(k), str)
                                   for k in ("id", "host", "username"))):
                    raise ValueError()
            return {"version": 1, "accounts": accounts, "defaults": defaults,
                    "bindings": bindings, "cleanup": cleanup}
        except (ValueError, OSError, RuntimeError, AuthError):
            raise AuthError("Nie można odczytać zapisanych kont. Plik konfiguracji jest niedostępny lub uszkodzony.") from None

    def _write(self, data):
        try:
            if self._central:
                _set_config_section("accounts", data)
                return
            self.data_dir.mkdir(parents=True, exist_ok=True)
            fd, temporary = auth_tempfile.mkstemp(prefix="accounts-", suffix=".tmp", dir=str(self.data_dir))
            try:
                with auth_os.fdopen(fd, "w", encoding="utf-8") as stream:
                    auth_json.dump(data, stream, ensure_ascii=False, indent=2)
                    stream.flush()
                    auth_os.fsync(stream.fileno())
                auth_os.replace(temporary, self.path)
            finally:
                if auth_os.path.exists(temporary):
                    auth_os.unlink(temporary)
        except (OSError, ValueError, RuntimeError):
            raise AuthError("Nie udało się zapisać listy kont. Sprawdź dostęp do folderu danych aplikacji.") from None

    def list_accounts(self):
        with self._metadata():
            data = self._read()
            return [dict(item, is_default=data["defaults"].get(item["host"]) == item["id"],
                         removal_pending=item.get("state") == "removing") for item in data["accounts"]]

    def get_account(self, account_id):
        for item in self.list_accounts():
            if item["id"] == account_id and item.get("state", "active") == "active":
                return item
        raise AuthError("To konto nie jest już połączone. Dodaj je ponownie.")

    def resolve_account(self, host, username=None, account_id=None, repo=None, remote=None):
        """Resolve metadata in one snapshot; None delegates authentication to Git."""
        host = auth_normalize_host(host)
        if any(value is not None and (not isinstance(value, str) or any(ord(char) < 32 for char in value))
               for value in (username, account_id)):
            raise AuthError("Dane wyboru konta zawierają nieprawidłowe znaki.")
        binding_key = self._binding_key(repo, remote, host) if repo else None
        with self._metadata():
            data = self._read()
            accounts = [dict(item, is_default=data["defaults"].get(host) == item["id"], removal_pending=False)
                        for item in data["accounts"] if item["host"] == host and item.get("state", "active") == "active"]
            bound = binding_key is not None and binding_key in data["bindings"]
            selected_id = account_id or (data["bindings"].get(binding_key) if bound else None)
        if account_id or bound:
            account = next((item for item in accounts if item["id"] == selected_id), None)
            if account is None:
                raise AuthError("Konto przypisane do tej operacji nie jest dostępne dla serwera. Połącz je ponownie lub wybierz inne konto repozytorium.")
            return account
        placeholders = {"git", "oauth2", "x-access-token", "gitlab-ci-token", "x-token-auth"}
        if username and username.casefold() not in placeholders:
            matches = [item for item in accounts if item["username"].casefold() == username.casefold()]
            if len(matches) == 1:
                return matches[0]
            if not matches:
                return None
            raise AuthError("Kilka kont odpowiada nazwie użytkownika w adresie. Wybierz konto dla tego repozytorium.")
        if len(accounts) <= 1:
            return accounts[0] if accounts else None
        defaults = [item for item in accounts if item["is_default"]]
        if len(defaults) == 1:
            return defaults[0]
        raise AuthError("Ten serwer ma kilka połączonych kont. Wybierz konto dla repozytorium lub ustaw konto domyślne.")

    def _request(self, provider, host, endpoint, token):
        _check_task_cancelled()
        if self._request_function is not None:
            result = self._request_function(provider, host, endpoint, token)
            _check_task_cancelled()
            return result
        host = auth_normalize_host(host)
        base = ("https://api.github.com" if host == "https://github.com" else host + "/api/v3") if provider == "github" else host + "/api/v4"
        headers = {"Accept": "application/json", "User-Agent": "Gitline/1.0"}
        if provider == "github":
            headers["Authorization"] = "Bearer " + token
        else:
            headers["PRIVATE-TOKEN"] = token
        request = auth_urlrequest.Request(base + endpoint, headers=headers)
        try:
            opener = auth_urlrequest.build_opener(AuthNoRedirect())
            # Socket waits are short for a cancellable catalog/login read. DNS
            # resolution remains OS-owned and may exceed this socket timeout.
            timeout = 3 if _task_cancel_event() is not None else 25
            deadline = auth_time.monotonic() + 25
            with opener.open(request, timeout=timeout) as response:
                reader = getattr(response, 'read1', response.read)
                raw = bytearray()
                while True:
                    _check_task_cancelled()
                    if auth_time.monotonic() >= deadline:
                        raise AuthError('Minął czas pobierania odpowiedzi serwera. Spróbuj ponownie.')
                    chunk = reader(min(64 * 1024, 8 * 1024 * 1024 + 1 - len(raw)))
                    _check_task_cancelled()
                    if not chunk:
                        break
                    raw.extend(chunk)
                    if len(raw) > 8 * 1024 * 1024:
                        raise AuthError("Odpowiedź serwera jest zbyt duża. Spróbuj ponownie.")
                return auth_json.loads(raw)
        except auth_urlerror.HTTPError as error:
            _check_task_cancelled()
            if error.code == 401:
                raise AuthError("Token jest nieprawidłowy lub wygasł. Utwórz nowy i połącz konto ponownie.") from None
            if error.code == 403:
                raise AuthError("Brak dostępu do API lub przekroczony limit. Sprawdź uprawnienia tokenu i wymagania SSO.") from None
            if error.code == 404:
                raise AuthError("Nie znaleziono API. Sprawdź adres serwera i wybranego dostawcę.") from None
            raise AuthError("Serwer zwrócił błąd HTTP " + str(error.code) + ". Spróbuj ponownie później.") from None
        except (auth_urlerror.URLError, TimeoutError, OSError):
            _check_task_cancelled()
            raise AuthError("Nie można połączyć się z serwerem. Sprawdź internet, adres oraz certyfikat HTTPS.") from None
        except (ValueError, UnicodeError):
            raise AuthError("Serwer zwrócił niepoprawną odpowiedź API.") from None

    @staticmethod
    def _validate_token(token):
        token = str(token).strip()
        if not token or len(token) > 16384 or any(ord(c) < 33 or ord(c) > 126 for c in token):
            raise AuthError("Wklej poprawny token dostępu, bez spacji i znaków nowej linii.")
        return token

    def login(self, provider, host, token, cancel=None, _extra=None):
        if provider not in ("github", "gitlab"):
            raise AuthError("Wybierz GitHub albo GitLab.")
        host = auth_normalize_host(host)
        token = self._validate_token(token)
        if cancel is not None and cancel.is_set():
            raise AuthError("Łączenie konta anulowano.")
        self._vault()  # Fail before contacting the service if secure persistence is unavailable.
        user = self._request(provider, host, "/user", token)
        if not isinstance(user, dict):
            raise AuthError("Serwer nie zwrócił profilu konta.")
        username = user.get("login" if provider == "github" else "username")
        if not isinstance(username, str) or not username or len(username) > 255 or any(ord(c) < 33 for c in username):
            raise AuthError("Serwer nie zwrócił poprawnej nazwy użytkownika.")
        if cancel is not None and cancel.is_set():
            raise AuthError("Łączenie konta anulowano.")
        identity = provider + "\n" + host + "\n" + str(user.get("id", username.lower()))
        account_id = auth_hashlib.sha256(identity.encode("utf-8")).hexdigest()[:32]
        generation = auth_uuid.uuid4().hex
        account = {"id": account_id, "provider": provider, "host": host, "username": username,
                   "display_name": str(user.get("name") or username), "auth_kind": "token",
                   "generation": generation, "credential_id": account_id + "/" + generation, "state": "active"}
        extra = dict(_extra or {})
        browser_cleanup_id = extra.pop("_browser_cleanup_id", None)
        account.update(extra)
        with self._account_lock(account_id):
            self._recover_account_locked(account_id)
            if cancel is not None and cancel.is_set():
                raise AuthError("Łączenie konta anulowano.")
            # Journal a new vault slot before touching it. A crash can leave cleanup
            # work, but it cannot overwrite the previous account's working token.
            cleanup_id = auth_uuid.uuid4().hex
            with self._metadata():
                data = self._read()
                previous = next((item for item in data["accounts"] if item["id"] == account_id), None)
                if browser_cleanup_id:
                    data["cleanup"] = [entry for entry in data["cleanup"] if entry["cleanup_id"] != browser_cleanup_id]
                data["cleanup"].append({"cleanup_id": cleanup_id, "account": account})
                self._write(data)
            try:
                self._vault().set_password(self.SERVICE, self._credential_id(account), token)
            except Exception:
                raise AuthError("Nie można zapisać tokenu w systemowym magazynie haseł.") from None
            if account.get("auth_kind") == "gcm":
                self._gcm_store(self._account_git_exe(account), host, account["gcm_namespace"], username, token)
            if cancel is not None and cancel.is_set():
                self._recover_account_locked(account_id)
                raise AuthError("Łączenie konta anulowano.")
            with self._metadata():
                data = self._read()
                data["accounts"] = [item for item in data["accounts"] if item["id"] != account_id] + [account]
                data["defaults"].setdefault(host, account_id)
                data["cleanup"] = [entry for entry in data["cleanup"] if entry["cleanup_id"] != cleanup_id]
                if previous:
                    data["cleanup"].append({"cleanup_id": auth_uuid.uuid4().hex, "account": previous})
                self._write(data)
            # The replacement is now durable. Failed retirement remains journaled
            # for a later retry without reporting the new login as a failure.
            try:
                self._recover_account_locked(account_id)
            except AuthError:
                pass
        return dict(account, is_default=data["defaults"].get(host) == account_id)

    def set_default(self, account_id):
        with self._metadata():
            data = self._read()
            account = next((item for item in data["accounts"] if item["id"] == account_id), None)
            if account is None or account.get("state", "active") != "active":
                raise AuthError("Nie znaleziono konta.")
            data["defaults"][account["host"]] = account_id
            self._write(data)

    def forget(self, account_id):
        with self._account_lock(account_id):
            with self._metadata():
                data = self._read()
                account = next((item for item in data["accounts"] if item["id"] == account_id), None)
                if account is not None:
                    account["state"] = "removing"
                    self._write(data)
            self._recover_account_locked(account_id)

    def _retire_credential(self, account):
        self._erase_gcm_account(account)
        try:
            vault, credential_id = self._vault(), self._credential_id(account)
            if vault.get_password(self.SERVICE, credential_id) is not None:
                vault.delete_password(self.SERVICE, credential_id)
        except Exception:
            raise AuthError("Nie można usunąć tokenu z systemowego magazynu haseł. Odłączenie oczekuje na ponowienie.") from None

    def _recover_account_locked(self, account_id):
        """Called with the account lock, never with the metadata lock held."""
        # Once credentials are journaled, cancellation must not interrupt their
        # retirement or the matching durable cleanup update.
        return _run_cancellable(None, lambda: self._recover_account_locked_impl(account_id))

    def _recover_account_locked_impl(self, account_id):
        with self._metadata():
            data = self._read()
            account = next((item for item in data["accounts"] if item["id"] == account_id), None)
            pending = [entry for entry in data["cleanup"] if entry["account"]["id"] == account_id]
        if account is not None and account.get("state") == "removing":
            self._retire_credential(account)
            with self._metadata():
                data = self._read()
                data["accounts"] = [item for item in data["accounts"] if item["id"] != account_id]
                if data["defaults"].get(account["host"]) == account_id:
                    others = [item for item in data["accounts"] if item["host"] == account["host"]
                              and item.get("state", "active") == "active"]
                    if len(others) == 1:
                        data["defaults"][account["host"]] = others[0]["id"]
                    else:
                        data["defaults"].pop(account["host"], None)
                self._write(data)
        for entry in pending:
            self._retire_credential(entry["account"])
            with self._metadata():
                data = self._read()
                data["cleanup"] = [item for item in data["cleanup"] if item["cleanup_id"] != entry["cleanup_id"]]
                self._write(data)

    def recover_pending(self):
        """Retry interrupted removals/failed login cleanup; safe to call in a worker."""
        with self._metadata():
            data = self._read()
            ids = {entry["account"]["id"] for entry in data["cleanup"]}
            ids.update(item["id"] for item in data["accounts"] if item.get("state") == "removing")
        errors = []
        for account_id in ids:
            try:
                with self._account_lock(account_id):
                    self._recover_account_locked(account_id)
            except AuthError as error:
                errors.append(str(error))
        return errors

    def _erase_gcm_account(self, account):
        if account.get("auth_kind") != "gcm":
            return
        # Only erase the dedicated Gitline namespace; other Git clients are unaffected.
        try:
            self._gcm_call(self._account_git_exe(account), "erase", account["host"],
                           account["gcm_namespace"], username=account["username"], timeout=10)
        except AuthError:
            raise AuthError("Nie udało się usunąć poświadczenia przeglądarki. Sprawdź instalację Git Credential Manager i spróbuj ponownie.") from None

    def _token(self, account):
        try:
            token = self._vault().get_password(self.SERVICE, self._credential_id(account))
        except Exception:
            raise AuthError("Nie można odczytać tokenu. Odblokuj systemowy magazyn haseł.") from None
        if not token:
            raise AuthError("Brakuje zapisanego tokenu. Połącz konto ponownie.")
        return self._validate_token(token)

    def credential_for(self, host, username=None, account_id=None, refresh=False, repo=None, remote=None):
        host = auth_normalize_host(host)
        account = self.resolve_account(host, username=username, account_id=account_id, repo=repo, remote=remote)
        if account is None:
            return None
        with self._account_lock(account["id"]):
            with self._metadata():
                current = next((item for item in self._read()["accounts"] if item["id"] == account["id"]), None)
            if (current is None or current.get("state", "active") != "active"
                    or self._generation(current) != self._generation(account)):
                raise AuthError("Wybrane konto zostało odłączone lub zmienione. Sprawdź konto przed ponowną próbą.")
            token = self._token(current)
            if refresh and current.get("auth_kind") == "gcm":
                try:
                    result = self._gcm_call(self._account_git_exe(current), "get", host, current["gcm_namespace"],
                                            username=current["username"], interactive=False,
                                            cancel=_task_cancel_event(), timeout=30)
                except AuthError:
                    _check_task_cancelled()
                    result = {}  # The current vault token remains usable when GCM is offline.
                _check_task_cancelled()
                if result.get("password"):
                    token = self._validate_token(result["password"])
                    try:
                        self._vault().set_password(self.SERVICE, self._credential_id(current), token)
                    except Exception:
                        raise AuthError("Nie można odświeżyć tokenu w systemowym magazynie haseł.") from None
            return {"username": current["username"], "password": token}

    def list_repositories(self, account_id):
        _check_task_cancelled()
        account = self.get_account(account_id)
        credential = self.credential_for(account["host"], account_id=account_id, refresh=True)
        _check_task_cancelled()
        if credential is None:
            raise AuthError("To konto nie jest już połączone.")
        token = credential["password"]
        result = []
        for page in range(1, 101):
            _check_task_cancelled()
            endpoint = ("/user/repos?sort=updated&direction=desc&per_page=100&page=" if account["provider"] == "github"
                        else "/projects?membership=true&order_by=last_activity_at&sort=desc&per_page=100&page=") + str(page)
            items = self._request(account["provider"], account["host"], endpoint, token)
            if not isinstance(items, list):
                raise AuthError("Serwer nie zwrócił listy repozytoriów.")
            for item in items:
                _check_task_cancelled()
                if not isinstance(item, dict):
                    continue
                is_github = account["provider"] == "github"
                clone_url = item.get("clone_url" if is_github else "http_url_to_repo", "")
                try:
                    clone_url = auth_validate_clone_url(clone_url)
                    if auth_normalize_host("https://" + auth_urlparse.urlsplit(clone_url).netloc) != account["host"]:
                        continue
                except AuthError:
                    continue
                result.append({"name": str(item.get("name", "")),
                               "full_name": str(item.get("full_name" if is_github else "path_with_namespace", item.get("name", ""))),
                               "clone_url": clone_url, "ssh_url": str(item.get("ssh_url" if is_github else "ssh_url_to_repo", "")),
                               "private": bool(item.get("private", item.get("visibility") != "public")),
                               "description": str(item.get("description") or ""),
                               "default_branch": str(item.get("default_branch") or "main"),
                               "account_id": account_id})
            if len(items) < 100:
                break
        return result

    @staticmethod
    def _account_git_exe(account):
        return account.get("git_exe") or discover_git()

    @staticmethod
    def find_gcm(git_exe):
        if not git_exe:
            return None
        git_path = AuthPath(git_exe).resolve()
        candidates = [git_path.parent / "git-credential-manager.exe", git_path.parent / "git-credential-manager",
                      git_path.parent.parent / "mingw64" / "bin" / "git-credential-manager.exe",
                      git_path.parent.parent / "libexec" / "git-core" / "git-credential-manager"]
        found = auth_shutil.which("git-credential-manager") or auth_shutil.which("git-credential-manager-core")
        if found:
            candidates.append(AuthPath(found))
        return next((str(path) for path in candidates if path.is_file()), None)

    @staticmethod
    def _gcm_environment(git_exe, namespace, interactive=False):
        env = auth_os.environ.copy()
        env["PATH"] = str(AuthPath(git_exe).resolve().parent) + auth_os.pathsep + env.get("PATH", "")
        env.update({"GCM_NAMESPACE": namespace, "GCM_INTERACTIVE": "true" if interactive else "false",
                    "GCM_GITHUB_AUTHMODES": "browser", "GCM_PROVIDER": "github", "GCM_GUI_PROMPT": "true"})
        for key in list(env):
            if key.startswith(("GIT_TRACE", "GCM_TRACE")) or key in ("GIT_CURL_VERBOSE",):
                env.pop(key, None)
        # GCM environment values override Git config, including URL-specific
        # settings. Merely removing variables would reactivate a configured
        # plaintext store or credential.traceSecrets logging.
        env.update({"GCM_CREDENTIAL_STORE": "wincredman" if auth_os.name == "nt" else
                        "keychain" if auth_sys.platform == "darwin" else "secretservice",
                    "GCM_TRACE": "false", "GCM_TRACE_SECRETS": "false",
                    "GCM_TRACE_MSAUTH": "false", "GCM_DEBUG": "false"})
        return env

    @staticmethod
    def _gcm_call(git_exe, action, host, namespace, username=None, interactive=False, cancel=None, timeout=180):
        gcm = AccountStore.find_gcm(git_exe)
        if not gcm:
            raise AuthError("Logowanie w przeglądarce wymaga Git Credential Manager. Możesz też połączyć konto tokenem.")
        env = AccountStore._gcm_environment(git_exe, namespace, interactive)
        payload = "protocol=https\nhost=" + auth_urlparse.urlsplit(auth_normalize_host(host)).netloc + "\n"
        if username:
            if any(c in username for c in "\r\n\x00"):
                raise AuthError("Niepoprawna nazwa konta.")
            payload += "username=" + username + "\n"
        payload += "\n"
        flags = getattr(auth_subprocess, "CREATE_NO_WINDOW", 0)
        try:
            process = auth_subprocess.Popen([gcm, action], stdin=auth_subprocess.PIPE, stdout=auth_subprocess.PIPE,
                                            stderr=auth_subprocess.PIPE, text=True, encoding="utf-8", errors="replace",
                                            env=env, creationflags=flags)
            started = auth_time.monotonic()
            first = True
            while True:
                if cancel is not None and cancel.is_set():
                    process.kill()
                    process.communicate()
                    raise AuthError("Łączenie konta anulowano.")
                if auth_time.monotonic() - started > timeout:
                    process.kill()
                    process.communicate()
                    raise AuthError("Minął czas logowania. Spróbuj ponownie lub użyj tokenu.")
                try:
                    output, _ = process.communicate(input=payload if first else None, timeout=0.2)
                    break
                except auth_subprocess.TimeoutExpired:
                    first = False
            if process.returncode:
                raise AuthError("Logowanie nie zostało zakończone. Spróbuj ponownie albo połącz konto tokenem.")
            values = {}
            for line in output.splitlines():
                key, separator, value = line.partition("=")
                if separator and key in ("username", "password"):
                    values[key] = value
            return values
        except OSError:
            raise AuthError("Nie udało się uruchomić Git Credential Manager. Użyj tokenu dostępu.") from None

    def browser_login(self, provider, host, git_exe, cancel=None):
        if provider != "github":
            raise AuthError("Dla GitLab połącz konto tokenem z uprawnieniami read_api i write_repository.")
        host = auth_normalize_host(host)
        self._vault()
        namespace = "gitline-" + auth_uuid.uuid4().hex
        session_id, cleanup_id = "browser-" + namespace, auth_uuid.uuid4().hex
        extra = {"auth_kind": "gcm", "gcm_namespace": namespace}
        extra["git_exe"] = str(git_exe)
        pending = dict(extra, id=session_id, host=host, username="", provider=provider,
                       display_name="Niedokończone logowanie", credential_id=session_id)
        with self._account_lock(session_id):
            with self._metadata():
                data = self._read()
                data["cleanup"].append({"cleanup_id": cleanup_id, "account": pending})
                self._write(data)
            try:
                values = self._gcm_call(git_exe, "get", host, namespace, interactive=True, cancel=cancel)
                token = values.get("password", "")
                if not token:
                    raise AuthError("Przeglądarka nie zwróciła poświadczenia. Spróbuj ponownie.")
                return self.login(provider, host, token, cancel=cancel,
                                  _extra=dict(extra, _browser_cleanup_id=cleanup_id))
            finally:
                try:
                    self._recover_account_locked(session_id)
                except AuthError:
                    pass  # Durable cleanup is retried on the next recovery pass.

    @staticmethod
    def _gcm_store(git_exe, host, namespace, username, token):
        gcm = AccountStore.find_gcm(git_exe)
        if not gcm:
            return
        env = AccountStore._gcm_environment(git_exe, namespace)
        payload = "protocol=https\nhost=" + auth_urlparse.urlsplit(host).netloc + "\nusername=" + username + "\npassword=" + token + "\n\n"
        try:
            auth_subprocess.run([gcm, "store"], input=payload, capture_output=True, text=True, encoding="utf-8",
                                timeout=15, env=env, creationflags=getattr(auth_subprocess, "CREATE_NO_WINDOW", 0))
        except (OSError, auth_subprocess.TimeoutExpired):
            pass  # The account token has already been secured in the application vault.


def credential_git_options(script_path=None):
    """Per-command Git options; call before the Git subcommand. No global config writes."""
    script = str(AuthPath(script_path or __file__).resolve()).replace("\\", "/")
    python_path = AuthPath(auth_sys.executable).resolve()
    if auth_os.name == "nt" and python_path.name.lower() == "pythonw.exe":
        # Git requires real protocol streams even if the GUI was double-clicked.
        python_path = python_path.with_name("python.exe")
    executable = str(python_path).replace("\\", "/")
    helper = "!" + auth_shlex.quote(executable) + " -I -X utf8 " + auth_shlex.quote(script)
    helper += " --credential-helper"
    return ["-c", "credential.helper=", "-c", "credential.helper=" + helper, "-c", "credential.useHttpPath=true"]


def credential_helper_main(action="get", store=None, input_stream=None, output_stream=None, error_stream=None):
    """Git's credential protocol. get only; diagnostics and secrets use separate streams."""
    if action != "get":
        return 0
    input_stream = input_stream or auth_sys.stdin
    output_stream = output_stream or auth_sys.stdout
    error_stream = error_stream or auth_sys.stderr
    try:
        fields = {}
        for _ in range(32):
            line = input_stream.readline(16385)
            if not line or line in ("\n", "\r\n"):
                break
            if len(line) > 16384:
                return 0
            key, sep, value = line.rstrip("\r\n").partition("=")
            if sep:
                fields[key] = value
        if fields.get("protocol") != "https" or not fields.get("host"):
            return 0
        host = auth_normalize_host("https://" + fields["host"])
        credential = (store or AccountStore()).credential_for(host, username=fields.get("username"),
                      account_id=auth_os.environ.get("GITLINE_ACCOUNT_ID"), refresh=True,
                      repo=auth_os.environ.get("GITLINE_REPOSITORY"),
                      remote=auth_os.environ.get("GITLINE_REMOTE", "origin"))
        if credential:
            output_stream.write("username=" + credential["username"] + "\npassword=" + credential["password"] + "\n\n")
            output_stream.flush()
    except Exception as error:
        # An unavailable explicit/bound account must never unlock a later helper.
        # A valid context with no application account returns None above instead.
        # Keep protocol stdout clean and report only our safe, actionable errors.
        # Unexpected exceptions can contain secrets, so never stringify them.
        message = (str(error) if isinstance(error, AuthError) else
                   "Nie udało się odczytać konta Gitline. Uruchom aplikację ponownie i sprawdź połączone konto.")
        with auth_contextlib.suppress(OSError, ValueError, AttributeError):
            diagnostic = "Gitline: " + message + "\n"
            if hasattr(error_stream, "buffer"):
                # Windows pipes default to the legacy code page; Git's captured
                # output is decoded as UTF-8 by the parent application.
                error_stream.buffer.write(diagnostic.encode("utf-8"))
                error_stream.buffer.flush()
            else:
                error_stream.write(diagnostic)
                error_stream.flush()
        with auth_contextlib.suppress(OSError, ValueError):
            output_stream.write("quit=true\n\n")
            output_stream.flush()
        return 0
    return 0


def auth_lock_test_child(directory, ready, done):
    """Private subprocess probe; explicitly marked temporary data, no real vault."""
    path = AuthPath(directory).resolve()
    ready, done = AuthPath(ready).resolve(), AuthPath(done).resolve()
    if (not path.name.startswith("gitline-auth-test-") or ready.parent != path or done.parent != path
            or not (path / "auth-test-only").is_file()):
        return 2
    ready.write_text("ready", encoding="utf-8")
    store = AccountStore(path, keyring_backend=object())
    with store._metadata():
        data = store._read()
        data["bindings"]["child-probe"] = "child"
        store._write(data)
    done.write_text("done", encoding="utf-8")
    return 0


if __name__ == '__main__' and len(sys.argv) == 5 and sys.argv[1] == '--auth-lock-test-child':
    raise SystemExit(auth_lock_test_child(*sys.argv[2:]))


if __name__ == '__main__' and len(sys.argv) > 1 and sys.argv[1] == '--credential-helper':
    raise SystemExit(credential_helper_main(sys.argv[2] if len(sys.argv) > 2 else 'get'))

from PySide6.QtCore import QObject, QRunnable, QThreadPool, Signal, Qt, QUrl
from PySide6.QtGui import QDesktopServices
from PySide6.QtWidgets import (QAbstractItemView, QComboBox, QDialog, QFrame, QHBoxLayout, QLabel, QLineEdit,
                               QListWidget, QListWidgetItem, QPushButton, QStackedWidget, QVBoxLayout, QWidget)


class AuthWorkerSignals(QObject):
    result = Signal(object)
    error = Signal(str)
    finished = Signal()


class AuthWorker(QRunnable):
    def __init__(self, function):
        super().__init__()
        self.function = function
        self.cancel = auth_threading.Event()
        self.signals = AuthWorkerSignals()

    def run(self):
        try:
            result = _run_cancellable(self.cancel, lambda: self.function(self.cancel))
            self.signals.result.emit(result)
        except AuthError as error:
            self.signals.error.emit(str(error))
        except Exception:
            self.signals.error.emit("Nie udało się połączyć konta. Spróbuj ponownie.")
        finally:
            self.function = None
            self.signals.finished.emit()


