class JsonSettings:
    """Qt preference values backed by the shared, editable configuration document."""
    def __init__(self, persist=True):
        self.persist = persist
        self._memory = {}
        if persist:
            with _config_lock():
                if not _config_has_section('preferences'):
                    _set_config_section('preferences', {})
                self._values()

    @staticmethod
    def _json_value(key):
        return key in ('recent', 'drafts') or key.startswith('newFileSelection/')

    @classmethod
    def _encode(cls, key, value):
        from PySide6.QtCore import QByteArray
        if isinstance(value, QByteArray):
            import base64
            return {'type': 'QByteArray', 'base64': base64.b64encode(bytes(value)).decode('ascii')}
        if cls._json_value(key) and isinstance(value, str):
            try: return json.loads(value)
            except ValueError: pass
        return value

    def _values(self):
        values = _config_section('preferences', {}) if self.persist else self._memory
        if not isinstance(values, dict):
            raise ConfigError(f'Sekcja preferences musi być obiektem JSON: {_config_path()}')
        return values

    def value(self, key, default=None):
        values = self._values()
        if key not in values: return default
        value = values[key]
        if isinstance(value, dict) and value.get('type') == 'QByteArray':
            import base64
            from PySide6.QtCore import QByteArray
            try: return QByteArray(base64.b64decode(value['base64'], validate=True))
            except (ValueError, TypeError, KeyError) as error:
                raise ConfigError(f'Nieprawidłowy zapis geometrii okna: {_config_path()}') from error
        if self._json_value(key) and not isinstance(value, str):
            return json.dumps(value, ensure_ascii=False)
        return value

    def setValue(self, key, value):
        if not self.persist:
            self._memory[key] = self._encode(key, value)
            return
        with _config_lock():
            values = self._values()
            values[key] = self._encode(key, value)
            _set_config_section('preferences', values)

    def sync(self):
        pass  # Each update is already flushed and atomically replaced on disk.


def fit_window_to_screen(window, preferred=None, minimum=(0, 0), *, available=None, center=False):
    """Keep normal window geometry and its minimum within the monitor work area."""
    if available is None:
        parent = window.parentWidget()
        screen = parent.screen() if center and parent is not None else window.screen()
        screen = screen or QApplication.primaryScreen()
        if screen is None:
            return
        available = screen.availableGeometry()
    framed = not bool(window.windowFlags() & Qt.WindowType.FramelessWindowHint)
    title_height = window.style().pixelMetric(QStyle.PixelMetric.PM_TitleBarHeight) if framed else 0
    margin = min(12, max(0, (min(available.width(), available.height()) - 1) // 4))
    bounds = available.adjusted(margin, margin + title_height, -margin, -margin)
    if bounds.isEmpty():
        bounds = available
    window.setMinimumSize(min(minimum[0], bounds.width()), min(minimum[1], bounds.height()))
    state = window.windowState()
    normal = window.normalGeometry() if window.isMaximized() or window.isFullScreen() else window.geometry()
    if not normal.isValid():
        normal = window.geometry()
    if preferred is not None:
        normal.setSize(QSize(*preferred))
    normal.setSize(normal.size().boundedTo(bounds.size()).expandedTo(window.minimumSize()))
    if center:
        normal.moveCenter(bounds.center())
    normal.moveLeft(max(bounds.left(), min(normal.left(), bounds.right() - normal.width() + 1)))
    normal.moveTop(max(bounds.top(), min(normal.top(), bounds.bottom() - normal.height() + 1)))
    if window.isMaximized() or window.isFullScreen():
        window.setWindowState(state & ~(Qt.WindowState.WindowMaximized | Qt.WindowState.WindowFullScreen))
    window.setGeometry(normal)
    if window.windowState() != state:
        window.setWindowState(state)


