def ui_label(text, kind='', wrap=False):
    widget = QLabel(text)
    widget.setTextFormat(Qt.TextFormat.PlainText)
    if kind:
        widget.setObjectName(kind)
    widget.setWordWrap(wrap)
    return widget


def git_progress_text(progress):
    stages = {'connecting': 'Łączenie z serwerem', 'enumerating': 'Przygotowanie obiektów',
              'counting': 'Zliczanie obiektów', 'compressing': 'Kompresja obiektów',
              'writing': 'Wysyłanie obiektów', 'receiving': 'Odbieranie obiektów',
              'resolving': 'Przetwarzanie zmian na serwerze',
              'awaiting_server': 'Oczekiwanie na potwierdzenie serwera'}
    parts = [stages.get(progress.phase, 'Wysyłanie commitów')]
    if progress.percent is not None: parts.append(f'{progress.percent}%')
    if progress.current is not None:
        parts.append(f'{progress.current}/{progress.total}' if progress.total is not None else str(progress.current))

    def size(value):
        for unit in ('B', 'KiB', 'MiB', 'GiB', 'TiB'):
            if value < 1024 or unit == 'TiB':
                return (f'{value:.0f}' if unit == 'B' else f'{value:.1f}').replace('.', ',') + ' ' + unit
            value /= 1024

    if progress.transferred_bytes is not None: parts.append(size(progress.transferred_bytes))
    if progress.bytes_per_second is not None: parts.append(size(progress.bytes_per_second) + '/s')
    if progress.endpoint_total > 1: parts.insert(0, f'Cel {progress.endpoint_index}/{progress.endpoint_total}')
    return ' · '.join(parts)


def _logo_parts(separation=0.0):
    """Gold link surfaces in a shared 24-unit space, with transparent crossings."""
    from PySide6.QtGui import QPainterPathStroker, QTransform
    gold = QLinearGradient(7, 4, 17, 20)
    for stop, shade in ((0, '#fff0c8'), (0.35, '#e6c986'), (0.49, '#c59b52'),
                        (0.72, '#e6c886'), (1, '#ae803c')):
        gold.setColorAt(stop, QColor(shade))
    fold = QLinearGradient(7, 7, 18, 20)
    for stop, shade in ((0, '#f1dba6'), (0.4, '#bc8c43'), (0.68, '#efd398'), (1, '#aa7b36')):
        fold.setColorAt(stop, QColor(shade))
    upper = QPainterPath(QPointF(8, 6.2))
    for x, y in ((9, 5.2), (14.8, 11), (9, 16.8), (3.2, 11), (6.6, 7.6)):
        upper.lineTo(x, y)
    ribbon = QPainterPath(QPointF(15, 7.2))
    for x, y in ((20.8, 13), (15, 18.8), (9.2, 13)):
        ribbon.lineTo(x, y)
    ribbon.closeSubpath()

    transforms, paths, materials = [], [], []
    for path, material, direction, center in ((upper, gold, -1, QPointF(9, 11)),
                                              (ribbon, fold, 1, QPointF(15, 13))):
        transform = QTransform()
        if separation:
            transform.translate(direction * 6 * separation, direction * 1.5 * separation)
            transform.translate(center.x(), center.y())
            transform.rotate(direction * 12 * separation)
            transform.translate(-center.x(), -center.y())
        brush = QBrush(material)
        brush.setTransform(transform)
        transforms.append(transform); paths.append(transform.map(path)); materials.append(brush)
    stroker = QPainterPathStroker()
    stroker.setWidth(2.2)
    stroker.setCapStyle(Qt.PenCapStyle.FlatCap)
    stroker.setJoinStyle(Qt.PenJoinStyle.BevelJoin)
    surfaces = [stroker.createStroke(path) for path in paths]
    stroker.setWidth(3.9)
    for index, (start, end) in enumerate(((QPointF(11.6, 7.8), QPointF(14.4, 10.6)),
                                         (QPointF(9.8, 13.6), QPointF(12.2, 16)))):
        crossing = QPainterPath(start); crossing.lineTo(end)
        cut = transforms[index].map(stroker.createStroke(crossing))
        surfaces[1 - index] = surfaces[1 - index].subtracted(cut)
    return tuple(zip(surfaces, materials))


def _paint_logo(p, separation=0.0):
    """Paint only the gold links; the spaces between them stay transparent."""
    p.setPen(Qt.PenStyle.NoPen)
    for surface, material in _logo_parts(separation):
        p.setBrush(material)
        p.drawPath(surface)


def ui_icon(name, color='#a6aec4', size=20):
    """Original vector icons painted by Qt; no external assets or icon fonts."""
    pixmap = QPixmap(size * 2, size * 2)
    pixmap.setDevicePixelRatio(2)
    pixmap.fill(Qt.GlobalColor.transparent)
    p = QPainter(pixmap)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.scale(size / 24, size / 24)
    p.setPen(QPen(QColor(color), 1.65, Qt.PenStyle.SolidLine,
                 Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
    if name == 'logo':
        _paint_logo(p)
    elif name == 'branch':
        p.drawLine(7, 7, 7, 17)
        path = QPainterPath(QPointF(7, 14)); path.cubicTo(7, 10, 17, 15, 17, 7)
        p.drawPath(path)
        for x, y in ((7, 4), (17, 4), (7, 20)):
            p.drawEllipse(QPointF(x, y), 2.4, 2.4)
    elif name == 'folder':
        path = QPainterPath(QPointF(3, 7)); path.lineTo(3, 5); path.lineTo(9, 5)
        path.lineTo(12, 8); path.lineTo(21, 8); path.lineTo(21, 19)
        path.lineTo(3, 19); path.closeSubpath(); p.drawPath(path)
    elif name in ('plus', 'close'):
        if name == 'plus': p.drawLine(12, 5, 12, 19); p.drawLine(5, 12, 19, 12)
        else: p.drawLine(6, 6, 18, 18); p.drawLine(18, 6, 6, 18)
    elif name == 'history':
        p.drawArc(QRectF(4, 4, 16, 16), 40 * 16, 300 * 16)
        p.drawLine(3, 5, 3, 10); p.drawLine(3, 10, 8, 10)
        p.drawLine(12, 7, 12, 12); p.drawLine(12, 12, 16, 14)
    elif name == 'changes':
        p.drawRoundedRect(QRectF(5, 3, 14, 18), 2, 2)
        p.drawLine(9, 8, 15, 8); p.drawLine(12, 5, 12, 11); p.drawLine(9, 16, 15, 16)
    elif name in ('down', 'up', 'clone'):
        if name == 'up':
            p.drawLine(12, 17, 12, 4); p.drawLine(7, 9, 12, 4); p.drawLine(17, 9, 12, 4)
        else:
            p.drawLine(12, 3, 12, 16); p.drawLine(7, 11, 12, 16); p.drawLine(17, 11, 12, 16)
        p.drawLine(4, 17, 4, 21); p.drawLine(4, 21, 20, 21); p.drawLine(20, 21, 20, 17)
    elif name == 'refresh':
        p.drawArc(QRectF(4, 4, 16, 16), 40 * 16, 280 * 16)
        p.drawLine(20, 3, 20, 9); p.drawLine(20, 9, 14, 9)
    elif name == 'user':
        p.drawEllipse(QRectF(8, 3, 8, 8)); p.drawArc(QRectF(4, 13, 16, 13), 0, 180 * 16)
    elif name == 'search':
        p.drawEllipse(QRectF(4, 3, 12, 12)); p.drawLine(14, 14, 20, 20)
    elif name == 'check':
        p.drawLine(5, 12, 10, 17); p.drawLine(10, 17, 20, 6)
    elif name == 'more':
        p.setBrush(QColor(color))
        for x in (5, 12, 19): p.drawEllipse(QPointF(x, 12), 1.2, 1.2)
    elif name == 'chevron':
        p.drawLine(6, 9, 12, 15); p.drawLine(12, 15, 18, 9)
    elif name == 'window_minimize':
        p.drawLine(5, 15, 19, 15)
    elif name == 'window_maximize':
        p.drawRect(QRectF(5, 5, 14, 14))
    elif name == 'window_restore':
        p.drawRect(QRectF(4, 8, 12, 12))
        path = QPainterPath(QPointF(8, 8)); path.lineTo(8, 4); path.lineTo(20, 4)
        path.lineTo(20, 16); path.lineTo(16, 16); p.drawPath(path)
    elif name == 'code':
        p.drawLine(8, 6, 2, 12); p.drawLine(2, 12, 8, 18)
        p.drawLine(16, 6, 22, 12); p.drawLine(22, 12, 16, 18)
        p.drawLine(14, 4, 10, 20)
    elif name == 'settings':
        for y, x in ((6, 8), (12, 16), (18, 10)):
            p.drawLine(3, y, 21, y); p.setBrush(QColor('#171a23'))
            p.drawEllipse(QPointF(x, y), 2.3, 2.3)
    p.end()
    return QIcon(pixmap)


def ui_button(text, callback=None, icon=None, kind=''):
    button = QPushButton(text)
    if kind: button.setObjectName(kind)
    if icon: button.setIcon(ui_icon(icon, '#211830' if kind == 'primary' else '#b3b9cd'))
    button.setCursor(Qt.CursorShape.PointingHandCursor)
    button.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
    accessible = text.strip() or {
        'plus': 'Dodaj', 'close': 'Zamknij', 'refresh': 'Odśwież',
        'more': 'Więcej opcji', 'search': 'Szukaj', 'settings': 'Ustawienia',
    }.get(icon, icon or 'Przycisk')
    button.setAccessibleName(accessible)
    if not text.strip():
        button.setToolTip(accessible)
    if callback: button.clicked.connect(callback)
    return button


class ElidedLabel(QLabel):
    """Keep the complete accessible text while letting narrow layouts shrink."""
    def __init__(self, text='', parent=None):
        super().__init__(text, parent)
        self.setTextFormat(Qt.TextFormat.PlainText)
        self.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)
        self.setMinimumWidth(0)

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setPen(self.palette().color(self.foregroundRole()))
        text = self.fontMetrics().elidedText(self.text(), Qt.TextElideMode.ElideMiddle, self.contentsRect().width())
        painter.drawText(self.contentsRect(), Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft, text)


