class ComboPopupDelegate(QStyledItemDelegate):
    """Keep the selected value distinct from keyboard focus in every dropdown."""
    def __init__(self, combo):
        super().__init__(combo.view())
        self.combo = combo

    def sizeHint(self, option, index):
        return QSize(option.fontMetrics.horizontalAdvance(str(index.data() or '')) + 58, 36)

    def paint(self, painter, option, index):
        enabled = bool(index.flags() & Qt.ItemFlag.ItemIsEnabled)
        selected = bool(option.state & QStyle.StateFlag.State_Selected)
        hovered = bool(option.state & QStyle.StateFlag.State_MouseOver)
        rect = option.rect.adjusted(1, 1, -1, -1)
        painter.save(); painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.setPen(QPen(QColor('#65527f'), 1) if enabled and selected else Qt.PenStyle.NoPen)
        painter.setBrush(QColor('#3a3053' if enabled and selected else '#272b3a' if enabled and hovered else '#191c26'))
        painter.drawRoundedRect(rect.adjusted(0, 0, -1, -1), 5, 5)
        icon_rect = QRect(rect.x()+8, rect.center().y()-8, 16, 16)
        if index.row() == self.combo.currentIndex():
            ui_icon('check', '#cbb9ff' if enabled else '#6f7588', 16).paint(painter, icon_rect)
        else:
            icon = index.data(Qt.ItemDataRole.DecorationRole)
            if isinstance(icon, QIcon): icon.paint(painter, icon_rect)
        painter.setFont(option.font)
        painter.setPen(QColor('#eee8ff' if enabled and selected else '#eef0f6' if enabled else '#6f7588'))
        text_rect = rect.adjusted(33, 0, -12, 0)
        text = option.fontMetrics.elidedText(str(index.data() or ''), Qt.TextElideMode.ElideMiddle, text_rect.width())
        painter.drawText(text_rect, Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft, text)
        painter.restore()

    def helpEvent(self, event, view, option, index):
        from PySide6.QtWidgets import QToolTip
        text = str(index.data(Qt.ItemDataRole.ToolTipRole) or index.data() or '')
        if text and option.fontMetrics.horizontalAdvance(text) > option.rect.width()-45:
            QToolTip.showText(event.globalPos(), text, view)
            return True
        return super().helpEvent(event, view, option, index)


class StyledComboBox(QComboBox):
    """Native combo interaction with a consistently sized, themed list popup."""
    def __init__(self, parent=None):
        from PySide6.QtWidgets import QListView, QProxyStyle
        super().__init__(parent)
        class ListPopupStyle(QProxyStyle):
            def styleHint(self, hint, option=None, widget=None, return_data=None):
                if hint == QStyle.StyleHint.SH_ComboBox_Popup: return 0
                return super().styleHint(hint, option, widget, return_data)
        # Qt's menu-style combo ignores maxVisibleItems and hides the scrollbar.
        # Own a separate Fusion style so application-wide style ownership is intact.
        self._popup_style = ListPopupStyle('Fusion'); self._popup_style.setParent(self)
        self.setStyle(self._popup_style)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setMaxVisibleItems(10)
        view = QListView(self); view.setObjectName('comboPopup')
        view.setMouseTracking(True); view.setUniformItemSizes(True)
        view.setVerticalScrollMode(QAbstractItemView.ScrollMode.ScrollPerPixel)
        view.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        view.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        view.setTextElideMode(Qt.TextElideMode.ElideMiddle)
        self.setView(view)
        self.setItemDelegate(ComboPopupDelegate(self))
        view.window().setObjectName('comboPopupContainer')
        self.currentTextChanged.connect(self.setToolTip)

    def showPopup(self):
        screen = self.screen().availableGeometry().adjusted(8, 8, -8, -8)
        width = self.width()
        limit = min(620, screen.width())
        for row in range(self.count()):
            width = max(width, self.fontMetrics().horizontalAdvance(self.itemText(row)) + 70)
            if width >= limit: break
        self.view().setMinimumWidth(min(width, limit))
        self.view().setMaximumHeight(min(10 * 36 + 12, max(72, screen.height()-20)))
        super().showPopup()
        popup = self.view().window()
        below = self.mapToGlobal(QPoint(0, self.height()+5))
        above = self.mapToGlobal(QPoint(0, -popup.height()-5))
        y = below.y() if below.y()+popup.height() <= screen.bottom() else above.y()
        popup.move(max(screen.left(), min(below.x(), screen.right()-popup.width()+1)),
                   max(screen.top(), min(y, screen.bottom()-popup.height()+1)))
        self.update()

    def hidePopup(self):
        super().hidePopup()
        self.update()

    def paintEvent(self, event):
        super().paintEvent(event)
        painter = QPainter(self)
        center = QPoint(self.width()-18, self.height()//2)
        if self.view().isVisible():
            painter.translate(center); painter.rotate(180); painter.translate(-center)
        ui_icon('chevron', '#c6bddb' if self.isEnabled() else '#6f7588', 16).paint(
            painter, QRect(center.x()-8, center.y()-8, 16, 16))


