class SmoothListWidget(QListWidget):
    """Pixel scrolling with brief wheel easing and direct precision gestures."""

    def __init__(self, parent=None):
        from PySide6.QtCore import QEasingCurve, QVariantAnimation
        super().__init__(parent)
        self.setVerticalScrollMode(QAbstractItemView.ScrollMode.ScrollPerPixel)
        self.setHorizontalScrollMode(QAbstractItemView.ScrollMode.ScrollPerPixel)
        self._scroll_target = float(self.verticalScrollBar().value())
        self._scroll_writing = False
        self._scroll_animation = QVariantAnimation(self)
        self._scroll_animation.setDuration(140)
        self._scroll_animation.setEasingCurve(QEasingCurve.Type.OutCubic)
        self._scroll_animation.valueChanged.connect(self._scroll_frame)
        self._scroll_animation.finished.connect(self.stop_scroll_animation)
        self.model().modelAboutToBeReset.connect(self.stop_scroll_animation)
        bar = self.verticalScrollBar()
        bar.rangeChanged.connect(self.stop_scroll_animation)
        bar.valueChanged.connect(self._scroll_value_changed)
        for scrollbar in (bar, self.horizontalScrollBar()):
            scrollbar.sliderPressed.connect(self.stop_scroll_animation)
            scrollbar.actionTriggered.connect(self.stop_scroll_animation)
            scrollbar.installEventFilter(self)

    def stop_scroll_animation(self, *unused):
        animation = getattr(self, '_scroll_animation', None)
        if animation is not None:
            animation.stop()
            self._scroll_target = float(self.verticalScrollBar().value())

    def _scroll_value_changed(self, value):
        if not self._scroll_writing:
            self.stop_scroll_animation()

    def _scroll_frame(self, value):
        # Configuring a stopped QVariantAnimation can emit valueChanged too.
        if self._scroll_animation.state() != self._scroll_animation.State.Running:
            return
        self._scroll_writing = True
        try:
            self.verticalScrollBar().setValue(round(value))
        finally:
            self._scroll_writing = False

    def wheelEvent(self, event):
        if not self.isVisible():
            self.stop_scroll_animation(); event.ignore(); return
        if event.modifiers() != Qt.KeyboardModifier.NoModifier or self.verticalScrollBar().isSliderDown():
            self.stop_scroll_animation()
            super().wheelEvent(event)
            return
        pixels = event.pixelDelta()
        if not pixels.isNull():
            self.stop_scroll_animation()
            moved = False
            for bar, delta in ((self.verticalScrollBar(), pixels.y()), (self.horizontalScrollBar(), pixels.x())):
                before = bar.value()
                bar.setValue(before - delta)
                moved = moved or bar.value() != before
            event.setAccepted(moved)
            return
        bar = self.verticalScrollBar()
        angle = event.angleDelta()
        if (not angle.y() or angle.x() or event.modifiers() != Qt.KeyboardModifier.NoModifier
                or event.phase() != Qt.ScrollPhase.NoScrollPhase or bar.isSliderDown()):
            self.stop_scroll_animation()
            super().wheelEvent(event)
            return
        lines = QApplication.wheelScrollLines()
        if not lines or bar.minimum() == bar.maximum():
            self.stop_scroll_animation(); event.ignore(); return
        current = float(bar.value())
        distance = -angle.y() / 120.0 * lines * max(1, bar.singleStep())
        distance = max(-bar.pageStep(), min(bar.pageStep(), distance))
        running = self._scroll_animation.state() == self._scroll_animation.State.Running
        # Reversing a wheel cancels the outstanding distance immediately.
        base = self._scroll_target if running and distance * (self._scroll_target - current) >= 0 else current
        target = min(float(bar.maximum()), max(float(bar.minimum()), base + distance))
        if target == current:
            self.stop_scroll_animation(); event.ignore(); return
        self._scroll_animation.stop()
        self._scroll_target = target
        self._scroll_animation.setStartValue(current)
        self._scroll_animation.setEndValue(target)
        self._scroll_animation.setCurrentTime(0)
        self._scroll_animation.start()
        event.accept()

    def eventFilter(self, watched, event):
        if (watched in (self.verticalScrollBar(), self.horizontalScrollBar()) and
                event.type() in (QEvent.Type.MouseButtonPress, QEvent.Type.KeyPress, QEvent.Type.Wheel, QEvent.Type.TouchBegin)):
            self.stop_scroll_animation()
        return super().eventFilter(watched, event)

    def keyPressEvent(self, event):
        self.stop_scroll_animation()
        super().keyPressEvent(event)

    def mousePressEvent(self, event):
        self.stop_scroll_animation()
        super().mousePressEvent(event)

    def hideEvent(self, event):
        self.stop_scroll_animation()
        super().hideEvent(event)


class RepositoryPopup(QFrame):
    def __init__(self, anchor):
        super().__init__(anchor.window(), Qt.WindowType.Popup | Qt.WindowType.FramelessWindowHint)
        self.anchor = anchor
        self.setObjectName('repositoryPopup')
        self.setAccessibleName('Wybierz repozytorium')
        self.setAttribute(Qt.WidgetAttribute.WA_NoMouseReplay)

    def show_below(self):
        screen = self.anchor.screen().availableGeometry()
        self.resize(min(480, screen.width()-24), min(600, screen.height()-80))
        point = self.anchor.mapToGlobal(QPoint(0, self.anchor.height()+5))
        x = max(screen.left()+8, min(point.x(), screen.right()-self.width()-8))
        y = max(screen.top()+8, min(point.y(), screen.bottom()-self.height()-8))
        self.move(x, y)
        self.anchor.setChecked(True)
        self.show()

    def hideEvent(self, event):
        self.anchor.setChecked(False)
        super().hideEvent(event)


class RecentRepositoryDelegate(QStyledItemDelegate):
    def sizeHint(self, option, index):
        return QSize(340, 30 if index.data(Qt.ItemDataRole.UserRole) is None else 62)

    def paint(self, painter, option, index):
        painter.save()
        data = index.data(Qt.ItemDataRole.UserRole)
        if data is None:
            painter.setFont(QFont('Segoe UI', 8, QFont.Weight.DemiBold))
            painter.setPen(QColor('#9da5ba'))
            painter.drawText(option.rect.adjusted(6, 3, -6, 0), Qt.AlignmentFlag.AlignVCenter,
                             str(index.data(Qt.ItemDataRole.DisplayRole) or ''))
            painter.restore()
            return
        rect = option.rect.adjusted(0, 2, 0, -2)
        selected = bool(option.state & QStyle.StateFlag.State_Selected)
        hover = bool(option.state & QStyle.StateFlag.State_MouseOver)
        painter.setPen(Qt.PenStyle.NoPen)
        painter.setBrush(QColor('#342b49' if selected else '#262a37' if hover else '#191c26'))
        painter.drawRoundedRect(rect, 6, 6)
        remote = isinstance(data, dict)
        current = not remote and bool(index.data(Qt.ItemDataRole.UserRole+1))
        title = (data.get('full_name') or data.get('name', '')) if remote else Path(data).name or str(data)
        subtitle = f"{data.get('host', '')} · @{data.get('account_username', '')}" if remote else str(data)
