def _apply_bundled_license_reviews(rows):
    """Apply an interpretation only to the complete, reviewed notice contents."""
    import hashlib
    reviews = {}
    for review in _BUNDLED_LICENSE_REVIEWS:
        reviews.setdefault(review['name'], []).append(review)
    digests = {}
    for row in rows:
        candidates = reviews.get(row['name'], ())
        if not candidates: continue
        actual = {}
        for label, url in row['proofs']:
            target = QUrl(url)
            if not target.isLocalFile(): continue
            path = target.toLocalFile()
            if path not in digests:
                try:
                    with Path(path).open('rb') as notice: content = notice.read(512 * 1024 + 1)
                    digests[path] = hashlib.sha256(content).hexdigest() if len(content) <= 512 * 1024 else None
                except OSError: digests[path] = None
            actual[label.replace('\\', '/')] = digests[path]
        for review in candidates:
            if actual != review['hashes']: continue
            for key in ('license', 'commercial', 'terms'):
                row[key] = review[key]
            if review.get('version'): row['version'] = review['version']
            row['terms'] += ' Ocena jest przypisana do dokładnie tych dołączonych tekstów licencji; ich zmiana wymaga ponownej weryfikacji.'
            row['proofs'].extend((label, url) for label, url in review['proofs'] if (label, url) not in row['proofs'])
            break
    return rows


def native_license_inventory(git_exe=None):
    """Bounded, local notice inventory; filenames never imply a license grant."""
    import stat
    rows = []
    max_notice_bytes = 512 * 1024
    entry_budget = 4096
    incomplete = set()
    notice_name = re.compile(r'^(?:licen[cs]e|copying\d*|notices?|copyright)(?:[._-].*)?$|^runtime\.library\.exception$', re.I)
    executable_suffixes = {'.py', '.pyc', '.pyd', '.exe', '.dll', '.com', '.bat', '.cmd', '.ps1', '.sh', '.lnk', '.url', '.msi', '.so', '.dylib'}

    def contained(path, boundary, directory=False):
        try:
            resolved = Path(path).resolve(strict=True)
            resolved.relative_to(boundary)
            details = resolved.stat()
            if directory:
                return resolved if stat.S_ISDIR(details.st_mode) else None
            if stat.S_ISREG(details.st_mode) and details.st_size <= max_notice_bytes:
                return resolved
        except (OSError, ValueError, RuntimeError):
            pass
        return None

    def notice_files(start, boundary, scope, include_readme=False):
        nonlocal entry_budget
        start = contained(start, boundary, directory=True)
        if start is None:
            return []
        files, pending, visited = [], [(start, 0)], set()
        while pending and entry_budget > 0:
            folder, depth = pending.pop()
            if folder in visited:
                continue
            visited.add(folder)
            try:
                with os.scandir(folder) as entries:
                    for entry in entries:
                        if entry_budget <= 0:
                            incomplete.add(scope)
                            break
                        entry_budget -= 1
                        path = Path(entry.path)
                        if entry.is_symlink():
                            continue
                        if entry.is_dir(follow_symlinks=False):
                            if depth < 4:
                                child = contained(path, boundary, directory=True)
                                if child is not None and child.is_relative_to(start):
                                    pending.append((child, depth + 1))
                            else:
                                incomplete.add(scope)
                            continue
                        matches = notice_name.fullmatch(entry.name)
                        if include_readme and re.fullmatch(r'readme(?:[._-].*)?', entry.name, re.I):
                            matches = True
                        if matches and path.suffix.casefold() not in executable_suffixes:
                            safe = contained(path, boundary)
                            if safe is not None and safe.is_relative_to(start):
                                files.append(safe)
                            elif not path.is_symlink():
                                incomplete.add(scope)
            except OSError:
                incomplete.add(scope)
        if pending:
            incomplete.add(scope)
        return sorted(set(files), key=lambda path: str(path).casefold())

    def add_notices(name, files, boundary, role, group, version='Nieustalona', extra_proofs=()):
        proofs = [(str(path.relative_to(boundary)), path.as_uri()) for path in files]
        proofs.extend(extra_proofs)
        terms = ('Odnalezione lokalne noty dotyczą tego składnika dystrybucji. Ich nazwy nie wystarczają '
                 'do ustalenia licencji ani prawa do bezpłatnego użycia komercyjnego. Przeczytaj dołączone '
                 'teksty i uwzględnij wszystkie licencje oraz wyjątki. Wersja nie jest wyprowadzana z nazwy folderu.')
        if group in incomplete:
            terms += ' Skan osiągnął ograniczenie lub nie odczytał części ścieżek; wykaz może być niepełny.'
        rows.append(dict(name=name, version=version, license='Zobacz dołączoną licencję',
                         commercial='Do weryfikacji', role=role, terms=terms, proofs=proofs,
                         active=True, group=group))

    # A Git executable may be a system installation or a private MinGit package.
    # Probe only documented package locations, never the repository or all parents.
    if git_exe:
        try:
            executable = Path(git_exe).expanduser().resolve(strict=True)
            git_root = None
            if executable.is_file() and executable.name.casefold() in ('git', 'git.exe'):
                for parent in list(executable.parents)[:3]:
                    relative = executable.relative_to(parent).as_posix().casefold()
                    if relative in ('cmd/git.exe', 'bin/git.exe', 'mingw64/bin/git.exe',
                                    'mingw32/bin/git.exe', 'usr/bin/git.exe', 'bin/git'):
                        git_root = parent
                        if (parent / 'cmd').is_dir() or relative.startswith(('mingw64/', 'mingw32/')):
                            break
            if git_root is not None:
                group = 'Składniki Gita'
                components = {}
                root_notice = contained(git_root / 'LICENSE.txt', git_root)
                if root_notice:
                    components['Git · licencja pakietu'] = [root_notice]
                for relative in ('usr/share/licenses', 'mingw64/share/licenses', 'mingw32/share/licenses'):
                    base = contained(git_root / relative, git_root, directory=True)
                    if base is None:
                        continue
                    for path in notice_files(base, git_root, group, include_readme=True):
                        parts = path.relative_to(base).parts
                        component = parts[0] if len(parts) > 1 else 'noty pakietu'
                        components.setdefault('Git · ' + component, []).append(path)
                for relative in ('mingw64/doc/git-credential-manager', 'mingw32/doc/git-credential-manager'):
                    base = contained(git_root / relative, git_root, directory=True)
                    if base is not None:
                        files = [path for path in notice_files(base, git_root, group)
                                 if path.name.casefold() in ('license', 'notice')]
                        if files:
                            components.setdefault('GCM · dołączone noty', []).extend(files)
                for name, files in sorted(components.items(), key=lambda item: item[0].casefold()):
                    add_notices(name, sorted(set(files)), git_root,
                                'Składnik wykrytej lokalnej dystrybucji Gita; noty z tego samego komponentu zgrupowano.', group)
        except (OSError, ValueError, RuntimeError):
            pass

    # pip's vendored libraries are not separate distributions in pip metadata.
    # vendor.txt supplies versions only; no commercial rights are inferred from it.
    try:
        distribution = importlib.metadata.distribution('pip')
        dist_root = Path(distribution.locate_file('')).resolve(strict=True)
        vendor_root = contained(dist_root / 'pip' / '_vendor', dist_root, directory=True)
        if vendor_root is not None:
            group = 'Składniki pip'
            manifest = contained(vendor_root / 'vendor.txt', dist_root)
            versions = {}
            if manifest is not None:
                with manifest.open('rb') as source:
                    content = source.read(max_notice_bytes + 1)
                if len(content) <= max_notice_bytes:
                    for line in content.decode('utf-8', 'replace').splitlines():
                        match = re.fullmatch(r'\s*([A-Za-z0-9][A-Za-z0-9_.-]*)==([A-Za-z0-9][A-Za-z0-9_.+-]*)\s*(?:#.*)?', line)
                        if match:
                            key = re.sub(r'[-_.]+', '-', match[1]).casefold()
                            versions[key] = match[2]
            components = {}
            for path in notice_files(vendor_root, dist_root, group):
                parts = path.relative_to(vendor_root).parts
                name = parts[0] if len(parts) > 1 else 'noty pakietu'
                components.setdefault(name, []).append(path)
            manifest_proof = [('Wykaz wersji pip/_vendor', manifest.as_uri())] if manifest else []
            for name, files in sorted(components.items(), key=lambda item: item[0].casefold()):
                key = re.sub(r'[-_.]+', '-', name).casefold()
                add_notices('pip · ' + name, files, dist_root,
                            'Biblioteka dołączona do instalatora środowiska pip.', group,
                            version=versions.get(key, 'Nieustalona'), extra_proofs=manifest_proof)
            if manifest and not components:
                add_notices('pip · wykaz bibliotek wbudowanych', [manifest], dist_root,
                            'Lokalny wykaz dostarczany z pip; nie odnaleziono tekstów licencji składników.', group)
    except (importlib.metadata.PackageNotFoundError, OSError, ValueError, RuntimeError):
        pass

    if os.name == 'nt':
        present = []
        try:
            distribution = importlib.metadata.distribution('PySide6-Essentials')
            dist_root = Path(distribution.locate_file('')).resolve(strict=True)
            qt_root = contained(dist_root / 'PySide6', dist_root, directory=True)
            if qt_root is not None:
                for name in ('msvcp140.dll', 'msvcp140_1.dll', 'msvcp140_2.dll', 'msvcp140_codecvt_ids.dll',
                             'vcruntime140.dll', 'vcruntime140_1.dll', 'concrt140.dll'):
                    try:
                        path = (qt_root / name).resolve(strict=True)
                        path.relative_to(dist_root)
                        if path.is_file():
                            present.append(name)
                    except (OSError, ValueError, RuntimeError):
                        continue
        except (importlib.metadata.PackageNotFoundError, OSError, ValueError, RuntimeError):
            pass
        rows.append(dict(name='Microsoft Visual C++ Runtime', version='Z dystrybucji Qt/Python',
                         license='Microsoft Software License Terms', commercial='Warunki Microsoft',
                         role='Biblioteki wykonawcze Windows' + (': ' + ', '.join(present) if present else '.'),
                         terms=('Biblioteki Microsoft mają własne warunki; licencja PySide6 nie obejmuje ich automatycznie. '
                                'Dalsza redystrybucja pakietów i pojedynczych DLL podlega Microsoft Software License Terms '
                                'oraz uprawnieniom licencjonowanych użytkowników Visual Studio. Używanie aplikacji '
                                'i prawo do samodzielnego przepakowania bibliotek to odrębne kwestie.'),
                         proofs=[('Zasady Microsoft dotyczące redystrybucji',
                                  'https://learn.microsoft.com/en-us/cpp/windows/redistributing-visual-cpp-files?view=msvc-170')],
                         active=bool(present), group='Składniki natywne'))
    return rows


def technology_inventory(git_exe=None):
    """Read package/tool versions locally; never consult accounts or the network."""
    from PySide6.QtCore import qVersion
    from urllib.parse import quote
    rows = []
    lgpl = ('Użytek komercyjny bez opłaty licencyjnej jest możliwy przy spełnieniu LGPLv3. '
            'Przy dystrybucji zachowaj wymagane noty oraz teksty LGPL/GPL, umożliwiaj użycie zgodnej '
            'zmodyfikowanej biblioteki i nie zabraniaj jej debugowania w tym celu. '
            'Dystrybucja biblioteki obejmuje obowiązki udostępnienia odpowiadających jej źródeł. '
            'Samo dynamiczne ładowanie nie zastępuje tych obowiązków.')
    rules = {
        'MIT': ('Tak · zachowaj noty', 'Dozwolone używanie, modyfikowanie i sprzedaż. Przy przekazywaniu kopii zachowaj informację o prawach autorskich i treść licencji.', 'https://opensource.org/license/mit'),
        'BSD-3-Clause': ('Tak · zachowaj noty', 'Zachowaj noty, warunki licencji i wyłączenie odpowiedzialności. Nazw autorów nie wolno używać do promowania produktu bez zgody.', 'https://opensource.org/license/bsd-3-clause'),
        'Apache-2.0': ('Tak · warunki Apache', 'Zachowaj licencję i wymagane atrybucje oraz NOTICE, jeśli występuje; oznacz zmiany w zmodyfikowanych plikach. Licencja określa także warunki patentowe i nie udziela praw do znaków towarowych.', 'https://www.apache.org/licenses/LICENSE-2.0'),
        'PSF-2.0': ('Tak · warunki PSF', 'Zachowaj licencję i noty o prawach autorskich; przy przekazywaniu zmodyfikowanego Pythona opisz zmiany. Składniki wbudowane mogą mieć odrębne licencje.', 'https://docs.python.org/3/license.html'),
    }

    def add(name, version, license_name, commercial, role, terms, proofs, *, active=True, group='Biblioteki'):
        rows.append(dict(name=name, version=version, license=license_name, commercial=commercial,
                         role=role, terms=terms, proofs=proofs, active=active, group=group))

    add('Python + biblioteka standardowa', platform.python_version(), 'PSF-2.0 + licencje składników',
        'Tak · warunki PSF', 'Interpreter, pliki, procesy, HTTP/TLS, JSON i bootstrap środowiska.',
        rules['PSF-2.0'][1], [('Licencja i składniki Pythona', 'https://docs.python.org/3/license.html')], group='Technologie')
    for module, role in (('Core', 'Zdarzenia, sygnały, timery, wątki i ustawienia.'),
                         ('Gui', 'Rysowanie wektorowe, ikony, tekst i animacja logo.'),
                         ('Widgets', 'Okna, kontrolki, listy i menu aplikacji.')):
        add('Qt ' + module, qVersion(), 'LGPL-3.0 (wybrana opcja)', 'Tak · warunki LGPLv3', role, lgpl,
            [('Licencje modułu', f'https://doc.qt.io/qt-6/qt{module.lower()}-index.html#licenses-and-attributions'),
             ('Warunki LGPLv3', 'https://doc.qt.io/qt-6/lgpl.html'),
             ('Składniki Qt', 'https://doc.qt.io/qt-6/licenses-used-in-qt.html')], group='Technologie')
    known = {re.sub(r'[-_.]+', '-', name).lower() for name in _TECHNOLOGY_LICENSES}
    for name, (verified, license_name, role, scope) in _TECHNOLOGY_LICENSES.items():
        active = name in _DEPENDENCIES
        try: installed = importlib.metadata.version(name) if active else None
        except importlib.metadata.PackageNotFoundError: installed = None
        version = installed or (_DEPENDENCIES.get(name) if active else verified)
        proofs = [('Deklaracja wydawcy · ' + verified, f'https://pypi.org/project/{quote(name)}/{verified}/')]
        if name in ('PySide6-Essentials', 'shiboken6'):
            commercial, terms = 'Tak · warunki LGPLv3', lgpl
            proofs.append(('Licencje Qt for Python', 'https://doc.qt.io/qtforpython-6/licenses.html'))
            if name == 'PySide6-Essentials':
                commercial = 'Zależnie od składnika'
                terms += (' Pakiet Essentials zawiera także moduły nieużywane przez Gitline, w tym składniki dostępne '
                          'w open source wyłącznie na GPL. Deklaracja wheel nie nadaje jednej licencji wszystkim plikom. '
                          'Przy przekazywaniu całego pakietu uwzględnij licencje wszystkich jego składników.')
                proofs.append(('Moduły i licencje Qt', 'https://doc.qt.io/qt-6/licensing.html'))
        else:
            commercial, terms, proof = rules[license_name]
            proofs.append(('Warunki licencji', proof))
        if installed and installed != verified:
            commercial = 'Do weryfikacji wersji'
            terms = f'Zainstalowano {installed}; poniższa deklaracja została sprawdzona dla {verified}.\n\n' + terms
        elif active and not installed:
            commercial = 'Brak zainstalowanego pakietu'
        add(name, version or '—', license_name, commercial,
            f'{role}\nPlatforma: {scope}.' + ('' if active else ' Nieużywana w tej konfiguracji.'), terms, proofs, active=active)
    # Include installer and any additional distributions without silently granting
    # them the terms of a similarly named or differently versioned package.
    for distribution in sorted(importlib.metadata.distributions(), key=lambda item: (item.metadata.get('Name') or '').casefold()):
        name = distribution.metadata.get('Name') or ''
        if not name or re.sub(r'[-_.]+', '-', name).lower() in known: continue
        declared = distribution.metadata.get('License-Expression') or distribution.metadata.get('License') or 'Brak deklaracji w metadanych'
        declared = ' '.join(declared.split())
        if len(declared) > 100: declared = 'Zobacz metadane wydawcy'
        terms = ('To dodatkowy pakiet zainstalowany w środowisku. Licencję odczytano z jego metadanych; '
                 'nie wykonano przeglądu tej wersji ani wszystkich wbudowanych składników.')
        proofs = [('Metadane wydawcy', f'https://pypi.org/project/{quote(name)}/{quote(distribution.version)}/')]
        if name.lower() == 'pip':
            declared = 'MIT + licencje składników'
            terms = ('Instalator zależności używany przy przygotowywaniu środowiska. pip jest na MIT, '
                     'ale zawiera biblioteki z własnymi licencjami. Ich wykaz i teksty licencji są częścią pip/_vendor.')
            proofs.append(('Zasady i licencje składników pip', 'https://pip.pypa.io/en/stable/development/vendoring-policy/'))
        add(name, distribution.version, declared, 'Sprawdź składniki' if name.lower() == 'pip' else 'Do weryfikacji',
            'Narzędzie instalacyjne.' if name.lower() == 'pip' else 'Dodatkowy pakiet środowiska.', terms, proofs, group='Środowisko')

    def tool_version(executable, args):
        if not executable: return 'Niewykryte'
        try:
            result = subprocess.run([str(executable), *args], stdin=subprocess.DEVNULL, capture_output=True,
                                    creationflags=_NO_WINDOW, timeout=5, env=_bootstrap_env())
            return _git_safe_text(result.stdout.decode('utf-8', 'replace').strip())[:100] if result.returncode == 0 else 'Nie odczytano wersji'
        except (OSError, subprocess.SubprocessError): return 'Nie odczytano wersji'

    git_version = tool_version(git_exe, ['--version']).removeprefix('git version ')
    add('Git', git_version, 'GPL-2.0-only', 'Tak · warunki GPLv2', 'Osobny proces wykonujący operacje w repozytoriach.',
        'Komercyjne używanie Gita jest dozwolone. Przy przekazywaniu jego binariów zachowaj licencję i noty '
        'oraz spełnij obowiązek zapewnienia odpowiadającego kodu źródłowego. Wywołanie osobnego programu Git '
        'nie jest tym samym co włączenie jego kodu do aplikacji.',
        [('Licencja projektu', 'https://github.com/git/git/blob/master/COPYING'),
         ('Tekst GPLv2', 'https://www.gnu.org/licenses/old-licenses/gpl-2.0.html')], group='Narzędzia')
    manager = AccountStore.find_gcm(git_exe) if git_exe else None
    add('Git Credential Manager', tool_version(manager, ['--version']), 'MIT', 'Tak · zachowaj noty',
        'Opcjonalne logowanie przez przeglądarkę; narzędzie dostarczane z niektórymi instalacjami Gita.',
        rules['MIT'][1] + ' Pakiet narzędzia zawiera też zależności opisane w ThirdPartyNotices.',
        [('Licencja GCM', 'https://github.com/git-ecosystem/git-credential-manager/blob/main/LICENSE'),
         ('Noty składników GCM', 'https://github.com/git-ecosystem/git-credential-manager/blob/main/NOTICE')], group='Narzędzia')
    if os.name == 'nt':
        add('Git for Windows / MinGit', git_version, 'GPL + licencje składników', 'Sprawdź składniki',
            'Dystrybucja Gita używana w Windows; może zawierać m.in. OpenSSL, cURL, OpenSSH i biblioteki kompresji.',
            'Poszczególne narzędzia mają własne licencje. Lista zależy od wybranej dystrybucji i wersji; '
            'licencja samego Gita nie zastępuje licencji pozostałych plików. Przy dystrybucji pakietu '
            'korzystaj z jego wykazu składników, licencji i odpowiadających źródeł.',
            [('Źródła i składniki Git for Windows', 'https://github.com/git-for-windows/git/wiki/Package-management'),
             ('Licencje dystrybucji', 'https://github.com/git-for-windows/build-extra/blob/main/ReleaseNotes.md#licenses')], group='Narzędzia')
    rows.extend(_apply_bundled_license_reviews(native_license_inventory(git_exe)))
    return rows


class TechnologiesDialog(QDialog):
    """A quiet, searchable license inventory with publisher evidence for each row."""
    def __init__(self, parent):
        from PySide6.QtWidgets import QTableWidget, QHeaderView
        super().__init__(parent)
        self.setWindowTitle(f'Technologie i licencje · {APP_NAME}')
        self.resize(1140, 760); self.setMinimumSize(900, 580)
        if parent.screen():
            available = parent.screen().availableGeometry()
            self.resize(min(1140, available.width() - 48), min(760, available.height() - 64))
        self.records = []; self.visible_records = []; self._token = None
        self.hub = parent.hub
        layout = QVBoxLayout(self); layout.setContentsMargins(24, 24, 24, 20); layout.setSpacing(12)
        layout.addWidget(ui_label('Technologie i licencje', 'title'))
        layout.addWidget(ui_label('Darmowe użycie komercyjne i obowiązki przy dystrybucji. Wybierz pozycję, aby poznać warunki.', 'muted', True))
        filters = QHBoxLayout()
        self.search = QLineEdit(); self.search.setPlaceholderText('Szukaj technologii, biblioteki lub licencji…')
        self.search.setAccessibleName('Filtr technologii i licencji'); filters.addWidget(self.search, 1)
        self.other_platforms = QCheckBox('Inne platformy'); filters.addWidget(self.other_platforms)
        self.other_platforms.setToolTip('Pokaż również zależności wymagane na innych systemach i wersjach Pythona')
        layout.addLayout(filters)
        self.table = QTableWidget(0, 5); self.table.setObjectName('technologyTable')
        self.table.setHorizontalHeaderLabels(['Technologia / biblioteka', 'Wersja', 'Licencja', 'Darmowy użytek komercyjny?', 'Dowód'])
        self.table.setAccessibleName('Technologie, wersje, licencje, warunki komercyjne i dowody')
        self.table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        self.table.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
        self.table.setSelectionMode(QAbstractItemView.SelectionMode.SingleSelection)
        self.table.setShowGrid(False); self.table.setAlternatingRowColors(True); self.table.setWordWrap(False)
        self.table.verticalHeader().hide(); self.table.verticalHeader().setDefaultSectionSize(42)
        self.table.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeMode.Interactive)
        self.table.horizontalHeader().setSectionResizeMode(0, QHeaderView.ResizeMode.Stretch)
        for column, width in ((1, 110), (2, 185), (3, 250), (4, 100)): self.table.setColumnWidth(column, width)
        self.table.setStyleSheet('QTableWidget { background: #11131b; alternate-background-color: #171a24; border: 1px solid #343747; border-radius: 8px; } '
                                'QTableWidget::item { padding: 6px 10px; border: 0; } '
                                'QTableWidget::item:selected { background: #332b48; color: #f2edff; } '
                                'QHeaderView::section { background: #20232e; color: #bbb4ce; padding: 11px 8px; border: 0; border-bottom: 1px solid #3a374a; }')
        layout.addWidget(self.table, 1)
        self.count_label = ui_label('Odczytywanie lokalnych wersji…', 'muted'); layout.addWidget(self.count_label)
        self._details_manual = False
        self.details_toggle = ui_button('Warunki i źródła', icon='chevron', kind='toolbarAction')
        self.details_toggle.setCheckable(True); self.details_toggle.setChecked(self.height() >= 660)
        self.details_toggle.clicked.connect(lambda checked: setattr(self, '_details_manual', True))
        layout.addWidget(self.details_toggle)
        self.details_panel = QWidget(); details_layout = QVBoxLayout(self.details_panel)
        details_layout.setContentsMargins(0, 0, 0, 0); details_layout.setSpacing(10)
        self.details = QPlainTextEdit(); self.details.setReadOnly(True); self.details.setFixedHeight(140)
        self.details.setAccessibleName('Zastosowanie i warunki licencji wybranej technologii')
        self.details.setPlaceholderText('Wybierz pozycję z tabeli.'); details_layout.addWidget(self.details)
        self.proof_row = QHBoxLayout(); details_layout.addLayout(self.proof_row)
        self.details_panel.setVisible(self.details_toggle.isChecked()); layout.addWidget(self.details_panel)
        self.details_toggle.toggled.connect(self.details_panel.setVisible)
        footer = QHBoxLayout()
        note = ui_label('Katalog: 09.09.2026. Wykazy składników są dostępne w źródłach pakietów.', 'muted', True)
        footer.addWidget(note, 1)
        self.copy_button = ui_button('Kopiuj zestawienie', self.copy_inventory); self.copy_button.setEnabled(False)
        footer.addWidget(self.copy_button); footer.addWidget(ui_button('Gotowe', self.accept, kind='primary'))
        layout.addLayout(footer)
        self.search.textChanged.connect(self.populate)
        self.other_platforms.toggled.connect(self.populate)
        self.table.currentCellChanged.connect(self.show_details)
        self.finished.connect(self.cancel_loading)
        git_exe = parent.backend.git_exe if parent.backend else None
        self._token = self.hub.submit(lambda: technology_inventory(git_exe), self.loaded, self.failed,
                                      scope='technology-inventory', kind='read', label='Odczyt technologii i licencji')

    def resizeEvent(self, event):
        super().resizeEvent(event)
        if hasattr(self, 'details_toggle') and not self._details_manual:
            self.details_toggle.setChecked(self.height() >= 660)

    def loaded(self, records):
        self._token = None; self.records = records; self.copy_button.setEnabled(True); self.populate()

    def failed(self, error):
        self._token = None; self.count_label.setText('Nie udało się odczytać listy technologii.')
        self.details.setPlainText(_git_safe_text(str(error)))

    def cancel_loading(self, result=0):
        if self._token is not None: self.hub.cancel(self._token); self._token = None

    def populate(self, *_):
        from PySide6.QtWidgets import QTableWidgetItem
        query = self.search.text().strip().casefold()
        self.visible_records = [record for record in self.records
                                if (record['active'] or self.other_platforms.isChecked())
                                and (not query or query in ' '.join(str(record[key]) for key in ('name', 'license', 'role', 'commercial')).casefold())]
        self.table.blockSignals(True); self.table.setRowCount(len(self.visible_records))
        for row, record in enumerate(self.visible_records):
            for column, key in enumerate(('name', 'version', 'license', 'commercial')):
                item = QTableWidgetItem(record[key]); item.setToolTip(record[key] + '\n' + record['role'])
                if not record['active']: item.setForeground(QColor('#8f91a2'))
                elif key == 'commercial': item.setForeground(QColor('#9fd8bd' if record[key].startswith('Tak') else '#dec38e'))
                self.table.setItem(row, column, item)
            button = ui_button('Źródło ↗', lambda checked=False, record=record: self.open_proof(record['proofs'][0][1]), kind='toolbarAction')
            button.setAccessibleName('Dowód licencji: ' + record['name']); button.setToolTip(record['proofs'][0][1])
            button.setStyleSheet('padding: 5px 8px; margin: 4px;'); self.table.setCellWidget(row, 4, button)
        self.table.blockSignals(False)
        self.count_label.setText(f'{len(self.visible_records)} pozycji · wersje odczytane lokalnie · źródła otwierają się w przeglądarce')
        if self.visible_records: self.table.setCurrentCell(0, 0)
        self.show_details()

    def show_details(self, *_):
        while self.proof_row.count():
            item = self.proof_row.takeAt(0)
            if item.widget(): item.widget().deleteLater()
        row = self.table.currentRow()
        if not 0 <= row < len(self.visible_records): self.details.clear(); return
        record = self.visible_records[row]
        self.details.setPlainText(f"{record['name']} · {record['version']}\n{record['role']}\n\n"
                                  f"Licencja: {record['license']}\n{record['terms']}")
        for label, url in record['proofs'][:2]:
            button = ui_button(label + ' ↗', lambda checked=False, url=url: self.open_proof(url), kind='toolbarAction')
            button.setMaximumWidth(285); button.setToolTip(label + '\n' + url); self.proof_row.addWidget(button)
        if len(record['proofs']) > 2:
            more = ui_button(f"Pozostałe źródła ({len(record['proofs']) - 2})", kind='toolbarAction')
            menu = QMenu(more)
            for label, url in record['proofs'][2:]:
                action = menu.addAction(label); action.setToolTip(url)
                action.triggered.connect(lambda checked=False, url=url: self.open_proof(url))
            more.setMenu(menu); self.proof_row.addWidget(more)
        self.proof_row.addStretch()

    def open_proof(self, url):
        target = QUrl(url)
        if target.isLocalFile():
            allowed = {proof for record in self.records for label, proof in record['proofs']}
            if url not in allowed: return
            path = Path(target.toLocalFile())
            try:
                with path.open('rb') as source: content = source.read(512 * 1024 + 1)
            except OSError as exc:
                self.count_label.setText('Nie można odczytać dołączonej licencji: ' + str(exc)); return
            text = content[:512 * 1024].decode('utf-8-sig', 'replace')
            if len(content) > 512 * 1024: text += '\n\n[Podgląd ograniczony do 512 KiB.]'
            viewer = QDialog(self); viewer.setWindowTitle('Dołączona licencja · ' + path.name); viewer.resize(800, 600)
            layout = QVBoxLayout(viewer); layout.addWidget(ui_label(str(path), 'muted', True))
            body = QPlainTextEdit(); body.setReadOnly(True); body.setPlainText(text); layout.addWidget(body, 1)
            layout.addWidget(ui_button('Gotowe', viewer.accept, kind='primary'))
            viewer.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose); viewer.open(); return
        if target.scheme() != 'https' or not QDesktopServices.openUrl(target):
            self.count_label.setText('Nie udało się otworzyć źródła. Adres: ' + url)

    def copy_inventory(self):
        lines = ['Technologia\tWersja\tLicencja\tDarmowy użytek komercyjny\tDowód\tWarunki']
        for record in self.visible_records:
            values = [record[key] for key in ('name', 'version', 'license', 'commercial')]
            values += [' | '.join(url for label, url in record['proofs']), record['terms']]
            lines.append('\t'.join(value.replace('\n', ' ').replace('\t', ' ') for value in values))
        QApplication.clipboard().setText('\n'.join(lines))
        self.count_label.setText(f'Skopiowano {len(self.visible_records)} pozycji wraz z warunkami i dowodami.')


StartupSplash = _startup_splash_type()


class WindowTitleBar(QFrame):
    """Compact client-side title bar, with native move/resize supplied by the window."""
    def __init__(self, window):
        super().__init__(window)
        self.host = window
        self._drag_origin = None
        self._drag_offset = None
        self.setObjectName('windowTitleBar'); self.setFixedHeight(32)
        self.setAccessibleName('Pasek tytułu okna')
        layout = QHBoxLayout(self); layout.setContentsMargins(12, 0, 0, 0); layout.setSpacing(8)
        mark = QLabel(); mark.setPixmap(ui_icon('logo', size=17).pixmap(17, 17))
        mark.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
        layout.addWidget(mark)
        self.caption = ElidedLabel(window.windowTitle()); self.caption.setObjectName('muted')
        self.caption.setStyleSheet('font-size: 11px;')
        self.caption.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
        layout.addWidget(self.caption, 1)
        window.windowTitleChanged.connect(self.caption.setText)
        controls = QHBoxLayout(); controls.setSpacing(0); controls.setContentsMargins(0, 0, 0, 0)
        self.minimize_button = ui_button('', window.showMinimized, 'window_minimize', 'windowControl')
        self.maximize_button = ui_button('', window.toggle_maximized, 'window_maximize', 'windowControl')
        self.close_button = ui_button('', window.close, 'close', 'windowClose')
        for button, label in ((self.minimize_button, 'Minimalizuj'), (self.maximize_button, 'Maksymalizuj'),
                              (self.close_button, 'Zamknij')):
            button.setFixedSize(46, 32); button.setIconSize(QSize(15, 15))
            button.setAccessibleName(label); button.setToolTip(label)
            controls.addWidget(button)
        layout.addLayout(controls)
        self.sync_window_state()

    def is_draggable(self, point):
        return self.rect().contains(point) and point.x() < self.minimize_button.geometry().left()

    def sync_window_state(self):
        maximized = self.host.isMaximized()
        self.maximize_button.setIcon(ui_icon('window_restore' if maximized else 'window_maximize', '#b3b9cd', 18))
        label = 'Przywróć rozmiar' if maximized else 'Maksymalizuj'
        self.maximize_button.setToolTip(label); self.maximize_button.setAccessibleName(label)

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton and self.is_draggable(event.position().toPoint()):
            self._drag_origin = event.globalPosition().toPoint()
            handle = self.host.windowHandle()
            self._drag_offset = None if handle and handle.startSystemMove() else self._drag_origin - self.host.frameGeometry().topLeft()
            event.accept(); return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if self._drag_offset is not None and event.buttons() & Qt.MouseButton.LeftButton:
            position = event.globalPosition().toPoint()
            if self.host.isMaximized():
                if (position-self._drag_origin).manhattanLength() < QApplication.startDragDistance(): return
                fraction = min(1., max(0., self._drag_offset.x()/max(1, self.host.width())))
                self.host.showNormal()
                self._drag_offset = QPoint(round(self.host.width()*fraction), self.height()//2)
            self.host.move(position-self._drag_offset)
            event.accept(); return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        self._drag_origin = self._drag_offset = None
        super().mouseReleaseEvent(event)

    def mouseDoubleClickEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton and self.is_draggable(event.position().toPoint()):
            self._drag_origin = self._drag_offset = None
            self.host.toggle_maximized(); event.accept(); return
        super().mouseDoubleClickEvent(event)


class _FrameResizeGrip(QWidget):
    """Transparent input strips; the platform still performs the resize."""
    def __init__(self, window, edges, cursor):
        super().__init__(window)
        self.edges = edges
        self.setCursor(cursor)
        self.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.setAccessibleName('Zmień rozmiar okna')
        self.setStyleSheet('background: transparent; border: none;')

    def mousePressEvent(self, event):
        handle = self.window().windowHandle()
        if event.button() == Qt.MouseButton.LeftButton and handle and handle.startSystemResize(self.edges):
            event.accept()
            return
        super().mousePressEvent(event)


class FramelessWindow(QMainWindow):
    """Custom chrome with native movement, sizing and Windows Snap hit testing."""
    _RESIZE_BORDER = 6

    def __init__(self, parent=None):
        super().__init__(parent)
        self._native_frame_api = None
        self._native_frame_hwnd = 0
        self._native_caption_pressed = False
        self._frame_grips = []
        self.setWindowFlags(self.windowFlags() | Qt.WindowType.FramelessWindowHint
                            | Qt.WindowType.WindowSystemMenuHint | Qt.WindowType.WindowMinMaxButtonsHint
                            | Qt.WindowType.WindowCloseButtonHint)
        edge, cursor = Qt.Edge, Qt.CursorShape
        grip_specs = ((edge.LeftEdge, cursor.SizeHorCursor), (edge.RightEdge, cursor.SizeHorCursor),
                      (edge.TopEdge, cursor.SizeVerCursor), (edge.BottomEdge, cursor.SizeVerCursor),
                      (edge.TopEdge | edge.LeftEdge, cursor.SizeFDiagCursor),
                      (edge.TopEdge | edge.RightEdge, cursor.SizeBDiagCursor),
                      (edge.BottomEdge | edge.LeftEdge, cursor.SizeBDiagCursor),
                      (edge.BottomEdge | edge.RightEdge, cursor.SizeFDiagCursor))
        self._frame_grips = [_FrameResizeGrip(self, edges, shape) for edges, shape in grip_specs]
        if sys.platform == 'win32' and QApplication.platformName() == 'windows':
            self._prepare_native_frame()

    def _prepare_native_frame(self):
        import ctypes
        from ctypes import wintypes
        try:
            api = ctypes.WinDLL('user32', use_last_error=True)
            api.GetWindowLongPtrW.argtypes = [wintypes.HWND, ctypes.c_int]
            api.GetWindowLongPtrW.restype = ctypes.c_ssize_t
            api.SetWindowLongPtrW.argtypes = [wintypes.HWND, ctypes.c_int, ctypes.c_ssize_t]
            api.SetWindowLongPtrW.restype = ctypes.c_ssize_t
            api.SetWindowPos.argtypes = [wintypes.HWND, wintypes.HWND, ctypes.c_int, ctypes.c_int,
                                         ctypes.c_int, ctypes.c_int, wintypes.UINT]
            api.SetWindowPos.restype = wintypes.BOOL
            api.ScreenToClient.argtypes = [wintypes.HWND, ctypes.POINTER(wintypes.POINT)]
            api.ScreenToClient.restype = wintypes.BOOL
            api.SetCapture.argtypes = [wintypes.HWND]
            api.SetCapture.restype = wintypes.HWND
            api.ReleaseCapture.argtypes = []
            api.ReleaseCapture.restype = wintypes.BOOL

            class TrackMouseEvent(ctypes.Structure):
                _fields_ = [('cbSize', wintypes.DWORD), ('dwFlags', wintypes.DWORD),
                            ('hwndTrack', wintypes.HWND), ('dwHoverTime', wintypes.DWORD)]

            api.TrackMouseEvent.argtypes = [ctypes.POINTER(TrackMouseEvent)]
            api.TrackMouseEvent.restype = wintypes.BOOL
            self._native_frame_api = (ctypes, wintypes, api, TrackMouseEvent)
        except (AttributeError, OSError):
            self._native_frame_api = None

    def _enable_native_frame(self):
        if not self._native_frame_api:
            return
        ctypes, _wintypes, api, _track_type = self._native_frame_api
        hwnd = int(self.winId())
        if hwnd == self._native_frame_hwnd:
            return
        style = api.GetWindowLongPtrW(hwnd, -16)
        # FramelessWindowHint removes WS_THICKFRAME. Restore sizing/system behavior;
        # Qt itself keeps NCCALCSIZE frameless and maximizes inside the work area.
        ctypes.set_last_error(0)
        previous = api.SetWindowLongPtrW(hwnd, -16, style | 0x000f0000)
        if not previous and ctypes.get_last_error():
            return
        if api.SetWindowPos(hwnd, None, 0, 0, 0, 0, 0x0037):  # FRAMECHANGED | NOMOVE | NOSIZE | NOZORDER | NOACTIVATE
            self._native_frame_hwnd = hwnd

    def toggle_maximized(self):
        if self.isMaximized() or self.isFullScreen():
            self.showNormal()
        else:
            self.showMaximized()

    def showEvent(self, event):
        super().showEvent(event)
        self._enable_native_frame()
        self._layout_resize_grips()
        title_bar = getattr(self, 'title_bar', None)
        if title_bar:
            title_bar.sync_window_state()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._layout_resize_grips()

    def changeEvent(self, event):
        super().changeEvent(event)
        if event.type() == QEvent.Type.WindowStateChange:
            self._layout_resize_grips()
            title_bar = getattr(self, 'title_bar', None)
            if title_bar:
                title_bar.sync_window_state()
        elif event.type() == QEvent.Type.ActivationChange and not self.isActiveWindow():
            self._set_native_caption_hover(False)

    def _layout_resize_grips(self):
        grips = getattr(self, '_frame_grips', ())
        if not grips:
            return
        visible = not (self._native_frame_hwnd or self.isMaximized() or self.isFullScreen())
        width, height, border = self.width(), self.height(), self._RESIZE_BORDER
        rectangles = ((0, border, border, max(0, height - 2 * border)),
                      (width - border, border, border, max(0, height - 2 * border)),
                      (border, 0, max(0, width - 2 * border), border),
                      (border, height - border, max(0, width - 2 * border), border),
                      (0, 0, border, border), (width - border, 0, border, border),
                      (0, height - border, border, border),
                      (width - border, height - border, border, border))
        for grip, rectangle in zip(grips, rectangles):
            grip.setGeometry(*rectangle)
            grip.setVisible(visible)
            if visible:
                grip.raise_()

    def _frame_hit_test(self, point):
        if not self.rect().contains(point):
            return 1  # HTCLIENT
        if not (self.isMaximized() or self.isFullScreen()):
            border = self._RESIZE_BORDER
            left, right = point.x() < border, point.x() >= self.width() - border
            top, bottom = point.y() < border, point.y() >= self.height() - border
            if top:
                return 13 if left else 14 if right else 12
            if bottom:
                return 16 if left else 17 if right else 15
            if left or right:
                return 10 if left else 11
        title_bar = getattr(self, 'title_bar', None)
        if title_bar and title_bar.isVisible():
            local = title_bar.mapFrom(self, point)
            if title_bar.rect().contains(local):
                button = title_bar.maximize_button
                if button.isVisible() and button.isEnabled() and button.rect().contains(button.mapFrom(self, point)):
                    return 9  # HTMAXBUTTON: exposes the Windows 11 Snap menu.
                if title_bar.is_draggable(local):
                    return 2  # HTCAPTION: native drag, restore-on-drag and double click.
        return 1

    def _native_local_point(self, message, screen_coordinates):
        ctypes, wintypes, api, _track_type = self._native_frame_api
        packed = int(message.lParam)
        point = wintypes.POINT(ctypes.c_short(packed & 0xffff).value,
                               ctypes.c_short((packed >> 16) & 0xffff).value)
        if screen_coordinates and not api.ScreenToClient(message.hWnd, ctypes.byref(point)):
            return QPoint(-1, -1)
        ratio = self.devicePixelRatioF()
        # Convert after mapping to the native client: desktop origins do not share
        # one scale factor when monitors have different DPI settings.
        return QPoint(math.floor(point.x / ratio), math.floor(point.y / ratio))

    def _set_native_caption_hover(self, hovered):
        title_bar = getattr(self, 'title_bar', None)
        if title_bar:
            button = title_bar.maximize_button
            if button.testAttribute(Qt.WidgetAttribute.WA_UnderMouse) != hovered:
                button.setAttribute(Qt.WidgetAttribute.WA_UnderMouse, hovered)
                button.update()

    def nativeEvent(self, event_type, message):
        if not self._native_frame_api or not self._native_frame_hwnd:
            return super().nativeEvent(event_type, message)
        ctypes, wintypes, api, track_type = self._native_frame_api
        native = wintypes.MSG.from_address(int(message))
        kind = native.message
        if kind == 0x0084:  # WM_NCHITTEST
            return True, self._frame_hit_test(self._native_local_point(native, True))
        if kind in (0x0200, 0x00a0) and self._native_caption_pressed:  # Captured mouse move
            point = self._native_local_point(native, kind == 0x00a0)
            self.title_bar.maximize_button.setDown(self._frame_hit_test(point) == 9)
            return True, 0
        if kind == 0x00a0:  # WM_NCMOUSEMOVE: retain DefWindowProc's Snap hover behavior.
            self._set_native_caption_hover(native.wParam == 9)
            if native.wParam == 9:
                tracking = track_type(ctypes.sizeof(track_type), 0x0012, native.hWnd, 0)
                api.TrackMouseEvent(ctypes.byref(tracking))  # TME_LEAVE | TME_NONCLIENT
        elif kind == 0x02a2:  # WM_NCMOUSELEAVE
            self._set_native_caption_hover(False)
        elif kind in (0x00a1, 0x00a3) and native.wParam == 9:  # NC left press / double click
            title_bar = getattr(self, 'title_bar', None)
            if title_bar and title_bar.maximize_button.isEnabled():
                self._native_caption_pressed = True
                title_bar.maximize_button.setDown(True)
                api.SetCapture(native.hWnd)
                return True, 0
        elif kind in (0x0202, 0x00a2) and self._native_caption_pressed:  # Client / NC left release
            point = self._native_local_point(native, kind == 0x00a2)
            button = self.title_bar.maximize_button
            activate = self._frame_hit_test(point) == 9 and button.isEnabled()
            self._native_caption_pressed = False
            button.setDown(False)
            api.ReleaseCapture()
            if activate:
                QTimer.singleShot(0, button.click)
            return True, 0
        elif kind in (0x0215, 0x001f):  # WM_CAPTURECHANGED / WM_CANCELMODE
            self._native_caption_pressed = False
            title_bar = getattr(self, 'title_bar', None)
            if title_bar:
                title_bar.maximize_button.setDown(False)
        elif kind == 0x0200:  # Moving into the client clears the NC hover state.
            self._set_native_caption_hover(False)
        return super().nativeEvent(event_type, message)


_DEFAULT_REWRITE_DIRECTORY = object()


class RewriteLeaseStore:
    """Write-ahead leases, separate for each repository and local branch."""
    def __init__(self, directory=_DEFAULT_REWRITE_DIRECTORY):
        self._central = directory is _DEFAULT_REWRITE_DIRECTORY
        self.directory = Path(APP_DATA) if self._central else Path(directory) if directory is not None else None
        self._memory = {}
        self._lock = auth_threading.RLock()

    def _central_records(self):
        try:
            with _config_lock():
                if not _config_has_section('rewrites'):
                    _set_config_section('rewrites', {})
                records = _config_section('rewrites')
                if not isinstance(records, dict):
                    raise ValueError('Invalid rewrite records')
                return records
        except (OSError, ValueError, RuntimeError):
            raise GitError('Nie można odczytać zapisanego stanu zmiany historii w gitline.json. Sprawdź konfigurację przed wysłaniem historii.') from None

    @staticmethod
    def key(repo, source_ref):
        import hashlib
        return hashlib.sha256((repository_scope(repo) + '\0' + source_ref).encode('utf-8')).hexdigest()

    @staticmethod
    def route_fingerprints(plan):
        import hashlib
        return [hashlib.sha256(url.encode('utf-8')).hexdigest() for url in plan.push_urls]

    @staticmethod
    def matches(record, plan):
        return bool(record and record.get('repo') == repository_scope(plan.repo)
            and record.get('source_ref') == plan.source_ref and record.get('remote_name') == plan.remote_name
            and record.get('push_url_hashes') == RewriteLeaseStore.route_fingerprints(plan)
            and record.get('destination_ref') == plan.destination_ref)

    @classmethod
    def _provenance_identity(cls, record):
        if not isinstance(record, dict):
            return None
        try:
            core = cls._validated(record, record.get('repo', ''), record.get('source_ref', ''))
            return {name: list(core[name]) if isinstance(core[name], list) else core[name] for name in
                    ('repo', 'source_ref', 'old_head', 'new_head', 'expected_remote_oid',
                     'remote_name', 'destination_ref', 'push_url_hashes')}
        except (GitError, TypeError, ValueError, KeyError):
            return None

    def get_provenance(self, record):
        """Optional history labels are separate from the authorization record."""
        identity = self._provenance_identity(record)
        if identity is None:
            return None
        key = self.key(identity['repo'], identity['source_ref']) + '.' + identity['new_head'] + '.history'
        try:
            with self._lock:
                if self._central:
                    data = self._central_records().get(key)
                elif self.directory is None:
                    data = self._memory.get(key)
                else:
                    with (self.directory / (key + '.json')).open('r', encoding='utf-8') as stream:
                        raw = stream.read(2 * 1024 * 1024 + 1)
                    if len(raw) > 2 * 1024 * 1024:
                        return None
                    data = json.loads(raw)
            if not isinstance(data, dict) or data.get('lease') != identity:
                return None
            return _clean_squash_provenance(data.get('provenance'), len(identity['new_head']))
        except (OSError, ValueError, TypeError, UnicodeError, RuntimeError):
            return None

    def save_provenance(self, record, provenance):
        identity = self._provenance_identity(record)
        metadata = _clean_squash_provenance(provenance, len(identity['new_head'])) if identity else None
        if metadata is None:
            return False
        key = self.key(identity['repo'], identity['source_ref']) + '.' + identity['new_head'] + '.history'
        try:
            # Full sidecar replacements need no read-modify-write lock. A failed
            # annotation write never changes or invalidates a force-push lease.
            with self._lock:
                if self.directory is not None:
                    self.directory.mkdir(parents=True, exist_ok=True)
                self._write(key, dict(lease=identity, provenance=metadata))
            return True
        except (OSError, ValueError, TypeError, RuntimeError):
            return False

    @staticmethod
    def _flat(record):
        return {name: list(value) if isinstance(value, list) else value
                for name, value in record.items() if name != 'previous'}

    @classmethod
    def _validated(cls, record, repo, source_ref, previous=False):
        valid = (isinstance(repo, (str, os.PathLike)) and bool(repo) and isinstance(source_ref, str)
                 and isinstance(record, dict) and record.get('repo') == repository_scope(repo)
                 and record.get('source_ref') == source_ref and source_ref.startswith('refs/heads/')
                 and all(isinstance(record.get(name), str) and re.fullmatch(r'[0-9a-f]{40}|[0-9a-f]{64}', record[name])
                         for name in ('old_head', 'new_head', 'expected_remote_oid'))
                 and len({len(record[name]) for name in ('old_head', 'new_head', 'expected_remote_oid')}) == 1
                 and all(isinstance(record.get(name), str) and record[name]
                         and not any(ord(char) < 32 for char in record[name])
                         for name in ('source_ref', 'remote_name', 'destination_ref'))
                 and record['destination_ref'].startswith('refs/heads/')
                 and 'push_urls' not in record
                 and isinstance(record.get('push_url_hashes'), list) and len(record['push_url_hashes']) == 1
                 and isinstance(record['push_url_hashes'][0], str)
                 and re.fullmatch(r'[0-9a-f]{64}', record['push_url_hashes'][0]))
        if not valid or previous and 'previous' in record:
            raise GitError('Zapisany stan zmiany historii jest nieprawidłowy. Wymuszone wysyłanie zostało zablokowane.')
        result = cls._flat(record)
        if 'previous' in record:
            prior = cls._validated(record['previous'], repo, source_ref, previous=True)
            if any(prior[name] != result[name] for name in
                   ('repo', 'source_ref', 'remote_name', 'destination_ref', 'push_url_hashes', 'expected_remote_oid')):
                raise GitError('Poprzedni zapis zmiany historii wskazuje inny cel lub stan serwera. Wymuszone wysyłanie zostało zablokowane.')
            result['previous'] = prior
        return result

    def get(self, repo, source_ref):
        key = self.key(repo, source_ref)
        with self._lock:
            if self._central:
                record = self._central_records().get(key)
            elif self.directory is None:
                record = self._memory.get(key)
            else:
                try: record = json.loads((self.directory / (key + '.json')).read_text(encoding='utf-8'))
                except FileNotFoundError: return None
                except (OSError, ValueError) as exc:
                    raise GitError('Nie można odczytać zapisanego stanu zmiany historii: ' + str(exc)) from exc
            if record is None: return None
            return self._validated(record, repo, source_ref)

    @contextlib.contextmanager
    def _file_lock(self, key):
        if self._central:
            with _config_lock():
                yield
            return
        if self.directory is None:
            yield
            return
        self.directory.mkdir(parents=True, exist_ok=True)
        descriptor = os.open(str(self.directory / (key + '.lock')), os.O_RDWR | os.O_CREAT, 0o600)
        acquired = False
        try:
            if os.fstat(descriptor).st_size == 0: os.write(descriptor, b'0')
            deadline = time.monotonic() + 30
            while not acquired:
                try:
                    os.lseek(descriptor, 0, os.SEEK_SET)
                    if os.name == 'nt':
                        import msvcrt
                        msvcrt.locking(descriptor, msvcrt.LK_NBLCK, 1)
                    else:
                        import fcntl
                        fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
                    acquired = True
                except OSError:
                    if time.monotonic() >= deadline:
                        raise GitError('Stan zmiany historii jest zajęty przez inną operację. Spróbuj ponownie.') from None
                    time.sleep(0.025)
            yield
        finally:
            if acquired:
                os.lseek(descriptor, 0, os.SEEK_SET)
                if os.name == 'nt':
                    import msvcrt
                    msvcrt.locking(descriptor, msvcrt.LK_UNLCK, 1)
                else:
                    import fcntl
                    fcntl.flock(descriptor, fcntl.LOCK_UN)
            os.close(descriptor)

    def _write(self, key, record):
        if self._central:
            with _config_lock():
                records = self._central_records()
                records[key] = record
                _set_config_section('rewrites', records)
            return
        if self.directory is None:
            self._memory[key] = record
            return
        name = None
        try:
            with tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', dir=self.directory,
                                             prefix=key + '.', suffix='.tmp', delete=False) as stream:
                name = stream.name
                json.dump(record, stream, ensure_ascii=False)
                stream.flush(); os.fsync(stream.fileno())
            os.replace(name, self.directory / (key + '.json'))
        finally:
            if name is not None:
                with contextlib.suppress(FileNotFoundError): Path(name).unlink()

    def save(self, record, previous=None):
        if not isinstance(record, dict):
            raise GitError('Brakuje prawidłowego zapisu zmiany historii.')
        candidate = self._flat(record)
        prior = previous if previous is not None else record.get('previous')
        if prior is not None:
            if not isinstance(prior, dict): raise GitError('Poprzedni zapis zmiany historii jest nieprawidłowy.')
            candidate['previous'] = self._flat(prior)
        repo, source_ref = candidate.get('repo', ''), candidate.get('source_ref', '')
        record = self._validated(candidate, repo, source_ref)
        key = self.key(repo, source_ref)
        with self._lock, self._file_lock(key):
            self._write(key, record)

    def clear(self, record):
        key = self.key(record['repo'], record['source_ref'])
        with self._lock, self._file_lock(key):
            current = self.get(record['repo'], record['source_ref'])
            if not current: return
            if self._flat(current) != self._flat(record):
                if current.get('previous') == self._flat(record):
                    self._write(key, self._flat(current))
                return
            if self._central:
                records = self._central_records()
                records.pop(key, None)
                _set_config_section('rewrites', records)
            elif self.directory is None: self._memory.pop(key, None)
            else:
                with contextlib.suppress(FileNotFoundError): (self.directory / (key + '.json')).unlink()

    @staticmethod
    def ancestor(backend, repo, ancestor, head):
        code, _ = backend._execute(repo, ['merge-base', '--is-ancestor', ancestor, head], allowed=(0, 1))
        return code == 0

    def active(self, backend, repo, source_ref, head_oid):
        if not source_ref or not head_oid: return None
        stored = self.get(repo, source_ref)
        if not stored: return None
        record = None
        for candidate in (self._flat(stored), stored.get('previous')):
            if (candidate and backend._optional(repo, ['rev-parse', '--verify', candidate['new_head'] + '^{commit}'])
                    and self.ancestor(backend, repo, candidate['new_head'], head_oid)
                    and not self.ancestor(backend, repo, candidate['expected_remote_oid'], head_oid)):
                record = candidate
                break
        if record is None: return None
        # A crash after a successful push can leave a lease on disk. Only expire
        # it when this exact target is known to contain the rewritten history.
        try:
            plan = backend.resolve_push_plan(repo, record['remote_name'], record['destination_ref'])
            if self.matches(record, plan):
                tracking = backend.push_tracking_state(repo, plan)
                if tracking['oid'] and self.ancestor(backend, repo, record['new_head'], tracking['oid']):
                    return None
        except GitError:
            pass  # Preserve the original lease; the push review will explain a changed route.
        return record


class ShutdownOverlay(QWidget):
    """A visible, repaintable shutdown state while accepted writes finish."""
    def __init__(self, parent):
        super().__init__(parent)
        self.started = time.monotonic()
        self.paint_count = 0
        self.setAccessibleName('Zamykanie Gitline')
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        layout = QVBoxLayout(self); layout.setContentsMargins(36, 36, 36, 36)
        layout.addStretch()
        card = QFrame(); card.setMaximumWidth(650)
        card.setStyleSheet('QFrame { background: #1c1c25; border: 1px solid #65523b; border-radius: 22px; }'
                           'QLabel { background: transparent; border: 0; color: #eae6e2; }')
        content = QVBoxLayout(card); content.setContentsMargins(36, 30, 36, 30); content.setSpacing(16)
        logo = QLabel(); logo.setPixmap(ui_icon('logo', '#e8c58b', 60).pixmap(60, 60)); content.addWidget(logo)
        eyebrow = QLabel('GITLINE  /  WORKSPACE'); eyebrow.setStyleSheet('color: #d7b783; font-size: 10px; letter-spacing: 2px;')
        content.addWidget(eyebrow)
        title = QLabel('Kończymy pracę'); title.setStyleSheet('font-size: 28px; font-weight: 600; color: #f3eee7;')
        content.addWidget(title)
        self.operation = QLabel('Przygotowanie do zamknięcia…'); self.operation.setWordWrap(True)
        self.operation.setStyleSheet('font-size: 15px; color: #e7ca9e;'); content.addWidget(self.operation)
        self.detail = QLabel('Zapisujemy ustawienia i kończymy bieżące operacje.'); self.detail.setWordWrap(True)
        self.detail.setStyleSheet('font-size: 12px; color: #aca6a1;'); content.addWidget(self.detail)
        self.progress = QProgressBar(); self.progress.setRange(0, 0); self.progress.setTextVisible(False)
        self.progress.setFixedHeight(5)
        self.progress.setStyleSheet('QProgressBar { border: 0; background: #302b28; border-radius: 2px; }'
                                   'QProgressBar::chunk { background: #d5ad72; border-radius: 2px; }')
        content.addWidget(self.progress)
        self.elapsed = QLabel('0 s'); self.elapsed.setStyleSheet('color: #8f8982; font-size: 11px;')
        content.addWidget(self.elapsed)
        layout.addWidget(card, 0, Qt.AlignmentFlag.AlignHCenter); layout.addStretch()
        parent.installEventFilter(self)
        self.setGeometry(parent.rect())

    def eventFilter(self, watched, event):
        if watched is self.parentWidget() and event.type() == QEvent.Type.Resize:
            self.setGeometry(watched.rect())
        return super().eventFilter(watched, event)

    def paintEvent(self, event):
        self.paint_count += 1
        painter = QPainter(self)
        backdrop = QLinearGradient(0, 0, self.width(), self.height())
        backdrop.setColorAt(0, QColor('#191720')); backdrop.setColorAt(1, QColor('#101219'))
        painter.fillRect(self.rect(), backdrop)

    def show_status(self, operation, detail, progress=None):
        self.operation.setText(operation); self.detail.setText(detail)
        seconds = max(0, int(time.monotonic() - self.started))
        self.elapsed.setText(f'{seconds // 60} min {seconds % 60} s' if seconds >= 60 else f'{seconds} s')
        if progress is not None and progress.percent is not None:
            self.progress.setRange(0, 100); self.progress.setValue(progress.percent)
        else:
            self.progress.setRange(0, 0)
        self.update()


class MainWindow(FramelessWindow):
    def __init__(self, initial_repo=None, persist=True, *, startup_tick=None):
        super().__init__()
        self._startup_tick = startup_tick
        self._startup_ready = False
        self._startup_visibility_queued = False
        self._startup_catalog_pending = False
        self._taskbar_request = None
        self._taskbar_poll = QTimer(self)
        self._taskbar_poll.timeout.connect(self._poll_taskbar_pin)
        if startup_tick is not None:
            # Restoring a maximized native window must not reveal it over the logo.
            self.setAttribute(Qt.WidgetAttribute.WA_DontShowOnScreen, True)
        self.persist = persist
        self.setWindowTitle(APP_NAME)
        self.setWindowIcon(ui_icon('logo', '#baa8ff', 64))
        fit_window_to_screen(self, preferred=(1360, 860), minimum=(1000, 640), center=True)
        if persist: _bootstrap_source_defaults()
        self.settings = JsonSettings(persist=persist)
        initial_path = initial_repo or (self.settings.value('last_repo') if persist else None)
        self.hub = TaskHub(self); self.hub.activity.connect(self.activity_changed)
        self.hub.operation_changed.connect(self.operation_changed)
        self.hub.progress_changed.connect(self.operation_progress_changed)
        self._progress_token = None
        self._dialogs = set()
        self._opening_path = ''
        self._repository_error_key = ''
        self._repository_status_key = ''
        self._close_pending = False
        self._shutdown_started = False
        self._shutdown_complete = False
        self._shutdown_saved = False
        self._shutdown_saving = False
        self._shutdown_preparing = False
        self._shutdown_overlay = None
        self._shutdown_timer = QTimer(self); self._shutdown_timer.setInterval(150)
        self._shutdown_timer.timeout.connect(self._advance_shutdown)
        self._operation_states = {}
        self._pending_selections = {}
        self._selection_requests = {}
        self._selection_needs_refresh = set()
        self._seen_new_files = {}
        self._unbound_clones = {}
        self._approved_routes = {}
        self._approved_route_labels = {}
        self._push_hint_context = None
        self.rewrite_leases = RewriteLeaseStore() if persist else RewriteLeaseStore(None)
        self._active_rewrite = None
        self._history_publication = {}
        self._history_publication_context = None
        self._history_publication_request = None
        self._history_publication_serial = 0
        self._history_publication_updated = 0.0
        self._history_files_context = None
        self._history_files_serial = 0
        self._history_files_error = False
        self.backend = None
        self.git_error = ''
        try:
            self.backend = GitBackend()
            self.backend.auth_options = credential_git_options()
        except Exception as exc: self.git_error = str(exc)
        self.store = AccountStore()
        self.catalog = RepositoryCatalog(self.store, self.hub, self)
        self._startup_checkpoint()
        self.repo = ''; self.state = None; self.refreshing = False; self.mutating = False
        self.opening = False; self.open_serial = 0; self.refresh_serial = 0; self.drafts = {}
        self.diff_serial = 0; self.view_mode = 0
        self._last_signature = None
        if persist:
            try:
                saved_drafts = json.loads(self.settings.value('drafts', '{}'))
                if isinstance(saved_drafts, dict):
                    self.drafts = {key: tuple(value) for key, value in saved_drafts.items()
                                   if isinstance(key, str) and isinstance(value, list) and len(value) == 2
                                   and all(isinstance(text, str) for text in value)}
            except (TypeError, ValueError):
                pass
        self.recent = []
        if persist:
            try: self.recent = json.loads(self.settings.value('recent', '[]'))
            except (TypeError, ValueError): pass
        if (persist and not initial_repo and initial_path
                and repository_ui_key(initial_path) not in {repository_ui_key(path) for path in self.recent}):
            # Older versions left last_repo behind when its recent entry was removed.
            self.settings.setValue('last_repo', '')
            initial_path = None
        self.build_ui()
        self._startup_checkpoint()
        self.repo_selector.setFocus(Qt.FocusReason.OtherFocusReason)
        self.update_accounts(refresh=persist, reveal=not initial_path)
        self._startup_checkpoint()
        if persist:
            def recovered(errors):
                self.update_accounts(refresh=True, reveal=False)
                if errors: self.show_error('\n'.join(errors))
            self.hub.submit(self.store.recover_pending, recovered, self.show_error,
                            scope='accounts', kind='write', label='Sprawdzanie zapisanych kont')
        self.populate_recent()
        self._startup_checkpoint()
        self.add_shortcuts()
        self.timer = QTimer(self); self.timer.setInterval(6000)
        self.timer.timeout.connect(self.update_history_dates)
        self.timer.timeout.connect(lambda: self.refresh(silent=True)); self.timer.start()
        if persist:
            geometry = self.settings.value('geometry')
            if geometry: self.restoreGeometry(geometry)
        fit_window_to_screen(self, minimum=(1000, 640))
        if not (initial_path and self.backend):
            self._mark_startup_ready()
        if initial_path:
            # Validate saved paths through the asynchronous Git operation too;
            # probing a disconnected network folder must not stall the 3D intro.
            self._opening_path = str(initial_path)
            serial = self.open_serial
            QTimer.singleShot(0, lambda: self.open_repo(initial_path)
                              if self.open_serial == serial and self._opening_path == str(initial_path) else None)
        self._startup_checkpoint()
        self._startup_tick = None

    def paintEvent(self, event):
        super().paintEvent(event)
        if (not self._startup_visibility_queued and self.isVisible()
                and not self.testAttribute(Qt.WidgetAttribute.WA_DontShowOnScreen)
                and 'GITLINE_STARTUP_EVENT' in os.environ):
            self._startup_visibility_queued = True
            # The normal golden splash consumes the marker first. If it was
            # closed early, finish this window's paint before releasing setup.
            QTimer.singleShot(0, self._notify_main_window_visible)

    def _notify_main_window_visible(self):
        if not self.isVisible() or self.testAttribute(Qt.WidgetAttribute.WA_DontShowOnScreen):
            self._startup_visibility_queued = False
            return
        if 'GITLINE_STARTUP_EVENT' in os.environ:
            _notify_startup_visible()

    def _startup_checkpoint(self):
        if self._startup_tick is not None:
            self._startup_tick()

    def _mark_startup_ready(self):
        self._startup_ready = True
        if self._startup_catalog_pending and not self._close_pending:
            self._startup_catalog_pending = False
            # Let the initial local snapshot finish applying before network jobs
            # compete for the shared worker pool.
            QTimer.singleShot(0, lambda: self.catalog.refresh(force=True) if not self._close_pending else None)

    def _clear_taskbar_pending(self):
        if self.persist:
            with _config_lock():
                bootstrap = _config_section('bootstrap', {})
                bootstrap['taskbar_pending'] = False
                _set_config_section('bootstrap', bootstrap)

    def _close_taskbar_request(self):
        self._taskbar_poll.stop()
        request, self._taskbar_request = self._taskbar_request, None
        if request is not None: request.close()

    def dismiss_taskbar_pin(self):
        self._close_taskbar_request()
        self._clear_taskbar_pending()
        self.shortcut_notice.hide()

    def _taskbar_manual_help(self, error):
        self._close_taskbar_request()
        self._clear_taskbar_pending()
        self.shortcut_label.setText(str(error) + '\n' + _TASKBAR_MANUAL_HINT)
        self.shortcut_button.hide()

    def request_taskbar_pin(self):
        if self._taskbar_request is not None: return
        try:
            self._taskbar_request = _start_taskbar_pin_request()
        except RuntimeError as error:
            self._taskbar_manual_help(error)
            return
        self.shortcut_button.setEnabled(False)
        self._taskbar_poll.start(100)

    def _poll_taskbar_pin(self):
        if self._taskbar_request is None: return
        try:
            result = self._taskbar_request.poll()
        except RuntimeError as error:
            self._taskbar_manual_help(error)
            return
        if result is not None:
            self.dismiss_taskbar_pin()
            if result is True: self.status.setText('Gitline przypięty do paska zadań.')

