    def build_repo_picker(self):
        self.repo_popup = RepositoryPopup(self.repo_selector)
        layout = QVBoxLayout(self.repo_popup); layout.setContentsMargins(12, 12, 12, 12); layout.setSpacing(8)
        self.repo_search = QLineEdit(); self.repo_search.setPlaceholderText('Znajdź repozytorium…')
        self.repo_search.setAccessibleName('Wyszukaj repozytorium na komputerze lub do sklonowania')
        self.repo_search.textChanged.connect(self.filter_recent)
        self.repo_search.returnPressed.connect(self.activate_recent_search)
        self.repo_search.installEventFilter(self)
        layout.addWidget(self.repo_search)
        self.repos = SmoothListWidget(); self.repos.setMouseTracking(True)
        self.repos.setAccessibleName('Repozytoria na komputerze i projekty do sklonowania')
        self.repos.setItemDelegate(RecentRepositoryDelegate(self.repos))
        self.repos.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.repos.itemClicked.connect(self.open_recent)
        self.repos.itemActivated.connect(self.open_recent)
        self.repos.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.repos.customContextMenuRequested.connect(self.recent_menu)
        layout.addWidget(self.repos, 1)
        self.no_repos = ui_label('Otwórz projekt lub sklonuj repozytorium, aby dodać je do listy.', 'muted', True)
        layout.addWidget(self.no_repos)
        separator = QFrame(); separator.setFrameShape(QFrame.Shape.HLine); layout.addWidget(separator)
        actions = QHBoxLayout(); actions.setSpacing(6)
        for text, icon, callback in (('Otwórz…', 'folder', self.choose_repo),
                                     ('Klonuj…', 'clone', self.clone_repo),
                                     ('Nowe…', 'plus', self.new_repo)):
            button = ui_button(text, lambda checked=False, action=callback: self.picker_action(action), icon, 'toolbarAction')
            actions.addWidget(button, 1)
        layout.addLayout(actions)
        catalog_row = QHBoxLayout(); catalog_row.setSpacing(6)
        self.repo_catalog_status = ui_label('', 'muted')
        self.repo_catalog_status.setStyleSheet('font-size: 11px;')
        self.repo_catalog_status.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)
        self.repo_catalog_status.setMinimumWidth(0)
        catalog_row.addWidget(self.repo_catalog_status, 1)
        self.repo_catalog_refresh = ui_button('Odśwież', lambda: self.catalog.refresh(force=True), 'refresh', 'toolbarAction')
        self.repo_catalog_refresh.setAccessibleName('Odśwież projekty z połączonych kont')
        catalog_row.addWidget(self.repo_catalog_refresh)
        catalog_row.addWidget(ui_button('Konta', lambda: self.picker_action(self.show_accounts), 'user', 'toolbarAction'))
        layout.addLayout(catalog_row)
        footer = QHBoxLayout()
        footer.addWidget(ui_button('Start', lambda: self.picker_action(self.show_home), kind='toolbarAction'))
        footer.addStretch()
        footer.addWidget(ui_button('O aplikacji', lambda: self.picker_action(self.show_about), kind='toolbarAction'))
        layout.addLayout(footer)

    def picker_action(self, callback):
        self.repo_popup.hide()
        callback()

    def show_repo_picker(self):
        if self._close_pending: return
        if self.repo_popup.isVisible():
            self.repo_popup.hide(); return
        self.repo_search.clear(); self.populate_recent(reset_scroll=True)
        self.repo_popup.show_below()
        self.repo_search.setFocus(Qt.FocusReason.PopupFocusReason)
        self.catalog.refresh()

    def filter_recent(self, text=''):
        self.populate_recent(reset_scroll=True)

    def activate_recent_search(self):
        item = self.repos.currentItem()
        if item is not None and not item.isHidden(): self.open_recent(item)

    def open_recent(self, item):
        if item is None or self._close_pending: return
        data = item.data(Qt.ItemDataRole.UserRole)
        if data is None: return
        self.repo_popup.hide()
        if isinstance(data, dict): self.clone_repo(dict(data))
        else: self.open_repo(data)

    def eventFilter(self, watched, event):
        if (watched is getattr(self, 'repo_search', None) and event.type() == QEvent.Type.KeyPress
                and event.key() == Qt.Key.Key_Down):
            self.repos.setFocus(Qt.FocusReason.TabFocusReason)
            return True
        return super().eventFilter(watched, event)

