        layout.addWidget(ui_label('Repozytoria z GitHuba i GitLabów są pobierane automatycznie. Wybierz projekt, aby sklonować go na dysk.', 'muted', True))
        self.remote_browser = RepositoryBrowser(self.catalog, page)
        layout.addWidget(self.remote_browser, 1)
