    def add_shortcuts(self):
        for sequence, callback in [('Ctrl+O', self.choose_repo), ('Ctrl+N', self.new_repo), ('Ctrl+R', self.show_repo_picker),
            ('Ctrl+Shift+O', self.clone_repo), ('F5', lambda: self.refresh()),
            ('Ctrl+Return', self.make_commit), ('Ctrl+K', self.command_palette),
            ('Ctrl+F', self.focus_diff_search), ('Escape', lambda: self.diff_search.hide())]:
            action = QAction(self); action.setShortcut(QKeySequence(sequence))
            if sequence == 'Ctrl+Return':
                action.setShortcuts([QKeySequence('Ctrl+Return'), QKeySequence('Ctrl+Enter')])
                action.setAutoRepeat(False)
            action.triggered.connect(callback); self.addAction(action)

    def activity_changed(self, count):
        if self._close_pending:
            QTimer.singleShot(0, self._advance_shutdown)
            return
        visible = [job for job in self.hub.jobs.values() if not job.background and job.state != 'cancelled']
        self.progress.setVisible(bool(visible))
        self.status_dot.setText('◌' if visible else '●')
        if hasattr(self, 'cancel_button'):
            self.cancel_button.setVisible(any(job.state == 'queued' or job.kind == 'read'
                                              for job in visible))
        if hasattr(self, 'repo'):
            scope = repository_scope(self.repo)
            self.mutating = any(job.kind == 'write' and job.scope == scope
                                for job in self.hub.jobs.values())
            self.update_enabled()
        self.render_transfer_progress()

    def operation_progress_changed(self, operation):
        if self._close_pending:
            self._advance_shutdown()
            return
        if (operation.scope == repository_scope(self.repo) and self.hub.jobs.get(operation.token) is operation
                and operation.state == 'running'):
            self.render_transfer_progress()

    def render_transfer_progress(self):
        if not hasattr(self, 'progress'): return
        scope = repository_scope(self.repo)
        jobs = [job for job in self.hub.jobs.values() if job.reports_progress and job.scope == scope
                and job.state in ('queued', 'running')]
        operation = min(jobs, key=lambda job: (job.state != 'running', job.token)) if jobs else None
        if operation is None:
            self.progress.setRange(0, 0)
            self.progress.setVisible(any(not job.background and job.state != 'cancelled'
                                         for job in self.hub.jobs.values()))
            if self._progress_token is not None:
                self._progress_token = None
                self.status.setToolTip(''); self.progress.setToolTip('')
                if self.status.text().startswith('Push · '): self.status.setText('Gotowy.')
            return
        self._progress_token = operation.token
        progress = operation.progress if operation.state == 'running' else None
        text = ('W kolejce' if operation.state == 'queued' else 'Sprawdzanie przed wysłaniem') if progress is None else git_progress_text(progress)
        text = 'Push · ' + text
        self.status.setText(text); self.status.setToolTip(text)
        self.progress.setToolTip(text)
        if progress is not None and progress.percent is not None:
            self.progress.setRange(0, 100); self.progress.setValue(progress.percent)
        else:
            self.progress.setRange(0, 0)
        self.progress.show()

    def operation_changed(self, operation):
        self._operation_states[operation.token] = operation.state
        if operation.state == 'running':
            self.activity_changed(len(self.hub.jobs))
        if len(self._operation_states) > 100:
            self._operation_states.pop(next(iter(self._operation_states)))
        if not hasattr(self, 'status') or not operation.label:
            return
        states = {'queued': 'W kolejce', 'running': 'W toku', 'success': 'Gotowe',
                  'error': 'Błąd', 'cancelled': 'Anulowano'}
        repository_operation = os.path.isabs(operation.scope)
        if operation.kind == 'write' and (not repository_operation or self._repository_notice_relevant(operation.scope)):
            self._repository_status_key = repository_ui_key(operation.scope) if repository_operation else ''
            self.status.setText(f'{states[operation.state]} · {operation.label}')
        self.render_transfer_progress()

    def cancel_pending(self):
        for operation in tuple(self.hub.jobs.values()):
            if operation.state == 'queued' or operation.kind == 'read':
                self.hub.cancel(operation.token, notify=True)

    def keep_dialog(self, dialog):
        """Keep asynchronous forms alive, disconnect and destroy them on completion."""
        self._dialogs.add(dialog)
        def finished(result):
            self._dialogs.discard(dialog)
            dialog.deleteLater()
            if self._close_pending: QTimer.singleShot(0, self._advance_shutdown)
        dialog.finished.connect(finished)
        if hasattr(dialog, 'busy_changed'):
            dialog.busy_changed.connect(lambda busy: QTimer.singleShot(0, self._advance_shutdown)
                                        if not busy and self._close_pending else None)
        dialog.open()
        return dialog

    def update_enabled(self, *unused):
        if not hasattr(self, 'commit_button'): return
        ready = bool(self.repo and self.backend and not self.mutating and not self.opening and not self._close_pending)
        self.more_button.setEnabled(ready)
        self.branches.setEnabled(ready and self.pages.currentIndex() == 1)
        self.new_branch_button.setEnabled(ready and self.state is not None and self.pages.currentIndex() == 1)
        self.repo_selector.setEnabled(not self._close_pending)
        self.folder_button.setEnabled(bool(self.repo and not self.opening and not self._close_pending))
        self.refresh_button.setEnabled(ready and not self.refreshing)
        selection_ready = self.file_selection_ready()
        self.files.blockSignals(True)
        for index in range(self.files.count()):
            item = self.files.item(index)
            flags = item.flags()
            flags = flags | Qt.ItemFlag.ItemIsUserCheckable if selection_ready else flags & ~Qt.ItemFlag.ItemIsUserCheckable
            if item.flags() != flags: item.setFlags(flags)
        self.files.blockSignals(False)
        self.files.viewport().update()
        self.update_selection_summary()
        self.select_all.setEnabled(selection_ready and any(not change.conflicted for change in self.state.changes) if self.state else False)
        remotes = bool(ready and self.pages.currentIndex() == 1 and self.state and self.state.remotes and repository_scope(self.repo) not in self._unbound_clones)
        for button in (self.fetch_button, self.pull_button, self.push_button): button.setEnabled(remotes)
        self.push_button.setText('Force push' if self._active_rewrite else 'Push')
        self.push_button.setToolTip('Wyślij zmienioną historię, sprawdzając zapisany stan zdalnej gałęzi' if self._active_rewrite
                                   else 'Wyślij lokalne commity do sprawdzonego celu')
        has_staged = bool(self.state and any(change.staged for change in self.state.changes))
        conflicts = bool(self.state and any(change.conflicted for change in self.state.changes))
        index_known = (repository_scope(self.repo) not in self._selection_needs_refresh
                       and repository_scope(self.repo) not in self._pending_selections)
        suggestion = self.suggested_commit_message()
        self.summary.setPlaceholderText(suggestion)
        summary_hint = f'Puste pole użyje opisu: {suggestion}. Możesz wpisać własny tytuł commita.'
        self.summary.setToolTip(summary_hint); self.summary.setAccessibleDescription(summary_hint)
        # A snapshot is a read. Accept the click now; TaskHub queues the write
        # after active reads and make_commit validates its captured HEAD again.
        self.commit_button.setEnabled(ready and index_known and has_staged and not conflicts)
        partial = bool(self.state and any(change.staged and change.unstaged for change in self.state.changes))
        self.commit_hint.setText('Odśwież stan plików przed commitem.' if not index_known else
                                'Rozwiąż konflikty i zaznacz poprawione pliki.' if conflicts else
                                'Kreska: tylko część zmian pliku trafi do commita.' if partial else
                                'Commit obejmie zaznaczone pliki.' if has_staged else 'Zaznacz pliki, które chcesz zatwierdzić.')
        self.account_button.setEnabled(not self.mutating)
        self.clone_selected_button.setEnabled(bool(self.remote_browser.current_project()) and not self._close_pending)
        self.summary.setEnabled(not self.mutating and not self.opening)
        self.description.setEnabled(not self.mutating and not self.opening)
        self.render_transfer_progress()

    def show_home(self):
        self.pages.setCurrentIndex(0)

    def show_view(self, index):
        if not self.repo: return
        self.pages.setCurrentIndex(1); self.view_mode = index
        self.commit_files_panel.setVisible(index == 1)
        self.tabs.blockSignals(True); self.tabs.setCurrentIndex(index); self.tabs.blockSignals(False)
        self.left_pages.setCurrentIndex(index)
        if index == 0: self.select_file(self.files.currentItem())
        else:
            self.select_commit(self.history.currentItem())
            self.load_history_publication()

    @staticmethod
    def repository_item_key(item):
        if item is None: return None
        data = item.data(Qt.ItemDataRole.UserRole)
        if isinstance(data, dict):
            return ('remote', data.get('account_id'), data.get('clone_url'))
        if isinstance(data, str): return ('local', repository_ui_key(data))
        return ('section', item.text().split(' · ', 1)[0])

    def populate_recent(self, reset_scroll=False):
        query = self.repo_search.text().strip().casefold()
        previous = None if reset_scroll else self.repository_item_key(self.repos.currentItem())
        bar = self.repos.verticalScrollBar()
        scroll = bar.value()
        anchor = self.repos.itemAt(QPoint(8, 0)) if not reset_scroll else None
        anchor_key = self.repository_item_key(anchor)
        offset = self.repos.visualItemRect(anchor).top() if anchor is not None else 0
        local = [path for path in self.recent if query in path.casefold()]
        projects = self.catalog.candidates(query=query)
        chosen = first = restored_anchor = None
        current_key = repository_ui_key(self.repo)
        preferred = previous or (('local', current_key) if self.repo and not query else None)
        blocked = self.repos.blockSignals(True)
        self.repos.setUpdatesEnabled(False)
        try:
            self.repos.stop_scroll_animation()
            self.repos.clear()
            for title, entries in (('NA TYM KOMPUTERZE', local), ('DO SKLONOWANIA', projects)):
                if not entries: continue
                header = QListWidgetItem(f'{title} · {len(entries)}')
                header.setFlags(Qt.ItemFlag.NoItemFlags)
                self.repos.addItem(header)
                if self.repository_item_key(header) == anchor_key: restored_anchor = header
                for data in entries:
                    remote = isinstance(data, dict)
                    if remote:
                        name = data.get('full_name') or data.get('name', '')
                        details = f"{data.get('host', '')} · @{data.get('account_username', '')}"
                        item = QListWidgetItem(name)
                        item.setToolTip(f"Klonuj {name}\n{details}\n{data.get('description') or ''}".rstrip())
                        item.setData(Qt.ItemDataRole.AccessibleTextRole, f'Klonuj {name}, {details}')
                    else:
                        item = QListWidgetItem(Path(data).name or data)
                        item.setToolTip(data)
                        item.setData(Qt.ItemDataRole.AccessibleTextRole, f'Otwórz {data}')
                        item.setData(Qt.ItemDataRole.UserRole+1, repository_ui_key(data) == current_key)
                    item.setData(Qt.ItemDataRole.UserRole, dict(data) if remote else data)
                    self.repos.addItem(item)
                    if first is None: first = item
                    key = self.repository_item_key(item)
                    if key == preferred: chosen = item
                    if key == anchor_key: restored_anchor = item
            self.repos.setCurrentItem(chosen or first)
            self.repos.doItemsLayout()
            if reset_scroll:
                bar.setValue(0)
                if chosen is not None:
                    self.repos.scrollToItem(chosen, QAbstractItemView.ScrollHint.EnsureVisible)
            elif restored_anchor is not None:
                bar.setValue(bar.value()+self.repos.visualItemRect(restored_anchor).top()-offset)
            else:
                bar.setValue(scroll)
        finally:
            self.repos.blockSignals(blocked)
            self.repos.setUpdatesEnabled(True)
        loading = bool(self.catalog.loading)
        errors = bool(self.catalog.account_error or self.catalog.errors)
        count = len(self.catalog.candidates())
        if loading: status = 'Pobieranie projektów…'
        elif errors: status = 'Nie udało się pobrać części projektów'
        elif self.catalog.accounts: status = f'Do sklonowania · {count}'
        else: status = 'Połącz konto, aby zobaczyć projekty'
        self.repo_catalog_status.setText(status)
        self.repo_catalog_status.setToolTip(status if not errors else
            'Sprawdź połączenie i dostęp do kont, a następnie odśwież listę. Zapisane wyniki pozostają dostępne.')
        self.repo_catalog_refresh.setEnabled(bool(self.catalog.accounts) and not loading)
        if query:
            empty = 'Brak pasujących repozytoriów.'
        elif loading:
            empty = 'Projekty z połączonych kont pojawią się tutaj za chwilę.'
        elif errors:
            empty = 'Nie udało się wczytać projektów. Odśwież listę lub sprawdź konta.'
        elif self.catalog.accounts:
            empty = 'Brak projektów do sklonowania. Możesz otworzyć repozytorium z dysku lub wkleić jego adres.'
        else:
            empty = 'Otwórz repozytorium z dysku lub połącz konto, aby zobaczyć projekty do sklonowania.'
        self.no_repos.setText(empty)
        self.no_repos.setVisible(first is None)

    def recent_menu(self, point):
        item = self.repos.itemAt(point)
        if not item: return
        data = item.data(Qt.ItemDataRole.UserRole)
        if not isinstance(data, str): return
        menu = QMenu(self.repo_popup); remove = menu.addAction('Usuń z listy ostatnich')
        if menu.exec(self.repos.viewport().mapToGlobal(point)) == remove and data in self.recent:
            self.remove_recent_repository(data)

    def _repository_notice_relevant(self, path):
        key = repository_ui_key(path)
        return bool(key and any(repository_ui_key(candidate) == key
                               for candidate in (self.repo, self._opening_path, *self.recent)))

    def _clear_repository_error(self, path):
        key = repository_ui_key(path)
        if not key: return
        if self._repository_error_key == key:
            self._repository_error_key = ''
            self.error_text.clear(); self.error_text.setToolTip(''); self.error_bar.hide()
        if self._repository_status_key == key:
            self._repository_status_key = ''
            self.status.setText('Gotowy.' if self.repo else 'Otwórz repozytorium.')
            self.status.setToolTip('')

    def _show_repository_error(self, path, error, silent=False):
        if silent:
            self.status.setText(_git_safe_text(str(error)))
        else:
            self.show_error(error)
            self._repository_error_key = repository_ui_key(path)
        self._repository_status_key = repository_ui_key(path)

    def _deactivate_repository(self):
        """Close only the current view; retain drafts and let submitted writes finish."""
        path = self.repo
        if not path: return
        self.drafts[path] = (self.summary.text(), self.description.toPlainText())
        if self.persist: self.settings.setValue('drafts', json.dumps(self.drafts, ensure_ascii=False))
        self.repo = ''; self.state = None; self.refreshing = False; self.mutating = False
        self.refresh_serial += 1
        self._history_publication_serial += 1; self._history_files_serial += 1
        self._history_publication_context = self._history_publication_request = None
        self._history_publication = {}; self._history_files_context = None
        self._active_rewrite = None; self._last_signature = None; self._push_hint_context = None
        self.hub.cancel_reads(scope=repository_ui_key(path))
        self.clear_diff()
        for widget in (self.files, self.history, self.branches):
            blocked = widget.blockSignals(True)
            widget.clear(); widget.blockSignals(blocked)
        self.summary.clear(); self.description.clear()
        self.repo_selector.set_repository(''); self.repo_path.clear()
        self.sync_label.setText('Otwórz repozytorium')
        self.push_target_label.setText('Push: wybierz repozytorium.')
        self.operation_notice.hide()
        self._clear_repository_error(path)
        self.show_home(); self.update_enabled()

    def remove_recent_repository(self, path):
        key = repository_ui_key(path)
        self.recent = [entry for entry in self.recent if repository_ui_key(entry) != key]
        self.save_recent()
        if self.persist and repository_ui_key(self.settings.value('last_repo', '')) == key:
            self.settings.setValue('last_repo', '')
        if repository_ui_key(self._opening_path) == key:
            self.open_serial += 1
            self._opening_path = ''; self.opening = False
            self.hub.cancel_reads(key='open-repository')
            self._mark_startup_ready()
        if repository_ui_key(self.repo) == key:
            self._deactivate_repository()
        self._clear_repository_error(path)
        self.populate_recent(); self.update_enabled()

    def save_recent(self):
        if self.persist: self.settings.setValue('recent', json.dumps(self.recent, ensure_ascii=False))

    def choose_repo(self):
        dialog = QFileDialog(self, 'Otwórz repozytorium')
        dialog.setFileMode(QFileDialog.FileMode.Directory)
        dialog.setOption(QFileDialog.Option.ShowDirsOnly, True)
        dialog.fileSelected.connect(self.open_repo)
        self.keep_dialog(dialog)

    def open_repo(self, path):
        if self._close_pending: return
        if not self.backend: self.show_error(self.git_error); return
        self.open_serial += 1; token = self.open_serial
        self._opening_path = str(path)
        self.opening = True; self.update_enabled()
        self.status.setText('Otwieranie repozytorium…')
        self._repository_status_key = repository_ui_key(path)
        def opened(result):
            if token == self.open_serial:
                self._opening_path = ''
                self.repo_opened(result)
        def failed(error):
            if token == self.open_serial:
                self._mark_startup_ready()
                self._opening_path = ''; self.opening = False
                self.update_enabled(); self._show_repository_error(path, error)
        self.hub.submit(lambda: self.backend.root(path), opened, failed,
                        scope='open-repository', key='open-repository', label='Otwieranie repozytorium')

    def repo_opened(self, path):
        if self._repository_error_key:
            self._clear_repository_error(self._repository_error_key)
        if self.repo:
            self.drafts[self.repo] = (self.summary.text(), self.description.toPlainText())
        self.hub.cancel_reads(key='preview')
        self.opening = False; self.refresh_serial += 1
        self.repo = str(path); self.state = None; self._last_signature = None; self._active_rewrite = None
        self._history_publication_serial += 1
        self._history_publication = {}; self._history_publication_context = None; self._history_publication_request = None
        self.hub.cancel_reads(key='history-publication')
        self._push_hint_context = None
        self.mutating = any(job.kind == 'write' and job.scope == repository_scope(path)
                            for job in self.hub.jobs.values())
        self.diff_serial += 1; self.summary.clear(); self.description.clear()
        draft = self.drafts.get(self.repo, ('', ''))
        self.summary.setText(draft[0]); self.description.setPlainText(draft[1])
        self.files.clear(); self.history.clear(); self.branches.clear()
        self.repo_selector.set_repository(path)
        self.setWindowTitle(APP_NAME)
        self.repo_path.setText(str(path)); self.repo_path.setToolTip(str(path))
        self.push_target_label.setText('Push: cel i konto zostaną sprawdzone przed wysłaniem.')
        self.recent = [str(path)] + [item for item in self.recent if item != str(path)]
        self.recent = self.recent[:30]; self.save_recent(); self.populate_recent()
        if self.persist: self.settings.setValue('last_repo', str(path))
        self.show_view(0); self.refreshing = False; self.refresh()

    def refresh(self, silent=False):
        if not self.repo or not self.backend or self.refreshing or self.mutating or self.opening or self._close_pending: return
        self.refreshing = True; self.update_enabled(); path = self.repo
        self.refresh_serial += 1; token = self.refresh_serial
        if not silent: self.status.setText('Sprawdzanie zmian…')
        def loaded(result):
            if path != self.repo or token != self.refresh_serial: return
            self._mark_startup_ready()
            if isinstance(result, RepositoryUnavailable):
                self._deactivate_repository()
                self._show_repository_error(path, repository_unavailable_message(path))
                return
            state, self._active_rewrite = result
            previous = self.state
            self.refreshing = False; self.state = state
            scope = repository_scope(path)
            self._selection_needs_refresh.discard(scope)
            approved = self._approved_routes.get(scope)
            source_ref = getattr(state, 'head_ref', '') or f'refs/heads/{state.branch}'
            if approved and approved[0] != source_ref:
                self.forget_push_route(path)
            elif approved:
                self.show_approved_push_route(path)
            signature = (state.branch, state.upstream, state.ahead, state.behind,
                tuple((f.path, f.index_status, f.worktree_status, f.original_path) for f in state.changes),
                tuple(c.oid for c in state.commits), tuple(state.branches), tuple(state.remotes), state.stash_count, state.operation)
            changed = signature != self._last_signature
            self._last_signature = signature
            self.branches.blockSignals(True); self.branches.clear()
            for branch in state.branches:
                self.branches.addItem(getattr(branch, 'name', str(branch)), branch)
            if self.branches.findText(state.branch) < 0: self.branches.insertItem(0, state.branch)
            self.branches.setCurrentText(state.branch); self.branches.blockSignals(False)
            self.branches.setToolTip(state.branch)
            self.sync_label.setText(f'↑ {state.ahead}   ↓ {state.behind}' if state.upstream else ('Pierwszy push' if state.remotes else 'Lokalnie'))
            self.sync_label.setToolTip(f'Commitów do wysłania: {state.ahead}. Do pobrania: {state.behind}.\nŚledzona gałąź: {state.upstream}'
                                      if state.upstream else 'Pierwszy push ustawi śledzoną gałąź.' if state.remotes else 'Repozytorium bez serwera zdalnego.')
            self.operation_notice.setVisible(bool(state.operation)); self.operation_notice.setText(f'Operacja w toku: {state.operation}. Sprawdź konflikty przed kolejnym commitem.')
            self.tabs.setTabText(0, f'Zmiany  ·  {len(state.changes)}')
            files_changed = previous is None or previous.changes != state.changes
            restored = getattr(self, '_history_selection_after_write', None)
            history_changed = (previous is None or previous.commits != state.commits
                               or bool(restored and restored[0] == scope))
            if files_changed: self.populate_files(quiet=silent)
            if history_changed: self.populate_history()
            if self.view_mode == 0 and not files_changed and self.files.currentItem():
                self.select_file(self.files.currentItem(), quiet=silent)
            elif self.view_mode == 1 and not history_changed and not silent:
                self.select_commit(self.history.currentItem())
            if not silent or changed:
                self.status.setText(f'{Path(path).name}  ·  {state.branch}  ·  ' + (f'{len(state.changes)} zmienionych plików' if state.changes else 'Wszystkie zmiany zapisane'))
                self._repository_status_key = repository_ui_key(path)
            self.update_enabled()
            context = (scope, source_ref, tuple(state.remotes))
            if state.remotes and (context != self._push_hint_context or not silent):
                self._push_hint_context = context
                self.inspect_push_target(path, source_ref)
            self.auto_select_new_files(state)
            self.load_history_publication(force=not silent)
        def failed(error):
            if path == self.repo and token == self.refresh_serial:
                self._mark_startup_ready()
                self.refreshing = False; self.update_enabled()
                self._show_repository_error(path, error, silent=silent)
        def snapshot():
            try:
                state = self.backend.snapshot(path)
            except GitError:
                try: unavailable = not Path(path).is_dir()
                except OSError: unavailable = True
                if unavailable: return RepositoryUnavailable(path)
                raise
            record = self.rewrite_leases.active(self.backend, path, getattr(state, 'head_ref', ''), getattr(state, 'head_oid', ''))
            return state, record
        self.hub.submit(snapshot, loaded, failed,
                        scope=repository_scope(path), key=f'snapshot:{repository_scope(path)}',
                        label='' if silent else 'Odświeżanie repozytorium', background=silent)

    @staticmethod
    def file_check_state(change):
        return (Qt.CheckState.PartiallyChecked if change.staged and change.unstaged else
                Qt.CheckState.Checked if change.staged else Qt.CheckState.Unchecked)

    def displayed_check_state(self, change):
        pending = self._pending_selections.get(repository_scope(self.repo), {})
        return pending.get(change.path, self.file_check_state(change))

    def update_selection_summary(self):
        changes = self.state.changes if self.state else []
        eligible = [change for change in changes if not change.conflicted]
        states = [self.displayed_check_state(change) for change in eligible]
        selected = sum(state != Qt.CheckState.Unchecked for state in states)
        partial = Qt.CheckState.PartiallyChecked in states
        state = (Qt.CheckState.Checked if eligible and selected == len(eligible) and not partial else
                 Qt.CheckState.PartiallyChecked if selected else Qt.CheckState.Unchecked)
        self.select_all.blockSignals(True); self.select_all.setCheckState(state); self.select_all.blockSignals(False)
        self.select_all.setText('Bez konfliktów' if len(eligible) != len(changes) else 'Wszystkie pliki')
        selection_hint = ('Zaznaczenie obejmuje wszystkie pliki bez konfliktów, także ukryte przez filtr. Konflikty sprawdź i zaznacz pojedynczo.'
                          if len(eligible) != len(changes) else 'Zaznacz lub odznacz wszystkie pliki, także ukryte przez filtr.')
        self.select_all.setToolTip(selection_hint + '\nPrawy przycisk myszy: odłóż lub przywróć zmiany (stash).')
        self.selection_header.setToolTip('Prawy przycisk myszy: odłóż lub przywróć zmiany (stash).')
        self.selection_count.setText(f'{selected} / {len(changes)}')
        self.selection_count.setToolTip('Liczba plików z zaznaczonymi zmianami / wszystkie zmienione pliki')

    def populate_files(self, *unused, quiet=False):
        current = self.files.currentItem()
        scroll = self.files.verticalScrollBar().value()
        selected = current.data(Qt.ItemDataRole.UserRole).path if current else None
        self.files.blockSignals(True); self.files.clear()
        query = self.file_filter.text().casefold()
        if self.state:
            for change in self.state.changes:
                if query not in change.path.casefold(): continue
                item = QListWidgetItem(); item.setData(Qt.ItemDataRole.UserRole, change)
                item.setCheckState(self.displayed_check_state(change))
                item.setText(f'{change.path} · {change.index_status}{change.worktree_status}')
                selection_hint = ('Konflikt: najpierw popraw plik. Zaznaczenie oznaczy go jako rozwiązany.' if change.conflicted else
                                  'Część zmian jest już zaznaczona. Kliknij checkbox, aby zaznaczyć cały plik.' if change.staged and change.unstaged else
                                  'Zmiany zaznaczone do commita. Odznaczenie zachowa je na dysku.' if change.staged else
                                  'Zaznacz checkbox, aby dodać zmiany tego pliku do commita.')
                item.setToolTip(change.path + (f' ← {change.original_path}' if change.original_path else '') + '\n' + selection_hint)
                self.files.addItem(item)
                if change.path == selected: self.files.setCurrentItem(item)
        if self.files.currentRow() < 0 and self.files.count(): self.files.setCurrentRow(0)
        self.files.blockSignals(False); self.files_empty.setVisible(self.files.count() == 0)
        if not unused: self.files.verticalScrollBar().setValue(scroll)
        if self.view_mode == 0: self.select_file(self.files.currentItem(), quiet=quiet)
        self.update_enabled()

    def populate_history(self, *unused):
        from PySide6.QtCore import QItemSelectionModel
        scroll = self.history.verticalScrollBar().value()
        current = self.history.currentItem(); current_oid = current.data(Qt.ItemDataRole.UserRole).oid if current else None
        selected = {item.data(Qt.ItemDataRole.UserRole).oid for item in self.history.selectedItems()}
        restored = getattr(self, '_history_selection_after_write', None)
        if restored and restored[0] == repository_scope(self.repo):
            current_oid = restored[1]; selected = {current_oid}; self._history_selection_after_write = None
        self.history.blockSignals(True); self.history.clear(); query = self.history_filter.text().casefold()
        if self.state:
            for commit in self.state.commits:
                if query not in f'{commit.subject} {commit.author} {commit.oid}'.casefold(): continue
                item = QListWidgetItem(); item.setData(Qt.ItemDataRole.UserRole, commit)
                item.setToolTip(f'{commit.subject}\n{commit.author} · {self.commit_date_text(commit.date)}\n{commit.oid}')
                item.setText(f'{commit.short_oid} · {commit.subject} · {commit.author}')
                self.history.addItem(item)
                item.setSelected(commit.oid in selected)
                if commit.oid == current_oid: self.history.setCurrentItem(item, QItemSelectionModel.SelectionFlag.NoUpdate)
        if self.history.currentRow() < 0 and self.history.count():
            remaining = self.history.selectedItems()
            if remaining: self.history.setCurrentItem(remaining[0], QItemSelectionModel.SelectionFlag.NoUpdate)
            else: self.history.setCurrentRow(0)
        self.history.blockSignals(False); self.history_empty.setVisible(self.history.count() == 0)
        if not unused: self.history.verticalScrollBar().setValue(scroll)
        self.apply_history_publication()
        if self.view_mode == 1: self.select_commit(self.history.currentItem())

    def history_publication_context(self):
        if not self.repo or self.state is None: return None
        state = self.state
        record = self._active_rewrite or {}
        return (repository_scope(self.repo), getattr(state, 'head_ref', '') or f'refs/heads/{state.branch}',
                getattr(state, 'head_oid', ''), tuple(commit.oid for commit in state.commits),
                state.upstream, state.ahead, state.behind, tuple(state.remotes),
                tuple(record.get(key) for key in ('old_head', 'new_head', 'expected_remote_oid', 'remote_name', 'destination_ref')),
                self._approved_routes.get(repository_scope(self.repo)))

    def load_history_publication(self, force=False):
        if (self._close_pending or self.view_mode != 1 or self.state is None or not self.repo
                or not callable(getattr(self.backend, 'history_publication', None))):
            return
        context = self.history_publication_context()
        if self._history_publication_request == context and not force: return
        if (not force and self._history_publication_context == context
                and time.monotonic() - self._history_publication_updated < 15):
            return
        self._history_publication_serial += 1; serial = self._history_publication_serial
        self._history_publication_request = context
        self.apply_history_publication()
        path, backend, commits = self.repo, self.backend, tuple(self.state.commits)
        record = dict(self._active_rewrite) if self._active_rewrite else None
        approved = self._approved_routes.get(repository_scope(path))

        def current():
            return (not self._close_pending and serial == self._history_publication_serial
                    and context == self.history_publication_context())

        def read():
            plan = None
            if approved and not record:
                try:
                    plan = backend.resolve_push_plan(path, approved[5], approved[6])
                    if plan.source_ref != context[1]: plan = False
                except GitError:
                    plan = False
            provenance = self.rewrite_leases.get_provenance(record) if record else None
            return backend.history_publication(path, commits, record=record, plan=plan, provenance=provenance)

        def loaded(result):
            if not current(): return
            self._history_publication_request = None
            self._history_publication_context = context
            self._history_publication = result
            self._history_publication_updated = time.monotonic()
            self.apply_history_publication()

        def failed(error):
            if not current(): return
            self._history_publication_request = None
            self._history_publication_context = context
            self._history_publication = {}
            self._history_publication_updated = time.monotonic()
            self.apply_history_publication()

        self.hub.submit(read, loaded, failed, scope=repository_scope(path), key='history-publication',
                        label='Sprawdzanie publikacji commitów', background=True)

    def apply_history_publication(self):
        context = self.history_publication_context()
        annotations = self._history_publication if context == self._history_publication_context else {}
        blocked = self.history.blockSignals(True)
        try:
            for row in range(self.history.count()):
                item = self.history.item(row); commit = item.data(Qt.ItemDataRole.UserRole)
                if commit is None: continue
                data = annotations.get(commit.oid, {})
                status = data.get('status', 'unknown')
                if status == 'rewrite_pending':
                    kind = 'squash' if data.get('is_squash') else 'rewritten'
                elif status == 'unknown' and self._active_rewrite and commit.oid == self._active_rewrite.get('new_head'):
                    kind = 'rewritten'
                else:
                    kind = status if status in ('local', 'published') else 'unknown'
                annotation = dict(kind=kind, total=data.get('original_count'),
                                  published=data.get('published_count'), local=data.get('local_count'))
                if kind == 'squash':
                    detail = 'Squash · czeka na Force push.'
                    if (all(type(annotation[key]) is int and annotation[key] >= 0 for key in ('total', 'published', 'local'))
                            and annotation['total'] >= 2 and annotation['published'] + annotation['local'] == annotation['total']):
                        detail += (f"\nPołączono {annotation['total']} oryginalnych commitów: "
                                   f"{annotation['published']} opublikowanych i {annotation['local']} lokalnych."
                                   '\nPodział według stanu celu wysyłania zapisanego przed squashem.')
                    else:
                        detail += '\nNie można potwierdzić liczby oryginalnych commitów i ich publikacji.'
                elif kind == 'rewritten':
                    detail = 'Commit po przepisaniu historii · czeka na Force push.'
                elif kind == 'published':
                    detail = 'Na serwerze · według ostatnio znanego stanu celu wysyłania.'
                elif kind == 'local':
                    detail = 'Lokalny · nie występuje w ostatnio znanej historii celu wysyłania.'
                else:
                    detail = 'Status publikacji nieustalony.'
                text = f'{commit.subject}\n{commit.author} · {self.commit_date_text(commit.date)}\n{commit.oid}\n\n{detail}'
                item.setData(Qt.ItemDataRole.UserRole+1, annotation)
                item.setData(Qt.ItemDataRole.AccessibleTextRole,
                             f'{commit.subject}. {commit.author}. {self.commit_date_text(commit.date)}. {detail}')
                item.setToolTip(text)
        finally:
            self.history.blockSignals(blocked)
        self.history.viewport().update()

    def can_squash(self):
        return bool(self.repo and self.backend and self.state and len(self.history.selectedItems()) >= 2
                    and not self.mutating and not self.opening and not self._close_pending)

    def _history_single_commit(self):
        selected = self.history.selectedItems()
        return selected[0].data(Qt.ItemDataRole.UserRole) if len(selected) == 1 else None

    def _history_action_ready(self):
        return bool(self.repo and self.backend and self.state and not self.mutating
                    and not self.opening and not self._close_pending)

    def can_undo(self):
        commit = self._history_single_commit()
        if (not self._history_action_ready() or commit is None or self.state.operation
                or commit.oid != self.state.head_oid or not self.state.head_ref or self._active_rewrite):
            return False
        publication = (self._history_publication if self._history_publication_context == self.history_publication_context() else {})
        return publication.get(commit.oid, {}).get('status') != 'published'

    def can_revert(self):
        return bool(self._history_action_ready() and self._history_single_commit() is not None
                    and not self.state.operation and self.state.head_ref)

    def can_reword(self):
        commit = self._history_single_commit()
        return bool(self._history_action_ready() and commit is not None
                    and commit.oid == self.state.head_oid and self.state.head_ref
                    and not self.state.operation and not any(change.conflicted for change in self.state.changes))

    def can_abort_revert(self):
        return bool(self._history_action_ready() and self.state.operation == 'revert')

    def add_revert_recovery_action(self, menu):
        if self.state is not None and self.state.operation == 'revert':
            menu.addSeparator()
            action = menu.addAction('Anuluj trwający revert…', self.abort_revert_dialog)
            action.setEnabled(self.can_abort_revert())
            action.setToolTip('Przywróć stan sprzed rozpoczętego revertu. Zmiany rozwiązywania jego konfliktów zostaną wycofane.')

    def history_context_menu(self, point):
        if not self.repo or not self.history.itemAt(point): return
        menu = QMenu(self.history)
        menu.setToolTipsVisible(True)
        undo = menu.addAction('Undo · cofnij ostatni lokalny commit…', self.undo_dialog)
        undo.setEnabled(self.can_undo())
        undo.setToolTip('Zaznacz jeden, ostatni nieopublikowany commit. Jego zmiany pozostaną w plikach i indeksie. '
                        'Publikacja zostanie sprawdzona według ostatnio pobranego stanu serwera.')
        revert = menu.addAction('Revert · odwróć wybrany commit…', self.revert_dialog)
        revert.setEnabled(self.can_revert())
        revert.setToolTip('Zaznacz jeden commit. Powstanie nowy commit odwracający jego zmiany, z zachowaniem opublikowanej historii.')
        reword = menu.addAction('Zmień opis commita…', self.reword_dialog)
        reword.setEnabled(self.can_reword())
        reword.setToolTip('Zmień tytuł i opis ostatniego commita bieżącej gałęzi. '
                          'Pliki i ich zaznaczenie pozostaną bez zmian. Wysłany commit będzie wymagał Force push.')
        menu.addSeparator()
        count = len(self.history.selectedItems())
        action = menu.addAction(f'Squash…  ({count} → 1)', self.squash_dialog)
        action.setEnabled(self.can_squash())
        if count < 2:
            menu.addAction('Zaznacz co najmniej 2 commity przez Shift+klik').setEnabled(False)
        self.add_revert_recovery_action(menu)
        menu.exec(self.history.viewport().mapToGlobal(point))

    def undo_dialog(self):
        if not self.can_undo(): return
        return self._history_change_dialog('undo', self.repo, self._history_single_commit().oid)

    def revert_dialog(self):
        if not self.can_revert(): return
        return self._history_change_dialog('revert', self.repo, self._history_single_commit().oid)

    def abort_revert_dialog(self):
        if not self.can_abort_revert(): return
        return self._history_change_dialog('abort_revert', self.repo)

    def _history_change_dialog(self, action, path, oid=None):
        backend = self.backend
        titles = {'undo': 'Undo · cofnij ostatni lokalny commit',
                  'revert': 'Revert · odwróć wybrany commit', 'abort_revert': 'Anuluj trwający revert'}
        buttons = {'undo': 'Cofnij commit, zachowaj zmiany', 'revert': 'Utwórz commit odwrotny',
                   'abort_revert': 'Anuluj rozpoczęty revert'}
        labels = {'undo': 'Cofanie lokalnego commita…', 'revert': 'Odwracanie commita…',
                  'abort_revert': 'Anulowanie revertu…'}
        dialog = OperationForm(self, titles[action], f'Repozytorium: {path}', action=buttons[action])
        dialog.resize(640, 430)
        dialog.history_action = action
        dialog.history_phase = 'checking'
        preview = QPlainTextEdit(); preview.setReadOnly(True)
        preview.setAccessibleName('Commit objęty operacją'); preview.setMaximumHeight(110)
        dialog.layout().insertWidget(dialog.layout().indexOf(dialog.status), preview)
        recovery = QWidget(); layout = QHBoxLayout(recovery); layout.setContentsMargins(0, 0, 0, 0)
        retry = dialog.history_retry_button = ui_button('Sprawdź ponownie', lambda: start_review())
        changes = dialog.history_changes_button = ui_button('Pokaż zmiany', lambda: show_changes())
        abort = dialog.history_abort_button = ui_button('Anuluj rozpoczęty revert', lambda: abort_conflict())
        layout.addWidget(retry); layout.addWidget(changes); layout.addWidget(abort)
        dialog.layout().insertWidget(dialog.layout().indexOf(dialog.buttons), recovery)
        reviewed = {}

        def phase(value):
            dialog.history_phase = value
            recovery.setVisible(value in ('blocked', 'conflict'))
            retry.setVisible(value == 'blocked')
            changes.setVisible(value in ('blocked', 'conflict'))
            abort.setVisible(value == 'conflict')
            abort.setEnabled(dialog.token is None and not self._close_pending)
            dialog.submit_button.setVisible(value not in ('blocked', 'conflict'))
            dialog.submit_button.setEnabled(value == 'ready' and dialog.token is None)
            dialog.submit_button.setText(buttons[action])

        def show_changes():
            if dialog.token is not None or self._close_pending: return
            dialog.reject()
            if self.repo != path: self.open_repo(path)
            self.show_view(0)

        def abort_conflict():
            if dialog.token is not None or self._close_pending: return
            dialog.reject()
            # Explicit recovery targets the original repository even after navigation.
            self._history_change_dialog('abort_revert', path)

        def prepare():
            if action == 'undo':
                plan = backend.prepare_undo(path, oid)
                if self.rewrite_leases.active(backend, path, plan.source_ref, plan.head_oid):
                    raise GitError('Zmieniona historia czeka na Force push. Zakończ tę operację przed Undo.')
                return plan
            if action == 'revert': return backend.prepare_revert(path, oid)
            return backend.prepare_revert_abort(path)

        def ready(plan):
            if dialog not in self._dialogs: return
            reviewed.update(plan=plan, conflict=False)
            preview.setPlainText(f'{plan.commit.oid}\n{plan.commit.message.strip()}')
            text = f'Gałąź: {plan.source_ref.removeprefix("refs/heads/")}\n\n'
            if action == 'undo':
                text += ('Commit zniknie z gałęzi. Jego zmiany oraz wcześniejsze zmiany pozostaną w plikach i indeksie. '
                         'Zapiszemy lokalną kopię historii.\n\n' + plan.publication_notice)
                if not plan.target_oid: text += '\nGałąź wróci do stanu sprzed pierwszego commita.'
                elif len(plan.commit.parents) > 1: text += '\nMerge: gałąź zostanie cofnięta do pierwszego rodzica.'
            elif action == 'revert':
                text += ('Powstanie nowy commit odwracający wybraną zmianę. Istniejące commity pozostaną w historii. '
                         'W razie konfliktów będzie można je rozwiązać lub anulować revert.')
                if plan.mainline: text += '\n\nMerge: odwrócone zostaną zmiany względem pierwszego rodzica.'
            else:
                text += ('Przywrócimy stan sprzed rozpoczętego revertu. Zmiany wprowadzone podczas rozwiązywania '
                         'jego konfliktów zostaną wycofane.')
            dialog.set_busy(None); dialog.status.setText(text); phase('ready')

        def failed(error):
            if dialog not in self._dialogs: return
            dialog.failed(error)
            phase('conflict' if reviewed.get('conflict') else 'blocked')

        def start_review():
            if dialog.token is not None or self._close_pending: return
            reviewed.clear(); phase('checking')
            token = self.hub.submit(prepare, ready, failed, scope=repository_scope(path),
                                    key=f'history-action:{id(dialog)}', label='Sprawdzanie operacji historii')
            dialog.set_busy(token)

        def submit(unused):
            if dialog.token is not None or dialog.history_phase != 'ready' or not reviewed.get('plan'): return
            plan = reviewed['plan']
            def write():
                if action == 'undo' and self.rewrite_leases.active(backend, path, plan.source_ref, plan.head_oid):
                    raise GitError('Zmieniona historia czeka na Force push. Zakończ tę operację przed Undo.')
                return getattr(backend, action)(path, plan)
            def done(result):
                if action == 'revert' and result.conflicted:
                    reviewed['conflict'] = True
                    # Use the coordinator's failure path while retaining abort context.
                    raise GitError(result.message)
                if action in ('undo', 'revert'):
                    if result.new_head:
                        self._history_selection_after_write = (repository_scope(path), result.new_head)
                    if action == 'undo' and path == self.repo: self.show_view(0)
                dialog.succeeded()
            phase('writing')
            token = self.mutate(labels[action], write, done, path=path, failure=failed)
            dialog.set_busy(token)
        dialog.submitted.connect(submit)
        phase('checking'); self.keep_dialog(dialog); start_review()
        return dialog

    def reword_dialog(self):
        if not self.can_reword(): return
        path, backend, oid = self.repo, self.backend, self._history_single_commit().oid
        dialog = OperationForm(self, 'Zmień opis commita',
            'Edytuj tytuł i opis ostatniego commita. Zawartość commita, pliki i ich zaznaczenie pozostaną bez zmian.',
            fields=(('Tytuł', '', 'Tytuł commita'),), action='Zapisz opis')
        dialog.resize(640, 540)
        title = dialog.reword_title = dialog.fields[0]
        body = dialog.reword_body = QPlainTextEdit()
        body.setAccessibleName('Opis commita'); body.setPlaceholderText('Dodatkowy opis (opcjonalnie)')
        body.setMinimumHeight(130)
        layout = dialog.layout(); position = layout.indexOf(dialog.status)
        layout.insertWidget(position, ui_label('Opis')); layout.insertWidget(position + 1, body, 1)
        retry = dialog.reword_retry_button = ui_button('Sprawdź ponownie', lambda: start_review())
        layout.insertWidget(layout.indexOf(dialog.buttons), retry)
        dialog.reword_phase = 'checking'
        reviewed = {}; initialized = False; initial_message = ''

        def message():
            subject, description = title.text().strip(), body.toPlainText().strip()
            return subject + ('\n\n' + description if description else '')

        def update_controls():
            idle = dialog.token is None and not self._close_pending
            editing = idle and dialog.reword_phase in ('ready', 'blocked')
            title.setEnabled(editing); body.setEnabled(editing)
            retry.setVisible(dialog.reword_phase == 'blocked'); retry.setEnabled(idle)
            dialog.submit_button.setEnabled(idle and dialog.reword_phase == 'ready'
                and bool(reviewed) and bool(title.text().strip()) and message() != initial_message)

        def prepare():
            plan = backend.prepare_reword(path, oid)
            publication = self.squash_publication(plan, backend=backend)
            record = publication[1]
            provenance = None
            if record is not None and record.get('new_head'):
                provenance = {'version': 1, 'complete': False, 'entries': []}
                with contextlib.suppress(Exception):
                    provenance = backend.squash_provenance(path, record,
                        provenance=self.rewrite_leases.get_provenance(record))
            return plan, publication, provenance

        def ready(result):
            nonlocal initialized, initial_message
            if dialog not in self._dialogs: return
            plan, (push, record, notice), provenance = result
            reviewed.update(plan=plan, push=push, record=record, provenance=provenance)
            if not initialized:
                subject, _, description = plan.commit.message.partition('\n')
                title.setText(subject); body.setPlainText(description.strip('\n'))
                initial_message = message(); initialized = True
            text = f'Commit: {plan.head_oid[:8]} · {plan.source_ref.removeprefix("refs/heads/")}\n'
            text += 'Zapis nada commitowi nowy identyfikator. Zachowamy lokalną kopię poprzedniej wersji.\n'
            if plan.signed: text += 'Podpis tego commita zostanie usunięty.\n'
            dialog.set_busy(None); dialog.status.setText(text + '\n' + notice)
            dialog.reword_phase = 'ready'; update_controls(); title.setFocus()

        def failed(error):
            if dialog not in self._dialogs: return
            reviewed.clear(); dialog.failed(error)
            dialog.reword_phase = 'blocked'; update_controls()

        def start_review():
            if dialog.token is not None or self._close_pending: return
            reviewed.clear(); dialog.reword_phase = 'checking'; update_controls()
            token = self.hub.submit(prepare, ready, failed, scope=repository_scope(path),
                key=f'reword-plan:{id(dialog)}', label='Sprawdzanie opisu commita')
            dialog.set_busy(token); update_controls()

        def submit(unused):
            if (dialog.token is not None or dialog.reword_phase != 'ready' or not reviewed
                    or self._close_pending or not title.text().strip() or message() == initial_message): return
            plan, push, record = reviewed['plan'], reviewed['push'], reviewed['record']
            provenance, text = reviewed['provenance'], message()
            def before_update(result):
                prior = record if record is not None and record.get('new_head') else None
                if self.rewrite_leases.active(backend, path, plan.source_ref, plan.head_oid) != prior:
                    raise GitError('Stan wysyłania historii zmienił się. Sprawdź commit ponownie.')
                if record is None: return
                if backend.resolve_push_plan(path, push.remote_override, push.destination_override) != push:
                    raise GitError('Cel wysyłania zmienił się. Sprawdź commit ponownie.')
                saved = dict(record, old_head=result.old_head, new_head=result.new_head)
                self.rewrite_leases.save(saved, previous=prior)
                with contextlib.suppress(Exception):
                    self.rewrite_leases.save_provenance(saved, backend.rewrite_reword_provenance(result, provenance))
            def done(result):
                if path == self.repo:
                    self.history_filter.blockSignals(True); self.history_filter.clear(); self.history_filter.blockSignals(False)
                self._history_selection_after_write = (repository_scope(path), result.new_head)
                dialog.succeeded()
                if self._repository_notice_relevant(path):
                    self._repository_status_key = repository_ui_key(path)
                    self.status.setText('Zmieniono opis commita.')
            dialog.reword_phase = 'writing'; update_controls()
            token = self.mutate('Zmiana opisu commita…', lambda: backend.reword(path, plan, text, before_update),
                                done, path=path, failure=failed)
            dialog.set_busy(token); update_controls()

        title.textChanged.connect(update_controls); body.textChanged.connect(update_controls)
        dialog.submitted.connect(submit)
        shortcut = QAction(dialog)
        shortcut.setShortcuts([QKeySequence('Ctrl+Return'), QKeySequence('Ctrl+Enter')])
        shortcut.setShortcutContext(Qt.ShortcutContext.WidgetWithChildrenShortcut); shortcut.setAutoRepeat(False)
        shortcut.triggered.connect(lambda: submit(None) if dialog.submit_button.isEnabled() else None)
        dialog.addAction(shortcut)
        update_controls(); self.keep_dialog(dialog); start_review()
        return dialog

    def squash_publication(self, plan, backend=None):
        backend = backend or self.backend; path = plan.repo
        prior = self.rewrite_leases.active(backend, path, plan.source_ref, plan.head_oid)
        approved = self._approved_routes.get(repository_scope(path))
        remote = prior['remote_name'] if prior else approved[5] if approved else None
        destination = prior['destination_ref'] if prior else approved[6] if approved else None
        try:
            push = backend.resolve_push_plan(path, remote, destination)
            if push.head_oid != plan.head_oid or push.source_ref != plan.source_ref:
                raise GitError('Gałąź zmieniła się podczas sprawdzania. Sprawdź historię ponownie.')
            if prior:
                if not self.rewrite_leases.matches(prior, push):
                    raise GitError('Zmieniono cel wysyłania po poprzedniej zmianie historii. Przywróć jego konfigurację przed kolejną zmianą.')
                return push, prior, 'Historia czeka już na Force push. Zachowamy pierwotnie zapisany stan serwera.'
            tracking = backend.push_tracking_state(path, push)
        except GitError as exc:
            if prior: raise
            return None, None, 'Zmiana zostanie zapisana lokalnie. Nie potwierdzono celu wysyłania: ' + str(exc)
        if not tracking['oid']:
            return push, None, 'Zmiana obejmie lokalną historię. Nie można potwierdzić publikacji. ' + tracking['reason']
        if tracking['requires_force']:
            return push, None, 'Gałąź już różni się od historii zdalnej. Ta zmiana nie odblokuje nadpisania tej rozbieżności.'
        if not self.rewrite_leases.ancestor(backend, path, plan.selected[0].oid, tracking['oid']):
            return push, None, 'Wybrana historia jest lokalna. Po zapisaniu zmiany wystarczy zwykły Push.'
        record = dict(repo=repository_scope(path), source_ref=plan.source_ref, old_head=plan.head_oid,
                      expected_remote_oid=tracking['oid'], remote_name=push.remote_name,
                      destination_ref=push.destination_ref, push_url_hashes=self.rewrite_leases.route_fingerprints(push))
        return push, record, ('Zmieniasz opublikowaną historię. Po zapisaniu zmiany przycisk zmieni się na Force push. '
                             'Wysyłanie zatrzyma się, jeśli serwer zmieni się od zapisanego stanu.')

    def squash_dialog(self):
        if not self.can_squash(): return
        path = self.repo
        selected = [item.data(Qt.ItemDataRole.UserRole) for item in
                    sorted(self.history.selectedItems(), key=self.history.row)]
        oids = tuple(commit.oid for commit in selected)
        if len(oids) < 2: return
        dialog = OperationForm(self, f'Squash · {len(oids)} commitów → 1',
            'Sprawdź zakres i wpisz opis połączonego commita. Zawartość plików pozostanie taka sama.', action='Squash')
        dialog.resize(630, 620)
        commits = QPlainTextEdit(); commits.setReadOnly(True); commits.setMaximumHeight(100)
        commits.setAccessibleName('Commity łączone w jeden')
        commits.setPlainText('\n'.join(f'{commit.oid[:8]}  {commit.subject}' for commit in reversed(selected)))
        message = QPlainTextEdit(); message.setAccessibleName('Opis połączonego commita'); message.setMinimumHeight(130)
        dialog.squash_message = message
        dialog.squash_state_label = ui_label('', wrap=True)
        dialog.squash_state_label.setAccessibleName('Stan operacji squash')
        editor = QWidget(); editor_layout = QVBoxLayout(editor); editor_layout.setContentsMargins(0, 0, 0, 0)
        editor_layout.addWidget(ui_label('Opis połączonego commita', 'eyebrow')); editor_layout.addWidget(message, 1)
        layout = dialog.layout(); layout.removeWidget(dialog.status)
        layout.insertWidget(2, dialog.squash_state_label); layout.insertWidget(3, dialog.status)
        layout.insertWidget(4, commits); layout.insertWidget(5, editor, 1)
        recovery = QWidget(); recovery_layout = QHBoxLayout(recovery)
        recovery_layout.setContentsMargins(0, 0, 0, 0)
        dialog.squash_show_changes = ui_button('Pokaż zmiany', lambda: show_changes(), 'file')
        dialog.squash_retry = ui_button('Sprawdź ponownie', lambda: start_review(), 'refresh')
        recovery_layout.addWidget(dialog.squash_show_changes); recovery_layout.addWidget(dialog.squash_retry)
        layout.insertWidget(6, recovery)
        reviewed = {}
        initialized = False

        def set_phase(phase):
            dialog.squash_phase = phase
            titles = {'checking': 'Sprawdzanie przed squashem…', 'ready': 'Gotowe do połączenia',
                      'writing': 'Łączenie commitów…', 'blocked': 'Squash nie został rozpoczęty',
                      'failed': 'Nie udało się zakończyć squashu'}
            error = phase in ('blocked', 'failed')
            color = '#ffb4a9' if error else '#c7b8f4'
            dialog.squash_state_label.setText(titles[phase])
            dialog.squash_state_label.setStyleSheet(f'color: {color}; font-size: 16px; font-weight: 600;')
            recovery.setVisible(error)
            dialog.squash_show_changes.setEnabled(path == self.repo and not self._close_pending)
            editor.setVisible(phase in ('ready', 'writing'))
            message.setEnabled(phase == 'ready')
            dialog.submit_button.setVisible(not error)
            dialog.submit_button.setText('Łączenie…' if phase == 'writing' else 'Squash')
            dialog.submit_button.setEnabled(phase == 'ready' and bool(message.toPlainText().strip()))
            dialog.buttons.button(QDialogButtonBox.StandardButton.Cancel).setText('Zamknij' if error else 'Anuluj')

        def show_changes():
            if dialog.token is not None or path != self.repo or self._close_pending: return
            dialog.reject()
            self.file_filter.clear()
            self.show_view(0)
            self.refresh()

        def prepare():
            plan = self.backend.prepare_squash(path, oids)
            publication = self.squash_publication(plan)
            record = publication[1]
            provenance = None
            if record and record.get('new_head'):
                provenance = {'version': 1, 'complete': False, 'entries': []}
                # Annotation failures cannot prevent a valid history rewrite.
                with contextlib.suppress(Exception):
                    provenance = self.backend.squash_provenance(path, record,
                        provenance=self.rewrite_leases.get_provenance(record))
            return plan, publication, provenance

        def ready(result):
            nonlocal initialized
            if dialog not in self._dialogs: return
            plan, (push, record, notice), provenance = result
            reviewed.update(plan=plan, push=push, record=record, provenance=provenance)
            commits.setPlainText('\n'.join(f'{item.oid[:8]}  {item.message.splitlines()[0] if item.message else "(bez opisu)"}' for item in plan.selected))
            if not initialized:
                message.setPlainText(plan.default_message)
                initialized = True
            detail = f'Gałąź: {plan.source_ref.removeprefix("refs/heads/")}\n'
            if plan.descendants: detail += f'Nowsze commity ({len(plan.descendants)}) zostaną zachowane z nowymi hashami.\n'
            if plan.signed_oids: detail += f'Podpisy {len(plan.signed_oids)} przepisywanych commitów zostaną usunięte.\n'
            detail += 'Nowe commity nie będą podpisane. Poprzednia historia zostanie zachowana jako kopia lokalna.\n\n' + notice
            dialog.set_busy(None); dialog.status.setText(detail)
            set_phase('ready'); message.setFocus()

        def failed(error):
            if dialog in self._dialogs:
                phase = 'failed' if dialog.squash_phase == 'writing' else 'blocked'
                reviewed.clear()
                dialog.failed(error); set_phase(phase)
                dialog.resize(630, 420)
                dialog.squash_retry.setFocus()

        def start_review():
            if dialog.token is not None or self._close_pending: return
            reviewed.clear(); set_phase('checking')
            token = self.hub.submit(prepare, ready, failed, scope=repository_scope(path),
                                    key=f'squash-plan:{id(dialog)}', label='Sprawdzanie zakresu commitów')
            dialog.set_busy(token)

        def submit(unused):
            if dialog.token is not None or not reviewed or not message.toPlainText().strip(): return
            plan, push, record = reviewed['plan'], reviewed['push'], reviewed['record']
            text = message.toPlainText().strip()
            def before_update(result):
                if record is None: return
                if self.backend.resolve_push_plan(path, push.remote_override, push.destination_override) != push:
                    raise GitError('Zmienił się cel wysyłania. Otwórz ponownie squash.')
                saved = dict(record, old_head=result.old_head, new_head=result.new_head)
                self.rewrite_leases.save(saved, previous=record if record.get('new_head') else None)
                with contextlib.suppress(Exception):
                    provenance = self.backend.rewrite_squash_provenance(plan, result, reviewed['provenance'])
                    self.rewrite_leases.save_provenance(saved, provenance)
            def done(result):
                if path == self.repo:
                    self.history_filter.blockSignals(True); self.history_filter.clear(); self.history_filter.blockSignals(False)
                self._history_selection_after_write = (repository_scope(path), result.squash_oid)
                dialog.succeeded()
                self.status.setText(f'Połączono {len(plan.selected)} commitów. Kopia historii: {result.backup_ref}')
            set_phase('writing')
            token = self.mutate('Łączenie commitów…', lambda: self.backend.squash(path, plan, text, before_update),
                                done, path=path, failure=failed)
            dialog.set_busy(token); message.setEnabled(token is None)
        message.textChanged.connect(lambda: dialog.submit_button.setEnabled(dialog.token is None and bool(reviewed) and bool(message.toPlainText().strip())))
        dialog.submitted.connect(submit)
        dialog.submit_button.setToolTip('Połącz zaznaczone commity w jeden · Ctrl+Enter')
        shortcut = QAction(dialog)
        shortcut.setShortcuts([QKeySequence('Ctrl+Return'), QKeySequence('Ctrl+Enter')])
        shortcut.setShortcutContext(Qt.ShortcutContext.WidgetWithChildrenShortcut)
        shortcut.setAutoRepeat(False)
        def submit_shortcut():
            if (dialog.token is None and reviewed and message.toPlainText().strip()
                    and dialog.submit_button.isEnabled()):
                dialog.submit_button.click()
        shortcut.triggered.connect(submit_shortcut); dialog.addAction(shortcut)
        set_phase('checking')
        self.keep_dialog(dialog)
        start_review()
        return dialog

    def clear_diff(self):
        self.hub.cancel_reads(key='preview')
        if self.view_mode == 1 or not self.repo: self.reset_commit_files()
        self._commit_details = None; self.diff_meta.hide(); self.commit_details_button.hide()
        self.diff_serial += 1; self.diff_pages.setCurrentIndex(0); self.diff_title.setText('Podgląd zmian'); self.diff.set_diff('')

    def select_file(self, item, previous=None, quiet=False):
        self.update_enabled()
        if not item or not self.repo: self.clear_diff(); return
        change = item.data(Qt.ItemDataRole.UserRole); path = self.repo; backend = self.backend
        self._commit_details = None; self.diff_meta.hide(); self.commit_details_button.hide()
        self.diff_title.setText(change.path); self.diff_title.setToolTip(change.path)
        self.diff_badge.setText('KONFLIKT' if change.conflicted else 'CZĘŚĆ ZMIAN' if change.staged and change.unstaged else
                               'ZAZNACZONY' if change.staged else 'NIEZAZNACZONY')
        self.diff_badge.setToolTip('')
        def preview():
            if change.staged and change.unstaged:
                selected = backend.diff(path, change.path, staged=True, original_path=change.original_path)
                remaining = backend.diff(path, change.path, staged=False, original_path=change.original_path)
                return DiffPreview('=== ZAZNACZONE DO COMMITA ===\n\n' + selected +
                                   '\n\n=== POZOSTAŁE ZMIANY — NIE TRAFIĄ DO COMMITA ===\n\n' + remaining,
                                   getattr(selected, 'truncated', False) or getattr(remaining, 'truncated', False))
            return backend.diff(path, change.path, staged=change.staged, original_path=change.original_path)
        self.load_diff(preview, quiet=quiet)

    def select_commit(self, item, previous=None):
        selected = sorted(self.history.selectedItems(), key=self.history.row)
        if not selected or not self.repo: self.clear_diff(); return
        commits = [row.data(Qt.ItemDataRole.UserRole) for row in selected]
        path = self.repo
        selection = (repository_scope(path), tuple(commit.oid for commit in commits))
        if (getattr(self, '_history_preview_selection', None) == selection
                and getattr(self, '_history_preview_serial', None) == self.diff_serial
                and getattr(self.diff, 'preview_state', None) != 'error' and not self._history_files_error):
            return
        self._commit_details = None
        if len(commits) > 1:
            self.commit_details_button.hide()
            self.diff_meta.hide()
            title = f'{len(commits)} commitów · łączne zmiany'
            self.diff_title.setText(title); self.diff_title.setToolTip('Zmiany od stanu sprzed najstarszego do stanu po najnowszym zaznaczonym commicie.')
            self.diff_badge.setText('ŁĄCZNY DIFF')
            self.diff_badge.setToolTip(f'Najstarszy commit: {commits[-1].oid}\nNajnowszy commit: {commits[0].oid}')
            positions = {commit.oid: index for index, commit in enumerate(self.state.commits)} if self.state else {}
            indexes = sorted(positions.get(commit.oid, -1) for commit in commits)
            if -1 in indexes or indexes != list(range(indexes[0], indexes[-1] + 1)):
                self.reset_commit_files('Wybierz ciągły zakres commitów')
                self.hub.cancel_reads(key='preview'); self.diff_serial += 1
                self.diff_pages.setCurrentIndex(1)
                self.diff.set_diff('Wybierz ciągły zakres commitów bez przerw. Użyj Shift lub Ctrl+Shift, aby zaznaczyć cały zakres.', state='empty')
            else:
                self.load_commit_files(path, selection[1])
                self.load_selected_commit_patch(path, selection[1])
            self._history_preview_selection, self._history_preview_serial = selection, self.diff_serial
            return
        commit = commits[0]
        self.diff_meta.setText(f'{commit.author}  ·  {self.commit_date_text(commit.date, relative=True)}')
        self.diff_meta.setToolTip(f'{commit.author}\n{commit.date}'); self.diff_meta.show()
        self.commit_details_button.setEnabled(False); self.commit_details_button.show()
        self.diff_title.setText(commit.subject); self.diff_title.setToolTip(commit.subject); self.diff_badge.setText(commit.short_oid)
        self.diff_badge.setToolTip(commit.oid)
        self.load_commit_files(path, selection[1])
        self.load_selected_commit_patch(path, selection[1])
        self._history_preview_selection, self._history_preview_serial = selection, self.diff_serial

    def reset_commit_files(self, caption='Pliki w commicie'):
        self._history_files_serial += 1; self._history_files_context = None; self._history_files_error = False
        self.hub.cancel_reads(key='history-files')
        if not hasattr(self, 'commit_files_list'): return
        self.commit_files_list.blockSignals(True); self.commit_files_list.clear(); self.commit_files_list.blockSignals(False)
        self.commit_files_list.setEnabled(False); self.commit_files_caption.setText(caption)

    def load_commit_files(self, path, oids):
        context = (repository_scope(path), tuple(oids))
        if self._history_files_context == context and not self._history_files_error: return
        self.reset_commit_files('Wczytywanie listy plików…')
        self._history_files_context = context; serial = self._history_files_serial
        def current():
            return (serial == self._history_files_serial and self._history_files_context == context
                    and repository_scope(self.repo) == context[0])
        def loaded(files):
            if not current(): return
            statuses = {'A': 'Dodany', 'D': 'Usunięty', 'M': 'Zmodyfikowany', 'R': 'Zmieniona nazwa',
                        'C': 'Skopiowany', 'T': 'Zmieniony typ', 'U': 'Konflikt', 'X': 'Zmiana'}
            self.commit_files_list.blockSignals(True); self.commit_files_list.clear()
            additions = sum(file.additions or 0 for file in files); deletions = sum(file.deletions or 0 for file in files)
            all_files = QListWidgetItem('Wszystkie pliki')
            binary_count = sum(file.binary for file in files)
            all_files.setData(Qt.ItemDataRole.UserRole + 1,
                              (f'Binarne: {binary_count}' if binary_count else '', f'+{additions}', f'−{deletions}'))
            all_files.setToolTip(f'Łącznie: {len(files)} plików · +{additions} / −{deletions} linii tekstowych')
            self.commit_files_list.addItem(all_files)
            for file in files:
                label = f'{file.original_path} → {file.path}' if file.original_path else file.path
                status = statuses.get(file.status, file.status)
                add, delete = ('—', '—') if file.binary else (f'+{file.additions}', f'−{file.deletions}')
                item = QListWidgetItem(label); item.setData(Qt.ItemDataRole.UserRole, file)
                item.setData(Qt.ItemDataRole.UserRole + 1, (status + (' · binarny' if file.binary else ''), add, delete))
                description = f'{label}\n{status}\n' + ('Plik binarny — bez liczników linii.' if file.binary else f'Dodane linie: {file.additions}\nUsunięte linie: {file.deletions}')
                item.setToolTip(description); item.setData(Qt.ItemDataRole.AccessibleTextRole, description)
                self.commit_files_list.addItem(item)
            self.commit_files_list.setCurrentRow(0); self.commit_files_list.blockSignals(False)
            self.commit_files_list.setEnabled(bool(files)); self._history_files_error = False
            self.commit_files_caption.setText(f'Pliki · {len(files)}' if files else 'Brak zmian plików w wybranym zakresie')
        def failed(error):
            if not current(): return
            self._history_files_error = True; self.commit_files_caption.setText('Nie wczytano plików · F5, aby ponowić')
            self.commit_files_caption.setToolTip(str(error))
        self.commit_files_caption.setToolTip('')
        self.hub.submit(lambda: self.backend.commit_files(path, oids), loaded, failed,
                        scope=repository_scope(path), key='history-files')

    def load_selected_commit_patch(self, path, oids):
        item = self.commit_files_list.currentItem()
        file = item.data(Qt.ItemDataRole.UserRole) if item and self._history_files_context == (repository_scope(path), tuple(oids)) else None
        backend = self.backend
        def preview():
            if file is not None: return backend.commit_file_diff(path, oids, file)
            if len(oids) == 1: return backend.commit_diff(path, oids[0])
            content = backend.commit_range_diff(path, oids)
            return content if content else RangePreview('Wybrane commity nie zmieniają końcowego stanu plików. Ich zmiany wzajemnie się znoszą.')
        self.load_diff(preview)

    def select_commit_file(self, item, previous=None):
        context = self._history_files_context
        if not item or self.view_mode != 1 or context is None or context[0] != repository_scope(self.repo): return
        self.load_selected_commit_patch(self.repo, context[1])
        self._history_preview_selection = context; self._history_preview_serial = self.diff_serial

    @staticmethod
    def commit_date_text(value, relative=False):
        return commit_date_text(value, relative=relative)

    def update_history_dates(self):
        # Reuse the UI's periodic tick so calendar labels roll over at midnight
        # without rebuilding the selection or requesting the diff again.
        if self.view_mode != 1 or self._close_pending: return
        self.history.viewport().update()
        selected = self.history.selectedItems()
        if len(selected) != 1: return
        commit = selected[0].data(Qt.ItemDataRole.UserRole)
        if commit is None: return
        details = self._commit_details
        if details is not None and details.oid == commit.oid:
            author, date = details.author, details.author_date
            context = '  ·  Merge: względem pierwszego rodzica' if len(details.parents) > 1 else ''
        else:
            author, date, context = commit.author, commit.date, ''
        self.diff_meta.setText(f'{author}  ·  {self.commit_date_text(date, relative=True)}{context}')

    def show_commit_details(self):
        details = self._commit_details
        if details is None: return
        dialog = QDialog(self); dialog.setWindowTitle('Informacje o commicie'); dialog.resize(720, 540)
        layout = QVBoxLayout(dialog); layout.setContentsMargins(24, 24, 24, 24); layout.setSpacing(12)
        layout.addWidget(ui_label('Opis commita', 'eyebrow'))
        message = QPlainTextEdit(); message.setReadOnly(True); message.setPlainText(details.message)
        message.setAccessibleName('Pełny opis commita'); layout.addWidget(message, 1)
        fields = QGridLayout(); fields.setHorizontalSpacing(16); fields.setVerticalSpacing(6)
        values = [('Hash', details.oid), ('Autor', f'{details.author} <{details.author_email}>'),
                  ('Data autora', self.commit_date_text(details.author_date)),
                  ('Zatwierdzający', f'{details.committer} <{details.committer_email}>'),
                  ('Data commita', self.commit_date_text(details.commit_date)),
                  ('Rodzice', ', '.join(details.parents) or 'Pierwszy commit')]
        for row, (label, value) in enumerate(values):
            fields.addWidget(ui_label(label, 'muted'), row, 0)
            field = QLineEdit(value); field.setReadOnly(True); field.setAccessibleName(label)
            field.setStyleSheet('padding: 5px 8px;'); fields.addWidget(field, row, 1)
        fields.setColumnStretch(1, 1); layout.addLayout(fields)
        actions = QHBoxLayout()
        actions.addWidget(ui_button('Kopiuj hash', lambda: QApplication.clipboard().setText(details.oid)))
        actions.addStretch(); actions.addWidget(ui_button('Gotowe', dialog.accept, kind='primary'))
        layout.addLayout(actions); self.keep_dialog(dialog)

    def load_diff(self, function, quiet=False):
        self.diff_serial += 1; serial = self.diff_serial
        self.diff_pages.setCurrentIndex(1)
        if not quiet: self.diff.set_diff('', state='loading')
        def loaded(content):
            if serial == self.diff_serial:
                if isinstance(content, CommitPreview):
                    self._commit_details = details = content.details
                    context = '  ·  Merge: względem pierwszego rodzica' if len(details.parents) > 1 else ''
                    self.diff_meta.setText(f'{details.author}  ·  {self.commit_date_text(details.author_date, relative=True)}{context}')
                    self.diff_meta.setToolTip(f'{details.author} <{details.author_email}>\n{details.author_date}{context}')
                    self.commit_details_button.setEnabled(True)
                    if not content:
                        content = CommitPreview('Ten commit nie zmienia plików względem pierwszego rodzica.'
                                                if len(details.parents) > 1 else 'Ten commit nie zmienia plików.', details)
                else:
                    content = content or 'Brak różnic tekstowych. Plik może zawierać wyłącznie zmianę uprawnień lub metadanych.'
                if content != getattr(self.diff, 'source_content', ''):
                    scroll = self.diff.verticalScrollBar().value()
                    self.diff.set_diff(content)
                    if quiet: self.diff.verticalScrollBar().setValue(scroll)
        def failed(error):
            if serial == self.diff_serial: self.diff.set_diff(error, state='error')
        self.hub.submit(function, loaded, failed, scope=repository_scope(self.repo), key='preview', background=quiet)

    def mutate(self, label, function, success=None, *, path=None, failure=None, refresh_after=True, report_progress=False, key=''):
        path = self.repo if path is None else path
        scope = repository_scope(path)
        # Closing rejects new actions, but choices accepted during a running
        # selection batch still need their serialized follow-up index write.
        selection_drain = (key == 'file-selection:' + scope
                           and scope in self._selection_requests and scope in self._pending_selections)
        if self._close_pending and not selection_drain:
            if failure: failure('Aplikacja kończy bieżące operacje przed zamknięciem.')
            return None
        if scope in self._pending_selections and key != 'file-selection:' + scope:
            error = 'Poczekaj na zapisanie wyboru plików.'
            if failure: failure(error)
            else: self.show_error(error)
            return None
        if path == self.repo:
            self.refresh_serial += 1
            self.refreshing = False
            self.diff_serial += 1
            self.hub.cancel_reads(key=f'snapshot:{scope}')
            self.hub.cancel_reads(key='preview')
        def done(result):
            self.mutating = any(job.kind == 'write' and job.scope == repository_scope(self.repo)
                                for job in self.hub.jobs.values())
            if self._repository_notice_relevant(path):
                self._repository_status_key = repository_ui_key(path)
                self.status.setText(f'{label} Gotowe.')
            if success: success(result)
            if path == self.repo and refresh_after: self.refresh()
            self.update_enabled()
        def failed(error):
            self.mutating = any(job.kind == 'write' and job.scope == repository_scope(self.repo)
                                for job in self.hub.jobs.values())
            self.update_enabled()
            if failure: failure(error)
            elif self._repository_notice_relevant(path): self._show_repository_error(path, f'{label}\n{error}')
            if path == self.repo: self.refresh()
        return self.hub.submit(function, done, failed, scope=scope, kind='write', key=key, label=label, report_progress=report_progress)

    def file_selection_ready(self):
        if not self.repo or not self.backend or self.state is None or self.opening or self._close_pending:
            return False
        scope = repository_scope(self.repo)
        writes = [job for job in self.hub.jobs.values() if job.kind == 'write' and job.scope == scope]
        return ((not self.mutating or bool(writes))
                and all(job.key == 'file-selection:' + scope for job in writes))

    def file_check_changed(self, item):
        change = item.data(Qt.ItemDataRole.UserRole)
        if change is None: return
        requested = item.checkState()
        expected = self.displayed_check_state(change)
        if requested == expected: return
        if not self.file_selection_ready():
            self.files.blockSignals(True); item.setCheckState(expected); self.files.blockSignals(False)
            return
        self.set_file_selection([change], requested == Qt.CheckState.Checked)

    def toggle_all_stage(self, checked):
        if not self.file_selection_ready():
            self.update_selection_summary(); return
        target = Qt.CheckState.Checked if checked else Qt.CheckState.Unchecked
        changes = [change for change in self.state.changes
                   if not change.conflicted and self.displayed_check_state(change) != target]
        if not changes:
            self.update_selection_summary(); return
        self.set_file_selection(changes, checked)

    def seen_new_file_paths(self, path):
        """Remember choices by repository and path, including an explicit uncheck."""
        scope = repository_scope(path)
        if scope not in self._seen_new_files:
            paths = []
            if self.persist:
                key = 'newFileSelection/' + auth_hashlib.sha256(scope.encode('utf-8')).hexdigest()
                try:
                    saved = json.loads(self.settings.value(key, '[]'))
                    if isinstance(saved, list):
                        paths = [value for value in saved if isinstance(value, str) and value and '\0' not in value]
                except (TypeError, ValueError):
                    pass
            self._seen_new_files[scope] = set(paths)
        return self._seen_new_files[scope]

    def remember_new_file_paths(self, path, paths):
        seen = self.seen_new_file_paths(path)
        previous = len(seen)
        seen.update(value for value in paths if value)
        if self.persist and len(seen) != previous:
            scope = repository_scope(path)
            key = 'newFileSelection/' + auth_hashlib.sha256(scope.encode('utf-8')).hexdigest()
            self.settings.setValue(key, json.dumps(sorted(seen), ensure_ascii=False))
            self.settings.sync()

    def auto_select_new_files(self, state):
        """Select a newly seen untracked file once, through the normal write queue."""
        if not self.repo or not self.backend or state is not self.state:
            return
        scope = repository_scope(self.repo)
        # A previously staged addition or rename may become untracked on uncheck.
        self.remember_new_file_paths(self.repo, [name for change in state.changes
            if (change.index_status, change.worktree_status) != ('?', '?')
            for name in (change.path, change.original_path) if name])
        if (self.opening or self._close_pending or self.refreshing or self.mutating
                or state.operation or any(change.conflicted for change in state.changes)
                or scope in self._pending_selections or scope in self._selection_needs_refresh
                or any(job.scope == scope and job.kind == 'write' for job in self.hub.jobs.values())):
            return
        seen = self.seen_new_file_paths(self.repo)
        changes = [change for change in state.changes
                   if (change.index_status, change.worktree_status) == ('?', '?')
                   and not change.original_path and not change.path.endswith('/') and change.path not in seen]
        if changes:
            self.set_file_selection(changes, True, automatic=True)

    def set_file_selection(self, changes, checked, *, automatic=False):
        """Keep the latest click visible while repository writes run serially."""
        if not changes or not self.file_selection_ready(): return
        path, backend = self.repo, self.backend
        scope = repository_scope(path)
        self.remember_new_file_paths(path, [name for change in changes
                                           for name in (change.path, change.original_path) if name])
        request = self._selection_requests.get(scope)
        if request is None:
            request = {'path': path, 'backend': backend, 'lock': threading.RLock(),
                       'todo': {}, 'versions': {}, 'serial': 0, 'submitted': False}
            self._selection_requests[scope] = request
        pending = self._pending_selections.setdefault(scope, {})
        with request['lock']:
            request['serial'] += 1
            for change in changes:
                request['versions'][change.path] = request['serial']
                request['todo'][change.path] = (request['serial'], change, bool(checked), automatic)
                pending[change.path] = Qt.CheckState.Checked if checked else Qt.CheckState.Unchecked
        self.repaint_file_selection(path)
        if not request['submitted']:
            self.submit_file_selection(scope, request)
        self.update_enabled()

    def repaint_file_selection(self, path):
        if path != self.repo: return
        self.files.blockSignals(True)
        for index in range(self.files.count()):
            item = self.files.item(index)
            change = item.data(Qt.ItemDataRole.UserRole)
            if change is not None:
                item.setCheckState(self.displayed_check_state(change))
        self.files.blockSignals(False)
        self.update_selection_summary()

    def submit_file_selection(self, scope, request):
        path, backend = request['path'], request['backend']
        request['submitted'] = True

        def write():
            # GUI clicks may replace todo while an earlier batch writes Git's
            # index. Only this short copy shares a lock with the GUI thread.
            with request['lock']:
                batch = dict(request['todo'])
                request['todo'].clear()
            automatic_paths = {name for name, (_, _, _, automatic) in batch.items() if automatic}
            allowed_automatic = set()
            if automatic_paths:
                # Recheck after queued reads finish: an external Git client may
                # have staged only part of a file or started a merge meanwhile.
                current = backend.snapshot(path)
                if not current.operation and not any(change.conflicted for change in current.changes):
                    allowed_automatic = {change.path for change in current.changes
                        if change.path in automatic_paths and not change.original_path
                        and (change.index_status, change.worktree_status) == ('?', '?')
                        and (Path(path, change.path).is_file() or Path(path, change.path).is_symlink())
                        and not Path(path, change.path).is_dir()}
            for checked, method in ((True, backend.stage), (False, backend.unstage)):
                selected = [change for _, change, wanted, automatic in batch.values()
                            if wanted == checked and (not automatic or change.path in allowed_automatic)]
                if selected:
                    method(path, selected)
            return batch, backend.changes(path)

        def confirmed(result):
            batch, changes = result
            pending = self._pending_selections.get(scope, {})
            with request['lock']:
                for name, (version, _, _, _) in batch.items():
                    if request['versions'].get(name) == version:
                        request['versions'].pop(name, None)
                        pending.pop(name, None)
                follow_up = bool(request['todo'])
            request['submitted'] = False
            if not pending:
                self._pending_selections.pop(scope, None)
                self._selection_requests.pop(scope, None)
            self._selection_needs_refresh.discard(scope)
            if path == self.repo and self.state is not None:
                self.state = dataclasses.replace(self.state, changes=changes)
                self._last_signature = None
                self.tabs.setTabText(0, f'Zmiany  ·  {len(changes)}')
                self.populate_files(quiet=True)
            if follow_up:
                self.submit_file_selection(scope, request)

        def failed(error):
            self._pending_selections.pop(scope, None)
            self._selection_requests.pop(scope, None)
            # Git may have written the index before its status read failed.
            # A failed follow-up refresh must not enable a commit from stale data.
            self._selection_needs_refresh.add(scope)
            self.repaint_file_selection(path); self.update_enabled()
            if self._repository_notice_relevant(path):
                self._show_repository_error(path, 'Nie udało się potwierdzić wyboru plików.\n' + error)

        self.mutate('Zapisywanie wyboru plików…', write, confirmed,
                    path=path, failure=failed, refresh_after=False, key='file-selection:' + scope)

    def suggested_commit_message(self):
        selected = [change for change in self.state.changes
                    if self.displayed_check_state(change) != Qt.CheckState.Unchecked] if self.state else []
        if len(selected) != 1: return 'update'
        filename = str(selected[0].path).replace('\\', '/').rsplit('/', 1)[-1]
        filename = ' '.join(filename.split())
        return f'{filename} changed' if filename else 'update'

    def effective_commit_message(self):
        return self.summary.text().strip() or self.suggested_commit_message()

    def make_commit(self):
        if not self.commit_button.isEnabled(): return
        path = self.repo; summary = self.effective_commit_message(); description = self.description.toPlainText().strip()
        backend = self.backend
        expected_head = (self.state.head_ref, self.state.head_oid)
        def done(result):
            self.drafts[path] = ('', '')
            if path == self.repo:
                self.summary.clear(); self.description.clear()
        self.mutate('Tworzenie commita…', lambda: backend.commit(path, summary, description, expected_head=expected_head), done, path=path)

    def switch_branch(self, index):
        if not self.state: return
        name = self.branches.itemText(index)
        if name == self.state.branch: return
        branch = self.branches.itemData(index) or name
        path = self.repo
        self.forget_push_route(path)
        self.mutate('Przełączanie gałęzi…', lambda: self.backend.switch_branch(path, branch), path=path)

    def new_branch(self):
        if (not self.repo or not self.backend or self.state is None or self.mutating
                or self.opening or self._close_pending): return
        path = self.repo
        head_ref = getattr(self.state, 'head_ref', '')
        current_name = head_ref.removeprefix('refs/heads/') if head_ref.startswith('refs/heads/') else ''
        dialog = OperationForm(self, 'Nowa gałąź', f'Repozytorium: {path}',
                               [('Nazwa gałęzi', current_name, 'feature/nowy-pomysl')], 'Utwórz gałąź')
        def submit(values):
            name, = values
            if not name: dialog.failed('Podaj nazwę gałęzi.'); return
            if name == current_name:
                dialog.failed('Wpisz inną nazwę — ta gałąź już istnieje.')
                dialog.fields[0].setFocus(Qt.FocusReason.OtherFocusReason); dialog.fields[0].selectAll()
                return
            token = self.mutate('Tworzenie gałęzi…', lambda: self.backend.create_branch(path, name),
                                lambda result: dialog.succeeded(), path=path, failure=dialog.failed)
            dialog.set_busy(token)
        dialog.submitted.connect(submit); self.keep_dialog(dialog)
        dialog.fields[0].setFocus(Qt.FocusReason.OtherFocusReason); dialog.fields[0].selectAll()
        return dialog

    def network_action(self, action):
        if not self.repo: return
        if repository_scope(self.repo) in self._unbound_clones:
            self.show_error('Repozytorium jest sklonowane, ale nie udało się zapisać wybranego konta. Ustaw konto dla serwera zdalnego przed operacją sieciową.')
            return
        if action == 'push':
            self.push_with_review(); return
        path = self.repo; method = getattr(self.backend, action)
        self.mutate({'fetch': 'Pobieranie informacji z serwera…', 'pull': 'Pobieranie zmian…'}[action], lambda: method(path), path=path)

    def account_for_endpoint(self, path, remote, endpoint, explicit=None):
        parsed = auth_urlparse.urlsplit(endpoint)
        if parsed.scheme != 'https':
            return None, 'SSH / konfiguracja Git'
        host = self.endpoint_host(endpoint)
        account = self.store.resolve_account(host, username=auth_urlparse.unquote(parsed.username or '') or None,
                                             account_id=explicit, repo=path, remote=remote)
        if account:
            return account['id'], f"@{account['username']} · {account['host']}"
        return None, 'Poświadczenia zapisane w Git'

    @staticmethod
    def endpoint_host(endpoint):
        parsed = auth_urlparse.urlsplit(endpoint)
        hostname = parsed.hostname or ''
        if ':' in hostname: hostname = '[' + hostname + ']'
        return auth_normalize_host('https://' + hostname + (':' + str(parsed.port) if parsed.port is not None else ''))

    def backend_for_identity(self, account_id):
        return (self.backend.with_account(account_id) if account_id is not None
                else self.backend.with_native_credentials())

    def push_with_identity(self, path, plan, account_id, explicit=None, progress=None):
        push = plan.push_plan if isinstance(plan, ForcePushPlan) else plan
        current, _ = self.resolve_push_identity(path, push, explicit)
        if current != account_id:
            raise AuthError('Konto repozytorium zmieniło się przed wysłaniem. Kliknij Push ponownie, aby użyć bieżącego konta.')
        backend = self.backend_for_identity(account_id)
        return (backend.force_push(path, plan, progress=progress) if isinstance(plan, ForcePushPlan)
                else backend.push(path, plan=plan, progress=progress))

    def remember_push_account(self, path, plan, explicit):
        if explicit is None: return
        hosts = {self.endpoint_host(url) for url in plan.push_urls if auth_urlparse.urlsplit(url).scheme == 'https'}
        for host in hosts:
            self.store.set_repository_account(path, plan.remote_name, host, explicit)

    def add_account_selector(self, dialog):
        combo = StyledComboBox(); combo.setAccessibleName('Konto do operacji z serwerem')
        combo.addItem('Automatycznie dla tego repozytorium', None)
        try:
            for account in self.store.list_accounts():
                if not account.get('removal_pending'):
                    combo.addItem(f"@{account['username']} · {account['host']}", account['id'])
        except AuthError as error:
            dialog.status.setText(str(error))
        position = dialog.layout().indexOf(dialog.status)
        dialog.layout().insertWidget(position, ui_label('KONTO LOGOWANIA', 'eyebrow'))
        dialog.layout().insertWidget(position + 1, combo)
        return combo

    @staticmethod
    def push_route(plan, account_id):
        return (plan.source_ref, plan.remote_name, tuple(plan.push_urls), plan.destination_ref, account_id,
                getattr(plan, 'remote_override', None), getattr(plan, 'destination_override', None))

    def forget_push_route(self, path):
        scope = repository_scope(path)
        self._approved_routes.pop(scope, None)
        self._approved_route_labels.pop(scope, None)
        if scope == repository_scope(self.repo):
            self.push_target_label.setText('Push: cel i konto zostaną sprawdzone przed wysłaniem.')
            self.push_target_label.setToolTip('')

    def show_approved_push_route(self, path):
        scope = repository_scope(path)
        route = self._approved_routes.get(scope)
        if not route or scope != repository_scope(self.repo): return
        identity = self._approved_route_labels.get(scope, route[4] or 'Konfiguracja Git')
        self.push_target_label.setText(f'Push → {route[1]}/{route[3].removeprefix("refs/heads/")} · {identity}')
        self.push_target_label.setToolTip('\n'.join(_git_safe_text(endpoint) for endpoint in route[2])
            + f'\nŹródło: {route[0]}\nKażde wysłanie ponownie sprawdza gałąź, serwer i konto.')

    def resolve_push_identity(self, path, plan, explicit=None):
        identities = [self.account_for_endpoint(path, plan.remote_name, endpoint, explicit)
                      for endpoint in plan.push_urls]
        if len({identity[0] for identity in identities}) > 1:
            raise AuthError('Serwer ma kilka adresów wysyłania z różnymi kontami. Skonfiguruj osobne serwery zdalne.')
        return identities[0] if identities else (None, 'Konfiguracja Git')

    def automatic_push_plan(self, path):
        approved = self._approved_routes.get(repository_scope(path))
        remote, destination = (approved[5], approved[6]) if approved else (None, None)
        plan = self.backend.resolve_push_plan(path, remote=remote, destination=destination)
        if approved and plan.source_ref != approved[0] and (remote is not None or destination is not None):
            plan = self.backend.resolve_push_plan(path)
        return plan, self.resolve_push_identity(path, plan)

    def inspect_push_target(self, path, source_ref):
        def current():
            return (not self._close_pending and path == self.repo and self.state is not None
                    and (getattr(self.state, 'head_ref', '') or f'refs/heads/{self.state.branch}') == source_ref)
        def ready(result):
            if not current(): return
            plan, identity = result
            if plan.source_ref != source_ref: return
            self.push_target_label.setText(f'Push → {plan.remote_name}/{plan.destination_ref.removeprefix("refs/heads/")} · {identity[1]}')
            self.push_target_label.setToolTip('\n'.join(_git_safe_text(url) for url in plan.push_urls)
                + '\nCel i konto są ustalane automatycznie z konfiguracji repozytorium.')
        def failed(error):
            if current() and error != 'Operacja anulowana.':
                self.push_target_label.setText('Push · ustaw cel lub konto')
                self.push_target_label.setToolTip(_git_safe_text(str(error)))
        self.hub.submit(lambda: self.automatic_push_plan(path), ready, failed,
                        scope=repository_scope(path), key='push-hint', background=True)

    def push_with_review(self):
        path = self.repo
        if self._active_rewrite:
            return self.force_push_dialog(path, self._active_rewrite)
        scope = repository_scope(path)
        def resolved(result):
            if self._close_pending: return
            plan, identity = result
            self._approved_routes[scope] = self.push_route(plan, identity[0])
            self._approved_route_labels[scope] = identity[1]
            self.show_approved_push_route(path)
            self.mutate('Wysyłanie commitów…', lambda progress: self.push_with_identity(path, plan, identity[0], progress=progress),
                        path=path, report_progress=True)
        def failed(error):
            if error == 'Operacja anulowana.' or self._close_pending: return
            approved = self._approved_routes.get(scope)
            self.push_dialog(path, remote=approved[5] if approved else None,
                             destination=approved[6] if approved else None, reason=error)
        return self.hub.submit(lambda progress: self.automatic_push_plan(path), resolved, failed, scope=scope,
            key=f'push-route:{scope}', label='Sprawdzanie celu wysyłania', report_progress=True)

    def force_push_dialog(self, path, record):
        dialog = OperationForm(self, 'Force push · zmieniona historia',
            f'Repozytorium: {path}\nOpublikujesz przepisane commity. Jeśli ktoś zmienił gałąź na serwerze od zapisanego stanu, '
            'Git zatrzyma wysyłanie. Współpracownicy będą musieli dostosować swoje lokalne gałęzie.', action='Sprawdź cel')
        dialog.setMinimumSize(560, 480)
        dialog.resize(620, 540)
        account = self.add_account_selector(dialog)
        reviewed = {}
        def invalidate(*unused):
            reviewed.clear(); dialog.submit_button.setText('Sprawdź cel')
        account.currentIndexChanged.connect(invalidate)
        def failed(error):
            if dialog in self._dialogs:
                account.setEnabled(True); invalidate(); dialog.failed(error)
        def submit(unused=()):
            if dialog.token is not None: return
            if reviewed:
                plan, identity = reviewed['plan'], reviewed['identity']
                backend = self.backend_for_identity(identity[0])
                def publish(progress):
                    push = plan.push_plan
                    if self.rewrite_leases.active(backend, path, push.source_ref, push.head_oid) != record:
                        raise GitError('Zmienił się zapisany stan zmiany historii. Sprawdź ponownie historię przed wysłaniem.')
                    result = self.push_with_identity(path, plan, identity[0], reviewed.get('explicit'), progress=progress)
                    try: self.rewrite_leases.clear(record)
                    except OSError:
                        result += '\nWysłano commity; zapis lokalnego stanu zostanie zweryfikowany przy odświeżeniu.'
                    return result
                def done(result):
                    if path == self.repo:
                        self._active_rewrite = None
                        self.apply_history_publication()
                    push = plan.push_plan
                    scope = repository_scope(path)
                    self._approved_routes[scope] = self.push_route(push, identity[0])
                    self._approved_route_labels[scope] = identity[1]
                    try: self.remember_push_account(path, push, reviewed.get('explicit'))
                    except AuthError as error: self.show_error(f'Commity zostały wysłane, ale nie udało się zapamiętać konta repozytorium: {error}')
                    self.show_approved_push_route(path); dialog.succeeded()
                token = self.mutate('Wysyłanie zmienionej historii…', publish, done, path=path, failure=failed, report_progress=True)
                dialog.set_busy(token); account.setEnabled(token is None)
                return
            explicit = account.currentData()
            def prepare():
                plan = self.backend.prepare_force_push(path, record['expected_remote_oid'],
                                                       record['remote_name'], record['destination_ref'])
                if not self.rewrite_leases.matches(record, plan.push_plan):
                    raise GitError('Cel wysyłania zmienił się od zmiany historii. Przywróć poprzedni serwer i adres przed Force push.')
                active = self.rewrite_leases.active(self.backend, path, plan.push_plan.source_ref, plan.push_plan.head_oid)
                if active != record:
                    raise GitError('Ta zmiana historii nie wymaga już wymuszonego wysyłania albo zmieniła się gałąź. Odśwież historię.')
                return plan, self.resolve_push_identity(path, plan.push_plan, explicit)
            def ready(result):
                if dialog not in self._dialogs: return
                plan, identity = result; push = plan.push_plan
                reviewed.update(plan=plan, identity=identity, explicit=explicit)
                dialog.set_busy(None); account.setEnabled(True)
                dialog.submit_button.setText('Force push do pokazanego celu')
                dialog.status.setText(f'Serwer: {push.remote_name}\nAdres: {_git_safe_text(push.push_urls[0])}\n'
                    f'Źródło: {push.source_ref} · {push.head_oid[:12]}\nCel: {push.destination_ref}\nKonto: {identity[1]}\n'
                    f'Zapisany commit serwera: {plan.expected_remote_oid[:12]}\n\n'
                    'Ten stan został zapisany przed zmianą historii. Odświeżanie go nie zmienia.')
            token = self.hub.submit(prepare, ready, failed, scope=repository_scope(path),
                                    key=f'force-push-plan:{id(dialog)}', label='Sprawdzanie historii przed Force push')
            dialog.set_busy(token); account.setEnabled(False)
        dialog.submitted.connect(submit)
        self.keep_dialog(dialog)
        QTimer.singleShot(0, lambda: submit() if dialog in self._dialogs else None)
        return dialog

    def push_dialog(self, path=None, remote=None, destination=None, reason=None):
        path = str(path) if isinstance(path, (str, os.PathLike)) else self.repo
        if not path: return
        dialog = OperationForm(self, 'Wyślij commity',
            f'Repozytorium: {path}\n' + (_git_safe_text(str(reason)) + '\n' if reason else '')
            + 'Puste pola dobiorą cel i konto automatycznie. Ręczny wybór konta zostanie zapamiętany dla tego repozytorium.',
            [('Serwer zdalny (opcjonalnie)', remote or '', 'Np. origin lub fork'),
             ('Gałąź docelowa (opcjonalnie)', destination or '', 'Np. main')], 'Sprawdź cel wysyłania')
        account = self.add_account_selector(dialog)
        reviewed = {}
        def invalidate(*unused):
            reviewed.clear()
            dialog.submit_button.setText('Sprawdź cel wysyłania')
            if dialog.token is None: dialog.status.setText('Sprawdź zmieniony cel przed wysłaniem.')
        for field in dialog.fields: field.textChanged.connect(invalidate)
        account.currentIndexChanged.connect(invalidate)
        def submit(values):
            if dialog.token is not None: return
            remote, destination = values
            explicit = account.currentData()
            specification = (remote, destination, explicit)
            if reviewed.get('specification') == specification:
                plan, account_id = reviewed['plan'], reviewed['account_id']
                account.setEnabled(False)
                def failed(error):
                    account.setEnabled(True); reviewed.clear()
                    dialog.submit_button.setText('Sprawdź cel wysyłania'); dialog.failed(error)
                def done(result):
                    try: self.remember_push_account(path, plan, explicit)
                    except AuthError as error: self.show_error(f'Commity zostały wysłane, ale nie udało się zapamiętać konta repozytorium: {error}')
                    dialog.succeeded()
                token = self.mutate('Wysyłanie commitów…', lambda progress: self.push_with_identity(path, plan, account_id, explicit, progress=progress),
                                    done, path=path, failure=failed, report_progress=True)
                if token is not None:
                    scope = repository_scope(path)
                    self._approved_routes[scope] = self.push_route(plan, account_id)
                    self._approved_route_labels[scope] = reviewed['identity_label']
                    self.show_approved_push_route(path)
                dialog.set_busy(token)
                return
            def resolve():
                plan = self.backend.resolve_push_plan(path, remote=remote or None, destination=destination or None)
                return plan, self.resolve_push_identity(path, plan, explicit)
            def resolved(result):
                if dialog not in self._dialogs: return
                plan, identity = result
                reviewed.update(specification=specification, plan=plan, account_id=identity[0], identity_label=identity[1])
                dialog.set_busy(None); account.setEnabled(True)
                endpoints = '\n'.join(_git_safe_text(endpoint) for endpoint in plan.push_urls)
                dialog.status.setText(f'Serwer: {plan.remote_name}\nAdres: {endpoints}\n'
                    f'Źródło: {plan.source_ref} · {plan.head_oid[:12]}\nCel: {plan.destination_ref}\n'
                    f'Konto: {identity[1]}\n' + ('Pierwszy push ustawi upstream.' if plan.set_upstream else 'Powiązanie pobierania pozostaje bez zmian.'))
                dialog.submit_button.setText('Wyślij do pokazanego celu')
                if repository_scope(path) in self._approved_routes:
                    self.show_approved_push_route(path)
                elif path == self.repo:
                    self.push_target_label.setText(f'Ostatnio sprawdzony Push → {plan.remote_name}/{plan.destination_ref.removeprefix("refs/heads/")} · {identity[1]}')
                    self.push_target_label.setToolTip(f'{endpoints}\nŹródło: {plan.source_ref} · {plan.head_oid[:12]}')
            def failed(error):
                if dialog in self._dialogs:
                    account.setEnabled(True); dialog.failed(error)
            token = self.hub.submit(resolve, resolved, failed, scope=repository_scope(path),
                                    key=f'push-plan:{id(dialog)}', label='Sprawdzanie celu wysyłania')
            dialog.set_busy(token); account.setEnabled(False)
        dialog.submitted.connect(submit)
        self.keep_dialog(dialog)
        QTimer.singleShot(0, lambda: submit(tuple(field.text().strip() for field in dialog.fields))
                          if dialog in self._dialogs else None)
        return dialog

    def repository_account_dialog(self):
        if not self.repo: return
        path = self.repo
        remote = self.state.remotes[0] if self.state and self.state.remotes else 'origin'
        dialog = OperationForm(self, 'Konto dla serwera zdalnego',
            f'Repozytorium: {path}\nPowiązanie dotyczy logowania do wybranego serwera. Dane autora commitów ustawia się osobno.',
            [('Nazwa serwera zdalnego', remote, 'origin')])
        account = self.add_account_selector(dialog)
        inspected = {'remote': None}
        def inspect_binding():
            remote_name = dialog.fields[0].text().strip()
            if dialog.token is not None or remote_name == inspected['remote'] or not remote_name: return
            def load():
                endpoint = self.backend.run(path, ['remote', 'get-url', '--', remote_name]).strip()
                parsed = auth_urlparse.urlsplit(endpoint)
                if parsed.scheme != 'https':
                    raise AuthError('Ten serwer używa SSH lub ścieżki lokalnej; konta aplikacji dotyczą HTTPS.')
                host = self.endpoint_host(endpoint)
                return host, self.store.get_repository_account(path, remote_name, host)
            def loaded(result):
                if dialog not in self._dialogs: return
                host, binding = result; inspected['remote'] = remote_name
                index = account.findData(binding)
                if index < 0:
                    account.addItem('Poprzednio wybrane konto jest odłączone — wybierz konto', binding)
                    index = account.count() - 1
                account.setCurrentIndex(index)
                account.setEnabled(True); dialog.set_busy(None)
                dialog.status.setText(f'Serwer: {host}' + ('\nPoprzednio wybrane konto jest odłączone — wybierz konto.' if binding and index == account.count() - 1 and account.itemText(index).startswith('Poprzednio') else ''))
            def failed(error):
                if dialog in self._dialogs: account.setEnabled(True); dialog.failed(error)
            token = self.hub.submit(load, loaded, failed, scope=repository_scope(path), key=f'account-binding:{id(dialog)}')
            dialog.set_busy(token); account.setEnabled(False)
        def submit(values):
            remote_name, = values
            account_id = account.currentData()
            if not remote_name or remote_name.startswith('-'):
                dialog.failed('Podaj nazwę istniejącego serwera zdalnego.'); return
            def save():
                endpoint = self.backend.run(path, ['remote', 'get-url', '--', remote_name]).strip()
                parsed = auth_urlparse.urlsplit(endpoint)
                if parsed.scheme != 'https':
                    raise AuthError('Konta aplikacji dotyczą HTTPS. Dla SSH używana jest konfiguracja systemu.')
                host = self.endpoint_host(endpoint)
                self.store.set_repository_account(path, remote_name, host, account_id)
            account.setEnabled(False)
            def failed(error): account.setEnabled(True); dialog.failed(error)
            def done(result):
                self._unbound_clones.pop(repository_scope(path), None)
                self.forget_push_route(path)
                dialog.succeeded()
            token = self.mutate('Zapisywanie konta repozytorium…', save,
                                done, path=path, failure=failed)
            dialog.set_busy(token)
        dialog.submitted.connect(submit)
        self.keep_dialog(dialog)
        dialog.fields[0].editingFinished.connect(inspect_binding)
        QTimer.singleShot(0, inspect_binding)
        return dialog

    def new_repo(self):
        if not self.backend: self.show_error(self.git_error); return
        dialog = QFileDialog(self, 'Wybierz folder dla nowego repozytorium')
        dialog.setFileMode(QFileDialog.FileMode.Directory)
        dialog.setOption(QFileDialog.Option.ShowDirsOnly, True)
        def selected(path):
            self.mutate('Tworzenie repozytorium…', lambda: self.backend.init_repo(path),
                        lambda result: self.open_repo(path), path=path)
        dialog.fileSelected.connect(selected); self.keep_dialog(dialog)

    def clone_repo(self, project=None):
        if not self.backend: self.show_error(self.git_error); return
        if self._close_pending: return
        if isinstance(project, dict):
            try:
                accounts = self.store.list_accounts()
                if not any(account['id'] == project.get('account_id') and not account.get('removal_pending')
                           for account in accounts):
                    raise AuthError('Konto tego projektu nie jest już dostępne. Połącz je ponownie lub wybierz inny projekt.')
            except AuthError as error:
                self.show_error(str(error))
                self.catalog.refresh()
                return
        dialog = CloneDialog(self.store, self, catalog=self.catalog, project=project)
        def submitted(request):
            navigation = self.open_serial
            cloned = dialog._cloned_request is not None
            def clone_and_bind():
                if not cloned:
                    self.backend.clone(request.url, request.target, account_id=request.account_id)
                parsed = auth_urlparse.urlsplit(request.url)
                if request.account_id and parsed.scheme == 'https':
                    try:
                        host = auth_normalize_host('https://' + parsed.netloc)
                        self.store.set_repository_account(request.target, 'origin', host, request.account_id)
                    except AuthError as error:
                        return str(error)
                return ''
            def done(result):
                if result:
                    self._unbound_clones[repository_scope(request.target)] = result
                    dialog.set_busy(None); dialog._cloned_request = request
                    for widget in (dialog.url, dialog.target, dialog.account, dialog.browser): widget.setEnabled(False)
                    dialog.clone_button.setText('Ponów zapis konta')
                    dialog.status.setText(f'Repozytorium zostało sklonowane do {request.target}.\n'
                        f'Nie udało się zapisać wybranego konta: {result}\nPonowienie zapisze konto bez powtarzania klonowania.')
                    return
                self._unbound_clones.pop(repository_scope(request.target), None)
                dialog.set_busy(None); dialog.accept()
                if navigation == self.open_serial and not self._close_pending:
                    self.open_repo(request.target)
            token = self.mutate('Klonowanie repozytorium…',
                clone_and_bind,
                done, path=request.target, failure=dialog.operation_failed)
            dialog.set_busy(token)
        dialog.clone_requested.connect(submitted)
        self.keep_dialog(dialog)
        return dialog

    def stash_availability(self):
        ready = bool(self.repo and self.backend and self.state and not self.mutating
                     and not self.opening and not self._close_pending
                     and repository_scope(self.repo) not in self._selection_needs_refresh)
        ready = ready and not any(change.conflicted for change in self.state.changes)
        return (bool(ready and self.state.head_oid and self.state.changes),
                bool(ready and self.state.stash_count))

    def add_stash_actions(self, menu):
        can_stash, can_restore = self.stash_availability()
        menu.setToolTipsVisible(True)
        stash = menu.addAction('Odłóż wszystkie zmiany (stash)…', self.stash_changes)
        stash.setEnabled(can_stash)
        stash.setToolTip('Obejmuje wszystkie lokalne zmiany, także nowe i odznaczone pliki oraz pliki ukryte przez filtr.')
        restore = menu.addAction(f'Przywróć ostatni stash ({self.state.stash_count if self.state else 0})', self.pop_stash)
        restore.setEnabled(can_restore)
        restore.setToolTip('Przywraca ostatnio odłożone zmiany. Po udanym przywróceniu usuwa ten wpis ze schowka.')

    def changes_context_menu(self, point):
        if not self.repo: return
        menu = QMenu(self)
        self.add_stash_actions(menu)
        self.add_revert_recovery_action(menu)
        menu.exec(self.selection_header.mapToGlobal(point))

    def more_menu(self):
        if not self.repo: return
        menu = QMenu(self)
        menu.addAction(ui_icon('branch'), 'Nowa gałąź…', self.new_branch)
        menu.addSeparator()
        menu.addAction('Ustaw autora commitów…', self.identity_dialog)
        menu.addAction('Ustaw serwer zdalny…', self.remote_dialog)
        menu.addAction('Konto dla serwera zdalnego…', self.repository_account_dialog)
        menu.addAction('Zmień cel wysyłania…', self.push_dialog)
        menu.addSeparator()
        self.add_stash_actions(menu)
        self.add_revert_recovery_action(menu)
        menu.addSeparator(); menu.addAction('Kopiuj ścieżkę repozytorium', lambda: QApplication.clipboard().setText(self.repo))
        menu.addSeparator(); menu.addAction('Technologie i licencje…', self.show_technologies)
        menu.exec(self.more_button.mapToGlobal(QPoint(0, self.more_button.height()+4)))

    def identity_dialog(self):
        if not self.repo: return
        path = self.repo
        dialog = OperationForm(self, 'Autor commitów', f'Dane autora zapiszą się tylko w repozytorium {path}. Konto logowania ustawia się osobno.',
            [('Imię lub pseudonim', '', 'Autor commita'), ('E-mail autora', '', 'autor@example.com')])
        def submit(values):
            name, email = values
            if not name or not email: dialog.failed('Podaj nazwę autora i e-mail.'); return
            token = self.mutate('Zapisywanie autora…', lambda: self.backend.set_identity(path, name, email),
                                lambda result: dialog.succeeded(), path=path, failure=dialog.failed)
            dialog.set_busy(token)
        dialog.submitted.connect(submit); self.keep_dialog(dialog)

    def remote_dialog(self):
        if not self.repo: return
        path = self.repo
        dialog = OperationForm(self, 'Serwer zdalny origin', f'Repozytorium: {path}',
                               [('Adres HTTPS lub SSH', '', 'https://github.com/zespol/projekt.git')])
        def submit(values):
            url, = values
            try: parsed = auth_urlparse.urlsplit(url)
            except ValueError: dialog.failed('Nieprawidłowy adres repozytorium.'); return
            if not url or url.startswith('-') or '\n' in url or '\r' in url or (parsed.scheme in ('http', 'https') and (parsed.scheme == 'http' or parsed.username or parsed.password)):
                dialog.failed('Użyj adresu HTTPS bez tokenu lub adresu SSH.'); return
            def save():
                exists = 'origin' in self.backend.run(path, ['remote']).splitlines()
                return self.backend.run(path, ['remote', 'set-url' if exists else 'add', 'origin', url])
            token = self.mutate('Zapisywanie serwera…', save, lambda result: dialog.succeeded(),
                                path=path, failure=dialog.failed)
            dialog.set_busy(token)
        dialog.submitted.connect(submit); self.keep_dialog(dialog)

    def stash_changes(self):
        if not self.stash_availability()[0]: return
        path = self.repo
        dialog = OperationForm(self, 'Odłóż wszystkie zmiany',
                               f'Repozytorium: {path}\nObejmuje także nowe i odznaczone pliki oraz pliki ukryte przez filtr.',
                               [('Opis schowka (opcjonalnie)', '', 'Praca w toku')], 'Odłóż zmiany')
        def submit(values):
            message, = values
            token = self.mutate('Odkładanie zmian…', lambda: self.backend.stash(path, message),
                                lambda result: dialog.succeeded(), path=path, failure=dialog.failed)
            dialog.set_busy(token)
        dialog.submitted.connect(submit); self.keep_dialog(dialog)

    def pop_stash(self):
        if not self.stash_availability()[1]: return
        path = self.repo; self.mutate('Przywracanie zmian ze schowka…', lambda: self.backend.stash_pop(path))

    def reveal_folder(self):
        if self.repo: QDesktopServices.openUrl(QUrl.fromLocalFile(self.repo))

    def show_accounts(self):
        dialog = AccountsDialog(self.store, self.backend.git_exe if self.backend else None, self)
        dialog.accounts_changed.connect(self.update_accounts)
        self.keep_dialog(dialog)

    def update_accounts(self, refresh=True, reveal=True):
        self._push_hint_context = None
        try:
            accounts = self.store.list_accounts()
            count = len(accounts)
            active = {account['id'] for account in accounts if not account.get('removal_pending')}
        except AuthError:
            count = 0
            active = set()
        for scope, route in tuple(self._approved_routes.items()):
            if route[4] is not None and route[4] not in active:
                self.forget_push_route(scope)
        self.account_button.setText(f'Konta · {count}' if count else 'Połącz konto')
        self.account_button.setAccessibleName(f'Zarządzaj kontami: {count}' if count else 'Połącz konto')
        if refresh and not self._close_pending:
            if self._startup_ready:
                self.catalog.refresh(force=True)
            else:
                self._startup_catalog_pending = True
            if count and reveal and not self.repo:
                self.pages.setCurrentIndex(2)

    def command_palette(self):
        dialog = QDialog(self); dialog.setWindowTitle('Szybkie polecenia'); dialog.setMinimumWidth(510)
        layout = QVBoxLayout(dialog); layout.setContentsMargins(18, 18, 18, 18)
        search = QLineEdit(); search.setPlaceholderText('Co chcesz zrobić?'); layout.addWidget(search)
        choices = QListWidget(); layout.addWidget(choices)
        commands = [('Otwórz repozytorium', self.choose_repo), ('Klonuj repozytorium', self.clone_repo),
                    ('Pokaż projekty do sklonowania', self.show_remote_projects),
                    ('Utwórz repozytorium', self.new_repo), ('Połącz lub zarządzaj kontami', self.show_accounts),
                    ('Przegląd projektów', self.show_home), ('O aplikacji', self.show_about),
                    ('Technologie i licencje', self.show_technologies)]
        if self.repo:
            commands += [('Pokaż zmiany', lambda: self.show_view(0)), ('Pokaż historię', lambda: self.show_view(1)),
                         ('Odśwież repozytorium', lambda: self.refresh()), ('Utwórz gałąź', self.new_branch),
                         ('Otwórz folder', self.reveal_folder), ('Ustaw autora commitów', self.identity_dialog)]
        def populate(text=''):
            choices.clear()
            for title, callback in commands:
                if text.casefold() in title.casefold():
                    item = QListWidgetItem(title); item.setData(Qt.ItemDataRole.UserRole, callback); choices.addItem(item)
            if choices.count(): choices.setCurrentRow(0)
        def activate(item=None):
            selected = item or choices.currentItem()
            if selected:
                callback = selected.data(Qt.ItemDataRole.UserRole); dialog.accept(); QTimer.singleShot(0, callback)
        search.textChanged.connect(populate); search.returnPressed.connect(activate); choices.itemActivated.connect(activate)
        populate(); search.setFocus(); self.keep_dialog(dialog)

    def focus_diff_search(self):
        if self.pages.currentIndex() == 1:
            self.diff_search.show(); self.diff_search.setFocus(); self.diff_search.selectAll()

    def find_in_diff(self):
        query = self.diff_search.text()
        if query and not self.diff.find(query):
            self.diff.moveCursor(QTextCursor.MoveOperation.Start); self.diff.find(query)

    def show_error(self, error):
        self._repository_error_key = self._repository_status_key = ''
        self.status.setText('Operacja nie została zakończona.')
        message = _git_safe_text(str(error))
        self.error_text.setText(message[:1800]); self.error_text.setToolTip(message)
        try: self.error_action.clicked.disconnect()
        except RuntimeError: pass
        author = any(term in message.lower() for term in ('identity unknown', 'tell me who', 'user.email', 'autora'))
        authentication = any(term in message.lower() for term in ('authentication', 'credential', 'token', 'konto', 'konta', 'logowania', '401', '403', 'publickey'))
        self.error_action.setText('Ustaw autora' if author else 'Sprawdź konta' if authentication else 'Odśwież stan')
        self.error_action.clicked.connect(self.identity_dialog if author else self.show_accounts if authentication else self.refresh)
        self.error_bar.show()

    def show_technologies(self):
        dialog = TechnologiesDialog(self); self.keep_dialog(dialog); return dialog

